-- ─── Curso de Oratoria: cómo hablar en público con seguridad (8 clases) ───
DO $hb01$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Oratoria: cómo hablar en público con seguridad' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, area, level, tags,
     objective, learning_outcomes, audience, duration_minutes, author_name, status, modality, cover_url, publico)
  VALUES ('edvanta', 'Curso de Oratoria: cómo hablar en público con seguridad', $hb01t$Curso práctico para aprender a hablar en público con claridad, estructura y seguridad. Aplica cada técnica a situaciones reales del sector farmacéutico: comités de farmacia, capacitaciones a auxiliares, visitas médicas, ponencias en congresos y reuniones con directivos.$hb01t$,
          $hb01t$<p>Curso práctico para aprender a hablar en público con claridad, estructura y seguridad. Aplica cada técnica a situaciones reales del sector farmacéutico: comités de farmacia, capacitaciones a auxiliares, visitas médicas, ponencias en congresos y reuniones con directivos.</p><h2>Objetivo</h2><p>Que el participante planee, estructure y presente un discurso de 3 a 5 minutos con un mensaje central claro, voz y cuerpo coherentes con el mensaje y capacidad para responder preguntas del público.</p><h2>Para quién es</h2><p>Químicos farmacéuticos, regentes de farmacia, visitadores médicos, auxiliares de servicio farmacéutico, estudiantes de últimos semestres y cualquier profesional que necesite presentar ideas en público.</p><h2>Cómo está organizado</h2><p>Cuatro unidades con dos clases en texto cada una. Cada clase trae un ejemplo aplicado al sector farmacéutico y de la salud, puntos clave y el siguiente paso.</p><h2>Referentes</h2><p>Chris Anderson (TED Talks: la guía oficial de TED para hablar en público); Carmine Gallo (Talk Like TED); Toastmasters International (método por proyectos con evaluación entre pares); Aristóteles (Retórica: ethos, pathos, logos); Barbara Minto (principio de la pirámide).</p>$hb01t$,
          'Oratoria y presentaciones', 'Habilidades Blandas', 'basico', ARRAY['Oratoria', 'Hablar en público', 'Comunicación', 'Presentaciones', 'Habilidades blandas']::text[],
          $hb01t$Que el participante planee, estructure y presente un discurso de 3 a 5 minutos con un mensaje central claro, voz y cuerpo coherentes con el mensaje y capacidad para responder preguntas del público.$hb01t$,
          ARRAY['Explicar los pilares de la oratoria y diagnosticar tu punto de partida al hablar en público.', 'Estructurar un discurso con apertura, cuerpo y cierre alrededor de un mensaje central.', 'Usar la voz y el lenguaje corporal para reforzar tu mensaje.', 'Ensayar con método, improvisar y responder preguntas del público sin quedarte en blanco.']::text[],
          $hb01t$Químicos farmacéuticos, regentes de farmacia, visitadores médicos, auxiliares de servicio farmacéutico, estudiantes de últimos semestres y cualquier profesional que necesite presentar ideas en público.$hb01t$,
          151, 'Edvanta', 'borrador', 'asincronica', '/img/cursos/oratoria.webp', 'profesionales')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Fundamentos de la oratoria', 0)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Qué es la oratoria y por qué cualquier persona puede aprender a hablar en público', 'Unidad 1 · Clase 1.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb01j${"tone":"info","title":"En esta clase","html":"<p>Qué es la oratoria, sus tres pilares (ethos, pathos y logos) y por qué hablar en público es una habilidad entrenable. Guía práctica con ejemplos del sector salud.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb01j${"html":"<p>Si alguna vez saliste de una presentación pensando \"yo sabía mucho más de lo que alcancé a decir\", esta clase es para ti. La buena noticia es que hablar bien en público no es un don con el que se nace: es un conjunto de habilidades concretas que se pueden aprender, practicar y medir. En esta clase vas a entender qué es la oratoria, cuáles son sus pilares y cómo se convierte el conocimiento técnico en un mensaje que la gente recuerda y usa.</p><h2>¿Qué es la oratoria?</h2><p>La oratoria es el arte de hablar en público con un propósito: informar, persuadir, inspirar o movilizar a una audiencia. No se trata de \"hablar bonito\". Se trata de lograr que, al final, el público entienda algo, crea algo o haga algo que antes no hacía.</p>\n<p>Una definición útil para el trabajo diario es esta: <strong>oratoria es lograr que una idea pase de tu cabeza a la cabeza de otra persona, sin pérdidas y con un efecto concreto.</strong></p><h2>Los tres pilares clásicos: ethos, pathos y logos</h2><p>Hace más de 2.300 años, Aristóteles describió en su <em>Retórica</em> tres medios de persuasión que siguen funcionando hoy:</p>\n<ul>\n<li><strong>Ethos (credibilidad):</strong> el público te escucha porque confía en ti. Se construye con preparación, coherencia, experiencia demostrada y honestidad sobre lo que no sabes.</li>\n<li><strong>Pathos (emoción):</strong> el público se conecta porque el tema le importa. Se construye con historias, ejemplos cercanos y mostrando qué está en juego para la audiencia.</li>\n<li><strong>Logos (lógica):</strong> el público acepta tu propuesta porque los argumentos tienen sentido. Se construye con datos, evidencia y un razonamiento ordenado.</li>\n</ul>\n<p>Un error frecuente en profesionales de la salud es apoyarse solo en el logos: diapositivas llenas de cifras, sin una historia que haga que esos números importen. El resultado es una charla correcta… que nadie recuerda.</p><h2>¿Por qué la oratoria se puede aprender?</h2><p>Chris Anderson, curador de las charlas TED, insiste en que no existe un único estilo de buen orador: hay oradores introvertidos, pausados, técnicos o muy expresivos que logran conectar. Lo que tienen en común no es el carisma, sino <strong>una idea clara y bien construida</strong>. Organizaciones como Toastmasters llevan décadas demostrando lo mismo: con práctica frecuente y retroalimentación, la mayoría de las personas mejora de forma visible en pocas semanas.</p>\n<p>La oratoria se puede dividir en cinco componentes entrenables:</p>\n<ol>\n<li><strong>Mensaje:</strong> saber exactamente qué quieres que la audiencia se lleve.</li>\n<li><strong>Estructura:</strong> ordenar las ideas para que sean fáciles de seguir.</li>\n<li><strong>Voz:</strong> volumen, ritmo, pausas y entonación.</li>\n<li><strong>Cuerpo:</strong> postura, gestos, mirada y uso del espacio.</li>\n<li><strong>Conexión:</strong> adaptar el contenido a quién te escucha y manejar sus preguntas.</li>\n</ol>\n<p>Este curso trabaja cada componente por separado y luego los integra.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb01j${"tone":"consejo","title":"Ejemplo aplicado: la misma información, dos resultados","html":"<p>Una química farmacéutica debe presentar al comité de farmacia la propuesta de cambiar el horario de dispensación de medicamentos de control. <strong>Versión A:</strong> proyecta 18 diapositivas con la normativa, las cifras de errores y el nuevo cronograma. <strong>Versión B:</strong> abre con un caso real (un paciente que esperó dos horas por un opioide para dolor oncológico), plantea el problema en una frase, muestra solo tres cifras y cierra pidiendo una decisión concreta. Ambas tienen la misma información; la versión B obtiene la aprobación porque combina ethos, pathos y logos.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb01j${"tone":"advertencia","title":"Errores comunes","html":"<ul>\n<li>Creer que el objetivo es \"no ponerse nervioso\". El objetivo es comunicar bien, incluso con nervios.</li>\n<li>Preparar las diapositivas antes que el mensaje.</li>\n<li>Imitar a otro orador en lugar de pulir el propio estilo.</li>\n<li>Pensar que hablar más tiempo demuestra más conocimiento.</li>\n</ul>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, $hb01j${"html":"<h2>Ejercicio rápido</h2><p>Piensa en la próxima presentación que debes hacer. Escribe en una línea: ¿qué debe <strong>saber</strong>, <strong>sentir</strong> y <strong>hacer</strong> la audiencia al terminar? Si no puedes responderlo, todavía no tienes un mensaje.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, $hb01j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La oratoria es comunicar con propósito, no hablar bonito.</li>\n<li>Ethos, pathos y logos son los tres pilares de la persuasión y se deben equilibrar.</li>\n<li>Hablar en público es un conjunto de habilidades entrenables: mensaje, estructura, voz, cuerpo y conexión.</li>\n</ol>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 6, $hb01j${"tone":"info","title":"Siguiente paso","html":"<p>En la clase 1.2 harás tu diagnóstico inicial: te grabarás dos minutos y medirás tu punto de partida en cada componente.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Diagnóstico del orador: cómo medir tu punto de partida al hablar en público', 'Unidad 1 · Clase 1.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb01j${"tone":"info","title":"En esta clase","html":"<p>Aprende a hacer tu diagnóstico como orador: grábate, mide muletillas, ritmo y contacto visual, y define tres metas de mejora con una rúbrica práctica.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb01j${"html":"<p>Nadie mejora lo que no mide. Antes de aprender técnicas, necesitas saber dónde estás hoy: si hablas demasiado rápido, si tus ideas se pierden, si miras al piso o si llenas los silencios con \"eh\", \"este\" o \"o sea\". En esta clase vas a hacer un diagnóstico honesto y sencillo, con tu celular y una rúbrica, para definir tres metas concretas de mejora.</p><h2>Por qué grabarte es incómodo (y por qué funciona)</h2><p>La mayoría de las personas se siente incómoda al escuchar su propia voz grabada. Es normal: cuando hablas, escuchas tu voz también a través de los huesos del cráneo, lo que la hace sonar más grave que la que oyen los demás. Superar esa incomodidad es el primer paso, porque la grabación te muestra lo que el público realmente ve y oye, no lo que crees que haces.</p><h2>Paso a paso del diagnóstico</h2><p><strong>1. Elige un tema que domines.</strong> Por ejemplo: \"cómo se almacena correctamente la insulina\" o \"qué hace mi servicio farmacéutico\".</p>\n<p><strong>2. Grábate durante dos minutos</strong> de pie, con el celular a la altura de los ojos y a unos dos metros. No leas. Puedes tener una tarjeta con tres palabras clave.</p>\n<p><strong>3. Mira el video tres veces</strong>, cada vez con un foco distinto:</p>\n<ul>\n<li><strong>Primera vez, sin sonido:</strong> observa postura, gestos, mirada y movimientos repetitivos.</li>\n<li><strong>Segunda vez, solo audio (sin mirar):</strong> escucha volumen, ritmo, pausas y muletillas.</li>\n<li><strong>Tercera vez, completo:</strong> evalúa si el mensaje fue claro y si la estructura se entiende.</li>\n</ul>\n<p><strong>4. Cuenta datos objetivos:</strong></p>\n<ul>\n<li><strong>Muletillas por minuto:</strong> cuenta cada \"eh\", \"este\", \"o sea\", \"¿sí?\", \"digamos\".</li>\n<li><strong>Velocidad:</strong> transcribe el audio (el dictado del celular sirve) y divide el número de palabras entre los minutos. Como referencia práctica, en español entre 130 y 160 palabras por minuto suele sentirse cómodo para una exposición; por encima de 180 la audiencia empieza a perder información.</li>\n<li><strong>Contacto visual:</strong> ¿qué porcentaje del tiempo miras a la cámara?</li>\n</ul>\n<p><strong>5. Califica con la rúbrica</strong> de 1 (inicial) a 4 (sólido) en los cinco componentes: mensaje, estructura, voz, cuerpo y conexión.</p><h2>Cómo interpretar tus resultados</h2><p>No intentes corregir todo al mismo tiempo. Elige <strong>las tres oportunidades con mayor impacto</strong>. Una regla útil: primero corrige lo que afecta la comprensión (mensaje y estructura), luego lo que afecta la credibilidad (voz y mirada) y por último los detalles de estilo.</p>\n<p>Escribe tus metas en formato medible:</p>\n<ul>\n<li>\"Bajar de 8 a 3 muletillas por minuto en cuatro semanas.\"</li>\n<li>\"Abrir todas mis presentaciones con una frase que diga el mensaje central.\"</li>\n<li>\"Mantener contacto visual con la cámara al menos el 70 % del tiempo.\"</li>\n</ul>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb01j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un visitador médico se graba presentando un antihipertensivo. Descubre que habla a 190 palabras por minuto, dice \"¿sí?\" once veces y nunca menciona en qué tipo de paciente conviene el producto. Sus tres metas: reducir la velocidad con pausas después de cada dato, reemplazar el \"¿sí?\" por un silencio y abrir con el perfil de paciente. A las tres semanas, sus visitas son más cortas y los médicos le hacen más preguntas.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb01j${"tone":"advertencia","title":"Errores comunes","html":"<ul>\n<li>Grabarse una sola vez y abandonar porque \"se ve mal\".</li>\n<li>Evaluarse solo por la apariencia y no por la claridad del mensaje.</li>\n<li>Ponerse metas vagas como \"hablar mejor\".</li>\n</ul>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb01j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Grabarse es la forma más rápida de ver lo que ve el público.</li>\n<li>Mide datos objetivos: muletillas, velocidad y contacto visual.</li>\n<li>Prioriza tres metas medibles, empezando por mensaje y estructura.</li>\n</ol>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, $hb01j${"tone":"info","title":"Siguiente paso","html":"<p>Guarda este primer video. Al final del curso lo compararás con tu discurso final para medir tu progreso.</p>"}$hb01j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 2. Estructura del discurso', 1)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo estructurar un discurso: apertura, cuerpo y cierre que el público recuerda', 'Unidad 2 · Clase 2.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb01j${"tone":"info","title":"En esta clase","html":"<p>Cómo estructurar un discurso o presentación paso a paso: aperturas que enganchan, un cuerpo de tres ideas y cierres con llamado a la acción. Con plantilla y ejemplos.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb01j${"html":"<p>La diferencia entre una charla que se olvida y una que se recuerda casi nunca está en la cantidad de información, sino en el orden. Una buena estructura funciona como un mapa: el público sabe dónde está, hacia dónde va y por qué vale la pena seguirte. En esta clase vas a aprender una estructura de tres partes que sirve para una intervención de tres minutos o para una ponencia de cuarenta.</p><h2>La estructura básica: decir, desarrollar, recordar</h2><p>La fórmula más sencilla, usada en entrenamiento militar, docente y corporativo, es:</p>\n<ol>\n<li><strong>Apertura:</strong> capta la atención y anuncia el mensaje.</li>\n<li><strong>Cuerpo:</strong> desarrolla de dos a tres ideas que sostienen el mensaje.</li>\n<li><strong>Cierre:</strong> resume y pide una acción.</li>\n</ol>\n<p>Puede parecer repetitivo, pero el oído no funciona como la lectura: el público no puede \"volver a la página anterior\". La repetición estratégica es lo que permite que la idea se quede.</p><h2>La apertura: los primeros 30 segundos</h2><p>En la apertura tienes dos tareas: ganar atención y dar una razón para escuchar. Evita empezar con \"Buenos días, mi nombre es… y hoy les voy a hablar de…\". Prueba alguna de estas aperturas:</p>\n<ul>\n<li><strong>Pregunta retadora:</strong> \"¿Cuántos de sus pacientes con hipertensión creen que pueden dejar el medicamento cuando se sienten bien?\"</li>\n<li><strong>Dato concreto:</strong> una cifra verificada y relevante para la audiencia.</li>\n<li><strong>Historia breve:</strong> un caso real (anonimizado) en menos de 40 segundos.</li>\n<li><strong>Contraste:</strong> \"Así trabajamos hoy… así podríamos trabajar en tres meses.\"</li>\n</ul>\n<p>Después de captar la atención, <strong>di tu mensaje central en una frase.</strong> Esto se conoce como BLUF (<em>bottom line up front</em>: lo esencial primero).</p><h2>El cuerpo: la regla de tres</h2><p>La memoria de trabajo es limitada, así que conviene agrupar el contenido en <strong>tres ideas principales</strong>. Para ordenarlas, elige un patrón:</p>\n<ul>\n<li><strong>Cronológico:</strong> antes, durante, después.</li>\n<li><strong>Problema–causa–solución:</strong> ideal para propuestas.</li>\n<li><strong>Comparativo:</strong> opción A, opción B, recomendación.</li>\n<li><strong>Por públicos:</strong> qué cambia para el paciente, el médico y la institución.</li>\n</ul>\n<p>Cada idea necesita tres elementos: <strong>afirmación</strong> (la idea en una frase), <strong>evidencia</strong> (dato, norma, estudio) y <strong>ejemplo</strong> (caso o imagen concreta). Usa transiciones explícitas: \"Ya vimos el problema; ahora veamos qué lo causa\".</p><h2>El cierre: no termines con \"eso es todo\"</h2><p>El cierre es lo que el público más recuerda. Tiene tres pasos:</p>\n<ol>\n<li><strong>Señala que vas a cerrar:</strong> \"Para terminar…\". La atención sube cuando el público sabe que falta poco.</li>\n<li><strong>Resume las tres ideas</strong> en una frase cada una.</li>\n<li><strong>Pide una acción concreta:</strong> aprobar, probar, revisar, inscribirse, cambiar un hábito.</li>\n</ol>\n<p>Si hay preguntas, hazlas <strong>antes</strong> del cierre final y reserva 20 segundos para volver a tu mensaje. Así no terminas con una pregunta débil.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb01j${"tone":"consejo","title":"Ejemplo aplicado: capacitación de 5 minutos a auxiliares","html":"<p><strong>Apertura:</strong> \"La semana pasada devolvimos tres neveras de insulinas por ruptura de cadena de frío. Hoy quiero que salgan sabiendo exactamente qué hacer al recibir un termolábil.\"\n<strong>Cuerpo:</strong> (1) qué revisar al recibir; (2) cómo registrar la temperatura; (3) qué hacer si está fuera de rango.\n<strong>Cierre:</strong> \"Revisar, registrar, reportar. A partir de mañana, cada recepción de termolábiles queda en el formato nuevo.\"</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb01j${"tone":"advertencia","title":"Errores comunes","html":"<ul>\n<li>Meter cinco o siete ideas \"porque todas son importantes\".</li>\n<li>Guardar la conclusión para el final, como en una novela de suspenso.</li>\n<li>Terminar con \"bueno, eso era todo, ¿preguntas?\".</li>\n</ul>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb01j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Apertura, cuerpo y cierre: di lo esencial, desarróllalo y recuérdalo.</li>\n<li>Limita el cuerpo a tres ideas, cada una con afirmación, evidencia y ejemplo.</li>\n<li>Cierra con resumen y una acción concreta, incluso después de las preguntas.</li>\n</ol>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, $hb01j${"tone":"info","title":"Siguiente paso","html":"<p>Descarga la plantilla \"Discurso de 3 minutos\" y llénala con tu tema de diagnóstico.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'El mensaje central: cómo resumir cualquier presentación en una sola frase', 'Unidad 2 · Clase 2.2', 1, 'manual', 18, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb01j${"tone":"info","title":"En esta clase","html":"<p>Aprende a construir el mensaje central de tu presentación con el principio de la pirámide y la prueba del ascensor. Técnica de oratoria con ejercicios.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb01j${"html":"<p>Si tu audiencia solo recordara una frase de tu presentación, ¿cuál sería? Si no tienes la respuesta, el público tampoco la tendrá. El mensaje central es la técnica de oratoria más importante y la más olvidada. En esta clase aprenderás a formularlo, a probarlo y a construir todo el discurso alrededor de él.</p><h2>¿Qué es el mensaje central?</h2><p>Es una oración completa, con sujeto y verbo, que expresa la idea que quieres que la audiencia acepte. No es un tema; es una afirmación.</p>\n<ul>\n<li><strong>Tema:</strong> \"La adherencia en hipertensión.\"</li>\n<li><strong>Mensaje central:</strong> \"Una llamada de seguimiento a los 15 días del inicio del tratamiento reduce los abandonos y cuesta menos que una hospitalización.\"</li>\n</ul>\n<p>El tema dice de qué vas a hablar. El mensaje dice qué quieres que piensen o hagan.</p><h2>El principio de la pirámide</h2><p>Barbara Minto, consultora de McKinsey, propuso organizar las ideas como una pirámide: <strong>arriba va la conclusión</strong>, debajo las razones que la sostienen y en la base la evidencia de cada razón. Es lo contrario de cómo solemos pensar (de los datos hacia la conclusión), pero es como el público prefiere escuchar, sobre todo directivos y médicos con poco tiempo.</p>\n<p>Estructura:</p>\n<ol>\n<li><strong>Mensaje central</strong> (la cima).</li>\n<li><strong>Tres razones</strong> que responden a \"¿por qué?\" o \"¿cómo?\".</li>\n<li><strong>Evidencia</strong> para cada razón: datos, normas, casos.</li>\n</ol><h2>Cuatro pruebas para validar tu mensaje</h2><ol>\n<li><strong>Prueba de la frase:</strong> ¿cabe en una oración de máximo 25 palabras?</li>\n<li><strong>Prueba del \"¿y qué?\":</strong> si alguien pregunta \"¿y qué?\", ¿tu frase ya responde por qué importa?</li>\n<li><strong>Prueba del ascensor:</strong> ¿podrías decirlo en 30 segundos a un gerente que sube contigo en un ascensor?</li>\n<li><strong>Prueba de la acción:</strong> ¿queda claro qué debe hacer la audiencia?</li>\n</ol><h2>Cómo llegar al mensaje: el método de reducción</h2><ol>\n<li>Escribe libremente todo lo que sabes del tema (5 minutos).</li>\n<li>Resume eso en tres párrafos.</li>\n<li>Resume los tres párrafos en tres frases.</li>\n<li>Pregúntate qué tienen en común esas tres frases: esa es tu cima.</li>\n</ol>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb01j${"tone":"consejo","title":"Ejemplo aplicado: propuesta a la gerencia","html":"<p>Un regente quiere proponer un programa de domicilios para pacientes crónicos.</p>\n<ul>\n<li><strong>Mensaje central:</strong> \"Un servicio de domicilios para pacientes crónicos nos permitiría retener a los clientes que hoy perdemos frente a las cadenas, con una inversión que se recupera en seis meses.\"</li>\n<li><strong>Razón 1:</strong> los pacientes crónicos compran cada mes (dato de ventas recurrentes).</li>\n<li><strong>Razón 2:</strong> la competencia ya lo ofrece (observación del mercado local).</li>\n<li><strong>Razón 3:</strong> el costo de operación es bajo con un domiciliario de medio tiempo (cálculo simple).</li>\n</ul>\n<p>Con esa pirámide, cada diapositiva tiene un propósito y cualquier pregunta encuentra su lugar.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb01j${"tone":"advertencia","title":"Errores comunes","html":"<ul>\n<li>Confundir el tema con el mensaje.</li>\n<li>Escribir un mensaje tan general que nadie puede estar en desacuerdo (\"la calidad es importante\").</li>\n<li>Cambiar el mensaje a mitad de la presentación.</li>\n</ul>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb01j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>El mensaje central es una afirmación, no un tema.</li>\n<li>La pirámide de Minto pone la conclusión primero y la sostiene con tres razones.</li>\n<li>Valida tu mensaje con las pruebas de la frase, el \"¿y qué?\", el ascensor y la acción.</li>\n</ol>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, $hb01j${"tone":"info","title":"Siguiente paso","html":"<p>Reescribe el mensaje central de tu discurso de diagnóstico y verifica que pase las cuatro pruebas.</p>"}$hb01j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 3. Voz y cuerpo', 2)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Técnicas de voz para hablar en público: respiración, volumen, ritmo, pausas y muletillas', 'Unidad 3 · Clase 3.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb01j${"tone":"info","title":"En esta clase","html":"<p>Ejercicios de oratoria para mejorar tu voz: respiración diafragmática, proyección, ritmo, pausas y cómo eliminar las muletillas al hablar en público.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb01j${"html":"<p>Tu voz es el vehículo de tu mensaje. Puedes tener la mejor estructura, pero si el público no te oye, si hablas en un solo tono o si cada frase termina en \"eh…\", la idea se pierde. La voz se entrena como un músculo. En esta clase vas a practicar una rutina de cinco minutos y cinco técnicas que mejoran de forma inmediata cómo te escuchan.</p><h2>1. Respiración diafragmática: la base de todo</h2><p>Cuando estamos nerviosos respiramos con la parte alta del pecho, rápido y poco profundo. Eso produce una voz débil y entrecortada. La respiración diafragmática usa la parte baja de los pulmones y da más aire y más control.</p>\n<p><strong>Ejercicio:</strong> acuéstate o siéntate derecho, con una mano en el pecho y otra en el abdomen. Inhala por la nariz en 4 tiempos, de modo que se mueva más la mano del abdomen. Exhala por la boca en 6 tiempos con una \"s\" suave. Repite 5 veces. Practícalo a diario durante una semana y luego hazlo de pie.</p><h2>2. Volumen y proyección</h2><p>Proyectar no es gritar. Es dirigir la voz a la persona más lejana del salón. Imagina que tu voz debe \"tocar\" la pared del fondo. Si hay micrófono, mantén la distancia constante (un puño) y habla a volumen normal.</p>\n<p><strong>Ejercicio:</strong> di la misma frase a tres distancias imaginarias: a una persona frente a ti, a alguien en la mitad del salón y a alguien al fondo. Siente cómo cambia el apoyo del abdomen, no la garganta.</p><h2>3. Ritmo y variación</h2><p>Una voz monótona adormece. Varía tres cosas: <strong>velocidad</strong> (más lento en los datos importantes, más ágil en el contexto), <strong>tono</strong> (sube y baja de forma natural) e <strong>intensidad</strong> (enfatiza la palabra clave de cada frase).</p>\n<p><strong>Ejercicio:</strong> lee en voz alta \"Este medicamento no se debe suspender sin consultar\" poniendo el énfasis en una palabra distinta cada vez. Notarás que el significado cambia.</p><h2>4. Pausas: el recurso más subestimado</h2><p>La pausa le da al público tiempo de procesar y a ti tiempo de pensar. Úsala:</p>\n<ul>\n<li>Antes de un dato importante (crea expectativa).</li>\n<li>Después de una pregunta (invita a pensar).</li>\n<li>Al cambiar de idea (marca la transición).</li>\n</ul>\n<p>Una pausa de dos segundos te parecerá eterna, pero para el público es natural y transmite seguridad.</p><h2>5. Cómo eliminar las muletillas</h2><p>Las muletillas (\"eh\", \"este\", \"o sea\", \"¿sí?\", \"digamos\") aparecen cuando el cerebro busca la siguiente palabra y no tolera el silencio. Para reducirlas:</p>\n<ol>\n<li><strong>Toma conciencia:</strong> cuéntalas en tus grabaciones.</li>\n<li><strong>Reemplaza por silencio:</strong> cuando sientas que viene la muletilla, cierra la boca y respira.</li>\n<li><strong>Prepara las transiciones:</strong> muchas muletillas aparecen al pasar de una idea a otra. Si tienes la frase de transición lista, desaparecen.</li>\n<li><strong>Pide ayuda:</strong> que un colega levante la mano cada vez que digas una muletilla durante un ensayo.</li>\n</ol><h2>Rutina vocal de 5 minutos antes de presentar</h2><ol>\n<li>Tres respiraciones diafragmáticas (1 min).</li>\n<li>Bostezos y estiramiento de mandíbula (30 s).</li>\n<li>Vibración de labios tipo \"brrr\" subiendo y bajando el tono (1 min).</li>\n<li>Trabalenguas a velocidad lenta y luego normal (1 min).</li>\n<li>Decir la primera frase de tu presentación tres veces con énfasis distinto (1 min).</li>\n<li>Un vaso de agua al clima (30 s).</li>\n</ol>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb01j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una QF que dicta talleres a pacientes con diabetes notaba que en la última fila se distraían. Aplicó proyección y pausas antes de cada recomendación (\"Y lo más importante… [pausa] es revisar los pies todos los días\"). En la evaluación del taller, la frase más recordada fue justamente la que tenía pausa.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb01j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La respiración diafragmática da apoyo y control a la voz.</li>\n<li>Varía velocidad, tono e intensidad; la monotonía apaga la atención.</li>\n<li>Las pausas transmiten seguridad y reemplazan a las muletillas.</li>\n</ol>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb01j${"tone":"info","title":"Siguiente paso","html":"<p>Haz la rutina vocal durante cinco días y grábate leyendo el mismo párrafo el día 1 y el día 5.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Lenguaje corporal al hablar en público: postura, gestos, mirada y uso del escenario', 'Unidad 3 · Clase 3.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb01j${"tone":"info","title":"En esta clase","html":"<p>Cómo usar el lenguaje corporal al hablar en público: postura de base, gestos con intención, contacto visual y movimiento en el escenario. Guía práctica.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb01j${"html":"<p>Antes de que digas la primera palabra, el público ya se formó una impresión por cómo entraste, cómo te paraste y hacia dónde miraste. El cuerpo puede reforzar tu mensaje o contradecirlo. En esta clase vas a construir una postura de base, aprender a usar los gestos con intención y manejar la mirada y el espacio para conectar con la audiencia.</p><h2>La postura de base: tu \"punto cero\"</h2><p>Una postura de base estable transmite seguridad y te da un lugar al cual volver:</p>\n<ul>\n<li>Pies separados al ancho de los hombros, peso repartido en ambos.</li>\n<li>Rodillas sin bloquear.</li>\n<li>Hombros relajados, pecho abierto.</li>\n<li>Brazos sueltos a los lados o manos juntas a la altura del ombligo, listas para gesticular.</li>\n</ul>\n<p>Evita balancearte, cruzar los pies o apoyarte en el atril. Estos movimientos no son graves en sí mismos, pero distraen y comunican inseguridad.</p><h2>Gestos con intención</h2><p>Los gestos ayudan a que el público entienda y recuerde. Hay tres tipos útiles:</p>\n<ul>\n<li><strong>Descriptivos:</strong> muestran tamaño, forma, cantidad (\"tres pasos\" con tres dedos).</li>\n<li><strong>Enfáticos:</strong> marcan lo importante (palma hacia abajo para algo firme).</li>\n<li><strong>Abiertos:</strong> palmas hacia arriba para invitar o incluir.</li>\n</ul>\n<p>Mantén las manos en la <strong>zona entre la cintura y los hombros</strong>. Por debajo se pierden; por encima pueden verse exagerados. Evita los gestos de \"cierre\" sostenidos: brazos cruzados, manos en los bolsillos o jugar con el bolígrafo o el clicker.</p><h2>La mirada: conectar persona por persona</h2><p>En lugar de \"barrer\" el salón con la vista, usa la técnica <strong>una idea, una persona</strong>: dirige una frase completa a una persona, luego cambia a otra en otra zona del salón. Así cada asistente siente que le hablas directamente. En salones grandes, divide el público en zonas (izquierda, centro, derecha, fondo) y recórrelas.</p>\n<p>No mires la pantalla mientras hablas. Si necesitas ver la diapositiva, usa el monitor de referencia o mira, toma la idea y vuelve a mirar al público antes de hablar.</p><h2>Movimiento en el escenario</h2><p>Moverse está bien si tiene propósito. Una técnica útil es <strong>anclar ideas a lugares</strong>: presentas la idea 1 en la izquierda, la 2 en el centro y la 3 en la derecha. Al resumir, vuelves a cada punto y el público asocia el lugar con la idea. Muévete en las transiciones y quédate quieto cuando digas algo importante.</p><h2>Una nota sobre las \"poses de poder\"</h2><p>Probablemente escuchaste que adoptar una \"pose de poder\" durante dos minutos cambia tus hormonas. Los estudios posteriores no lograron replicar los efectos hormonales, aunque algunas personas reportan sentirse más seguras. La recomendación práctica es sencilla: usa una postura abierta y cómoda porque comunica seguridad al público, no porque sea un truco químico.</p><h2>Coherencia: cuando el cuerpo contradice al mensaje</h2><p>Si dices \"estoy muy contento de estar aquí\" con los brazos cruzados y la mirada en el piso, el público creerá al cuerpo. Revisa en tus ensayos que la emoción del cuerpo acompañe a la de las palabras.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb01j${"tone":"consejo","title":"Ejemplo aplicado: la visita médica","html":"<p>En un consultorio no hay escenario, pero el cuerpo habla igual. Un visitador que se sienta en el borde de la silla, con la tableta como barrera entre él y el médico, transmite prisa. Si se sienta derecho, deja la tableta a un lado, muestra el dato en el momento justo y mantiene la mirada mientras el médico habla, transmite seguridad y escucha.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb01j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Una postura de base estable te da seguridad y un punto de regreso.</li>\n<li>Gesticula con intención en la zona entre la cintura y los hombros.</li>\n<li>Mira persona por persona y muévete con propósito.</li>\n</ol>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb01j${"tone":"info","title":"Siguiente paso","html":"<p>Repite tu video de diagnóstico aplicando la postura de base y la técnica \"una idea, una persona\". Compara los dos videos sin sonido.</p>"}$hb01j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 4. Práctica y situaciones reales', 3)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo ensayar un discurso: práctica deliberada, retroalimentación y memoria de apoyo', 'Unidad 4 · Clase 4.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb01j${"tone":"info","title":"En esta clase","html":"<p>Cómo ensayar un discurso de forma efectiva: práctica deliberada, ensayos por bloques, tarjetas de apoyo y retroalimentación. Guía de oratoria para principiantes.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb01j${"html":"<p>Muchas personas \"ensayan\" leyendo las diapositivas en silencio la noche anterior. Eso no es ensayar: es repasar. Un ensayo de verdad se hace en voz alta, de pie, con tiempo medido y con el objetivo de mejorar algo específico. En esta clase aprenderás un método de ensayo de cinco días basado en la práctica deliberada, que te permite presentar con naturalidad sin memorizar palabra por palabra.</p><h2>Memorizar vs. internalizar</h2><p>Memorizar un texto completo es riesgoso: si olvidas una palabra, pierdes el hilo, y la presentación suena recitada. Lo recomendable es <strong>internalizar la estructura</strong>: saber de memoria el orden de las ideas, la primera y la última frase, y las transiciones. Lo demás lo dices con tus palabras, de forma un poco distinta cada vez.</p>\n<p>Excepciones que sí conviene memorizar:</p>\n<ul>\n<li>Los primeros 30 segundos (ahí están los nervios más altos).</li>\n<li>El cierre y la llamada a la acción.</li>\n<li>Cifras, nombres y citas textuales.</li>\n</ul><h2>La práctica deliberada</h2><p>El psicólogo Anders Ericsson describió la práctica deliberada como un entrenamiento enfocado en una habilidad concreta, con retroalimentación inmediata y fuera de la zona de comodidad. Aplicado a la oratoria:</p>\n<ul>\n<li>Cada ensayo tiene <strong>un objetivo</strong> (por ejemplo, \"hacer pausas antes de los datos\").</li>\n<li>Se mide el resultado (grabación, cronómetro, colega).</li>\n<li>Se repite el bloque que falló, no toda la charla.</li>\n</ul><h2>Plan de ensayo en 5 días</h2><p><strong>Día 1 — Ensayo de estructura:</strong> di la charla en voz alta mirando solo la pirámide del mensaje. Cronometra. Ajusta si te pasas del tiempo.\n<strong>Día 2 — Ensayo por bloques:</strong> practica la apertura cinco veces, luego cada idea y luego el cierre. Trabaja las transiciones.\n<strong>Día 3 — Ensayo grabado completo:</strong> de pie, con diapositivas. Revisa el video con el checklist.\n<strong>Día 4 — Ensayo con público:</strong> presenta ante una o dos personas y pide retroalimentación con el formato \"qué funcionó / qué mejorar / una sugerencia\".\n<strong>Día 5 — Ensayo general en condiciones reales:</strong> misma ropa, mismo equipo, idealmente en el mismo lugar. Luego descansa.</p><h2>Tarjetas de apoyo</h2><p>Si necesitas apoyo, usa tarjetas pequeñas con <strong>palabras clave</strong>, no frases completas. Una tarjeta por idea, numeradas. En presentaciones virtuales, puedes pegar notas al lado de la cámara, a la altura de los ojos.</p><h2>Cómo pedir y recibir retroalimentación</h2><p>Pide retroalimentación específica: \"¿Se entendió la recomendación final?\" es mejor que \"¿cómo me fue?\". Cuando la recibas, escucha sin justificarte, toma nota y agradece. Luego decide qué aplicar. En Toastmasters, la evaluación entre pares sigue una lógica parecida: primero lo que funcionó, luego una o dos oportunidades concretas y cierre con ánimo.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb01j${"tone":"consejo","title":"Ejemplo aplicado: ponencia en un congreso","html":"<p>Una QF debe presentar un póster oral de 7 minutos sobre farmacovigilancia activa en un congreso. Con el plan de 5 días descubre en el día 1 que su charla dura 11 minutos. Recorta los antecedentes, deja tres resultados y ensaya por bloques. El día 4, su colega le dice que la conclusión no se entiende; la reescribe en una frase. El día del congreso termina en 6 minutos 40 segundos y recibe tres preguntas.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb01j${"tone":"advertencia","title":"Errores comunes","html":"<ul>\n<li>Ensayar solo mentalmente o sentado.</li>\n<li>Ensayar siempre desde el principio y nunca practicar el cierre.</li>\n<li>Cambiar todo el contenido la noche anterior.</li>\n</ul>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb01j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Internaliza la estructura; memoriza solo apertura, cierre y datos.</li>\n<li>Cada ensayo tiene un objetivo y una medición.</li>\n<li>Ensaya en voz alta, de pie, con público y en condiciones reales.</li>\n</ol>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, $hb01j${"tone":"info","title":"Siguiente paso","html":"<p>Aplica el plan de 5 días a tu discurso final del curso.</p>"}$hb01j$::jsonb);
