  VALUES (v_curso, v_unidad, 'Cómo improvisar y responder preguntas del público sin quedarte en blanco', 'Unidad 4 · Clase 4.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb01j${"tone":"info","title":"En esta clase","html":"<p>Aprende a improvisar y a responder preguntas difíciles en público con el método PREP, pausas estratégicas y frases puente. Ejemplos para el sector salud.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb01j${"html":"<p>Puedes preparar tu presentación al detalle, pero la ronda de preguntas siempre trae sorpresas: un médico que cuestiona tu dato, un directivo que pide una cifra que no tienes o un asistente que hace un comentario en lugar de una pregunta. La improvisación también se entrena. En esta clase aprenderás el método PREP, una secuencia para manejar cualquier pregunta y frases puente para cuando no sabes la respuesta.</p><h2>El método PREP para respuestas improvisadas</h2><p>PREP es una estructura de cuatro pasos que ordena tu respuesta en segundos:</p>\n<ol>\n<li><strong>P — Punto:</strong> responde directamente en una frase.</li>\n<li><strong>R — Razón:</strong> explica por qué.</li>\n<li><strong>E — Ejemplo:</strong> da un caso, dato o evidencia.</li>\n<li><strong>P — Punto:</strong> repite la respuesta para cerrar.</li>\n</ol>\n<p><strong>Ejemplo:</strong> \"¿Por qué recomiendan tomar la levotiroxina en ayunas?\"</p>\n<ul>\n<li><strong>P:</strong> \"Porque así se absorbe mejor y la dosis es más estable.\"</li>\n<li><strong>R:</strong> \"Los alimentos y algunos suplementos, como el calcio y el hierro, disminuyen su absorción.\"</li>\n<li><strong>E:</strong> \"Por eso pedimos tomarla con agua, idealmente 30 a 60 minutos antes del desayuno, según indique el inserto.\"</li>\n<li><strong>P:</strong> \"En resumen: en ayunas y siempre a la misma hora.\"</li>\n</ul><h2>Los cinco pasos para manejar una pregunta</h2><ol>\n<li><strong>Escucha completa:</strong> no interrumpas ni empieces a responder mentalmente.</li>\n<li><strong>Agradece o valida:</strong> \"Buena pregunta\" puede sonar automático; prueba \"Gracias, es un punto clave\".</li>\n<li><strong>Repite o reformula:</strong> así todo el salón la oye y tú ganas segundos.</li>\n<li><strong>Responde con PREP</strong>, mirando a todo el público, no solo a quien preguntó.</li>\n<li><strong>Verifica:</strong> \"¿Eso responde su inquietud?\"</li>\n</ol><h2>Cuando no sabes la respuesta</h2><p>La credibilidad se pierde más por inventar que por reconocer un límite. Usa frases honestas:</p>\n<ul>\n<li>\"No tengo ese dato exacto aquí. Lo verifico en la ficha técnica y se lo envío hoy por correo.\"</li>\n<li>\"Es una pregunta que va más allá del alcance de este estudio; lo que sí sabemos es…\"</li>\n<li>\"¿Alguien del grupo tiene experiencia con eso?\"</li>\n</ul>\n<p>En el sector salud esto es especialmente importante: nunca improvises una dosis, una interacción o una indicación. Ofrece verificar en una fuente confiable.</p><h2>Preguntas difíciles o agresivas</h2><ul>\n<li><strong>Separa la emoción del contenido:</strong> \"Entiendo que es frustrante esperar por un medicamento pendiente. Lo que estamos haciendo es…\".</li>\n<li><strong>No te defiendas personalmente;</strong> responde al problema.</li>\n<li><strong>Si es un comentario largo,</strong> busca la pregunta: \"Si entiendo bien, su pregunta es…\".</li>\n<li><strong>Si alguien monopoliza,</strong> ofrece continuar después: \"Me encantaría profundizar; ¿lo hablamos al final para dar espacio a otras preguntas?\".</li>\n</ul><h2>Improvisar un discurso corto</h2><p>Si te piden \"unas palabras\" sin aviso, usa la estructura <strong>pasado–presente–futuro</strong> (de dónde venimos, dónde estamos, hacia dónde vamos) o <strong>PREP</strong>. Toma tres segundos para elegir tu punto antes de abrir la boca.</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb01j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>En un comité, el director médico pregunta a la QF: \"¿Y usted cómo sabe que el cambio de proveedor no va a generar desabastecimiento?\". Ella respira, reformula (\"La preocupación es la continuidad del suministro\") y responde con PREP: \"Lo mitigamos con un stock de seguridad de 30 días (P), porque el nuevo proveedor tiene un tiempo de entrega mayor (R); en la prueba piloto de dos meses no hubo quiebres (E). Por eso proponemos el cambio con ese colchón (P).\"</p>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb01j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>PREP (punto, razón, ejemplo, punto) estructura cualquier respuesta.</li>\n<li>Reformular la pregunta te da tiempo y aclara para todos.</li>\n<li>Si no sabes, dilo y ofrece verificar; en salud nunca improvises datos clínicos.</li>\n</ol>"}$hb01j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb01j${"tone":"info","title":"Siguiente paso","html":"<p>Practica con el banco de preguntas difíciles: pide a alguien que te haga tres al azar y responde con PREP en menos de 45 segundos cada una.</p>"}$hb01j$::jsonb);
END
$hb01$;

-- ─── Curso para perder el miedo a hablar en público (8 clases) ───
DO $hb02$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso para perder el miedo a hablar en público' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, area, level, tags,
     objective, learning_outcomes, audience, duration_minutes, author_name, status, modality, cover_url, publico)
  VALUES ('edvanta', 'Curso para perder el miedo a hablar en público', $hb02t$Curso práctico para entender por qué aparece el miedo a hablar en público y reducirlo con herramientas validadas: respiración, reinterpretación de la activación, exposición gradual y preparación. Incluye un plan personal de 30 días.$hb02t$,
          $hb02t$<p>Curso práctico para entender por qué aparece el miedo a hablar en público y reducirlo con herramientas validadas: respiración, reinterpretación de la activación, exposición gradual y preparación. Incluye un plan personal de 30 días.</p><h2>Objetivo</h2><p>Que el participante identifique sus detonantes del miedo escénico, aplique técnicas fisiológicas y cognitivas para regular la ansiedad y complete una escalera de exposición gradual que termine en una presentación real.</p><h2>Para quién es</h2><p>Profesionales y estudiantes del sector farmacéutico y de la salud que sienten nervios intensos antes o durante una exposición, una reunión o una entrevista.</p><h2>Cómo está organizado</h2><p>Cuatro unidades con dos clases en texto cada una. Cada clase trae un ejemplo aplicado al sector farmacéutico y de la salud, puntos clave y el siguiente paso.</p><h2>Referentes</h2><p>Investigación de Thomas Gilovich y Kenneth Savitsky (efecto foco e ilusión de transparencia); Alison Wood Brooks (reinterpretar la ansiedad como entusiasmo, Harvard, 2014); Balban y col., Cell Reports Medicine 2023 (respiración y estado de ánimo); terapia cognitivo-conductual (exposición gradual).</p>$hb02t$,
          'Oratoria y presentaciones', 'Habilidades Blandas', 'basico', ARRAY['Miedo escénico', 'Hablar en público', 'Ansiedad', 'Glosofobia', 'Habilidades blandas']::text[],
          $hb02t$Que el participante identifique sus detonantes del miedo escénico, aplique técnicas fisiológicas y cognitivas para regular la ansiedad y complete una escalera de exposición gradual que termine en una presentación real.$hb02t$,
          ARRAY['Entender qué es el miedo a hablar en público, por qué ocurre y qué pensamientos lo alimentan.', 'Aplicar técnicas de respiración y de reinterpretación para regular los nervios.', 'Avanzar con una escalera de exposición gradual y una rutina previa a cada presentación.', 'Rescatarte cuando te quedas en blanco y seguir un plan de 30 días, sabiendo cuándo buscar ayuda profesional.']::text[],
          $hb02t$Profesionales y estudiantes del sector farmacéutico y de la salud que sienten nervios intensos antes o durante una exposición, una reunión o una entrevista.$hb02t$,
          151, 'Edvanta', 'borrador', 'asincronica', '/img/cursos/miedo-a-hablar-en-publico.webp', 'profesionales')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Entender el miedo', 0)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Miedo a hablar en público (glosofobia): qué es, por qué ocurre y qué le pasa a tu cuerpo', 'Unidad 1 · Clase 1.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb02j${"tone":"info","title":"En esta clase","html":"<p>Qué es el miedo a hablar en público o glosofobia, por qué aparece, qué le pasa a tu cuerpo (corazón, voz, manos) y por qué es tan común. Explicación clara.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb02j${"html":"<p>El corazón se acelera, las manos sudan, la boca se seca y, justo cuando empiezas a hablar, la mente se queda en blanco. Si te ha pasado, no estás solo: el miedo a hablar en público es uno de los temores más frecuentes en adultos, incluso entre profesionales con mucha experiencia técnica. En esta clase vas a entender qué es, por qué ocurre y por qué tu cuerpo reacciona así. Entenderlo es el primer paso para manejarlo.</p><h2>¿Qué es la glosofobia?</h2><p><strong>Glosofobia</strong> es el nombre técnico del miedo intenso a hablar en público. Puede ir desde unos nervios normales antes de una presentación importante hasta una ansiedad que lleva a evitar cualquier situación en la que haya que hablar frente a otros. Cuando el miedo es muy intenso, persistente y afecta la vida laboral o social, puede hacer parte de un <strong>trastorno de ansiedad social</strong>, que requiere evaluación por un profesional de la salud mental.</p>\n<p>En este curso trabajamos el rango más común: nervios que incomodan, pero que se pueden manejar con entrenamiento.</p><h2>Por qué ocurre: tu cerebro cree que estás en peligro</h2><p>Para el cerebro, ser observado y evaluado por un grupo es una situación de riesgo social: podrías ser juzgado o rechazado. Ante esa amenaza percibida se activa la <strong>respuesta de estrés</strong>, la misma que nos preparaba para huir o pelear. El sistema nervioso simpático libera adrenalina y cortisol, y el cuerpo se prepara para la acción.</p><h2>Qué le pasa a tu cuerpo y por qué</h2><ul>\n<li><strong>Corazón acelerado:</strong> para llevar más sangre a los músculos.</li>\n<li><strong>Respiración rápida y superficial:</strong> para obtener oxígeno rápido; por eso la voz se siente sin aire.</li>\n<li><strong>Boca seca:</strong> la digestión y la salivación pasan a segundo plano.</li>\n<li><strong>Manos frías o sudorosas, temblor:</strong> la sangre se redirige y los músculos se tensan.</li>\n<li><strong>Mente en blanco:</strong> la activación intensa dificulta el acceso a la memoria de trabajo.</li>\n<li><strong>Enrojecimiento:</strong> cambios en el flujo de sangre en la piel.</li>\n</ul>\n<p>Todas estas reacciones son <strong>normales, temporales y no peligrosas</strong>. El problema no es la reacción en sí, sino la interpretación: \"si me tiembla la voz, todos van a pensar que no sé\".</p><h2>El ciclo del miedo</h2><p>El miedo escénico se mantiene por un ciclo:</p>\n<ol>\n<li><strong>Anticipación:</strong> días antes imaginas lo peor.</li>\n<li><strong>Síntomas físicos</strong> durante la presentación.</li>\n<li><strong>Interpretación catastrófica:</strong> \"se dieron cuenta, fue un desastre\".</li>\n<li><strong>Evitación:</strong> la próxima vez buscas excusas para no presentar.</li>\n<li>La evitación da alivio inmediato, pero <strong>refuerza el miedo</strong> a largo plazo.</li>\n</ol>\n<p>Romper el ciclo implica intervenir en varios puntos: el cuerpo (respiración), los pensamientos (reinterpretación) y la conducta (exposición gradual). Eso es lo que haremos en este curso.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb02j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un regente de farmacia con diez años de experiencia evita las capacitaciones de su equipo y siempre le pide a otra persona que las dicte. Sabe el contenido mejor que nadie, pero desde un mal momento en la universidad siente que \"no sirve para hablar\". Al entender que su reacción es una respuesta normal de estrés y no una falta de capacidad, acepta empezar con una charla de cinco minutos a dos auxiliares.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb02j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La glosofobia es muy frecuente y tiene distintos niveles de intensidad.</li>\n<li>Los síntomas son la respuesta normal de estrés: incómodos pero no peligrosos.</li>\n<li>La evitación alivia a corto plazo y mantiene el miedo a largo plazo.</li>\n</ol>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, $hb02j${"html":"<h2>Cuándo buscar ayuda profesional</h2><p>Si el miedo te impide trabajar o estudiar, aparece en muchas situaciones sociales o se acompaña de ataques de pánico, consulta con un psicólogo o médico. La terapia cognitivo-conductual tiene buena evidencia para la ansiedad social.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, $hb02j${"tone":"info","title":"Siguiente paso","html":"<p>Responde el test de autoevaluación y anota tu nivel de miedo (0 a 10) para medir tu progreso.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Los pensamientos que alimentan los nervios: efecto foco, ilusión de transparencia y perfeccionismo', 'Unidad 1 · Clase 1.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb02j${"tone":"info","title":"En esta clase","html":"<p>Descubre los pensamientos que alimentan los nervios al hablar en público: efecto foco, ilusión de transparencia y perfeccionismo, y cómo cuestionarlos.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb02j${"html":"<p>¿Alguna vez sentiste que todo el salón notaba tus nervios, pero después alguien te dijo \"te vi muy tranquilo\"? No es casualidad. Nuestro cerebro sobreestima cuánto nos observan y cuánto se nota lo que sentimos. En esta clase vas a conocer tres trampas mentales que inflan el miedo a hablar en público y una técnica sencilla para cuestionarlas.</p><h2>Trampa 1: el efecto foco</h2><p>Los psicólogos Thomas Gilovich y Kenneth Savitsky describieron el <strong>efecto foco</strong> (<em>spotlight effect</em>): tendemos a creer que los demás notan nuestra apariencia y nuestros errores mucho más de lo que realmente lo hacen. En uno de sus experimentos, estudiantes que vestían una camiseta llamativa estimaron que cerca de la mitad de sus compañeros la notaría; en la realidad, la recordó una proporción bastante menor.</p>\n<p><strong>Aplicado a hablar en público:</strong> ese pequeño tropiezo con una palabra que te parece enorme, la mayoría del público no lo registra. Están pensando en su propio día, en el tema o en su celular.</p><h2>Trampa 2: la ilusión de transparencia</h2><p>Los mismos investigadores estudiaron la <strong>ilusión de transparencia</strong>: creemos que nuestros estados internos (nervios, ansiedad) son mucho más visibles de lo que son. En un estudio con personas que daban un discurso, quienes se sentían nerviosos creían que se les notaba mucho; los observadores los calificaron como bastante menos nerviosos. Un hallazgo interesante: <strong>solo explicarles a los oradores que existe esta ilusión</strong> mejoró su desempeño y su tranquilidad.</p>\n<p><strong>Aplicado:</strong> tu corazón late fuerte por dentro, pero por fuera el público ve a una persona que habla, un poco seria quizás. No ve tu pulso.</p><h2>Trampa 3: el perfeccionismo</h2><p>Creer que una buena presentación debe ser perfecta aumenta la presión y convierte cada pequeño error en un fracaso. El público no espera perfección: espera <strong>utilidad y autenticidad</strong>. De hecho, un error bien manejado (\"perdón, me adelanté; vuelvo a la cifra anterior\") humaniza al orador.</p><h2>Otras distorsiones frecuentes</h2><ul>\n<li><strong>Lectura de mente:</strong> \"Ese médico bostezó, seguro le parezco aburrido.\"</li>\n<li><strong>Catastrofización:</strong> \"Si me quedo en blanco, pierdo el trabajo.\"</li>\n<li><strong>Generalización:</strong> \"Siempre me va mal al hablar.\"</li>\n<li><strong>Filtro negativo:</strong> recordar el único comentario crítico e ignorar los positivos.</li>\n</ul><h2>Técnica: el registro de pensamientos</h2><p>Esta técnica, propia de la terapia cognitivo-conductual, te ayuda a poner a prueba tus pensamientos en lugar de creerlos automáticamente:</p>\n<ol>\n<li><strong>Situación:</strong> \"Presentación al comité el jueves.\"</li>\n<li><strong>Pensamiento automático:</strong> \"Se van a dar cuenta de que estoy nervioso y van a pensar que no domino el tema.\" (Creencia: 80 %)</li>\n<li><strong>Evidencia a favor:</strong> \"La última vez me temblaron las manos.\"</li>\n<li><strong>Evidencia en contra:</strong> \"Nadie lo comentó; aprobaron mi propuesta; la ilusión de transparencia dice que se nota menos de lo que siento.\"</li>\n<li><strong>Pensamiento alternativo:</strong> \"Puede que se note un poco, pero lo que evalúan es la propuesta, y la conozco bien.\" (Creencia: 60 %)</li>\n<li><strong>Nueva creencia en el pensamiento original:</strong> 35 %.</li>\n</ol>\n<p>No buscas pensar en positivo de forma ingenua, sino <strong>pensar de forma más realista</strong>.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb02j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una auxiliar de servicio farmacéutico debe explicar a su equipo el nuevo procedimiento de devoluciones. Su pensamiento: \"Si me equivoco, mis compañeros se van a burlar.\" Al hacer el registro reconoce que sus compañeros también están aprendiendo el procedimiento y que lo que necesitan es claridad, no perfección.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb02j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>El efecto foco y la ilusión de transparencia hacen que sobreestimes cuánto se notan tus nervios.</li>\n<li>El público busca utilidad y autenticidad, no perfección.</li>\n<li>El registro de pensamientos te ayuda a reemplazar ideas catastróficas por ideas realistas.</li>\n</ol>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb02j${"tone":"info","title":"Siguiente paso","html":"<p>Haz un registro de pensamientos sobre tu próxima situación de hablar en público.</p>"}$hb02j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 2. Herramientas para regular el cuerpo y la mente', 1)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Técnicas de respiración para controlar los nervios antes de una exposición', 'Unidad 2 · Clase 2.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb02j${"tone":"info","title":"En esta clase","html":"<p>Técnicas de respiración para controlar los nervios antes de una exposición o entrevista: exhalación prolongada, suspiro fisiológico y respiración en caja.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb02j${"html":"<p>Cuando los nervios aparecen, el consejo más común es \"respira\". Pero ¿cómo? No todas las formas de respirar calman igual. La clave está en la <strong>exhalación</strong>: alargarla activa el sistema nervioso parasimpático, el que frena la respuesta de estrés. En esta clase aprenderás tres técnicas que puedes usar en el pasillo, en el baño o incluso frente al público, sin que nadie lo note.</p><h2>Por qué la respiración calma</h2><p>La respiración es una de las pocas funciones del sistema nervioso autónomo que podemos controlar a voluntad. Al inhalar, la frecuencia cardíaca tiende a subir un poco; al exhalar, tiende a bajar. Por eso, cuando la exhalación es más larga que la inhalación, el cuerpo recibe una señal de seguridad. Además, respirar lento evita la hiperventilación, que produce mareo, hormigueo y sensación de falta de aire.</p><h2>Técnica 1: el suspiro fisiológico</h2><p>Es un patrón que el cuerpo hace de forma espontánea (por ejemplo, después de llorar). Un estudio de Balban y colaboradores publicado en <em>Cell Reports Medicine</em> en 2023 comparó varias prácticas de respiración de cinco minutos diarios durante un mes y encontró que el suspiro cíclico se asoció con mayor mejoría del estado de ánimo y menor frecuencia respiratoria en reposo que la meditación de atención plena.</p>\n<p><strong>Cómo hacerlo:</strong></p>\n<ol>\n<li>Inhala por la nariz hasta llenar los pulmones.</li>\n<li>Sin soltar el aire, haz una segunda inhalación corta para \"completar\".</li>\n<li>Exhala lentamente por la boca, lo más largo que puedas.</li>\n<li>Repite de 2 a 3 veces para un efecto rápido, o durante 5 minutos como práctica diaria.</li>\n</ol><h2>Técnica 2: respiración 4-6</h2><p>Ideal para los minutos previos a presentar.</p>\n<ol>\n<li>Inhala por la nariz contando hasta 4.</li>\n<li>Exhala por la boca, como si soplaras a través de un pitillo, contando hasta 6.</li>\n<li>Repite durante 2 minutos.</li>\n</ol><h2>Técnica 3: respiración en caja</h2><p>Usada en entornos de alta presión porque, además de calmar, ocupa la mente con el conteo.</p>\n<ol>\n<li>Inhala en 4 tiempos.</li>\n<li>Sostén en 4.</li>\n<li>Exhala en 4.</li>\n<li>Sostén en 4.</li>\n<li>Repite 4 ciclos.</li>\n</ol>\n<p>Si sostener el aire te genera incomodidad, elimina las pausas y usa la técnica 4-6.</p><h2>Respirar durante la presentación</h2><p>Frente al público no puedes hacer ejercicios visibles, pero sí puedes:</p>\n<ul>\n<li><strong>Exhalar antes de empezar:</strong> al llegar al frente, suelta el aire lentamente mientras miras al público. Luego habla.</li>\n<li><strong>Usar las pausas para respirar:</strong> al final de cada idea, una inhalación tranquila por la nariz.</li>\n<li><strong>No hablar con los pulmones vacíos:</strong> si sientes que te falta el aire, termina la frase, haz una pausa, inhala y continúa.</li>\n</ul><h2>Rutina de 3 momentos</h2><ul>\n<li><strong>La noche anterior:</strong> 5 minutos de suspiro cíclico.</li>\n<li><strong>10 minutos antes:</strong> respiración 4-6 durante 2 minutos.</li>\n<li><strong>Al llegar al frente:</strong> una exhalación larga, mira a una persona amable y empieza.</li>\n</ul><h2>Advertencia de seguridad</h2><p>Si tienes una condición respiratoria o cardiovascular, o si sientes mareo intenso al practicar, detente y consulta a tu médico. Las técnicas de respiración no reemplazan el tratamiento de un trastorno de ansiedad.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb02j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una estudiante de Química Farmacéutica que se ahogaba al sustentar su trabajo de grado practicó el suspiro cíclico durante dos semanas. El día de la sustentación usó la respiración 4-6 en el pasillo y una exhalación larga al llegar al frente. Notó el corazón acelerado los primeros minutos, pero pudo hablar sin quedarse sin aire.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb02j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Alargar la exhalación es la clave para calmar el cuerpo.</li>\n<li>El suspiro fisiológico, la respiración 4-6 y la respiración en caja son técnicas sencillas y discretas.</li>\n<li>Durante la presentación, usa las pausas para respirar.</li>\n</ol>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb02j${"tone":"info","title":"Siguiente paso","html":"<p>Practica el suspiro cíclico 5 minutos al día durante una semana y registra tu nivel de calma de 0 a 10 antes y después.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Reinterpretar los nervios: cómo convertir la ansiedad en energía para presentar', 'Unidad 2 · Clase 2.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb02j${"tone":"info","title":"En esta clase","html":"<p>Aprende a reinterpretar la ansiedad al hablar en público como entusiasmo, con base en la investigación de Alison Wood Brooks. Técnica práctica y ejemplos.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb02j${"html":"<p>\"Cálmate\" es probablemente el consejo más repetido antes de una presentación… y uno de los menos efectivos. Pasar de un estado de alta activación a la calma total es difícil. Hay una alternativa respaldada por investigación: en lugar de intentar apagar la activación, <strong>cambiarle el nombre</strong>. En esta clase aprenderás a reinterpretar la ansiedad como energía y a usar autoinstrucciones que mejoran tu desempeño.</p><h2>La investigación: \"estoy emocionado\"</h2><p>Alison Wood Brooks, profesora de Harvard Business School, publicó en 2014 una serie de experimentos en el <em>Journal of Experimental Psychology: General</em>. Pidió a participantes que, antes de tareas estresantes como cantar en público, dar un discurso o resolver problemas matemáticos, dijeran en voz alta \"estoy ansioso\", \"estoy tranquilo\" o \"estoy emocionado\". Quienes dijeron \"estoy emocionado\" tuvieron mejor desempeño y se sintieron más entusiasmados que quienes intentaron calmarse.</p>\n<p>¿La explicación? La ansiedad y el entusiasmo son estados fisiológicos parecidos: ambos tienen alta activación (corazón rápido, energía). La diferencia está en la interpretación: la ansiedad se enfoca en la amenaza; el entusiasmo, en la oportunidad. Pasar de un estado activado a otro estado activado es más fácil que pasar de la activación a la calma.</p><h2>La activación tiene un lado útil</h2><p>Un nivel moderado de activación mejora la atención, la energía y la expresividad. Un orador sin ningún nervio puede sonar plano. El objetivo no es eliminar la activación, sino <strong>llevarla a un nivel útil y darle un sentido</strong>.</p><h2>Cómo aplicar la reinterpretación</h2><ol>\n<li><strong>Nota la sensación sin juzgarla:</strong> \"Mi corazón está acelerado.\"</li>\n<li><strong>Cámbiale el nombre:</strong> \"Esto es energía. Mi cuerpo se está preparando para hacerlo bien.\"</li>\n<li><strong>Dilo en voz alta o mentalmente:</strong> \"Estoy emocionado por presentar esto.\"</li>\n<li><strong>Conecta con el propósito:</strong> \"Lo que voy a explicar les va a servir a estos pacientes.\"</li>\n</ol><h2>Autoinstrucciones: habla contigo como le hablarías a un colega</h2><p>La forma en que te hablas importa. Algunas investigaciones sugieren que hablarte en segunda o tercera persona (\"Laura, tú puedes explicar esto, lo conoces bien\") crea distancia psicológica y ayuda a regular emociones. Prueba un guion breve:</p>\n<ul>\n<li>\"Estás nervioso porque te importa. Eso es bueno.\"</li>\n<li>\"No tienes que ser perfecto; tienes que ser útil.\"</li>\n<li>\"Empieza con la primera frase. Ya la sabes.\"</li>\n</ul><h2>Enfócate hacia afuera</h2><p>Gran parte de la ansiedad viene de preguntarse \"¿qué van a pensar de mí?\". Cambia la pregunta por \"¿qué necesita esta audiencia de mí?\". Cuando la atención se dirige al público y al mensaje, queda menos espacio para la autoobservación.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb02j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un visitador médico nuevo siente el estómago revuelto antes de entrar a la consulta de un cardiólogo reconocido. En lugar de pensar \"me va a ir mal\", se dice: \"Andrés, esto es energía. Traes un estudio que le puede servir a sus pacientes; enfócate en eso.\" Entra con la frase de apertura preparada y se concentra en escuchar las preguntas del médico.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb02j${"tone":"advertencia","title":"Errores comunes","html":"<ul>\n<li>Decirse \"cálmate\" de forma repetida y frustrarse porque no funciona.</li>\n<li>Creer que reinterpretar es \"mentirse\": no lo es; es elegir una lectura igual de válida de las mismas sensaciones.</li>\n<li>Reinterpretar sin preparación: la técnica potencia una buena preparación, no la reemplaza.</li>\n</ul>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb02j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Ansiedad y entusiasmo comparten la misma activación física.</li>\n<li>Decir \"estoy emocionado\" mejora el desempeño más que intentar calmarse.</li>\n<li>Háblate como a un colega y dirige tu atención a lo que necesita la audiencia.</li>\n</ol>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, $hb02j${"tone":"info","title":"Siguiente paso","html":"<p>Escribe tu propio guion de tres autoinstrucciones y úsalo en tu próxima reunión o presentación.</p>"}$hb02j$::jsonb);

