  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'La escalera de exposición: cómo perder el miedo a hablar en público paso a paso', 'Unidad 3 · Clase 3.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb02j${"tone":"info","title":"En esta clase","html":"<p>Cómo perder el miedo a hablar en público paso a paso con una escalera de exposición gradual: de situaciones fáciles a presentaciones reales. Plantilla incluida.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb02j${"html":"<p>Si hay una técnica que separa a quienes superan el miedo a hablar en público de quienes lo cargan toda la vida, es la exposición. El miedo se reduce cuando enfrentamos de forma repetida la situación temida y comprobamos que lo que tememos no ocurre o que podemos manejarlo. La clave es hacerlo <strong>de forma gradual</strong>: ni lanzarse a un auditorio de 300 personas mañana, ni seguir evitando. En esta clase construirás tu propia escalera.</p><h2>Por qué funciona la exposición</h2><p>La exposición es uno de los componentes centrales de la terapia cognitivo-conductual para la ansiedad. Cuando te expones a una situación y te quedas en ella el tiempo suficiente, ocurren dos cosas:</p>\n<ol>\n<li><strong>Habituación:</strong> la intensidad de la ansiedad baja con la repetición.</li>\n<li><strong>Nuevo aprendizaje:</strong> tu cerebro registra que la catástrofe esperada no ocurrió (\"me tembló la voz y nadie se burló\").</li>\n</ol>\n<p>La evitación impide ambos procesos.</p><h2>Cómo construir tu escalera</h2><p><strong>Paso 1. Haz una lista</strong> de 10 situaciones relacionadas con hablar en público, de la más fácil a la más difícil para ti.</p>\n<p><strong>Paso 2. Califica cada situación</strong> con unidades subjetivas de ansiedad (USA) de 0 a 100.</p>\n<p><strong>Paso 3. Ordénalas</strong> de menor a mayor. Intenta que haya peldaños cada 10 puntos aproximadamente.</p>\n<p><strong>Paso 4. Empieza por un peldaño de 30–40 USA:</strong> suficientemente retador para aprender, no tan alto que te bloquee.</p>\n<p><strong>Paso 5. Repite cada peldaño</strong> hasta que la ansiedad baje a la mitad o te sientas capaz. Luego sube.</p><h2>Ejemplo de escalera en el sector farmacéutico</h2><table><thead><tr><th>Peldaño</th><th>Situación</th><th>USA</th></tr></thead><tbody><tr><td>1</td><td>Grabarme 1 minuto explicando un medicamento y no borrarlo</td><td>20</td></tr><tr><td>2</td><td>Hacer una pregunta en una reunión de equipo</td><td>30</td></tr><tr><td>3</td><td>Explicar a un paciente cómo usar un inhalador, frente a un compañero</td><td>35</td></tr><tr><td>4</td><td>Presentar 3 minutos a dos colegas de confianza</td><td>45</td></tr><tr><td>5</td><td>Dar el reporte semanal en la reunión de área</td><td>50</td></tr><tr><td>6</td><td>Capacitación de 10 minutos a auxiliares</td><td>60</td></tr><tr><td>7</td><td>Presentar en una reunión virtual con cámara encendida a 15 personas</td><td>65</td></tr><tr><td>8</td><td>Presentar una propuesta al comité de farmacia</td><td>75</td></tr><tr><td>9</td><td>Charla de 15 minutos en un evento de la asociación</td><td>85</td></tr><tr><td>10</td><td>Ponencia en un congreso</td><td>95</td></tr></tbody></table><h2>Reglas para que la exposición funcione</h2><ul>\n<li><strong>Quédate en la situación:</strong> no salgas apenas suba la ansiedad.</li>\n<li><strong>Elimina las conductas de seguridad:</strong> leer todo el texto, evitar mirar al público o hablar muy rápido \"para terminar pronto\" impiden el aprendizaje. Redúcelas poco a poco.</li>\n<li><strong>Repite con frecuencia:</strong> varias exposiciones cortas en una semana funcionan mejor que una sola grande al mes.</li>\n<li><strong>Registra:</strong> anota USA antes, durante y después, y qué aprendiste.</li>\n</ul><h2>Busca oportunidades reales</h2><p>Las oportunidades de exposición están en tu día a día: reuniones, capacitaciones internas, grupos de estudio. Los clubes de oratoria como Toastmasters ofrecen un espacio seguro para practicar de forma frecuente.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb02j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una QF hospitalaria con miedo intenso a la ronda médica empezó por el peldaño 2: hacer una pregunta en cada reunión. A las dos semanas pasó a reportar una intervención farmacéutica por semana. Al mes presentó un caso completo en la ronda. Su ansiedad inicial de 80 bajó a 45, y lo más importante: dejó de evitar.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb02j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La exposición gradual reduce el miedo por habituación y nuevo aprendizaje.</li>\n<li>Construye una escalera de 10 peldaños calificados de 0 a 100.</li>\n<li>Quédate en la situación, reduce las conductas de seguridad y repite con frecuencia.</li>\n</ol>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb02j${"tone":"info","title":"Siguiente paso","html":"<p>Diseña tu escalera y completa los dos primeros peldaños esta semana.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Preparación que reduce la ansiedad: la rutina previa y los primeros 60 segundos', 'Unidad 3 · Clase 3.2', 1, 'manual', 18, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb02j${"tone":"info","title":"En esta clase","html":"<p>Consejos para hablar en público con menos ansiedad: rutina de preparación, checklist logístico y cómo dominar los primeros 60 segundos de tu presentación.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb02j${"html":"<p>Gran parte de la ansiedad al hablar en público viene de la incertidumbre: ¿funcionará el computador?, ¿cuánta gente habrá?, ¿cómo empiezo? Cada incertidumbre que resuelves antes es una fuente menos de nervios. Además, la ansiedad suele ser máxima en el primer minuto y luego baja. En esta clase vas a preparar una rutina previa y a dominar tus primeros 60 segundos, el momento más difícil.</p><h2>La curva de la ansiedad</h2><p>Muchas personas describen el mismo patrón: la ansiedad sube en la anticipación, llega a su pico justo antes y durante el primer minuto, y empieza a bajar cuando se entra en el contenido. Por eso, <strong>si aseguras el arranque, el resto fluye mejor</strong>.</p><h2>Preparación del contenido</h2><ul>\n<li>Prepara con tiempo: la improvisación de último minuto multiplica los nervios.</li>\n<li>Usa la estructura apertura–cuerpo–cierre y un mensaje central claro.</li>\n<li>Ensaya en voz alta al menos tres veces.</li>\n<li>Prepara respuestas a las cinco preguntas más probables.</li>\n</ul><h2>Preparación logística (checklist)</h2><p><strong>El día anterior:</strong></p>\n<ul>\n<li>Presentación guardada en dos lugares (USB y nube) y en PDF.</li>\n<li>Confirmar lugar, hora, equipos disponibles y duración asignada.</li>\n<li>Ropa elegida, cómoda y apropiada.</li>\n<li>Dormir lo suficiente; evitar el exceso de cafeína.</li>\n</ul>\n<p><strong>El día de la presentación:</strong></p>\n<ul>\n<li>Llegar 20–30 minutos antes.</li>\n<li>Probar proyector, clicker, micrófono y conexión.</li>\n<li>Ubicar dónde vas a estar parado y dónde está el agua.</li>\n<li>Si es virtual: probar cámara, audio, iluminación y compartir pantalla.</li>\n</ul><h2>Los primeros 60 segundos</h2><p>Escribe y <strong>memoriza</strong> tus primeros 60 segundos. Incluye:</p>\n<ol>\n<li><strong>Una exhalación larga</strong> al llegar al frente, mirando al público.</li>\n<li><strong>Una apertura fuerte</strong> (pregunta, dato o historia breve).</li>\n<li><strong>Tu mensaje central</strong> en una frase.</li>\n<li><strong>El mapa:</strong> \"Vamos a ver tres cosas: …\".</li>\n</ol>\n<p>Al tener este bloque memorizado, tu mente no necesita buscar palabras en el momento de mayor activación.</p><h2>La rutina previa de 10 minutos</h2><ol>\n<li>Revisa tus tarjetas una vez (no reescribas).</li>\n<li>Respiración 4-6 durante dos minutos.</li>\n<li>Rutina vocal corta: vibración de labios y estiramiento de mandíbula.</li>\n<li>Autoinstrucción: \"Estoy emocionado. Esto les va a servir.\"</li>\n<li>Busca en el público dos o tres \"caras amables\" para empezar mirándolas.</li>\n</ol><h2>Conversa antes de presentar</h2><p>Saludar a algunos asistentes antes de empezar convierte a \"la audiencia\" en personas concretas. Cuando empieces, ya tendrás aliados en el salón.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb02j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un coordinador de droguería debía presentar los resultados del trimestre al gerente regional por videollamada. Probó la conexión media hora antes, tenía el archivo en PDF por si fallaba la presentación y memorizó su primer minuto: \"En este trimestre crecimos 8 % en pacientes crónicos y bajamos los pendientes a la mitad. Les voy a mostrar cómo lo logramos y qué necesitamos para el próximo.\" La reunión arrancó con seguridad y el resto fluyó.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb02j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Resolver la incertidumbre logística reduce la ansiedad.</li>\n<li>El primer minuto concentra el pico de nervios: memorízalo.</li>\n<li>Una rutina previa de 10 minutos te lleva a un nivel de activación útil.</li>\n</ol>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb02j${"tone":"info","title":"Siguiente paso","html":"<p>Escribe tus primeros 60 segundos para tu próximo peldaño de la escalera y ensáyalos cinco veces.</p>"}$hb02j$::jsonb);

