  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb02j${"tone":"info","title":"En esta clase","html":"<p>Qué hacer si te quedas en blanco al hablar en público: 7 técnicas de rescate para recuperar el hilo sin que el público lo note. Con ejemplos prácticos.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb02j${"html":"<p>Es el temor número uno de muchos oradores: estás en medio de la presentación y, de repente, no recuerdas qué seguía. La mente se queda en blanco. Primero, una buena noticia: casi siempre dura unos pocos segundos y el público rara vez lo percibe como un problema. Segundo: puedes tener un plan. En esta clase vas a aprender siete técnicas de rescate para recuperar el hilo con naturalidad.</p><h2>Por qué ocurre</h2><p>Cuando la activación sube mucho, el acceso a la memoria de trabajo se dificulta. Es más probable quedarse en blanco cuando se memorizó un texto palabra por palabra (si se pierde una palabra, se pierde la cadena) o cuando se intenta recordar en lugar de seguir una estructura.</p><h2>Técnica 1: la pausa intencional</h2><p>Lo que para ti es un silencio eterno, para el público es una pausa normal. Detente, respira, mira tus notas o al público. Dos o tres segundos de pausa transmiten reflexión, no olvido.</p><h2>Técnica 2: repite tu última frase</h2><p>Repetir o parafrasear lo último que dijiste (\"Entonces, como decía, la cadena de frío se rompe en la recepción…\") suele activar la memoria de lo que seguía. Además, refuerza la idea para el público.</p><h2>Técnica 3: resume lo dicho</h2><p>\"Hasta aquí hemos visto dos cosas: el problema y su causa.\" Al resumir, ordenas tu mente y recuperas el mapa de la presentación.</p><h2>Técnica 4: consulta tus notas sin culpa</h2><p>Tener tarjetas con palabras clave no es un signo de debilidad. Mira la tarjeta con calma, encuentra la palabra y continúa. Si usas diapositivas, el título de la siguiente puede ser tu ancla.</p><h2>Técnica 5: haz una pregunta al público</h2><p>\"¿Alguno de ustedes ha tenido un caso así?\" Mientras responden, recuperas el hilo. Úsala con moderación y asegúrate de que la pregunta sea pertinente.</p><h2>Técnica 6: salta al siguiente punto</h2><p>Si la idea no vuelve, pasa a la siguiente: \"Vamos ahora a…\". Muchas veces la idea olvidada regresa después y puedes incluirla (\"Algo que quiero agregar sobre el primer punto…\"). El público no conoce tu guion; no sabrá que cambiaste el orden.</p><h2>Técnica 7: sé honesto con naturalidad</h2><p>Si nada funciona: \"Perdí el hilo por un segundo, déjenme revisar.\" Dicho con calma y una sonrisa, humaniza al orador. La mayoría del público empatiza.</p><h2>Prevención: cómo reducir la probabilidad</h2><ul>\n<li>Internaliza la estructura en lugar de memorizar el texto.</li>\n<li>Ten tarjetas numeradas con palabras clave.</li>\n<li>Usa títulos de diapositivas que digan la idea (te sirven de guion).</li>\n<li>Ensaya en voz alta, incluso con interrupciones.</li>\n</ul><h2>Ejercicio de simulación</h2><p>Pide a un compañero que, durante tu ensayo, te interrumpa dos veces con un aplauso o una pregunta irrelevante. Practica retomar con alguna de las técnicas. Entrenar el \"rescate\" reduce el miedo a que ocurra.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb02j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un visitador médico, en medio de la presentación del estudio clínico, olvida el segundo beneficio del producto. Hace una pausa, toma la tableta y dice: \"Le muestro el dato exacto.\" Mira la diapositiva, recupera la idea y continúa. El médico solo percibió que fue preciso.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb02j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Quedarse en blanco es breve y el público casi nunca lo nota.</li>\n<li>Pausa, repite, resume, consulta notas, pregunta, salta o sé honesto.</li>\n<li>Internalizar la estructura y ensayar con interrupciones lo previene.</li>\n</ol>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb02j${"tone":"info","title":"Siguiente paso","html":"<p>Elige dos técnicas de rescate favoritas y practícalas en tu próximo ensayo con interrupciones.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Plan de 30 días para vencer el miedo escénico y cuándo buscar ayuda profesional', 'Unidad 4 · Clase 4.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb02j${"tone":"info","title":"En esta clase","html":"<p>Plan de 30 días para vencer el miedo escénico: rutina diaria, exposición semanal y seguimiento. Señales de alerta para buscar ayuda profesional.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb02j${"html":"<p>Ya tienes las herramientas: entiendes tu miedo, sabes regular el cuerpo, reinterpretar la activación, exponerte de forma gradual, preparar tu arranque y rescatarte si te quedas en blanco. Ahora el reto es la constancia. El miedo escénico no desaparece con una sola presentación exitosa; se debilita con repetición. En esta clase vas a armar un plan de 30 días y a conocer las señales que indican que es momento de buscar apoyo profesional.</p><h2>Los tres principios del plan</h2><ol>\n<li><strong>Práctica diaria breve:</strong> 10 minutos al día valen más que tres horas un domingo.</li>\n<li><strong>Exposición semanal:</strong> al menos dos peldaños de la escalera por semana.</li>\n<li><strong>Registro:</strong> lo que no se mide se olvida; el registro te muestra el progreso cuando la mente te dice que \"no has avanzado\".</li>\n</ol><h2>Semana 1: bases</h2><ul>\n<li><strong>Diario:</strong> 5 minutos de suspiro cíclico + 5 minutos de lectura en voz alta con pausas.</li>\n<li><strong>Exposición:</strong> peldaños 1 y 2 (grabarte y hacer una pregunta en una reunión).</li>\n<li><strong>Registro:</strong> USA antes y después; un aprendizaje por día.</li>\n</ul><h2>Semana 2: voz y estructura</h2><ul>\n<li><strong>Diario:</strong> respiración + un minuto improvisado con PREP sobre un tema al azar.</li>\n<li><strong>Exposición:</strong> peldaños 3 y 4 (explicar algo frente a uno o dos colegas).</li>\n<li><strong>Cognitivo:</strong> un registro de pensamientos antes de cada exposición.</li>\n</ul><h2>Semana 3: público real</h2><ul>\n<li><strong>Diario:</strong> respiración + ensayo de tus primeros 60 segundos.</li>\n<li><strong>Exposición:</strong> peldaños 5 y 6 (reporte en reunión, capacitación corta).</li>\n<li><strong>Retroalimentación:</strong> pide a una persona de confianza un comentario de \"qué funcionó / qué mejorar\".</li>\n</ul><h2>Semana 4: consolidación</h2><ul>\n<li><strong>Diario:</strong> rutina completa de 10 minutos.</li>\n<li><strong>Exposición:</strong> peldaño 7 u 8 (reunión virtual con cámara o propuesta formal).</li>\n<li><strong>Cierre:</strong> grábate nuevamente y compara con tu video y tu test del inicio.</li>\n</ul><h2>Cómo manejar las recaídas</h2><p>Es normal tener un mal día. Una presentación con más nervios de lo esperado no borra el progreso. Revisa qué pasó (¿dormiste poco?, ¿saltaste la preparación?, ¿era un peldaño muy alto?), ajusta y vuelve al peldaño anterior si es necesario. Lo importante es <strong>no volver a la evitación</strong>.</p><h2>Celebra los logros</h2><p>Anota cada logro, por pequeño que sea: \"Hice una pregunta en la reunión\", \"Presenté con la cámara encendida\". Revisar esa lista antes de una nueva exposición es un recordatorio con evidencia de que sí puedes.</p><h2>Cuándo buscar ayuda profesional</h2><p>Este curso está diseñado para nervios comunes. Busca evaluación con un psicólogo, psiquiatra o médico si:</p>\n<ul>\n<li>El miedo te lleva a rechazar oportunidades laborales o académicas importantes.</li>\n<li>Aparece en muchas situaciones sociales, no solo al hablar en público (comer frente a otros, hablar con desconocidos, ser observado).</li>\n<li>Tienes ataques de pánico (palpitaciones intensas, sensación de ahogo, miedo a morir o perder el control).</li>\n<li>Usas alcohol, sustancias o medicamentos sin indicación para enfrentar presentaciones.</li>\n<li>Después de 30 días de práctica constante no notas ningún cambio.</li>\n</ul>\n<p>Los tratamientos para la ansiedad social, como la terapia cognitivo-conductual, tienen buena evidencia. Pedir ayuda es una decisión profesional y sensata, no un fracaso. Ningún medicamento debe usarse para \"controlar los nervios\" sin prescripción y seguimiento médico.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb02j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un QF de una cadena de droguerías completó el plan de 30 días. Su nivel de miedo bajó de 8 a 5 sobre 10. No desapareció, pero dejó de evitar: presentó su primera capacitación regional y se inscribió en un club de oratoria para mantener la práctica.</p>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb02j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La constancia (práctica diaria breve y exposición semanal) es lo que debilita el miedo.</li>\n<li>Las recaídas son normales; lo importante es no volver a evitar.</li>\n<li>Si el miedo es intenso, generalizado o con pánico, busca ayuda profesional.</li>\n</ol>"}$hb02j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb02j${"tone":"info","title":"Siguiente paso","html":"<p>Descarga el calendario de 30 días, pon la fecha de inicio y comparte tu compromiso en el foro.</p>"}$hb02j$::jsonb);
END
$hb02$;

-- ─── Curso de Presentaciones Efectivas y Storytelling (8 clases) ───
DO $hb03$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Presentaciones Efectivas y Storytelling' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, area, level, tags,
     objective, learning_outcomes, audience, duration_minutes, author_name, status, modality, cover_url, publico)
  VALUES ('edvanta', 'Curso de Presentaciones Efectivas y Storytelling', $hb03t$Curso para diseñar y presentar presentaciones que informan y convencen: análisis de audiencia, storytelling, diseño de diapositivas basado en evidencia, comunicación de datos clínicos, presentaciones virtuales y pitch de 3 minutos.$hb03t$,
          $hb03t$<p>Curso para diseñar y presentar presentaciones que informan y convencen: análisis de audiencia, storytelling, diseño de diapositivas basado en evidencia, comunicación de datos clínicos, presentaciones virtuales y pitch de 3 minutos.</p><h2>Objetivo</h2><p>Que el participante diseñe y presente una presentación de 10 minutos con una narrativa clara, diapositivas que sigan principios de aprendizaje multimedia y datos comunicados con precisión, además de un pitch de 3 minutos.</p><h2>Para quién es</h2><p>Químicos farmacéuticos, equipos de mercadeo y ventas farmacéuticas, coordinadores de servicio farmacéutico, docentes y estudiantes del área de la salud.</p><h2>Cómo está organizado</h2><p>Cuatro unidades con dos clases en texto cada una. Cada clase trae un ejemplo aplicado al sector farmacéutico y de la salud, puntos clave y el siguiente paso.</p><h2>Referentes</h2><p>Nancy Duarte (Resonate y slide:ology: contraste &quot;lo que es / lo que podría ser&quot;); Richard E. Mayer (principios de aprendizaje multimedia); Cole Nussbaumer Knaflic (Storytelling with Data); Joseph Campbell (el viaje del héroe); Barbara Minto (situación–complicación–resolución).</p>$hb03t$,
          'Oratoria y presentaciones', 'Habilidades Blandas', 'intermedio', ARRAY['Presentaciones', 'Storytelling', 'Diapositivas', 'Pitch', 'Habilidades blandas']::text[],
          $hb03t$Que el participante diseñe y presente una presentación de 10 minutos con una narrativa clara, diapositivas que sigan principios de aprendizaje multimedia y datos comunicados con precisión, además de un pitch de 3 minutos.$hb03t$,
          ARRAY['Definir la audiencia, el objetivo y el mensaje antes de diseñar una presentación.', 'Estructurar historias y comunicar datos y resultados para que se entiendan.', 'Diseñar diapositivas basadas en evidencia y presentar datos clínicos y técnicos con claridad.', 'Presentar en Teams, Zoom o Meet y preparar un pitch de 3 minutos.']::text[],
          $hb03t$Químicos farmacéuticos, equipos de mercadeo y ventas farmacéuticas, coordinadores de servicio farmacéutico, docentes y estudiantes del área de la salud.$hb03t$,
          147, 'Edvanta', 'borrador', 'asincronica', '/img/cursos/presentaciones-efectivas.webp', 'profesionales')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Audiencia y propósito', 0)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Qué hace efectiva una presentación: audiencia, objetivo y mensaje', 'Unidad 1 · Clase 1.1', 0, 'manual', 18, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb03j${"tone":"info","title":"En esta clase","html":"<p>Qué hace efectiva una presentación: el triángulo audiencia–objetivo–mensaje, por qué fallan las presentaciones y cómo planear antes de abrir PowerPoint.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb03j${"html":"<p>Una presentación efectiva no es la que tiene las diapositivas más bonitas, sino la que logra su propósito: que la audiencia entienda, decida o actúe. La mayoría de las presentaciones que fallan lo hacen antes de abrir PowerPoint, porque nadie definió para quién eran, para qué servían y qué debía quedar claro. En esta clase aprenderás a planear con el triángulo audiencia–objetivo–mensaje.</p><h2>Por qué fallan las presentaciones</h2><ul>\n<li><strong>Se diseñan desde el contenido y no desde la audiencia:</strong> \"voy a contar todo lo que sé\".</li>\n<li><strong>No tienen un objetivo de acción:</strong> terminan en \"gracias\" y nadie sabe qué sigue.</li>\n<li><strong>Mezclan documento y presentación:</strong> diapositivas con párrafos que nadie lee mientras escucha.</li>\n<li><strong>Carecen de hilo narrativo:</strong> son una lista de temas, no una historia.</li>\n<li><strong>Abusan de los datos:</strong> 14 gráficos sin decir qué significa cada uno.</li>\n<li><strong>No se ensayan.</strong></li>\n</ul><h2>El triángulo de la planeación</h2><h3>1. Audiencia: ¿quién me escucha?</h3>\n<p>Pregúntate: ¿qué saben ya?, ¿qué les preocupa?, ¿qué decisión pueden tomar?, ¿cuánto tiempo y atención tienen? No es lo mismo presentar un antidiabético a un endocrinólogo que a un comité de compras o a un grupo de pacientes.</p>\n<h3>2. Objetivo: ¿qué quiero que hagan?</h3>\n<p>Formula el objetivo como una acción observable: \"que el comité apruebe incluir el medicamento en el listado institucional\", \"que los auxiliares apliquen el nuevo protocolo de dispensación desde el lunes\". Si el objetivo es solo \"informar\", pregúntate para qué necesitan esa información.</p>\n<h3>3. Mensaje: ¿qué deben recordar?</h3>\n<p>El mensaje central es la frase que conecta lo que la audiencia necesita con lo que tú propones. Ejemplo: \"Incluir este iSGLT2 en el listado reduce hospitalizaciones por falla cardíaca en nuestros pacientes de alto riesgo con un impacto presupuestal controlado.\"</p><h2>Presentar no es leer un documento</h2><p>Nancy Duarte acuñó el término <em>slideument</em> para la diapositiva que intenta ser documento y presentación al mismo tiempo, y falla en ambas cosas. Si el contenido necesita leerse con detalle (tablas completas, normativa, referencias), prepara un <strong>documento de apoyo</strong> para entregar, y deja en las diapositivas solo lo que refuerza lo que dices.</p><h2>El proceso recomendado</h2><ol>\n<li><strong>Planea en papel</strong> (audiencia, objetivo, mensaje).</li>\n<li><strong>Arma la estructura</strong> con notas adhesivas o un guion de títulos.</li>\n<li><strong>Escribe lo que vas a decir.</strong></li>\n<li><strong>Diseña las diapositivas</strong> al final, como apoyo visual.</li>\n<li><strong>Ensaya</strong> y ajusta.</li>\n</ol>\n<p>Abrir PowerPoint en el paso 1 es la causa más frecuente de presentaciones recargadas.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb03j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un gerente de producto debe presentar el lanzamiento de un nuevo anticoagulante a la fuerza de ventas. Primera versión: 45 diapositivas copiadas del dosier científico. Tras el triángulo: audiencia = visitadores que necesitan saber qué decir en 3 minutos; objetivo = que cada uno practique la visita con el nuevo mensaje; mensaje = \"Para el paciente que olvida dosis, la toma una vez al día facilita la adherencia\". Resultado: 12 diapositivas y un taller práctico.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb03j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Una presentación efectiva se mide por lo que la audiencia entiende, decide o hace.</li>\n<li>Planea con el triángulo audiencia–objetivo–mensaje antes de diseñar.</li>\n<li>Separa la presentación del documento de apoyo.</li>\n</ol>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb03j${"tone":"info","title":"Siguiente paso","html":"<p>Llena el lienzo de planeación para una presentación real que tengas en el próximo mes.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Análisis de audiencia: cómo adaptar tu presentación a médicos, directivos, pacientes o equipos', 'Unidad 1 · Clase 1.2', 1, 'manual', 18, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb03j${"tone":"info","title":"En esta clase","html":"<p>Cómo hacer una presentación adaptada a tu audiencia: mapa de audiencia, nivel técnico, motivaciones y objeciones. Ejemplos con médicos, directivos y pacientes.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb03j${"html":"<p>El mismo contenido puede ser brillante para una audiencia y un fracaso para otra. Un dato de reducción de riesgo relativo emociona a un cardiólogo, confunde a un paciente y deja indiferente a un director financiero si no lo traduces a costos. En esta clase aprenderás a construir un mapa de audiencia y a adaptar tu presentación en lenguaje, profundidad y argumentos.</p><h2>El mapa de audiencia</h2><p>Responde estas seis preguntas antes de preparar el contenido:</p>\n<ol>\n<li><strong>¿Quiénes son?</strong> Cargo, formación, número de personas, quién decide.</li>\n<li><strong>¿Qué saben del tema?</strong> Nivel técnico: experto, intermedio o lego.</li>\n<li><strong>¿Qué les importa?</strong> Sus metas y presiones: resultados clínicos, presupuesto, tiempo, seguridad del paciente, indicadores.</li>\n<li><strong>¿Qué piensan hoy?</strong> Su postura inicial: a favor, neutral, escéptica.</li>\n<li><strong>¿Qué objeciones pueden tener?</strong> \"Es más caro\", \"ya tenemos algo parecido\", \"no hay tiempo\".</li>\n<li><strong>¿Qué necesitan para actuar?</strong> Evidencia, aprobación de otro, un piloto, un costo.</li>\n</ol><h2>Cuatro audiencias típicas del sector salud</h2><h3>Médicos especialistas</h3>\n<ul>\n<li>Valoran la evidencia de calidad: diseño del estudio, desenlaces duros, guías.</li>\n<li>Tienen poco tiempo: ve al grano y espera preguntas técnicas.</li>\n<li>Evita el lenguaje publicitario o las promesas absolutas.</li>\n</ul>\n<h3>Directivos y comités</h3>\n<ul>\n<li>Piensan en impacto: costos, riesgos, indicadores, cumplimiento normativo.</li>\n<li>Prefieren la conclusión primero (principio de la pirámide).</li>\n<li>Lleva una recomendación clara y las alternativas consideradas.</li>\n</ul>\n<h3>Pacientes y cuidadores</h3>\n<ul>\n<li>Necesitan lenguaje sencillo, ejemplos cotidianos y pasos concretos.</li>\n<li>Convierte porcentajes en frecuencias naturales: \"de cada 100 personas como usted…\".</li>\n<li>Verifica la comprensión con preguntas abiertas.</li>\n</ul>\n<h3>Equipos operativos (auxiliares, técnicos)</h3>\n<ul>\n<li>Necesitan saber qué cambia en su trabajo diario y por qué.</li>\n<li>Usa demostraciones, listas de verificación y práctica.</li>\n<li>Reconoce su experiencia: suelen conocer los problemas reales.</li>\n</ul><h2>Adaptar sin cambiar la verdad</h2><p>Adaptar no significa exagerar ni ocultar. Significa elegir <strong>qué evidencia, qué ejemplo y qué nivel de detalle</strong> sirve a esa audiencia. Los datos de seguridad y las limitaciones deben estar presentes para todas las audiencias, con el lenguaje adecuado.</p><h2>Cuando la audiencia es mixta</h2><p>Si en el salón hay especialistas y personal administrativo:</p>\n<ul>\n<li>Define el mensaje para quien toma la decisión.</li>\n<li>Explica los términos técnicos brevemente la primera vez.</li>\n<li>Ofrece un anexo técnico para quien quiera profundizar.</li>\n<li>Usa ejemplos que todos entiendan.</li>\n</ul>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb03j${"tone":"consejo","title":"Ejemplo aplicado: un dato, tres audiencias","html":"<p>El dato: un programa de seguimiento farmacoterapéutico en pacientes con insuficiencia cardíaca se asoció con menos reingresos en el piloto de la institución.</p>\n<ul>\n<li><strong>Para cardiólogos:</strong> diseño del piloto, criterios de inclusión, desenlaces y limitaciones.</li>\n<li><strong>Para el comité directivo:</strong> reingresos evitados, costo del programa y retorno estimado.</li>\n<li><strong>Para pacientes:</strong> \"Si una química farmacéutica lo llama cada mes para revisar sus medicamentos, es menos probable que tenga que volver a urgencias.\"</li>\n</ul>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb03j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>El mapa de audiencia define lenguaje, profundidad y argumentos.</li>\n<li>Médicos buscan evidencia; directivos, impacto; pacientes, claridad; equipos, aplicación.</li>\n<li>Adaptar no es exagerar: la seguridad y las limitaciones van siempre.</li>\n</ol>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb03j${"tone":"info","title":"Siguiente paso","html":"<p>Haz el mapa de audiencia de tu presentación y escribe las tres objeciones más probables con su respuesta.</p>"}$hb03j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 2. Storytelling', 1)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Qué es el storytelling y cómo estructurar una historia que convence', 'Unidad 2 · Clase 2.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb03j${"tone":"info","title":"En esta clase","html":"<p>Qué es el storytelling, por qué las historias convencen y tres estructuras para usarlo en presentaciones: SCR, \"lo que es / lo que podría ser\" y el viaje del héroe.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb03j${"html":"<p>Los datos informan, pero las historias mueven. Recordamos un caso concreto mucho mejor que una tabla de resultados, y una historia bien contada le da sentido a los números. El storytelling no es inventar ni adornar: es organizar información real con una estructura narrativa para que la audiencia la entienda, la recuerde y actúe. En esta clase aprenderás tres estructuras que puedes usar desde mañana.</p><h2>¿Qué es el storytelling?</h2><p>Storytelling es el arte de comunicar por medio de historias. En una presentación profesional, una historia tiene cuatro elementos:</p>\n<ul>\n<li><strong>Un personaje</strong> con el que la audiencia se identifica (un paciente, un equipo, la propia audiencia).</li>\n<li><strong>Un conflicto o problema</strong> que genera tensión.</li>\n<li><strong>Un cambio o resolución.</strong></li>\n<li><strong>Un significado:</strong> qué aprendemos o qué debemos hacer.</li>\n</ul><h2>Por qué funcionan las historias</h2><p>Las historias captan la atención porque generan expectativa (¿qué va a pasar?), facilitan la comprensión al dar contexto y mejoran la memoria al conectar los datos con una secuencia y una emoción. Además, permiten que la audiencia se ponga en el lugar del personaje.</p><h2>Estructura 1: Situación – Complicación – Resolución (SCR)</h2><p>Propuesta por Barbara Minto, es ideal para presentaciones ejecutivas.</p>\n<ul>\n<li><strong>Situación:</strong> el contexto estable que la audiencia reconoce. \"Nuestro servicio dispensa 3.000 fórmulas diarias.\"</li>\n<li><strong>Complicación:</strong> lo que cambió o amenaza. \"En el último trimestre, los errores de dispensación aumentaron un 40 %.\"</li>\n<li><strong>Resolución:</strong> tu propuesta. \"Un sistema de doble verificación en medicamentos de alto riesgo puede reducirlos.\"</li>\n</ul><h2>Estructura 2: Lo que es / lo que podría ser</h2><p>Nancy Duarte analizó discursos memorables y encontró un patrón: alternan entre <strong>cómo están las cosas hoy</strong> y <strong>cómo podrían estar</strong>. Esa tensión mantiene la atención y hace deseable el cambio. Cierran con una \"nueva felicidad\": cómo se ve el mundo cuando la audiencia actúa.</p>\n<p>Ejemplo: \"Hoy, un paciente con EPOC sale de la droguería sin saber usar su inhalador (lo que es). Imaginen que cada dispensación incluyera una demostración de dos minutos (lo que podría ser)…\"</p><h2>Estructura 3: El viaje del héroe (versión corta)</h2><p>Basada en el trabajo de Joseph Campbell. Lo importante en presentaciones: <strong>el héroe es la audiencia o el paciente, no tú</strong>. Tú eres el guía que ofrece una herramienta.</p>\n<ol>\n<li>El héroe en su mundo cotidiano.</li>\n<li>Aparece un problema.</li>\n<li>Encuentra un guía y una herramienta.</li>\n<li>Supera el obstáculo.</li>\n<li>Regresa transformado.</li>\n</ol><h2>Cómo contar un caso en 60 segundos</h2><ol>\n<li><strong>Personaje con un detalle concreto:</strong> \"Doña Marta, 72 años, vive sola en Bello.\"</li>\n<li><strong>Problema:</strong> \"Toma siete medicamentos y confundía las cajas.\"</li>\n<li><strong>Momento de cambio:</strong> \"En la revisión, la QF le organizó un pastillero por colores.\"</li>\n<li><strong>Resultado:</strong> \"En tres meses su presión llegó a la meta.\"</li>\n<li><strong>Puente al mensaje:</strong> \"Por eso proponemos…\"</li>\n</ol><h2>Ética del storytelling en salud</h2><ul>\n<li>Usa casos reales con consentimiento o anonimizados de forma que no se pueda identificar al paciente.</li>\n<li>No conviertas un caso individual en una prueba de eficacia: la historia ilustra, la evidencia demuestra.</li>\n<li>No exageres resultados ni omitas eventos adversos.</li>\n</ul>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb03j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Una historia tiene personaje, conflicto, cambio y significado.</li>\n<li>SCR, \"lo que es / lo que podría ser\" y el viaje del héroe son estructuras prácticas.</li>\n<li>En salud, la historia ilustra y la evidencia demuestra; cuida la confidencialidad.</li>\n</ol>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb03j${"tone":"info","title":"Siguiente paso","html":"<p>Escribe un caso de 60 segundos de tu práctica profesional usando los cinco pasos.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Storytelling con datos: cómo contar resultados y cifras para que se entiendan', 'Unidad 2 · Clase 2.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb03j${"tone":"info","title":"En esta clase","html":"<p>Storytelling con datos: cómo elegir el gráfico correcto, quitar el ruido y destacar el mensaje para que tus cifras se entiendan. Ejemplos con datos de salud.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb03j${"html":"<p>Un gráfico mal diseñado puede esconder un hallazgo importante, y uno bien diseñado puede hacer que una decisión se tome en segundos. Contar historias con datos consiste en elegir qué mostrar, cómo mostrarlo y qué decir para que la audiencia vea lo mismo que tú ves. En esta clase aplicarás un método de cuatro pasos inspirado en el trabajo de Cole Nussbaumer Knaflic.</p><h2>Paso 1: define qué quieres que la audiencia vea</h2><p>Antes de elegir el gráfico, escribe la frase que resume el hallazgo: \"Los errores de dispensación se concentran en el turno de la noche.\" Esa frase será el <strong>título del gráfico</strong>. Un título como \"Errores por turno\" describe; uno como \"El 60 % de los errores ocurre en el turno de la noche\" comunica.</p><h2>Paso 2: elige el gráfico adecuado</h2><ul>\n<li><strong>Comparar categorías:</strong> barras horizontales (fáciles de leer, admiten etiquetas largas).</li>\n<li><strong>Mostrar una tendencia en el tiempo:</strong> líneas.</li>\n<li><strong>Mostrar partes de un todo:</strong> barras apiladas al 100 %; usa tortas solo con dos o tres categorías.</li>\n<li><strong>Un número clave:</strong> muéstralo grande, con una frase de contexto.</li>\n<li><strong>Relación entre dos variables:</strong> dispersión.</li>\n</ul>\n<p>Evita los gráficos en 3D, los ejes que no empiezan en cero en barras y las tortas con muchas porciones.</p><h2>Paso 3: quita el ruido</h2><p>Cada elemento que no aporta compite por la atención. Elimina:</p>\n<ul>\n<li>Bordes, sombras y fondos.</li>\n<li>Líneas de cuadrícula fuertes (déjalas tenues o quítalas).</li>\n<li>Leyendas separadas: etiqueta las series directamente.</li>\n<li>Decimales innecesarios.</li>\n</ul><h2>Paso 4: dirige la atención</h2><p>Usa el color con intención: todo en gris y <strong>un solo color</strong> para el dato que importa. Agrega una anotación breve junto al punto clave (\"inicio del nuevo protocolo\"). Revela la información por partes si el gráfico es complejo.</p><h2>Comunicar datos clínicos con precisión</h2><p>En el sector salud, la forma de presentar los resultados puede cambiar la percepción del beneficio:</p>\n<ul>\n<li><strong>Reducción del riesgo relativo</strong> (\"reduce el riesgo un 25 %\") suena más impactante que la <strong>reducción del riesgo absoluto</strong> (\"de 8 % a 6 %, una diferencia de 2 puntos\").</li>\n<li>Presenta ambos y, cuando aplique, el <strong>número necesario a tratar (NNT)</strong>.</li>\n<li>Indica el periodo de seguimiento, la población y los intervalos de confianza para audiencias técnicas.</li>\n<li>Muestra también los eventos adversos con la misma claridad.</li>\n</ul><h2>Narrar el gráfico</h2><p>Cuando muestres un gráfico, sigue esta secuencia:</p>\n<ol>\n<li><strong>Qué estamos viendo:</strong> \"En el eje horizontal están los meses; cada barra es el número de errores.\"</li>\n<li><strong>Qué destacar:</strong> \"Miren la barra de marzo.\"</li>\n<li><strong>Qué significa:</strong> \"Es el mes en que entró el personal nuevo sin inducción.\"</li>\n<li><strong>Qué hacer:</strong> \"Por eso proponemos una inducción de dos días.\"</li>\n</ol>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb03j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una coordinadora presenta la adherencia de pacientes hipertensos. Versión inicial: una tabla con 12 meses y 5 sedes. Versión mejorada: un gráfico de líneas con cuatro sedes en gris y una en azul, título \"La sede Norte duplicó la adherencia tras implementar llamadas de seguimiento\" y una anotación en el mes de inicio del programa. La gerencia aprobó extender el programa en esa misma reunión.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb03j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>El título del gráfico debe decir el hallazgo, no el tema.</li>\n<li>Elige el gráfico según el mensaje, quita el ruido y usa el color para dirigir la atención.</li>\n<li>En salud presenta riesgo absoluto y relativo, y los datos de seguridad con igual claridad.</li>\n</ol>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb03j${"tone":"info","title":"Siguiente paso","html":"<p>Toma un gráfico de una presentación reciente y rediséñalo con los cuatro pasos.</p>"}$hb03j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 3. Diseño de diapositivas', 2)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo hacer una buena presentación en PowerPoint: diseño de diapositivas basado en evidencia', 'Unidad 3 · Clase 3.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb03j${"tone":"info","title":"En esta clase","html":"<p>Cómo hacer una buena presentación en PowerPoint con principios de Mayer: una idea por diapositiva, títulos-afirmación, imágenes con sentido y menos texto.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb03j${"html":"<p>Las diapositivas no son tu guion ni tu documento: son un apoyo visual para lo que dices. Cuando están llenas de viñetas, el público intenta leer y escuchar al mismo tiempo, y termina sin hacer bien ninguna de las dos cosas. La investigación sobre aprendizaje multimedia ofrece principios claros para diseñar diapositivas que ayudan a entender y recordar. En esta clase los aplicarás con ejemplos del sector salud.</p><h2>Los principios de Mayer que más importan</h2><p>Richard E. Mayer, psicólogo de la Universidad de California en Santa Bárbara, estudió durante décadas cómo aprendemos con palabras e imágenes. Estos son los principios más útiles para presentaciones:</p>\n<ol>\n<li><strong>Coherencia:</strong> se aprende mejor cuando se elimina el material que no aporta (imágenes decorativas, música, datos curiosos irrelevantes).</li>\n<li><strong>Señalización:</strong> se aprende mejor cuando se destaca lo esencial (flechas, color, resaltado).</li>\n<li><strong>Redundancia:</strong> se aprende mejor con imagen + narración que con imagen + narración + el mismo texto escrito en pantalla. Leer en voz alta las viñetas es redundante.</li>\n<li><strong>Contigüidad espacial:</strong> las etiquetas deben ir junto a lo que describen, no en una leyenda aparte.</li>\n<li><strong>Segmentación:</strong> el contenido complejo se entiende mejor por partes.</li>\n<li><strong>Multimedia:</strong> palabras con imágenes pertinentes funcionan mejor que solo palabras.</li>\n</ol><h2>Una idea por diapositiva</h2><p>Cada diapositiva debe responder una sola pregunta o sostener una sola idea. Si tienes tres ideas, usa tres diapositivas. Más diapositivas con menos contenido es mejor que pocas diapositivas saturadas.</p><h2>Títulos-afirmación</h2><p>Reemplaza los títulos temáticos (\"Resultados\") por oraciones que digan la conclusión (\"La doble verificación redujo los errores a la mitad\"). Si alguien solo lee los títulos de tu presentación, debería entender toda la historia. Este enfoque, conocido como afirmación-evidencia, es muy usado en comunicación científica.</p><h2>Reglas prácticas de diseño</h2><ul>\n<li><strong>Texto:</strong> máximo 20–30 palabras por diapositiva, tamaño mínimo 24 puntos en el cuerpo.</li>\n<li><strong>Tipografía:</strong> una o dos familias, sin serifa para pantalla, buen contraste.</li>\n<li><strong>Color:</strong> una paleta de 2–3 colores más grises; un color de acento para lo importante.</li>\n<li><strong>Imágenes:</strong> pertinentes y de buena calidad; evita las fotos genéricas de personas dándose la mano. Verifica licencias de uso.</li>\n<li><strong>Espacio en blanco:</strong> no llenes cada rincón; el espacio ayuda a ver lo importante.</li>\n<li><strong>Consistencia:</strong> misma posición de títulos, márgenes y estilo en todas las diapositivas.</li>\n</ul><h2>Qué hacer con el texto que sobra</h2><p>Si te cuesta quitar texto, pásalo a las <strong>notas del orador</strong> o a un <strong>documento de apoyo</strong> para entregar después. Las referencias bibliográficas pueden ir en tamaño pequeño al pie de la diapositiva y completas al final.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb03j${"tone":"consejo","title":"Ejemplo aplicado: diapositiva antes y después","html":"<p><strong>Antes:</strong> título \"Insulina glargina\"; ocho viñetas con mecanismo, dosis, conservación, efectos adversos, interacciones y presentaciones.\n<strong>Después (3 diapositivas):</strong></p>\n<ol>\n<li>\"La glargina es una insulina basal de acción prolongada\" + gráfico simple del perfil de acción.</li>\n<li>\"Antes de abrir: nevera; en uso: temperatura ambiente según el inserto\" + ícono de nevera y de termómetro.</li>\n<li>\"La hipoglucemia es el efecto adverso que más debe vigilarse\" + tres síntomas con íconos.</li>\n</ol>\n<p>Las tres diapositivas se entienden en segundos y el orador explica el detalle.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb03j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Aplica coherencia, señalización y redundancia: menos texto, más foco.</li>\n<li>Una idea por diapositiva y títulos que digan la conclusión.</li>\n<li>El detalle va en las notas o en un documento de apoyo.</li>\n</ol>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb03j${"tone":"info","title":"Siguiente paso","html":"<p>Rediseña tres diapositivas de una presentación tuya con estos principios.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo presentar datos clínicos y técnicos en diapositivas sin perder al público', 'Unidad 3 · Clase 3.2', 1, 'manual', 18, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb03j${"tone":"info","title":"En esta clase","html":"<p>Cómo presentar datos clínicos y técnicos en diapositivas: tablas simplificadas, revelado progresivo, comparaciones y fuentes. Guía para profesionales de salud.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb03j${"html":"<p>En el sector salud, las presentaciones suelen incluir estudios clínicos, tablas de dosificación, flujogramas e indicadores. Es información necesaria, pero también la que más fácilmente \"apaga\" a la audiencia. El reto es mantener el rigor sin saturar. En esta clase aprenderás técnicas para presentar tablas, estudios y procesos de forma clara y verificable.</p><h2>Presentar un estudio clínico en tres diapositivas</h2><p>En lugar de copiar el resumen del artículo, organiza:</p>\n<ol>\n<li><strong>La pregunta y el diseño:</strong> \"¿Reduce X las hospitalizaciones en pacientes con…?\" Tipo de estudio, población, número de pacientes, comparador y seguimiento.</li>\n<li><strong>El resultado principal:</strong> un gráfico o un número grande con su contexto (riesgo absoluto, relativo e intervalo de confianza para audiencias técnicas).</li>\n<li><strong>Lo que significa para nosotros:</strong> aplicabilidad a tu población, seguridad y limitaciones.</li>\n</ol><h2>Tablas simplificadas</h2><p>Las tablas completas sirven para leer, no para presentar. Para simplificarlas:</p>\n<ul>\n<li>Deja solo las filas y columnas que sostienen tu mensaje.</li>\n<li>Alinea los números a la derecha y usa el mismo número de decimales.</li>\n<li>Destaca con color la fila o celda importante.</li>\n<li>Pon el título-afirmación encima: \"Solo dos de los cinco esquemas cumplen la meta de costo\".</li>\n<li>Lleva la tabla completa al anexo o al documento de apoyo.</li>\n</ul><h2>Revelado progresivo</h2><p>Para flujogramas, algoritmos o gráficos con varias series, muestra la información <strong>por partes</strong>: primero el eje y el primer paso, luego el siguiente. Así el público sigue tu explicación en lugar de adelantarse. Usa animaciones simples (\"aparecer\"), nunca efectos llamativos.</p><h2>Comparaciones claras</h2><p>Cuando compares alternativas (medicamentos, proveedores, esquemas):</p>\n<ul>\n<li>Usa los mismos criterios en el mismo orden.</li>\n<li>Prefiere íconos o marcas simples (✓, –) a párrafos.</li>\n<li>Termina con una recomendación explícita.</li>\n</ul><h2>Rigor y trazabilidad</h2><p>Una presentación técnica pierde credibilidad cuando no se sabe de dónde salen los datos. Incluye siempre:</p>\n<ul>\n<li><strong>Fuente</strong> (autor, revista o institución, año).</li>\n<li><strong>Fecha de corte</strong> de los datos institucionales.</li>\n<li><strong>Población</strong> a la que aplica.</li>\n<li><strong>Limitaciones</strong> relevantes.</li>\n</ul>\n<p>Si mencionas información de un medicamento, verifica que coincida con el <strong>inserto o la información aprobada por el INVIMA</strong> para Colombia. Las indicaciones y dosis pueden diferir entre países.</p><h2>Normas de uso de información promocional</h2><p>Si trabajas en la industria farmacéutica, recuerda que las presentaciones a profesionales de la salud deben ser veraces, equilibradas y ajustarse a la información aprobada del producto, a la normativa colombiana y a los códigos de ética del sector. Evita comparaciones no sustentadas y usos no aprobados.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb03j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un QF presenta al comité de farmacia la comparación de tres anticoagulantes orales. Usa una diapositiva de pregunta, una tabla simplificada con cinco criterios (indicación aprobada, ajuste renal, interacciones relevantes, antídoto disponible, costo por mes), revela fila por fila y cierra con una recomendación por perfil de paciente. Las referencias completas van en un anexo entregado por correo.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb03j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Presenta un estudio en tres pasos: pregunta y diseño, resultado, aplicabilidad.</li>\n<li>Simplifica tablas, revela por partes y compara con criterios iguales.</li>\n<li>Cita fuente, fecha, población y limitaciones; verifica la información con el inserto aprobado.</li>\n</ol>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb03j${"tone":"info","title":"Siguiente paso","html":"<p>Prepara una presentación de un estudio clínico en tres diapositivas siguiendo esta estructura.</p>"}$hb03j$::jsonb);

