  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb03j${"tone":"info","title":"En esta clase","html":"<p>Cómo hacer presentaciones virtuales efectivas en Teams, Zoom o Meet: preparación técnica, interacción cada 5 minutos, cámara y manejo del chat.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb03j${"html":"<p>En una presentación virtual compites con el correo, el celular y otras pestañas abiertas. No puedes ver si la audiencia está atenta y la energía se diluye a través de la pantalla. Por eso, presentar en línea exige más estructura, más interacción y más preparación técnica que una presentación presencial. En esta clase aprenderás a diseñar y conducir presentaciones virtuales que mantienen la atención.</p><h2>Preparación técnica</h2><ul>\n<li><strong>Conexión:</strong> cable de red si es posible; cierra aplicaciones que consumen ancho de banda.</li>\n<li><strong>Cámara:</strong> a la altura de los ojos, con la cara ocupando el tercio superior del encuadre.</li>\n<li><strong>Luz:</strong> de frente (una ventana o lámpara detrás de la cámara), nunca a tu espalda.</li>\n<li><strong>Audio:</strong> un audífono con micrófono mejora mucho la calidad frente al micrófono del portátil.</li>\n<li><strong>Fondo:</strong> ordenado y neutro, o fondo desenfocado.</li>\n<li><strong>Plan B:</strong> presentación en PDF, número de teléfono del organizador y enlace alterno.</li>\n</ul><h2>Diseño para la atención en línea</h2><ul>\n<li><strong>Interacción cada 5–7 minutos:</strong> una pregunta en el chat, una encuesta, una reacción, una pausa para reflexionar.</li>\n<li><strong>Diapositivas más simples y más frecuentes:</strong> el cambio visual ayuda a mantener la atención.</li>\n<li><strong>Duración más corta:</strong> si en presencial tenías 45 minutos, apunta a 30 y deja tiempo para preguntas.</li>\n<li><strong>Agenda visible:</strong> muestra en qué parte vas.</li>\n</ul><h2>Conducción: energía y conexión</h2><ul>\n<li><strong>Mira a la cámara</strong> cuando digas lo importante, no a la pantalla. Puedes poner una nota adhesiva junto a la cámara como recordatorio.</li>\n<li><strong>Sube un poco la energía:</strong> la pantalla aplana la expresión; gesticula dentro del encuadre y varía la voz.</li>\n<li><strong>Nombra a las personas:</strong> \"Carolina, tú que manejas el inventario, ¿cómo lo ves?\" (avisa antes si vas a hacer preguntas directas).</li>\n<li><strong>Narra lo que haces:</strong> \"Voy a compartir mi pantalla… ¿la ven bien?\".</li>\n</ul><h2>Manejo del chat y las preguntas</h2><ul>\n<li>Pide a un <strong>coanfitrión</strong> que modere el chat y te pase las preguntas.</li>\n<li>Haz pausas planeadas para revisar el chat.</li>\n<li>Responde por nombre y reformula la pregunta para que todos la escuchen.</li>\n</ul><h2>Herramientas de interacción</h2><ul>\n<li>Encuestas integradas en la plataforma.</li>\n<li>Pizarras colaborativas para lluvia de ideas.</li>\n<li>Salas para grupos pequeños en talleres.</li>\n<li>Cuestionarios rápidos al final para verificar la comprensión.</li>\n</ul>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb03j${"tone":"consejo","title":"Ejemplo aplicado: capacitación virtual a una red de droguerías","html":"<p>Una QF capacita a 40 regentes sobre el reporte de eventos adversos. Abre con una encuesta: \"¿Cuántos eventos adversos reportaste el último mes?\". Divide la charla en tres bloques de 8 minutos, cada uno con un caso y una pregunta en el chat. Un coanfitrión recoge dudas. Cierra con un cuestionario de cinco preguntas. La participación en el chat se mantiene durante toda la sesión y los reportes aumentan el mes siguiente.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb03j${"tone":"advertencia","title":"Errores comunes","html":"<ul>\n<li>Leer las diapositivas con la cámara apagada.</li>\n<li>Hablar 40 minutos sin interacción.</li>\n<li>No probar la plataforma antes.</li>\n<li>Compartir la pantalla completa con notificaciones visibles.</li>\n</ul>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb03j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Prepara la tecnología y ten un plan B.</li>\n<li>Diseña interacción cada 5–7 minutos y presentaciones más cortas.</li>\n<li>Mira a la cámara, sube la energía y apóyate en un coanfitrión.</li>\n</ol>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, $hb03j${"tone":"info","title":"Siguiente paso","html":"<p>Planea tu próxima reunión virtual con al menos tres momentos de interacción.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Elevator pitch: cómo presentar una idea, un proyecto o un producto en 3 minutos', 'Unidad 4 · Clase 4.2', 1, 'manual', 18, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb03j${"tone":"info","title":"En esta clase","html":"<p>Qué es un elevator pitch y cómo hacer uno de 60 segundos o 3 minutos para presentar una idea, proyecto o producto. Estructura, ejemplos y errores comunes.</p>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb03j${"html":"<p>Un <em>elevator pitch</em> es una presentación breve y persuasiva que podrías hacer en el tiempo que dura un viaje en ascensor. Sirve para presentarte en una entrevista o en un evento de networking, para proponer un proyecto al gerente o para presentar un producto o servicio a un cliente. Cuanto menos tiempo tienes, más preparación necesitas. En esta clase construirás un pitch de 60 segundos y uno de 3 minutos.</p><h2>La estructura del pitch</h2><ol>\n<li><strong>Gancho (10 %):</strong> una frase que despierte interés: una pregunta, un dato o un problema concreto.</li>\n<li><strong>Problema (20 %):</strong> qué dolor tiene la audiencia y por qué importa ahora.</li>\n<li><strong>Solución (25 %):</strong> qué propones, en lenguaje simple.</li>\n<li><strong>Prueba (20 %):</strong> evidencia de que funciona: un piloto, un dato, un caso, una referencia.</li>\n<li><strong>Diferencial (10 %):</strong> por qué tú, por qué esto y no otra alternativa.</li>\n<li><strong>Llamado a la acción (15 %):</strong> qué pides concretamente: una reunión, un piloto, una aprobación.</li>\n</ol><h2>Pitch de 60 segundos (unas 140–160 palabras)</h2><p>Ejemplo de un QF que propone un servicio a una IPS:</p>\n<p>\"¿Sabían que muchos de los reingresos de pacientes mayores están relacionados con problemas de sus medicamentos? (gancho) En su IPS, los pacientes polimedicados salen de hospitalización con cambios en su tratamiento y nadie verifica cómo los toman en casa (problema). Propongo un programa de conciliación al egreso y una llamada de seguimiento a los siete días, a cargo de un químico farmacéutico (solución). En un piloto de tres meses con 60 pacientes en otra institución, identificamos discrepancias en la mayoría de los egresos y las resolvimos antes de que causaran daño (prueba). Lo hacemos con un formato estandarizado y reportes mensuales para su comité de calidad (diferencial). ¿Podemos agendar 30 minutos la próxima semana para mostrarles el formato y definir un piloto? (acción)\".</p>\n<p><em>Nota: si usas cifras de un piloto, deben ser reales y verificables.</em></p><h2>Pitch de 3 minutos</h2><p>Mantiene la misma estructura, pero agrega:</p>\n<ul>\n<li>Una historia breve en el problema (un paciente, un caso).</li>\n<li>Una o dos cifras adicionales en la prueba.</li>\n<li>Una frase sobre el modelo: cómo se implementa, cuánto cuesta o cuánto tiempo toma.</li>\n<li>Una respuesta anticipada a la objeción principal.</li>\n</ul><h2>Consejos para presentarlo</h2><ul>\n<li><strong>Habla de la audiencia, no de ti:</strong> \"ustedes\" más que \"nosotros\".</li>\n<li><strong>Evita la jerga</strong> si la audiencia no es técnica.</li>\n<li><strong>Ensáyalo en voz alta</strong> hasta que suene natural, no recitado.</li>\n<li><strong>Mide el tiempo:</strong> un pitch de 60 segundos que dura 90 ya no es un pitch.</li>\n<li><strong>Adapta el gancho</strong> a cada audiencia.</li>\n</ul>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb03j${"tone":"advertencia","title":"Errores comunes","html":"<ul>\n<li>Empezar con la historia de la empresa o tu hoja de vida.</li>\n<li>Intentar decir todo.</li>\n<li>No pedir nada al final.</li>\n<li>Usar cifras que no puedes sustentar.</li>\n</ul>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb03j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Gancho, problema, solución, prueba, diferencial y acción.</li>\n<li>El pitch se centra en la audiencia y termina con una petición concreta.</li>\n<li>Prepara versiones de 60 segundos y 3 minutos, y ensáyalas.</li>\n</ol>"}$hb03j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb03j${"tone":"info","title":"Siguiente paso","html":"<p>Escribe y graba tu pitch de 60 segundos para una idea o servicio real.</p>"}$hb03j$::jsonb);
END
$hb03$;

-- ─── Curso de Comunicación Asertiva en el Trabajo (8 clases) ───
DO $hb04$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Comunicación Asertiva en el Trabajo' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, area, level, tags,
     objective, learning_outcomes, audience, duration_minutes, author_name, status, modality, cover_url, publico)
  VALUES ('edvanta', 'Curso de Comunicación Asertiva en el Trabajo', $hb04t$Curso para expresar ideas, necesidades y desacuerdos con claridad y respeto: estilos de comunicación, mensajes yo, técnica DESC, decir no, escucha activa, comunicación no violenta, retroalimentación y manejo de conflictos.$hb04t$,
          $hb04t$<p>Curso para expresar ideas, necesidades y desacuerdos con claridad y respeto: estilos de comunicación, mensajes yo, técnica DESC, decir no, escucha activa, comunicación no violenta, retroalimentación y manejo de conflictos.</p><h2>Objetivo</h2><p>Que el participante identifique su estilo predominante de comunicación y aplique técnicas asertivas (DESC, mensajes yo, CNV, SBI) para pedir, negarse, dar retroalimentación y resolver conflictos en el entorno laboral.</p><h2>Para quién es</h2><p>Profesionales y auxiliares del sector farmacéutico y de la salud, coordinadores de equipo y personal de atención al público.</p><h2>Cómo está organizado</h2><p>Cuatro unidades con dos clases en texto cada una. Cada clase trae un ejemplo aplicado al sector farmacéutico y de la salud, puntos clave y el siguiente paso.</p><h2>Referentes</h2><p>Marshall B. Rosenberg (Comunicación No Violenta); Sharon y Gordon Bower (Asserting Yourself: método DESC); Manuel J. Smith (Cuando digo no, me siento culpable); Carl Rogers (escucha activa); Center for Creative Leadership (modelo SBI); Kim Scott (Radical Candor); Thomas y Kilmann (estilos de manejo de conflictos).</p>$hb04t$,
          'Comunicación interpersonal', 'Habilidades Blandas', 'basico', ARRAY['Comunicación asertiva', 'Escucha activa', 'Comunicación no violenta', 'Retroalimentación', 'Habilidades blandas']::text[],
          $hb04t$Que el participante identifique su estilo predominante de comunicación y aplique técnicas asertivas (DESC, mensajes yo, CNV, SBI) para pedir, negarse, dar retroalimentación y resolver conflictos en el entorno laboral.$hb04t$,
          ARRAY['Reconocer los estilos de comunicación y tu nivel de asertividad.', 'Expresar desacuerdos con mensajes yo y la técnica DESC, y decir no sin culpa.', 'Escuchar activamente y aplicar los cuatro pasos de la comunicación no violenta.', 'Dar y recibir retroalimentación con el modelo SBI y manejar conflictos con método.']::text[],
          $hb04t$Profesionales y auxiliares del sector farmacéutico y de la salud, coordinadores de equipo y personal de atención al público.$hb04t$,
          149, 'Edvanta', 'borrador', 'asincronica', '/img/cursos/comunicacion-asertiva.webp', 'profesionales')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Fundamentos de la asertividad', 0)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Qué es la comunicación asertiva: estilos pasivo, agresivo, pasivo-agresivo y asertivo con ejemplos', 'Unidad 1 · Clase 1.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb04j${"tone":"info","title":"En esta clase","html":"<p>Qué es la comunicación asertiva, en qué se diferencia de los estilos pasivo, agresivo y pasivo-agresivo, con ejemplos reales del trabajo.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb04j${"html":"<p>Tu jefe te pide quedarte otra vez hasta tarde. Un colega se atribuye tu trabajo. Un paciente te grita porque el medicamento no llegó. En cada una de estas situaciones puedes callar, atacar, quejarte por detrás o decir lo que piensas con claridad y respeto. Esa última opción es la comunicación asertiva. En esta clase vas a conocer los cuatro estilos de comunicación, reconocer el tuyo y entender por qué la asertividad es una habilidad que se aprende.</p><h2>¿Qué es la comunicación asertiva?</h2><p>La comunicación asertiva es la capacidad de <strong>expresar tus ideas, necesidades, opiniones y límites de forma clara, directa y honesta, respetando al mismo tiempo los derechos y la dignidad de la otra persona</strong>. No es decir siempre que sí ni imponer tu punto de vista: es encontrar el equilibrio entre el respeto por ti y el respeto por el otro.</p><h2>Los cuatro estilos de comunicación</h2><h3>Estilo pasivo</h3>\n<p>Evita el conflicto a costa de sus propias necesidades. No expresa desacuerdo, acepta tareas que no puede asumir y luego se siente frustrado.</p>\n<ul>\n<li><strong>Frases típicas:</strong> \"No hay problema\", \"Como tú digas\", \"No importa\".</li>\n<li><strong>Lenguaje corporal:</strong> mirada baja, voz baja, postura encogida.</li>\n<li><strong>Consecuencias:</strong> resentimiento, estrés, sensación de no ser tomado en cuenta.</li>\n</ul>\n<h3>Estilo agresivo</h3>\n<p>Defiende sus necesidades a costa de las de los demás. Impone, interrumpe, culpa o descalifica.</p>\n<ul>\n<li><strong>Frases típicas:</strong> \"Siempre haces todo mal\", \"Esto es tu culpa\", \"Porque lo digo yo\".</li>\n<li><strong>Lenguaje corporal:</strong> voz alta, señalar con el dedo, invadir el espacio.</li>\n<li><strong>Consecuencias:</strong> gana a corto plazo, pero daña relaciones y genera miedo o rechazo.</li>\n</ul>\n<h3>Estilo pasivo-agresivo</h3>\n<p>Parece pasivo en la superficie, pero expresa el enojo de forma indirecta: sarcasmo, indirectas, quejas a escondidas, \"olvidos\" intencionales.</p>\n<ul>\n<li><strong>Frases típicas:</strong> \"Ah, qué bien que por fin llegaste\", \"Haz lo que quieras\".</li>\n<li><strong>Consecuencias:</strong> confusión, desconfianza, conflictos que nunca se resuelven.</li>\n</ul>\n<h3>Estilo asertivo</h3>\n<p>Expresa con claridad lo que piensa y necesita, escucha y busca soluciones.</p>\n<ul>\n<li><strong>Frases típicas:</strong> \"Entiendo que es urgente. Hoy no puedo quedarme; puedo dejarlo listo mañana a las 9.\"</li>\n<li><strong>Lenguaje corporal:</strong> contacto visual, voz firme y tranquila, postura abierta.</li>\n<li><strong>Consecuencias:</strong> relaciones de confianza, problemas resueltos, menos estrés.</li>\n</ul><h2>Ejemplo: una misma situación, cuatro respuestas</h2><p>Situación: la coordinadora le pide a una auxiliar cubrir el turno del domingo por tercera vez en el mes.</p>\n<ul>\n<li><strong>Pasiva:</strong> \"Sí, claro\" (y cancela el almuerzo familiar con rabia).</li>\n<li><strong>Agresiva:</strong> \"¡Siempre me toca a mí! Aquí abusan de uno.\"</li>\n<li><strong>Pasivo-agresiva:</strong> \"Bueno… como aquí solo existo yo…\" (y llega tarde el domingo).</li>\n<li><strong>Asertiva:</strong> \"Ya cubrí dos domingos este mes y tengo un compromiso familiar. Este domingo no puedo. Si quieres, te ayudo a revisar quién está disponible o propongo una rotación.\"</li>\n</ul><h2>La asertividad se aprende</h2><p>Nadie es asertivo en todas las situaciones. Puedes ser asertivo con tus compañeros y pasivo con tu jefe, o agresivo cuando estás cansado. La asertividad es un conjunto de habilidades —qué decir, cómo decirlo y cuándo— que mejoran con práctica.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb04j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La asertividad equilibra el respeto por ti y por el otro.</li>\n<li>Los estilos pasivo, agresivo y pasivo-agresivo tienen costos para la persona y para el equipo.</li>\n<li>Tu estilo puede cambiar según la situación; la asertividad se entrena.</li>\n</ol>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb04j${"tone":"info","title":"Siguiente paso","html":"<p>Recuerda tres situaciones laborales recientes y clasifica cómo respondiste en cada una.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Derechos asertivos y autodiagnóstico: ¿qué tan asertivo eres?', 'Unidad 1 · Clase 1.2', 1, 'manual', 18, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb04j${"tone":"info","title":"En esta clase","html":"<p>Cómo ser asertivo empezando por tus derechos asertivos y un autodiagnóstico práctico. Identifica en qué situaciones y con quién te cuesta más.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb04j${"html":"<p>Muchas personas no son asertivas porque, en el fondo, sienten que no tienen derecho a decir que no, a equivocarse o a pedir. Antes de aprender técnicas, conviene revisar esas creencias. En esta clase conocerás los derechos asertivos, harás un autodiagnóstico y descubrirás en qué situaciones y con qué personas te cuesta más comunicarte con asertividad.</p><h2>¿Qué son los derechos asertivos?</h2><p>Son principios que reconocen que todas las personas, en igualdad de condiciones, pueden expresar sus necesidades y límites. El psicólogo Manuel J. Smith los popularizó en su libro <em>Cuando digo no, me siento culpable</em>. Adaptados al trabajo, algunos son:</p>\n<ol>\n<li>Derecho a ser tratado con respeto y dignidad.</li>\n<li>Derecho a decir no sin sentirte culpable.</li>\n<li>Derecho a expresar tus opiniones y sentimientos.</li>\n<li>Derecho a pedir lo que necesitas (sabiendo que el otro puede decir no).</li>\n<li>Derecho a equivocarte y hacerte responsable de tus errores.</li>\n<li>Derecho a cambiar de opinión.</li>\n<li>Derecho a decir \"no lo sé\" o \"no entiendo\".</li>\n<li>Derecho a pedir tiempo para pensar antes de responder.</li>\n<li>Derecho a establecer prioridades y límites.</li>\n<li>Derecho a no justificarte en exceso.</li>\n</ol>\n<p><strong>Importante:</strong> cada derecho implica una responsabilidad. Tu derecho a decir no convive con el derecho del otro a pedir. Los derechos asertivos tampoco te eximen de tus funciones laborales ni de las normas; te permiten negociarlas con respeto.</p><h2>Creencias que bloquean la asertividad</h2><ul>\n<li>\"Si digo que no, van a pensar que no soy buen compañero.\"</li>\n<li>\"Pedir ayuda es mostrar debilidad.\"</li>\n<li>\"Si expreso mi desacuerdo, voy a generar un conflicto.\"</li>\n<li>\"Mi jefe siempre tiene la razón.\"</li>\n<li>\"Debo saberlo todo.\"</li>\n</ul>\n<p>Identificar estas creencias es el primer paso para cuestionarlas.</p><h2>Autodiagnóstico: tres dimensiones</h2><p>Responde de 1 (nunca) a 5 (siempre):</p>\n<p><strong>Expresar:</strong></p>\n<ul>\n<li>Digo lo que pienso aunque los demás opinen distinto.</li>\n<li>Expreso mis desacuerdos con mi jefe.</li>\n<li>Pido aclaraciones cuando no entiendo una instrucción.</li>\n</ul>\n<p><strong>Defender límites:</strong></p>\n<ul>\n<li>Digo que no cuando una solicitud no es razonable.</li>\n<li>Pido que me traten con respeto cuando no lo hacen.</li>\n<li>No acepto tareas que no puedo cumplir.</li>\n</ul>\n<p><strong>Pedir y recibir:</strong></p>\n<ul>\n<li>Pido ayuda cuando la necesito.</li>\n<li>Acepto elogios sin minimizarlos.</li>\n<li>Recibo críticas sin atacar ni justificarme en exceso.</li>\n</ul>\n<p>Puntuaciones bajas en una dimensión te indican dónde concentrar tu práctica.</p><h2>El mapa de situaciones</h2><p>Además de la puntuación, identifica <strong>con quién</strong> y <strong>en qué situaciones</strong> te cuesta más:</p>\n<ul>\n<li>¿Con figuras de autoridad (jefes, médicos)?</li>\n<li>¿Con pacientes o clientes molestos?</li>\n<li>¿Con compañeros cercanos?</li>\n<li>¿Cuando estás cansado o bajo presión?</li>\n</ul>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb04j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una QF recién llegada a un hospital nota en su autodiagnóstico que con sus compañeros es asertiva, pero con los médicos es pasiva: cuando detecta un posible error en una prescripción, duda en llamar. Reconoce la creencia \"el médico sabe más que yo\" y la reemplaza por \"mi función es contribuir a la seguridad del paciente; preguntar es parte de mi trabajo\". Esa será su meta principal del curso.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb04j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Los derechos asertivos reconocen que puedes expresar necesidades y límites, con responsabilidad.</li>\n<li>Las creencias limitantes suelen estar detrás de la falta de asertividad.</li>\n<li>El autodiagnóstico te muestra en qué dimensión y con quién te cuesta más.</li>\n</ol>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb04j${"tone":"info","title":"Siguiente paso","html":"<p>Completa el cuestionario y escribe tu meta asertiva principal para este curso.</p>"}$hb04j$::jsonb);

