  VALUES (v_curso, 'Unidad 2. Técnicas para expresar, pedir y decir no', 1)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Mensajes yo y técnica DESC: cómo expresar un desacuerdo sin atacar', 'Unidad 2 · Clase 2.1', 0, 'manual', 18, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb04j${"tone":"info","title":"En esta clase","html":"<p>Ejemplos de comunicación asertiva con mensajes yo y la técnica DESC (describir, expresar, especificar, consecuencias) para expresar desacuerdos en el trabajo.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb04j${"html":"<p>\"Tú nunca avisas\", \"Usted siempre llega tarde\", \"Ustedes no entienden nada\". Los mensajes que empiezan por \"tú\" suelen sonar a acusación, y la otra persona reacciona defendiéndose. Cambiar la forma de formular un mensaje puede transformar una discusión en una conversación. En esta clase aprenderás dos herramientas: los mensajes yo y la técnica DESC.</p><h2>Mensajes tú vs. mensajes yo</h2><p>Un <strong>mensaje tú</strong> pone el foco en el otro y suele incluir un juicio: \"Eres desordenado\".\nUn <strong>mensaje yo</strong> pone el foco en lo que observas, lo que sientes y lo que necesitas: \"Cuando encuentro los medicamentos fuera de su lugar, me preocupo porque podemos dispensar uno equivocado. Necesito que volvamos a dejarlos en su estante.\"</p>\n<p>Estructura del mensaje yo:</p>\n<ol>\n<li><strong>Cuando…</strong> (hecho concreto y observable).</li>\n<li><strong>Me siento…</strong> (emoción).</li>\n<li><strong>Porque…</strong> (impacto o necesidad).</li>\n<li><strong>Necesito / te propongo…</strong> (petición).</li>\n</ol><h2>La técnica DESC</h2><p>Propuesta por Sharon y Gordon Bower, la técnica DESC organiza un mensaje asertivo en cuatro pasos. Es útil para conversaciones que preparas con anticipación.</p>\n<ul>\n<li><strong>D — Describir:</strong> el comportamiento concreto, sin juicios ni generalizaciones. \"En las últimas tres semanas, el reporte de inventario llegó después de las 10 a. m.\"</li>\n<li><strong>E — Expresar:</strong> cómo te afecta o qué sientes. \"Me preocupa porque el pedido al proveedor se cierra a las 9 y quedamos sin reponer.\"</li>\n<li><strong>S — Especificar:</strong> qué cambio concreto pides. \"Te pido que lo envíes antes de las 8:30 a. m. ¿Qué necesitarías para lograrlo?\"</li>\n<li><strong>C — Consecuencias:</strong> el beneficio de hacer el cambio (y, si es necesario, lo que pasará si no). \"Así evitamos los agotados de los lunes y nos ahorramos los reclamos.\"</li>\n</ul><h2>Reglas para describir sin juzgar</h2><ul>\n<li>Usa hechos observables: fechas, cantidades, acciones.</li>\n<li>Evita \"siempre\" y \"nunca\".</li>\n<li>Evita etiquetas: \"irresponsable\", \"desorganizado\", \"grosero\".</li>\n<li>Habla de la conducta, no de la persona.</li>\n</ul>\n<table><thead><tr><th>Juicio</th><th>Descripción</th></tr></thead><tbody><tr><td>\"Eres irresponsable\"</td><td>\"Esta semana no se registraron dos recepciones de termolábiles.\"</td></tr><tr><td>\"Siempre me interrumpes\"</td><td>\"En la reunión, me interrumpiste dos veces mientras presentaba.\"</td></tr><tr><td>\"No te importa el equipo\"</td><td>\"No has respondido los tres correos del cronograma.\"</td></tr></tbody></table><h2>Cuándo y dónde</h2><ul>\n<li><strong>En privado:</strong> nunca corrijas en público.</li>\n<li><strong>Pronto:</strong> cerca del hecho, pero no en caliente.</li>\n<li><strong>Con tiempo:</strong> no en el pasillo ni con prisa.</li>\n</ul>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb04j${"tone":"consejo","title":"Ejemplo aplicado: con un médico","html":"<p>Una QF detecta por tercera vez prescripciones de un medicamento con dosis que superan la máxima recomendada en pacientes con falla renal. Prepara un DESC: \"Doctor, en los últimos 15 días encontré tres fórmulas con dosis que superan las recomendadas para la función renal del paciente (D). Me preocupa el riesgo de toxicidad (E). Le propongo que revisemos juntos la tabla de ajuste renal y que yo le avise cada vez que lo detecte (S). Así reducimos el riesgo y el tiempo de devolución de las fórmulas (C).\"</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb04j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Los mensajes yo describen hechos, emociones y necesidades sin acusar.</li>\n<li>DESC: describir, expresar, especificar y consecuencias.</li>\n<li>Describe conductas concretas, sin juicios, en privado y con tiempo.</li>\n</ol>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb04j${"tone":"info","title":"Siguiente paso","html":"<p>Prepara un DESC para una situación pendiente en tu trabajo.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo decir no en el trabajo sin sentirte culpable: técnicas asertivas', 'Unidad 2 · Clase 2.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb04j${"tone":"info","title":"En esta clase","html":"<p>Cómo decir no en el trabajo sin sentirte culpable: no empático, disco rayado, banco de niebla y aplazamiento asertivo, con frases de ejemplo.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb04j${"html":"<p>Decir que sí a todo parece una forma de ser buen compañero, pero tiene un costo: sobrecarga, errores por cansancio y frustración. Decir no de forma asertiva no es negarse a colaborar; es proteger tu capacidad de hacer bien lo que ya te comprometiste a hacer. En esta clase aprenderás cinco técnicas para negarte con respeto y firmeza.</p><h2>Por qué nos cuesta decir no</h2><ul>\n<li>Miedo a decepcionar o a parecer poco comprometido.</li>\n<li>Deseo de agradar.</li>\n<li>Temor a consecuencias laborales.</li>\n<li>Hábito: \"siempre he sido el que ayuda\".</li>\n</ul>\n<p>Recuerda: cada sí a algo es un no a otra cosa (tu tiempo, tu descanso, tus prioridades).</p><h2>Técnica 1: el no empático</h2><p>Reconoce la necesidad del otro y luego di no con claridad.\n\"Entiendo que necesitas cerrar el informe hoy. No puedo ayudarte esta tarde porque tengo la auditoría de medicamentos de control.\"</p><h2>Técnica 2: el no con alternativa</h2><p>Ofrece otra opción cuando sea posible.\n\"Hoy no puedo, pero mañana a las 10 tengo una hora libre y te ayudo a revisarlo.\"\n\"No puedo cubrir el turno completo; puedo quedarme hasta las 4.\"</p><h2>Técnica 3: el disco rayado</h2><p>Cuando la otra persona insiste, repite tu respuesta con calma, con las mismas o parecidas palabras, sin entrar en discusiones ni nuevas justificaciones.\n—\"Pero es que es urgente.\"\n—\"Entiendo que es urgente; hoy no puedo.\"\n—\"Solo es un ratico.\"\n—\"Lo sé; hoy no puedo.\"</p><h2>Técnica 4: el banco de niebla</h2><p>Útil ante críticas o presiones manipuladoras. Reconoces la parte de verdad que pueda tener el comentario sin ceder en tu decisión.\n—\"Antes siempre ayudabas.\"\n—\"Es cierto, antes ayudaba más. Ahora tengo otras responsabilidades y hoy no puedo.\"</p><h2>Técnica 5: el aplazamiento asertivo</h2><p>Pide tiempo para pensar antes de responder, sobre todo si tiendes a decir sí automáticamente.\n\"Déjame revisar mi agenda y te confirmo en una hora.\"</p><h2>Decir no a un jefe</h2><p>Con un superior, el no suele tomar la forma de una <strong>negociación de prioridades</strong>:\n\"Puedo hacer el informe de rotación para el viernes. Si lo hago, el inventario de la bodega 2 pasa para el lunes. ¿Cuál prefieres que priorice?\"\nAsí no te niegas a la tarea, sino que haces visible el costo y le devuelves la decisión a quien la tiene.</p><h2>Lo que no debes hacer</h2><ul>\n<li>Justificarte en exceso: cuantas más excusas das, más argumentos tiene el otro para insistir.</li>\n<li>Mentir: inventar compromisos genera desconfianza si se descubre.</li>\n<li>Decir \"tal vez\" cuando quieres decir no: solo aplaza el conflicto.</li>\n<li>Disculparte de forma repetida.</li>\n</ul><h2>Cuándo no aplica decir no</h2><p>Hay situaciones en las que las funciones del cargo, la normativa o la seguridad del paciente obligan. En esos casos, la asertividad consiste en expresar tus límites o condiciones (\"Puedo hacerlo, pero necesito apoyo para…\") y en usar los canales formales cuando la carga sea permanentemente excesiva.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb04j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un visitador médico recibe una solicitud de un médico para conseguir muestras médicas en cantidades que superan la política de la compañía. Usa el no empático con alternativa: \"Doctor, entiendo que las muestras le sirven para sus pacientes. No puedo entregarle esa cantidad por la política de la compañía. Lo que sí puedo hacer es traerle el material educativo para pacientes y la información del programa de apoyo.\"</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb04j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Decir no protege tu capacidad de cumplir bien tus compromisos.</li>\n<li>No empático, con alternativa, disco rayado, banco de niebla y aplazamiento.</li>\n<li>Con un jefe, convierte el no en una negociación de prioridades.</li>\n</ol>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb04j${"tone":"info","title":"Siguiente paso","html":"<p>Practica en parejas el disco rayado y el banco de niebla con el guion de juego de roles.</p>"}$hb04j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 3. Escuchar y conectar', 2)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Escucha activa: qué es, técnicas y ejemplos para escuchar de verdad', 'Unidad 3 · Clase 3.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb04j${"tone":"info","title":"En esta clase","html":"<p>Qué es la escucha activa, sus técnicas (parafrasear, reflejar, resumir, preguntar) y ejemplos para aplicarla con compañeros, jefes y pacientes.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb04j${"html":"<p>La asertividad no es solo hablar con claridad; también es escuchar de verdad. Muchas discusiones se alargan porque cada persona está preparando su respuesta mientras la otra habla. La escucha activa rompe ese ciclo: cuando la otra persona se siente escuchada, baja la defensa y se abre a buscar soluciones. En esta clase aprenderás las técnicas de escucha activa y practicarás cómo aplicarlas.</p><h2>¿Qué es la escucha activa?</h2><p>El concepto fue desarrollado por los psicólogos Carl Rogers y Richard Farson. La escucha activa es <strong>prestar atención completa a lo que la otra persona dice y siente, y demostrarle que la has comprendido</strong>. No significa estar de acuerdo, sino entender antes de responder.</p><h2>Los tres niveles de escucha</h2><ol>\n<li><strong>Escucha interna:</strong> te escuchas a ti mismo mientras el otro habla (\"¿qué voy a responder?\").</li>\n<li><strong>Escucha enfocada:</strong> te concentras en las palabras del otro.</li>\n<li><strong>Escucha global:</strong> captas palabras, emociones, tono, lenguaje corporal y lo que no se dice.</li>\n</ol>\n<p>El objetivo es pasar del nivel 1 al 2 y al 3.</p><h2>Seis técnicas de escucha activa</h2><h3>1. Atención plena</h3>\n<p>Deja el celular, mira a la persona, orienta tu cuerpo hacia ella. Asiente y usa expresiones breves (\"ajá\", \"entiendo\") para mostrar que sigues la conversación.</p>\n<h3>2. Parafrasear</h3>\n<p>Repite con tus palabras lo que entendiste: \"Entonces, lo que me dices es que el pedido llegó incompleto y nadie te avisó.\"</p>\n<h3>3. Reflejar emociones</h3>\n<p>Nombra la emoción que percibes: \"Parece que eso te frustró bastante.\"</p>\n<h3>4. Preguntas abiertas</h3>\n<p>Invita a ampliar: \"¿Qué pasó después?\", \"¿Cómo te afectó?\", \"¿Qué te gustaría que hiciéramos?\". Evita las preguntas que empiezan por \"¿por qué no…?\" porque suenan a reproche.</p>\n<h3>5. Resumir</h3>\n<p>Al final, recoge los puntos principales: \"Hablamos de tres cosas: el retraso, la falta de aviso y la necesidad de un responsable. ¿Me faltó algo?\"</p>\n<h3>6. Silencio</h3>\n<p>Después de que la persona termina, espera un par de segundos. Muchas veces agrega lo más importante.</p><h2>Barreras para escuchar</h2><ul>\n<li><strong>Interrumpir</strong> o terminar las frases del otro.</li>\n<li><strong>Aconsejar demasiado pronto:</strong> \"Lo que tienes que hacer es…\".</li>\n<li><strong>Minimizar:</strong> \"No es para tanto\".</li>\n<li><strong>Cambiar el foco a ti:</strong> \"A mí me pasó algo peor…\".</li>\n<li><strong>Juzgar</strong> mientras escuchas.</li>\n</ul><h2>Escucha activa con pacientes</h2><p>En la atención farmacéutica, escuchar bien es una herramienta clínica. El paciente que dice \"esas pastillas me caen mal\" puede estar describiendo un efecto adverso, una mala técnica de administración o una creencia. Parafrasear (\"¿Me dice que siente náuseas cuando toma la metformina?\") y preguntar (\"¿Cómo la está tomando, con o sin comida?\") permite identificar el problema real.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb04j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una auxiliar llega molesta a decirle a su coordinadora que \"nadie la ayuda\". En lugar de defender al equipo, la coordinadora escucha: \"Te sientes sola con la carga del mostrador en la hora pico (reflejo). ¿En qué momentos es más pesado? (pregunta abierta)\". Descubren que el problema es de 12 a 2, cuando los demás almuerzan al tiempo. Ajustan los horarios.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb04j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Escuchar activamente es entender antes de responder, no necesariamente estar de acuerdo.</li>\n<li>Parafrasear, reflejar, preguntar, resumir y usar el silencio.</li>\n<li>Evita interrumpir, aconsejar pronto, minimizar o cambiar el foco a ti.</li>\n</ol>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb04j${"tone":"info","title":"Siguiente paso","html":"<p>En tu próxima conversación importante, practica parafrasear al menos dos veces antes de dar tu opinión.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Comunicación no violenta (CNV): los 4 pasos de Marshall Rosenberg con ejemplos', 'Unidad 3 · Clase 3.2', 1, 'manual', 18, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb04j${"tone":"info","title":"En esta clase","html":"<p>Qué es la comunicación no violenta de Marshall Rosenberg y cómo aplicar sus 4 pasos: observación, sentimiento, necesidad y petición, con ejemplos laborales.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb04j${"html":"<p>La comunicación no violenta, desarrollada por el psicólogo estadounidense Marshall B. Rosenberg, parte de una idea sencilla: detrás de cada queja, crítica o reclamo hay una necesidad no satisfecha. Si aprendemos a expresar nuestras necesidades y a escuchar las de los demás sin juicios, los conflictos se vuelven más fáciles de resolver. En esta clase aprenderás los cuatro pasos de la CNV y cómo aplicarlos en el trabajo.</p><h2>Los cuatro componentes de la CNV</h2><h3>1. Observación (sin evaluación)</h3>\n<p>Describe lo que ves u oyes, como si fuera una cámara de video. Rosenberg insistía en que separar la observación de la evaluación es una de las tareas más difíciles y más importantes.</p>\n<ul>\n<li>Evaluación: \"Eres desconsiderado con el equipo.\"</li>\n<li>Observación: \"En las dos últimas reuniones llegaste 20 minutos tarde.\"</li>\n</ul>\n<h3>2. Sentimiento</h3>\n<p>Expresa la emoción que te genera. Cuidado con los falsos sentimientos que en realidad son juicios sobre el otro: \"me siento ignorado\", \"me siento manipulado\". Usa emociones reales: preocupado, frustrado, tranquilo, agradecido, cansado.</p>\n<h3>3. Necesidad</h3>\n<p>Identifica la necesidad que está detrás del sentimiento: respeto, colaboración, claridad, descanso, seguridad, reconocimiento, previsibilidad.\n\"Me siento frustrado porque necesito que el tiempo de la reunión se aproveche para todos.\"</p>\n<h3>4. Petición</h3>\n<p>Pide una acción concreta, positiva y realizable. Una petición se diferencia de una exigencia en que acepta un no y busca alternativas.</p>\n<ul>\n<li>Vaga: \"Necesito que te comprometas más.\"</li>\n<li>Concreta: \"¿Podrías avisarme por chat si vas a llegar después de la hora de inicio?\"</li>\n</ul><h2>La fórmula completa</h2><p>\"Cuando [observación], me siento [sentimiento] porque necesito [necesidad]. ¿Estarías dispuesto a [petición]?\"</p>\n<p>No hace falta decirlo siempre con esta estructura exacta: con práctica, se vuelve natural.</p><h2>Escuchar con empatía usando CNV</h2><p>La CNV también sirve para escuchar. Cuando alguien te ataca o se queja, intenta adivinar su sentimiento y su necesidad:\nPaciente: \"¡Esta droguería es un desastre, nunca tienen nada!\"\nRespuesta CNV: \"Parece que está muy molesto porque necesitaba el medicamento hoy y no lo encontró. ¿Es así?\"\nNo estás aceptando la acusación; estás conectando con lo que la persona necesita. Desde ahí, es más fácil buscar una solución.</p><h2>Transformar frases</h2><table><thead><tr><th>Frase reactiva</th><th>Versión CNV</th></tr></thead><tbody><tr><td>\"Ustedes nunca entregan a tiempo.\"</td><td>\"El pedido de esta semana llegó el jueves y no el martes. Me preocupa porque necesito previsibilidad para atender a los pacientes. ¿Podemos acordar un aviso si hay retraso?\"</td></tr><tr><td>\"Usted no me explica nada.\"</td><td>\"No me quedó claro cómo registrar las devoluciones. Me siento inseguro porque necesito hacerlo bien. ¿Me lo puede mostrar una vez más?\"</td></tr></tbody></table><h2>Límites de la CNV</h2><p>La CNV no es un guion para manipular ni una forma de evitar los límites. Hay situaciones (acoso, agresión, riesgo para un paciente) en las que se debe actuar con firmeza y usar los canales institucionales.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb04j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Observación, sentimiento, necesidad y petición.</li>\n<li>Separa observaciones de evaluaciones y peticiones de exigencias.</li>\n<li>También puedes escuchar con CNV: adivina el sentimiento y la necesidad del otro.</li>\n</ol>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb04j${"tone":"info","title":"Siguiente paso","html":"<p>Transforma tres frases reactivas que hayas dicho o escuchado recientemente al formato CNV.</p>"}$hb04j$::jsonb);

