  VALUES (v_clase, 'destacado', 0, $hb04j${"tone":"info","title":"En esta clase","html":"<p>Cómo dar retroalimentación efectiva con el modelo SBI (situación, comportamiento, impacto) y cómo recibir críticas en el trabajo sin ponerte a la defensiva.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb04j${"html":"<p>La retroalimentación es una de las herramientas más poderosas para mejorar el desempeño, pero también una de las más evitadas. Algunos la dan con tanta suavidad que el mensaje se pierde; otros, con tanta dureza que la persona solo escucha el ataque. En esta clase aprenderás el modelo SBI para dar retroalimentación clara y útil, y una secuencia para recibir críticas con apertura.</p><h2>El modelo SBI</h2><p>Desarrollado por el Center for Creative Leadership, el modelo SBI tiene tres componentes:</p>\n<ul>\n<li><strong>S — Situación:</strong> cuándo y dónde ocurrió. \"Ayer, en la entrega de turno de las 2 p. m.…\"</li>\n<li><strong>B — Comportamiento</strong> (<em>behavior</em>): qué hizo la persona, de forma observable. \"…entregaste el reporte de pendientes por escrito con el nombre de cada paciente y la fecha probable de entrega…\"</li>\n<li><strong>I — Impacto:</strong> qué efecto tuvo. \"…y el turno de la tarde pudo llamar a los pacientes sin tener que buscar la información. Nos ahorró casi una hora.\"</li>\n</ul>\n<p>Después, abre la conversación: \"¿Cómo lo ves?\" o, si es una retroalimentación de mejora, \"¿Qué podríamos hacer diferente?\".</p><h2>Retroalimentación de mejora con SBI</h2><p>\"En la reunión del lunes con el proveedor (S), dijiste frente a él que nuestro inventario 'era un desastre' (B). Eso debilitó nuestra posición para negociar los plazos (I). ¿Qué pasó? ¿Cómo podríamos manejarlo la próxima vez?\"</p><h2>Franqueza con cuidado</h2><p>Kim Scott, en su libro <em>Radical Candor</em>, propone que la buena retroalimentación combina dos cosas: <strong>preocuparse personalmente</strong> por la persona y <strong>desafiar directamente</strong> su desempeño. Cuando falta el cuidado, la retroalimentación se vuelve agresiva; cuando falta el desafío, se vuelve una empatía inútil que no ayuda a mejorar.</p><h2>Por qué evitar el \"sándwich\"</h2><p>El famoso sándwich (elogio–crítica–elogio) suele fallar: la persona aprende a esperar la crítica cada vez que recibe un elogio, o se queda solo con lo positivo. Es mejor dar retroalimentación positiva y de mejora por separado, de forma frecuente y específica.</p><h2>Reglas de oro</h2><ul>\n<li><strong>Oportuna:</strong> cerca del hecho.</li>\n<li><strong>Específica:</strong> conductas concretas, no rasgos de personalidad.</li>\n<li><strong>Privada</strong> si es de mejora; puede ser pública si es de reconocimiento (según la persona).</li>\n<li><strong>Frecuente:</strong> no esperes a la evaluación anual.</li>\n<li><strong>Bidireccional:</strong> pregunta y escucha.</li>\n</ul><h2>Cómo recibir críticas</h2><p>Recibir una crítica activa nuestras defensas. Sigue estos cuatro pasos:</p>\n<ol>\n<li><strong>Escucha hasta el final</strong> sin interrumpir ni justificarte.</li>\n<li><strong>Agradece:</strong> \"Gracias por decírmelo.\" No significa que estés de acuerdo; reconoce el esfuerzo del otro.</li>\n<li><strong>Pide precisión:</strong> \"¿Me das un ejemplo concreto?\", \"¿Qué te gustaría que hiciera diferente?\".</li>\n<li><strong>Decide qué tomar:</strong> puedes estar de acuerdo, parcialmente de acuerdo o en desacuerdo. Si es necesario, pide tiempo para pensarlo.</li>\n</ol>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb04j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una QF directora técnica nota que un regente nuevo omite verificar la fecha de vencimiento en la recepción. Usa SBI: \"Esta mañana, en la recepción del pedido de antibióticos (S), registraste los lotes sin revisar la fecha de vencimiento (B). Si entra un producto próximo a vencer, podemos dispensarlo vencido o tener que devolverlo con pérdida (I). ¿Qué te dificultó revisarlo? ¿Te sirve que repasemos el procedimiento?\"</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb04j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>SBI: situación, comportamiento e impacto, y luego una pregunta abierta.</li>\n<li>Combina cuidado personal y desafío directo; evita el sándwich.</li>\n<li>Para recibir críticas: escucha, agradece, pide precisión y decide.</li>\n</ol>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb04j${"tone":"info","title":"Siguiente paso","html":"<p>Da una retroalimentación positiva con SBI a un compañero esta semana.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Manejo de conflictos en el trabajo: 5 estilos y un método para resolver desacuerdos', 'Unidad 4 · Clase 4.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb04j${"tone":"info","title":"En esta clase","html":"<p>Manejo de conflictos en el trabajo: los 5 estilos de Thomas-Kilmann y un método de 6 pasos para resolver desacuerdos con ejemplos del sector salud.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb04j${"html":"<p>Los conflictos en el trabajo son inevitables: distintas prioridades, recursos limitados, turnos, cargas de trabajo y formas de pensar. El problema no es el conflicto en sí, sino cómo se maneja. Un conflicto bien gestionado puede mejorar procesos y fortalecer relaciones; uno evitado o mal manejado se convierte en un clima laboral tóxico. En esta clase conocerás cinco estilos de manejo de conflictos y un método de seis pasos para resolverlos.</p><h2>Los cinco estilos de Thomas-Kilmann</h2><p>Kenneth Thomas y Ralph Kilmann describieron cinco formas de responder a un conflicto, según dos dimensiones: cuánto te enfocas en tus propios intereses (asertividad) y cuánto en los del otro (cooperación).</p>\n<ol>\n<li><strong>Competir</strong> (alta asertividad, baja cooperación): \"Se hace como yo digo.\" Útil en emergencias o cuando está en juego la seguridad del paciente. Desgasta si se usa siempre.</li>\n<li><strong>Acomodarse</strong> (baja asertividad, alta cooperación): \"Hagámoslo como tú quieras.\" Útil cuando el tema importa más al otro o para preservar la relación. Riesgoso si se vuelve hábito.</li>\n<li><strong>Evitar</strong> (baja en ambas): \"Mejor no toquemos el tema.\" Útil si el asunto es trivial o los ánimos están muy calientes. Peligroso si el problema es importante.</li>\n<li><strong>Transigir o ceder mutuamente</strong> (media en ambas): \"Partamos la diferencia.\" Útil cuando hay presión de tiempo y poderes similares.</li>\n<li><strong>Colaborar</strong> (alta en ambas): \"Busquemos una solución que funcione para los dos.\" Ideal para temas importantes; requiere tiempo y confianza.</li>\n</ol>\n<p>No hay un estilo correcto para todo. La habilidad está en <strong>elegir el estilo según la situación</strong>.</p><h2>Método de seis pasos para una conversación de conflicto</h2><h3>1. Prepárate</h3>\n<p>Define qué quieres lograr, cuáles son tus intereses y cuáles podrían ser los del otro. Elige momento y lugar privados.</p>\n<h3>2. Abre con un propósito compartido</h3>\n<p>\"Quiero que hablemos de cómo nos estamos repartiendo los turnos, porque a los dos nos interesa que el servicio funcione y no quemarnos.\"</p>\n<h3>3. Escucha primero</h3>\n<p>Pide su perspectiva y aplica escucha activa: parafrasea, refleja, pregunta.</p>\n<h3>4. Expresa tu perspectiva</h3>\n<p>Usa DESC o CNV: hechos, impacto, necesidades.</p>\n<h3>5. Busca opciones juntos</h3>\n<p>Separa la generación de ideas de la evaluación. \"¿Qué alternativas tenemos?\" Anota todas antes de descartar.</p>\n<h3>6. Acuerda y haz seguimiento</h3>\n<p>Define quién hace qué y cuándo, y una fecha para revisar si funciona.</p><h2>Cuándo escalar</h2><p>Algunos conflictos no se resuelven entre las partes: acoso laboral, discriminación, riesgos para la seguridad del paciente o incumplimientos normativos. En Colombia, la Ley 1010 de 2006 regula el acoso laboral y las empresas deben tener mecanismos como el comité de convivencia laboral. Conoce los canales de tu organización.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb04j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Conflicto entre la QF de farmacia hospitalaria y la jefe de enfermería por los horarios de entrega de medicamentos a los pisos. Cada una culpaba a la otra de los retrasos. En una conversación con el método de seis pasos descubren el interés común (que los pacientes reciban la dosis a tiempo) y la causa real (las fórmulas llegan juntas a las 10 a. m.). Acuerdan dos cortes de entrega y revisan los resultados a las dos semanas.</p>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb04j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Competir, acomodarse, evitar, transigir y colaborar: cada estilo tiene su momento.</li>\n<li>Prepárate, abre con propósito compartido, escucha, expresa, busca opciones y acuerda.</li>\n<li>Conoce cuándo y cómo escalar por canales institucionales.</li>\n</ol>"}$hb04j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb04j${"tone":"info","title":"Siguiente paso","html":"<p>Identifica tu estilo predominante y prepara una conversación pendiente con los seis pasos.</p>"}$hb04j$::jsonb);
END
$hb04$;

-- ─── Curso de Lenguaje Corporal y Comunicación No Verbal (8 clases) ───
DO $hb05$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Lenguaje Corporal y Comunicación No Verbal' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, area, level, tags,
     objective, learning_outcomes, audience, duration_minutes, author_name, status, modality, cover_url, publico)
  VALUES ('edvanta', 'Curso de Lenguaje Corporal y Comunicación No Verbal', $hb05t$Curso para comprender y usar la comunicación no verbal con rigor: canales (kinésica, proxémica, paralenguaje, háptica, apariencia), mitos frecuentes, postura, gestos, mirada, voz, uso del espacio en el mostrador y la consulta, lectura contextual de otros y comunicación en cámara.$hb05t$,
          $hb05t$<p>Curso para comprender y usar la comunicación no verbal con rigor: canales (kinésica, proxémica, paralenguaje, háptica, apariencia), mitos frecuentes, postura, gestos, mirada, voz, uso del espacio en el mostrador y la consulta, lectura contextual de otros y comunicación en cámara.</p><h2>Objetivo</h2><p>Que el participante alinee su comunicación no verbal con su mensaje verbal, interprete señales no verbales de otros de forma contextual y prudente, y adapte su presencia a la atención presencial y virtual.</p><h2>Para quién es</h2><p>Profesionales de atención al paciente, visitadores médicos, equipos comerciales, docentes y personas que se preparan para entrevistas.</p><h2>Cómo está organizado</h2><p>Cuatro unidades con dos clases en texto cada una. Cada clase trae un ejemplo aplicado al sector farmacéutico y de la salud, puntos clave y el siguiente paso.</p><h2>Referentes</h2><p>Albert Mehrabian (estudios de 1967 y su uso correcto); Paul Ekman (expresiones faciales de las emociones); Lisa Feldman Barrett (críticas a la lectura universal de emociones); Edward T. Hall (proxémica, The Hidden Dimension); Mark Knapp y Judith Hall (Nonverbal Communication in Human Interaction).</p>$hb05t$,
          'Comunicación interpersonal', 'Habilidades Blandas', 'basico', ARRAY['Lenguaje corporal', 'Comunicación no verbal', 'Proxémica', 'Paralenguaje', 'Habilidades blandas']::text[],
          $hb05t$Que el participante alinee su comunicación no verbal con su mensaje verbal, interprete señales no verbales de otros de forma contextual y prudente, y adapte su presencia a la atención presencial y virtual.$hb05t$,
          ARRAY['Reconocer los canales de la comunicación no verbal y desmontar sus mitos más comunes.', 'Proyectar seguridad y apertura con la postura, los gestos, la mirada y la expresión facial.', 'Usar la voz y el espacio en el mostrador, la consulta y las reuniones.', 'Leer señales no verbales en su contexto y cuidar tu presencia en videollamadas y entrevistas.']::text[],
          $hb05t$Profesionales de atención al paciente, visitadores médicos, equipos comerciales, docentes y personas que se preparan para entrevistas.$hb05t$,
          152, 'Edvanta', 'borrador', 'asincronica', '/img/cursos/lenguaje-corporal.webp', 'profesionales')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Fundamentos y mitos', 0)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Qué es la comunicación no verbal: canales, funciones y ejemplos', 'Unidad 1 · Clase 1.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb05j${"tone":"info","title":"En esta clase","html":"<p>Qué es la comunicación no verbal, sus canales (kinésica, proxémica, paralenguaje, háptica, apariencia y cronémica), sus funciones y ejemplos cotidianos.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb05j${"html":"<p>Cuando un paciente se acerca al mostrador, antes de que diga una palabra ya sabes algo: si viene con prisa, preocupado o molesto. Y él también sabe algo de ti: si estás disponible, distraído o interesado. Esa información viaja por la comunicación no verbal. En esta clase vas a conocer qué es, cuáles son sus canales, para qué sirve y por qué es tan importante en el trabajo con personas.</p><h2>¿Qué es la comunicación no verbal?</h2><p>La comunicación no verbal es <strong>toda la información que transmitimos sin palabras</strong>: con el cuerpo, la cara, la voz, el espacio, el contacto, la apariencia y el uso del tiempo. Está presente siempre, incluso cuando no hablamos, y muchas veces es menos consciente y controlada que las palabras.</p><h2>Los canales de la comunicación no verbal</h2><h3>1. Kinésica (movimiento del cuerpo)</h3>\n<p>Postura, gestos, movimientos de las manos, expresiones faciales y mirada. Ejemplo: asentir mientras el paciente habla indica que lo sigues.</p>\n<h3>2. Proxémica (uso del espacio)</h3>\n<p>La distancia que mantenemos con los demás y cómo organizamos el espacio. Ejemplo: un mostrador alto y lleno de exhibidores crea distancia; una zona de asesoría con sillas a la misma altura facilita la conversación.</p>\n<h3>3. Paralenguaje (cómo suena la voz)</h3>\n<p>Tono, volumen, velocidad, pausas, risas, suspiros. Ejemplo: \"Claro, con gusto\" puede sonar amable o fastidiado según el tono.</p>\n<h3>4. Háptica (contacto físico)</h3>\n<p>Apretón de manos, palmada en el hombro. En contextos de salud y en entornos laborales, el contacto debe ser respetuoso, pertinente y consentido.</p>\n<h3>5. Apariencia y artefactos</h3>\n<p>Ropa, uniforme, bata, carné, presentación personal, objetos. La bata y el carné, por ejemplo, ayudan a que el paciente identifique a quién preguntar.</p>\n<h3>6. Cronémica (uso del tiempo)</h3>\n<p>Puntualidad, tiempos de espera, tiempo dedicado a una persona. Hacer esperar a alguien sin explicación comunica falta de consideración.</p><h2>Funciones de la comunicación no verbal</h2><p>Mark Knapp y otros investigadores describen varias funciones:</p>\n<ul>\n<li><strong>Repetir:</strong> decir \"tres tabletas\" mientras muestras tres dedos.</li>\n<li><strong>Complementar:</strong> sonreír al dar la bienvenida.</li>\n<li><strong>Sustituir:</strong> levantar la mano para pedir la palabra.</li>\n<li><strong>Acentuar:</strong> golpear suavemente la mesa al decir \"esto es muy importante\".</li>\n<li><strong>Regular:</strong> mirar a alguien para indicarle que es su turno de hablar.</li>\n<li><strong>Contradecir:</strong> decir \"no estoy molesto\" con los brazos cruzados y el ceño fruncido.</li>\n</ul>\n<p>Cuando el mensaje verbal y el no verbal se contradicen, las personas tienden a dar más peso al no verbal, especialmente cuando se trata de emociones y actitudes.</p><h2>Cultura y contexto</h2><p>El significado de muchos gestos depende de la cultura. Un gesto amistoso en un país puede ser ofensivo en otro. Incluso dentro de Colombia hay diferencias regionales en la distancia, el volumen de la voz y el contacto. Por eso, ninguna señal tiene un significado único y universal.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb05j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un visitador médico entra al consultorio mirando el celular, se sienta sin esperar la invitación, habla rápido y mira el reloj. Aunque su información sea buena, el médico percibe prisa y desinterés. Al repetir la visita con saludo, contacto visual, espera a la invitación para sentarse y pausas, el contenido es el mismo pero la recepción cambia.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb05j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La comunicación no verbal incluye cuerpo, espacio, voz, contacto, apariencia y tiempo.</li>\n<li>Repite, complementa, sustituye, acentúa, regula o contradice el mensaje verbal.</li>\n<li>Su significado depende de la cultura y del contexto.</li>\n</ol>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb05j${"tone":"info","title":"Siguiente paso","html":"<p>Observa una conversación de una serie o noticiero durante dos minutos sin sonido y anota qué información captas por cada canal.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Mitos del lenguaje corporal: la regla 7-38-55, los brazos cruzados y la detección de mentiras', 'Unidad 1 · Clase 1.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb05j${"tone":"info","title":"En esta clase","html":"<p>La verdad sobre la regla 7-38-55 de Mehrabian, los brazos cruzados y la detección de mentiras. Qué dice realmente la investigación sobre el lenguaje corporal.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb05j${"html":"<p>\"El 93 % de la comunicación es no verbal.\" \"Si se toca la nariz, está mintiendo.\" \"Los brazos cruzados significan rechazo.\" Seguramente has escuchado estas afirmaciones en cursos, videos o artículos. Son atractivas, fáciles de recordar… y engañosas. En esta clase vas a revisar los mitos más difundidos sobre el lenguaje corporal y qué dice realmente la investigación, para que uses esta herramienta con rigor.</p><h2>Mito 1: la regla 7-38-55</h2><p>La afirmación popular dice que en toda comunicación el 7 % del significado viene de las palabras, el 38 % del tono de voz y el 55 % del lenguaje corporal.</p>\n<p><strong>Lo que realmente estudió Albert Mehrabian:</strong> en 1967 publicó dos estudios experimentales con participantes que escuchaban <strong>palabras sueltas</strong> (como \"querido\" o \"terrible\") dichas con distintos tonos, o que veían fotografías de rostros. El objetivo era ver cómo se juzgaba la <strong>actitud o el sentimiento</strong> del hablante (agrado o desagrado) cuando las palabras, la voz y la cara <strong>se contradecían</strong>.</p>\n<p>El propio Mehrabian ha aclarado que esas proporciones <strong>no se aplican a la comunicación en general</strong>. Si así fuera, podrías entender una conferencia en un idioma que no hablas solo mirando al orador.</p>\n<p><strong>Lo útil que sí queda:</strong> cuando las palabras y el cuerpo se contradicen al expresar emociones, las personas suelen confiar más en las señales no verbales. Por eso importa la coherencia.</p><h2>Mito 2: los brazos cruzados significan rechazo</h2><p>Una persona puede cruzar los brazos porque tiene frío, porque está cómoda, porque no sabe qué hacer con las manos o porque está concentrada. <strong>Ningún gesto aislado tiene un significado único.</strong> La interpretación requiere contexto, conjunto de señales y conocer cómo se comporta esa persona habitualmente.</p><h2>Mito 3: se puede detectar una mentira por el lenguaje corporal</h2><p>Tocarse la nariz, desviar la mirada o moverse en la silla no son señales confiables de mentira. Las revisiones de investigación sobre detección del engaño (por ejemplo, el metaanálisis de Bond y DePaulo, 2006) han encontrado que las personas aciertan solo un poco más que el azar cuando intentan detectar mentiras. Los nervios, la cultura y la personalidad producen las mismas señales que se atribuyen a mentir.</p>\n<p><strong>Riesgo práctico:</strong> juzgar a un paciente o a un colega como mentiroso por su lenguaje corporal puede llevar a malos tratos y malas decisiones.</p><h2>Mito 4: las expresiones faciales son universales y fáciles de leer</h2><p>Paul Ekman propuso que existen emociones básicas (alegría, tristeza, ira, miedo, sorpresa, asco) con expresiones reconocibles en distintas culturas. Investigadoras como Lisa Feldman Barrett han mostrado que la relación entre expresión y emoción es mucho más variable: la gente no siempre frunce el ceño cuando está enojada, y el contexto cambia la interpretación. Las expresiones faciales dan pistas, no certezas.</p><h2>Mito 5: las poses de poder cambian tus hormonas</h2><p>Como vimos en el Curso de Oratoria, los efectos hormonales de las poses de poder no se replicaron. Sí puede ser útil adoptar una postura abierta por cómo te perciben los demás.</p><h2>Cómo usar el lenguaje corporal con rigor</h2><ol>\n<li><strong>Observa conjuntos de señales</strong>, no gestos aislados.</li>\n<li><strong>Considera el contexto</strong> (lugar, situación, cultura, clima).</li>\n<li><strong>Compara con la línea base</strong> de la persona.</li>\n<li><strong>Formula hipótesis, no conclusiones:</strong> \"Parece incómodo; voy a preguntarle.\"</li>\n<li><strong>Verifica con palabras:</strong> \"Noto que esto le genera dudas, ¿qué le preocupa?\"</li>\n</ol>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb05j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La regla 7-38-55 no se aplica a la comunicación en general.</li>\n<li>Ningún gesto aislado tiene un significado único; el lenguaje corporal no detecta mentiras de forma fiable.</li>\n<li>Usa las señales no verbales como hipótesis y verifica preguntando.</li>\n</ol>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb05j${"tone":"info","title":"Siguiente paso","html":"<p>Busca en redes sociales una afirmación sobre lenguaje corporal y analízala con lo aprendido.</p>"}$hb05j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 2. Tu cuerpo comunica', 1)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Postura, gestos y manos: cómo proyectar seguridad y apertura', 'Unidad 2 · Clase 2.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb05j${"tone":"info","title":"En esta clase","html":"<p>Lenguaje corporal para proyectar seguridad y apertura: postura, uso de las manos, gestos ilustradores y gestos que distraen. Guía práctica con ejemplos.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb05j${"html":"<p>Tu postura y tus manos están hablando todo el tiempo. Pueden transmitir seguridad, disponibilidad y claridad, o nervios, prisa y distancia. No se trata de aprender poses artificiales, sino de eliminar lo que distrae y usar el cuerpo para apoyar lo que dices. En esta clase trabajarás la postura de pie y sentado, el uso de las manos y los gestos que ayudan o estorban.</p><h2>La postura de pie</h2><p>Una postura que transmite seguridad y disponibilidad:</p>\n<ul>\n<li>Pies firmes, separados al ancho de la cadera.</li>\n<li>Peso repartido; evita apoyarte en una sola pierna por mucho tiempo.</li>\n<li>Columna erguida sin rigidez, hombros relajados.</li>\n<li>Cabeza alineada, mentón paralelo al piso.</li>\n<li>Torso orientado hacia la persona con la que hablas.</li>\n</ul>\n<p>En el mostrador, evita apoyarte con los codos o encorvarte sobre el computador mientras el paciente habla: comunica que estás en otra cosa.</p><h2>La postura sentado</h2><p>En una consulta, una reunión o una entrevista:</p>\n<ul>\n<li>Siéntate con la espalda apoyada y el cuerpo ligeramente inclinado hacia adelante cuando escuchas (señal de interés).</li>\n<li>Pies apoyados en el piso.</li>\n<li>Manos visibles sobre la mesa o los muslos.</li>\n<li>Evita echarte hacia atrás con los brazos detrás de la cabeza (puede leerse como desinterés o superioridad) o sentarte en el borde de la silla (prisa o ansiedad).</li>\n</ul><h2>Las manos: tipos de gestos</h2><p>Los investigadores clasifican los gestos de las manos en varios tipos. Tres son clave en la práctica:</p>\n<h3>Gestos ilustradores</h3>\n<p>Acompañan y aclaran lo que dices: mostrar un tamaño, contar con los dedos, señalar una dirección. <strong>Ayudan a la comprensión</strong> y se asocian con oradores percibidos como más claros y cálidos.</p>\n<h3>Emblemas</h3>\n<p>Gestos con un significado directo en una cultura (pulgar arriba, \"ok\"). Úsalos con cuidado: su significado varía entre culturas.</p>\n<h3>Gestos adaptadores</h3>\n<p>Movimientos para manejar la tensión: tocarse el pelo, frotarse las manos, jugar con el bolígrafo, acomodarse la ropa. <strong>Distraen</strong> y suelen percibirse como nerviosismo. No son \"malos\", pero conviene reducirlos.</p><h2>Recomendaciones para las manos</h2><ul>\n<li>Mantén las manos visibles; ocultarlas en los bolsillos o detrás de la espalda resta apertura.</li>\n<li>Gesticula en la zona entre la cintura y los hombros.</li>\n<li>Usa palmas abiertas para invitar o explicar; palma hacia abajo para dar firmeza.</li>\n<li>Evita señalar a una persona con el dedo índice; usa la mano abierta.</li>\n<li>Si no sabes qué hacer con las manos, déjalas juntas a la altura del ombligo, de forma relajada.</li>\n</ul><h2>Coherencia entre gesto y palabra</h2><p>El gesto debe ir al mismo tiempo que la palabra que acompaña. Si dices \"esto es muy importante\" y el gesto llega después, se ve ensayado. Por eso es mejor no planear gestos específicos, sino permitir que surjan mientras piensas en el mensaje y luego revisar en video cuáles distraen.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb05j${"tone":"consejo","title":"Ejemplo aplicado: explicar el uso de un inhalador","html":"<p>Una regente explica a un paciente con asma cómo usar el inhalador. Si solo habla, el paciente pierde pasos. Si acompaña cada paso con un gesto ilustrador (agitar, exhalar, sellar los labios, inhalar lento, contener) y luego le pide al paciente que lo haga, la comprensión mejora. La demostración es comunicación no verbal al servicio de la seguridad del paciente.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb05j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Una postura erguida, relajada y orientada hacia la persona transmite disponibilidad.</li>\n<li>Los gestos ilustradores ayudan; los adaptadores distraen.</li>\n<li>Mantén las manos visibles y coherentes con las palabras.</li>\n</ol>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb05j${"tone":"info","title":"Siguiente paso","html":"<p>Grábate explicando un procedimiento de tu trabajo y cuenta tus gestos adaptadores.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Mirada y expresión facial: cómo conectar con la mirada y leer emociones con prudencia', 'Unidad 2 · Clase 2.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb05j${"tone":"info","title":"En esta clase","html":"<p>Cómo usar el contacto visual para conectar, cuánto mirar sin incomodar y cómo interpretar expresiones faciales con prudencia. Con ejemplos en atención al paciente.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb05j${"html":"<p>La mirada es uno de los canales más potentes de la comunicación no verbal. Con ella mostramos interés, regulamos los turnos de conversación y generamos confianza. La cara, por su parte, comunica emociones que pueden reforzar o contradecir las palabras. En esta clase aprenderás a usar el contacto visual de forma natural y a interpretar las expresiones faciales con prudencia.</p><h2>Las funciones de la mirada</h2><ul>\n<li><strong>Mostrar atención:</strong> mirar a quien habla indica que escuchas.</li>\n<li><strong>Regular la conversación:</strong> solemos mirar al otro cuando terminamos de hablar para cederle el turno.</li>\n<li><strong>Expresar emociones y actitudes:</strong> interés, duda, calidez.</li>\n<li><strong>Obtener información:</strong> vemos las reacciones del otro.</li>\n</ul><h2>¿Cuánto mirar?</h2><p>No existe un porcentaje exacto válido para todos, pero algunas pautas prácticas ayudan:</p>\n<ul>\n<li><strong>Al escuchar</strong> se suele mirar más que al hablar. Mantener la mirada mientras el otro habla transmite atención.</li>\n<li><strong>Al hablar</strong> es normal desviar la mirada para pensar; vuelve a mirar al terminar las ideas importantes.</li>\n<li><strong>Evita la mirada fija sin pausas:</strong> puede resultar intimidante. Rompe el contacto de forma natural cada pocos segundos.</li>\n<li><strong>Considera la cultura y la persona:</strong> algunas personas (por ejemplo, ciertas personas neurodivergentes o de algunas culturas) se sienten incómodas con mucho contacto visual. Respeta su ritmo.</li>\n</ul><h2>Mirada en grupo</h2><p>En reuniones, reparte la mirada entre todos los participantes, no solo hacia quien tiene más poder. Cuando alguien hace una pregunta, mírale al principio y luego extiende la mirada al grupo mientras respondes.</p><h2>La sonrisa</h2><p>Una sonrisa genuina al saludar facilita la conexión y transmite disponibilidad. Sin embargo, sonreír de forma constante en una situación seria (dar una mala noticia, atender una queja grave) puede parecer falta de empatía. Ajusta tu expresión a la emoción de la conversación.</p><h2>Leer expresiones faciales con prudencia</h2><p>Paul Ekman describió expresiones asociadas a emociones básicas: alegría, tristeza, ira, miedo, sorpresa y asco. Estas descripciones son útiles como punto de partida, pero la investigación más reciente, incluida la de Lisa Feldman Barrett, muestra que:</p>\n<ul>\n<li>La misma emoción puede expresarse de formas distintas.</li>\n<li>La misma expresión puede tener distintos significados según el contexto (un ceño fruncido puede ser concentración, dolor o confusión).</li>\n<li>La cultura influye en cuándo y cómo se muestran las emociones.</li>\n</ul>\n<p><strong>Regla práctica:</strong> cuando notes una expresión, úsala como una pista para preguntar, no para concluir.</p>\n<ul>\n<li>\"Noto que frunce el ceño; ¿algo de lo que le expliqué no quedó claro?\"</li>\n<li>\"Parece preocupada; ¿hay algo del tratamiento que le inquiete?\"</li>\n</ul><h2>La cara también escucha</h2><p>Tu cara reacciona mientras el otro habla. Expresiones de impaciencia, sorpresa exagerada o desaprobación pueden hacer que la persona se cierre. En la atención al paciente, mantener una expresión atenta y tranquila facilita que cuente información sensible (por ejemplo, que no está tomando el medicamento).</p><h2>Mascarillas y mirada</h2><p>En contextos donde se usa tapabocas, gran parte de la expresión facial queda oculta. Compensa con la mirada (los ojos también sonríen), con el tono de voz y con palabras explícitas: \"Con mucho gusto le explico\".</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb05j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una QF explica a un paciente que debe empezar a usar insulina. Mientras habla, nota que el paciente baja la mirada y aprieta los labios. En lugar de seguir con la técnica de aplicación, se detiene: \"Noto que esto le genera algo. ¿Qué piensa de empezar la insulina?\" El paciente confiesa que su padre \"empezó con insulina y luego perdió una pierna\". La conversación cambia hacia sus creencias y temores.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb05j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La mirada muestra atención, regula turnos y genera confianza; evita la mirada fija sin pausas.</li>\n<li>Ajusta la sonrisa y la expresión a la emoción de la conversación.</li>\n<li>Las expresiones faciales son pistas, no certezas: pregunta para verificar.</li>\n</ol>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb05j${"tone":"info","title":"Siguiente paso","html":"<p>En tus próximas tres conversaciones, practica mirar más mientras escuchas y verifica una emoción con una pregunta.</p>"}$hb05j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 3. Voz y espacio', 2)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Paralenguaje: qué comunica tu voz además de las palabras', 'Unidad 3 · Clase 3.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb05j${"tone":"info","title":"En esta clase","html":"<p>Qué es el paralenguaje y cómo el tono, el volumen, la velocidad y las pausas cambian el significado de lo que dices. Ejemplos y ejercicios prácticos.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb05j${"html":"<p>\"Con mucho gusto.\" Dos palabras que pueden sonar cálidas, neutras, cansadas o irónicas. Lo que cambia no son las palabras, sino cómo suenan. Ese \"cómo\" se llama paralenguaje, y en la atención telefónica, en el mostrador o en una videollamada puede definir si la persona se siente bien atendida. En esta clase vas a conocer los componentes del paralenguaje y a entrenar tu voz para que acompañe tu intención.</p><h2>¿Qué es el paralenguaje?</h2><p>El paralenguaje son las <strong>características vocales que acompañan a las palabras</strong>: tono, volumen, velocidad, ritmo, pausas, timbre, entonación y también sonidos no lingüísticos como suspiros, risas o carraspeos. Transmite emociones, actitudes y énfasis.</p><h2>Componentes del paralenguaje</h2><h3>Tono</h3>\n<p>La altura de la voz (más aguda o más grave). Un tono que sube al final de una frase afirmativa puede sonar a pregunta o a inseguridad (\"Su medicamento llega el martes↑\"). Para dar seguridad, termina las afirmaciones con un tono descendente.</p>\n<h3>Volumen</h3>\n<p>Debe ajustarse al espacio y a la privacidad. En una droguería, hablar en voz alta sobre el diagnóstico de un paciente vulnera su intimidad; hablar demasiado bajo obliga a repetir.</p>\n<h3>Velocidad</h3>\n<p>Hablar muy rápido transmite prisa y reduce la comprensión; muy lento puede sonar condescendiente. En la entrega de instrucciones sobre medicamentos, baja la velocidad en los datos clave (dosis, horario, advertencias).</p>\n<h3>Pausas</h3>\n<p>Dan tiempo para procesar, marcan lo importante y transmiten calma. Una pausa antes de una indicación clave aumenta la atención.</p>\n<h3>Entonación y énfasis</h3>\n<p>La palabra que enfatizas cambia el sentido: \"<strong>No</strong> tome este medicamento con alcohol\" vs. \"No tome este medicamento con <strong>alcohol</strong>\".</p>\n<h3>Timbre y calidad vocal</h3>\n<p>La \"textura\" de la voz. Se ve afectada por el cansancio, la tensión y la hidratación.</p><h2>La sonrisa se escucha</h2><p>Cuando sonríes, cambia la forma de la boca y eso modifica el sonido de la voz. En la atención telefónica, sonreír de forma genuina al saludar hace que la voz suene más cálida. Algunos centros de contacto incluso ponen espejos en los puestos de trabajo para recordarlo.</p><h2>Ajustar la voz a la emoción del otro</h2><ul>\n<li><strong>Paciente molesto:</strong> volumen moderado, ritmo pausado, tono firme y tranquilo. No subas la voz para \"igualarlo\".</li>\n<li><strong>Paciente preocupado o triste:</strong> tono más suave, más pausas, menor velocidad.</li>\n<li><strong>Paciente con dificultad auditiva:</strong> volumen un poco más alto, articulación clara, de frente para que pueda ver tus labios; no grites.</li>\n<li><strong>Persona mayor:</strong> no infantilices el tono (\"¿cómo está, mi abuelito?\"); habla con respeto adulto.</li>\n</ul><h2>Ejercicio: la misma frase, cinco intenciones</h2><p>Di \"El medicamento está agotado\" con estas intenciones: informativa, empática, apurada, molesta y solucionadora. Grábate y escucha las diferencias. Luego elige la versión que usarías con un paciente y agrega una solución: \"Lamento decirle que el medicamento está agotado hoy. Le puedo ofrecer…\".</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb05j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>En una línea de atención de un gestor farmacéutico, los indicadores de satisfacción eran bajos aunque las respuestas eran correctas. Al escuchar las grabaciones, el equipo notó una voz monótona y rápida, con frases que terminaban en tono ascendente. Tras un entrenamiento de paralenguaje (saludo con sonrisa, velocidad más baja, cierres descendentes), los comentarios negativos sobre \"mala atención\" disminuyeron.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb05j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>El paralenguaje incluye tono, volumen, velocidad, pausas, entonación y timbre.</li>\n<li>Termina las afirmaciones con tono descendente y baja la velocidad en los datos clave.</li>\n<li>Ajusta tu voz a la emoción y a las necesidades de la otra persona.</li>\n</ol>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb05j${"tone":"info","title":"Siguiente paso","html":"<p>Graba tres llamadas o explicaciones (con autorización si involucran a otros) y evalúa tu tono, velocidad y pausas.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Proxémica: cómo usar el espacio en el mostrador, la consulta y las reuniones', 'Unidad 3 · Clase 3.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb05j${"tone":"info","title":"En esta clase","html":"<p>Qué es la proxémica, las zonas de distancia de Edward T. Hall y cómo organizar el espacio en el mostrador, la consulta y las reuniones para comunicar mejor.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb05j${"html":"<p>¿Te has sentido incómodo cuando alguien se acerca demasiado al hablar? ¿O distante cuando una conversación importante ocurre a través de un mostrador alto y ruidoso? El espacio también comunica. La proxémica estudia cómo usamos la distancia y cómo organizamos los espacios, y tiene implicaciones directas en la atención al paciente, la confidencialidad y la calidad de la conversación. En esta clase aprenderás a usar el espacio a tu favor.</p><h2>¿Qué es la proxémica?</h2><p>El término fue propuesto por el antropólogo Edward T. Hall en la década de 1960. En su libro <em>La dimensión oculta</em> describió cómo las personas usan el espacio según su cultura y su relación con los demás.</p><h2>Las cuatro zonas de Hall</h2><p>Hall describió cuatro distancias aproximadas, a partir de observaciones en Estados Unidos (varían según la cultura):</p>\n<ol>\n<li><strong>Zona íntima (0 a 45 cm):</strong> reservada para personas muy cercanas o para procedimientos que requieren contacto (por ejemplo, la toma de presión arterial o la aplicación de una vacuna).</li>\n<li><strong>Zona personal (45 cm a 1,2 m):</strong> conversaciones entre conocidos, asesorías cercanas.</li>\n<li><strong>Zona social (1,2 a 3,6 m):</strong> interacciones de trabajo, atención al público, reuniones.</li>\n<li><strong>Zona pública (más de 3,6 m):</strong> conferencias, charlas ante grupos.</li>\n</ol>\n<p>En América Latina, muchas personas se sienten cómodas con distancias algo menores que las descritas por Hall, pero hay grandes diferencias individuales.</p><h2>Respetar la zona íntima en salud</h2><p>Algunos servicios farmacéuticos requieren entrar en la zona íntima: toma de presión, aplicación de inyectables, demostración de técnica de inhaladores o de aplicación de insulina. Para hacerlo con respeto:</p>\n<ul>\n<li><strong>Anuncia lo que vas a hacer</strong> antes de acercarte: \"Le voy a poner el brazalete en el brazo izquierdo.\"</li>\n<li><strong>Pide permiso</strong> y verifica comodidad.</li>\n<li><strong>Usa espacios privados</strong> cuando sea posible.</li>\n<li><strong>Explica y mantén el contacto profesional.</strong></li>\n</ul><h2>El espacio físico comunica</h2><h3>El mostrador</h3>\n<p>Un mostrador alto, lleno de exhibidores y con una fila detrás del paciente dificulta la conversación y la confidencialidad. Algunas soluciones:</p>\n<ul>\n<li>Un <strong>punto de asesoría</strong> separado o una zona con menos ruido.</li>\n<li><strong>Distancia de privacidad</strong> marcada en el piso para la fila.</li>\n<li>Mantener libre el espacio entre tú y el paciente.</li>\n</ul>\n<h3>La consulta o el área de atención farmacéutica</h3>\n<ul>\n<li>Evita que el escritorio sea una barrera: siéntate en ángulo de 90° con la persona en lugar de frente a frente; facilita la colaboración y reduce la sensación de confrontación.</li>\n<li>Coloca la pantalla del computador de forma que puedas mostrar información al paciente.</li>\n</ul>\n<h3>Las reuniones</h3>\n<ul>\n<li>La persona que se sienta en la cabecera suele asumir (o recibir) un rol de autoridad.</li>\n<li>Las mesas redondas o en \"U\" facilitan la participación.</li>\n<li>En conversaciones difíciles, sentarse al mismo lado de la mesa, mirando juntos el documento, transmite \"resolvamos esto juntos\".</li>\n</ul><h2>Territorio y objetos</h2><p>Las personas marcan su territorio con objetos (una chaqueta en la silla, papeles en la mesa). En espacios compartidos, respetar esos territorios evita conflictos innecesarios.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb05j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una droguería de barrio recibió quejas porque los pacientes \"sentían pena\" de preguntar por medicamentos para infecciones de transmisión sexual o anticonceptivos. El regente instaló una pequeña zona de asesoría al lado del mostrador, con una línea de distancia para la fila. Las consultas de asesoría aumentaron y los pacientes comentaron que se sentían más tranquilos.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb05j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La proxémica estudia el uso de la distancia y el espacio en la comunicación.</li>\n<li>Zonas de Hall: íntima, personal, social y pública; varían según la cultura y la persona.</li>\n<li>Diseña el espacio para proteger la confidencialidad y facilitar la colaboración.</li>\n</ol>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb05j${"tone":"info","title":"Siguiente paso","html":"<p>Haz un diagnóstico del espacio de atención de tu lugar de trabajo con el checklist.</p>"}$hb05j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 4. Leer a otros y comunicar en cámara', 3)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo leer el lenguaje corporal de otros: línea base, conjuntos de señales y contexto', 'Unidad 4 · Clase 4.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb05j${"tone":"info","title":"En esta clase","html":"<p>Cómo leer el lenguaje corporal de otras personas con rigor: línea base, conjuntos de señales, contexto y verificación. Aplicado a pacientes, médicos y clientes.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb05j${"html":"<p>Leer el lenguaje corporal de otra persona puede ayudarte a notar que un paciente no entendió, que un médico perdió el interés o que un cliente tiene una objeción que no dice. Pero, como vimos en los mitos, interpretar mal una señal puede llevarte a conclusiones equivocadas. En esta clase aprenderás un método de cuatro pasos para observar con atención, interpretar con prudencia y verificar con preguntas.</p><h2>Paso 1: establece la línea base</h2><p>La línea base es <strong>cómo se comporta habitualmente una persona</strong> cuando está tranquila: cómo se sienta, cuánto gesticula, su tono de voz, cuánto mira. Algunas personas cruzan los brazos siempre; otras hablan rápido por naturaleza. Lo que te da información no es el gesto, sino <strong>el cambio respecto a su línea base</strong>.</p>\n<p>Cómo hacerlo: observa a la persona durante los primeros minutos de una conversación neutra (el saludo, una pregunta sencilla).</p><h2>Paso 2: busca conjuntos de señales</h2><p>Una señal aislada es poco informativa. Varias señales que apuntan en la misma dirección y que ocurren al mismo tiempo son más confiables.</p>\n<p>Ejemplo: un médico que (1) mira el reloj, (2) orienta los pies hacia la puerta, (3) responde con monosílabos y (4) empieza a ordenar papeles probablemente quiere terminar la visita. Una sola de esas señales no dice mucho.</p><h2>Paso 3: considera el contexto</h2><p>Pregúntate:</p>\n<ul>\n<li>¿Qué está pasando en el entorno? (frío, ruido, una fila larga, una emergencia).</li>\n<li>¿Cuál es la situación de la persona? (dolor, preocupación por un diagnóstico, cansancio).</li>\n<li>¿Hay factores culturales, de edad o de salud que influyan? (por ejemplo, la enfermedad de Parkinson reduce la expresividad facial; algunas personas en el espectro autista hacen menos contacto visual).</li>\n<li>¿Qué acaba de pasar en la conversación? (¿la señal apareció justo después de mencionar el precio?).</li>\n</ul><h2>Paso 4: verifica con palabras</h2><p>Convierte tu observación en una pregunta abierta y respetuosa:</p>\n<ul>\n<li>\"Noto que se quedó pensando cuando le mencioné el horario. ¿Le queda difícil tomarlo a esa hora?\"</li>\n<li>\"Doctor, veo que tiene poco tiempo. ¿Prefiere que le deje el resumen y volvamos a hablar la próxima semana?\"</li>\n<li>\"Parece que tiene alguna duda sobre el precio. ¿Le gustaría ver otra alternativa?\"</li>\n</ul>\n<p>Esta pregunta no solo verifica tu hipótesis: muestra a la persona que estás atento a ella.</p><h2>Señales frecuentes en la atención y qué preguntar</h2><table><thead><tr><th>Conjunto de señales</th><th>Hipótesis posible</th><th>Pregunta de verificación</th></tr></thead><tbody><tr><td>Ceño fruncido, mirada al papel, silencio</td><td>No entendió la instrucción</td><td>\"¿Quiere que se lo explique de otra forma?\"</td></tr><tr><td>Brazos cruzados, voz alta, respiración rápida</td><td>Molestia o frustración</td><td>\"Veo que esto le ha generado mucha molestia. ¿Qué pasó?\"</td></tr><tr><td>Mirada baja, voz baja, respuestas cortas</td><td>Vergüenza o incomodidad</td><td>\"Si prefiere, podemos hablar en el punto de asesoría.\"</td></tr><tr><td>Asiente, se inclina hacia adelante, pregunta</td><td>Interés</td><td>\"¿Qué más le gustaría saber?\"</td></tr></tbody></table><h2>Ética de la observación</h2><p>Leer el lenguaje corporal es para <strong>atender mejor</strong>, no para manipular ni para juzgar. No uses las señales para presionar una venta ni para etiquetar a alguien como mentiroso. En la atención en salud, la observación cuidadosa es parte de la empatía clínica.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb05j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una auxiliar entrega un antibiótico y explica la dosis. La paciente asiente, pero mira al niño que lleva en brazos, se muerde el labio y guarda la fórmula rápido. La auxiliar pregunta: \"¿Le quedó claro cada cuánto se lo da al niño? ¿Quiere que se lo anote en la caja?\". La madre reconoce que no entendió y que estaba distraída. La auxiliar escribe el horario en la caja con un marcador.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb05j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Compara con la línea base: lo que informa es el cambio.</li>\n<li>Busca conjuntos de señales y considera el contexto.</li>\n<li>Verifica con preguntas abiertas y usa la observación para atender mejor.</li>\n</ol>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb05j${"tone":"info","title":"Siguiente paso","html":"<p>En tus próximas cinco atenciones, aplica el paso 4 al menos una vez y registra qué descubriste.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Lenguaje corporal en videollamadas y entrevistas: encuadre, mirada a cámara y presencia', 'Unidad 4 · Clase 4.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb05j${"tone":"info","title":"En esta clase","html":"<p>Lenguaje corporal en una entrevista de trabajo y en videollamadas: encuadre, mirada a la cámara, postura, gestos y errores frecuentes. Guía práctica.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb05j${"html":"<p>Hoy muchas entrevistas de trabajo, reuniones con médicos, capacitaciones y visitas comerciales ocurren por videollamada. En la pantalla, el lenguaje corporal se reduce a un rectángulo: tu cara, tus hombros, tus manos y tu fondo. Pequeños detalles —una cámara que te muestra desde abajo, una mirada que no llega al lente o una luz a contraluz— pueden afectar la impresión que das. En esta clase aprenderás a cuidar tu presencia en entrevistas presenciales y virtuales.</p><h2>Entrevista presencial: los momentos clave</h2><ul>\n<li><strong>La llegada:</strong> puntualidad (5 a 10 minutos antes), saludo cordial a todas las personas, incluida la recepción.</li>\n<li><strong>El saludo:</strong> contacto visual, sonrisa natural y, si corresponde, un apretón de manos firme, no aplastante.</li>\n<li><strong>Al sentarte:</strong> espera la invitación, espalda apoyada y ligeramente inclinado hacia adelante, manos visibles.</li>\n<li><strong>Mientras escuchas:</strong> asiente, mantén la mirada, evita interrumpir.</li>\n<li><strong>Mientras respondes:</strong> reparte la mirada entre los entrevistadores, gesticula con naturalidad.</li>\n<li><strong>La salida:</strong> agradece, mantén la compostura hasta salir del edificio.</li>\n</ul><h2>Videollamadas: el encuadre</h2><ul>\n<li><strong>Altura de la cámara:</strong> a la altura de los ojos. Una cámara baja (portátil sobre la mesa) te muestra desde abajo, con un ángulo poco favorecedor. Usa libros o un soporte.</li>\n<li><strong>Plano:</strong> de la mitad del pecho hacia arriba, con un poco de espacio sobre la cabeza.</li>\n<li><strong>Distancia:</strong> que se vean tus hombros y parte de las manos al gesticular.</li>\n<li><strong>Fondo:</strong> ordenado, neutro, sin elementos que distraigan.</li>\n</ul><h2>La mirada a la cámara</h2><p>En una videollamada, mirar a los ojos de la otra persona en la pantalla hace que, para ella, parezca que miras hacia abajo. Para generar sensación de contacto visual:</p>\n<ul>\n<li><strong>Mira al lente</strong> cuando hables de algo importante o al responder una pregunta clave.</li>\n<li>Coloca la ventana de la videollamada justo debajo de la cámara para reducir el ángulo.</li>\n<li>Mira la pantalla cuando escuches, para ver las reacciones.</li>\n</ul><h2>Postura y gestos en pantalla</h2><ul>\n<li>Siéntate derecho y ligeramente hacia adelante; recostarte demasiado se ve desinteresado.</li>\n<li>Gesticula dentro del encuadre, a la altura del pecho; los gestos fuera del plano no se ven.</li>\n<li>Asiente un poco más que en persona: las señales sutiles se pierden en la pantalla.</li>\n<li>Evita tocarte la cara, mirar otras ventanas o el celular.</li>\n</ul><h2>Luz y sonido</h2><ul>\n<li>Luz de frente (ventana o lámpara detrás de la cámara).</li>\n<li>Audífonos con micrófono para evitar eco.</li>\n<li>Silencia notificaciones.</li>\n</ul><h2>Errores frecuentes en entrevistas virtuales</h2><ul>\n<li>Conectarse en un lugar con ruido o con interrupciones.</li>\n<li>Leer las respuestas desde otra ventana (se nota en los ojos).</li>\n<li>Cámara apagada sin explicación.</li>\n<li>Ropa formal arriba y descuidada abajo (si te levantas, se ve).</li>\n<li>No probar la plataforma antes.</li>\n</ul>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb05j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un químico farmacéutico aspirante a un cargo de asuntos regulatorios tenía su entrevista final por videollamada. En la prueba con un amigo descubrió que la cámara del portátil lo mostraba desde abajo y con la ventana a su espalda. Subió el portátil sobre unos libros, se ubicó frente a la ventana y pegó una nota junto a la cámara que decía \"mira aquí\". En la entrevista se sintió más seguro y la conexión con el panel fue mejor.</p>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb05j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>En presencial cuida llegada, saludo, postura al sentarte, escucha y salida.</li>\n<li>En virtual, cámara a la altura de los ojos, luz de frente y mirada al lente en los momentos clave.</li>\n<li>Gesticula dentro del encuadre y asiente un poco más que en persona.</li>\n</ol>"}$hb05j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb05j${"tone":"info","title":"Siguiente paso","html":"<p>Haz una videollamada de prueba con alguien de confianza y revisa la grabación con el checklist.</p>"}$hb05j$::jsonb);
END
$hb05$;

-- ─── Curso de Negociación y Persuasión (8 clases) ───
DO $hb06$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Negociación y Persuasión' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, area, level, tags,
     objective, learning_outcomes, audience, duration_minutes, author_name, status, modality, cover_url, publico)
  VALUES ('edvanta', 'Curso de Negociación y Persuasión', $hb06t$Curso para preparar y conducir negociaciones y conversaciones persuasivas con método: negociación distributiva e integrativa, MAAN/BATNA y ZOPA, método Harvard, preguntas calibradas, principios de Cialdini, persuasión ética en salud, manejo de objeciones y cierre de acuerdos.$hb06t$,
          $hb06t$<p>Curso para preparar y conducir negociaciones y conversaciones persuasivas con método: negociación distributiva e integrativa, MAAN/BATNA y ZOPA, método Harvard, preguntas calibradas, principios de Cialdini, persuasión ética en salud, manejo de objeciones y cierre de acuerdos.</p><h2>Objetivo</h2><p>Que el participante prepare una negociación con MAAN, precio de reserva e intereses de las partes, la conduzca con el método Harvard y técnicas de escucha táctica, y aplique principios de persuasión y manejo de objeciones dentro de un marco ético.</p><h2>Para quién es</h2><p>Visitadores médicos, representantes de ventas farmacéuticas, KAM, compradores de droguerías y servicios farmacéuticos, directores técnicos y gerentes de punto de venta.</p><h2>Cómo está organizado</h2><p>Cuatro unidades con dos clases en texto cada una. Cada clase trae un ejemplo aplicado al sector farmacéutico y de la salud, puntos clave y el siguiente paso.</p><h2>Referentes</h2><p>Roger Fisher, William Ury y Bruce Patton (Getting to Yes / Sí, ¡de acuerdo!, Proyecto de Negociación de Harvard); Robert B. Cialdini (Influencia y Pre-suasión: 7 principios); Chris Voss (Rompe la barrera del no: empatía táctica, preguntas calibradas); Deepak Malhotra y Max Bazerman (Negotiation Genius).</p>$hb06t$,
          'Liderazgo y relaciones laborales', 'Habilidades Blandas', 'intermedio', ARRAY['Negociación', 'Persuasión', 'Método Harvard', 'Manejo de objeciones', 'Habilidades blandas']::text[],
          $hb06t$Que el participante prepare una negociación con MAAN, precio de reserva e intereses de las partes, la conduzca con el método Harvard y técnicas de escucha táctica, y aplique principios de persuasión y manejo de objeciones dentro de un marco ético.$hb06t$,
          ARRAY['Distinguir la negociación distributiva de la integrativa y prepararla con MAAN, precio de reserva y ZOPA.', 'Negociar con los principios del método Harvard, preguntas calibradas y escucha táctica.', 'Aplicar los principios de persuasión de Cialdini dentro de un marco ético propio del sector salud.', 'Responder objeciones y cerrar acuerdos con concesiones y seguimiento.']::text[],
          $hb06t$Visitadores médicos, representantes de ventas farmacéuticas, KAM, compradores de droguerías y servicios farmacéuticos, directores técnicos y gerentes de punto de venta.$hb06t$,
          152, 'Edvanta', 'borrador', 'asincronica', '/img/cursos/negociacion-persuasion.webp', 'profesionales')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Fundamentos y preparación', 0)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Qué es negociar: negociación distributiva vs. integrativa y los errores más comunes', 'Unidad 1 · Clase 1.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb06j${"tone":"info","title":"En esta clase","html":"<p>Cómo negociar: diferencias entre negociación distributiva e integrativa, los elementos de toda negociación y los errores más frecuentes que hacen perder valor.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb06j${"html":"<p>Negociamos todo el tiempo: con un proveedor por un plazo de pago, con el jefe por un aumento, con un médico por un espacio en su agenda, con un compañero por los turnos de diciembre. Muchas personas creen que negociar es regatear o \"ganarle\" al otro. Pero las negociaciones más valiosas no se ganan: se construyen. En esta clase vas a entender qué es negociar, los dos grandes tipos de negociación y los errores que más valor hacen perder.</p><h2>¿Qué es negociar?</h2><p>Negociar es un <strong>proceso de comunicación entre dos o más partes que tienen intereses en parte comunes y en parte opuestos, para llegar a un acuerdo</strong> que sea mejor para ellas que no tenerlo. Si los intereses fueran totalmente opuestos, no habría acuerdo posible; si fueran idénticos, no habría nada que negociar.</p><h2>Negociación distributiva</h2><p>También llamada \"de suma cero\" o \"competitiva\". Se negocia <strong>un solo recurso fijo</strong> (normalmente el precio): lo que gana uno lo pierde el otro.</p>\n<ul>\n<li>Ejemplo: comprar un equipo usado en el que solo se discute el precio.</li>\n<li>Tácticas típicas: anclar alto, conceder poco a poco, ocultar información.</li>\n<li>Riesgo: deteriora la relación y deja valor sin aprovechar.</li>\n</ul><h2>Negociación integrativa</h2><p>También llamada \"colaborativa\" o \"de suma variable\". Se negocian <strong>varios temas a la vez</strong> y las partes buscan crear valor intercambiando lo que a cada una le importa menos por lo que le importa más.</p>\n<ul>\n<li>Ejemplo: una droguería negocia con un distribuidor no solo el precio, sino el plazo de pago, la frecuencia de entrega, el manejo de devoluciones por vencimiento y el apoyo en exhibición.</li>\n<li>Requiere confianza, intercambio de información y creatividad.</li>\n<li>Resultado: acuerdos más amplios y relaciones de largo plazo.</li>\n</ul><h2>El caso de la naranja</h2><p>Dos hermanas discuten por una naranja. Deciden partirla a la mitad. Una usa su mitad para hacer jugo y bota la cáscara; la otra usa la cáscara para un pastel y bota la pulpa. Si hubieran preguntado <strong>para qué</strong> querían la naranja, cada una habría tenido el doble. Este ejemplo, popularizado en la literatura sobre negociación de Harvard, muestra la diferencia entre <strong>posiciones</strong> (lo que digo que quiero: \"la naranja\") e <strong>intereses</strong> (por qué lo quiero: \"jugo\" o \"cáscara\").</p><h2>Los elementos de toda negociación</h2><ol>\n<li><strong>Partes:</strong> quién negocia y quién decide realmente.</li>\n<li><strong>Intereses:</strong> necesidades, preocupaciones y deseos detrás de las posiciones.</li>\n<li><strong>Opciones:</strong> posibles acuerdos.</li>\n<li><strong>Alternativas:</strong> lo que harás si no hay acuerdo.</li>\n<li><strong>Criterios:</strong> referencias objetivas para decidir qué es justo.</li>\n<li><strong>Relación:</strong> cómo queda el vínculo después del acuerdo.</li>\n<li><strong>Comunicación:</strong> cómo se intercambia la información.</li>\n<li><strong>Compromisos:</strong> qué se acuerda concretamente.</li>\n</ol><h2>Errores más comunes</h2><ul>\n<li><strong>Ir sin preparación:</strong> no saber cuál es tu límite ni tu alternativa.</li>\n<li><strong>Negociar solo el precio:</strong> ignorar otras variables que pueden crear valor.</li>\n<li><strong>Ceder rápido para evitar el conflicto.</strong></li>\n<li><strong>Ver al otro como enemigo</strong> y no como contraparte con problemas propios.</li>\n<li><strong>Hablar más que escuchar.</strong></li>\n<li><strong>Aceptar la primera oferta</strong> sin explorar.</li>\n<li><strong>No dejar por escrito</strong> lo acordado.</li>\n</ul>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb06j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una directora técnica negocia con un laboratorio la compra de antibióticos para la clínica. El laboratorio no puede bajar más el precio. En lugar de estancarse, ella explora intereses: al laboratorio le interesa el volumen anual garantizado; a la clínica, el plazo de pago y el cambio de producto próximo a vencer. Acuerdan precio igual, compromiso de volumen, pago a 90 días y reposición de producto con menos de seis meses de vida útil. Ambas partes ganan más que con un descuento.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb06j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Negociar es buscar un acuerdo mejor que no tenerlo, con intereses comunes y opuestos.</li>\n<li>La negociación integrativa crea valor al negociar varios temas a la vez.</li>\n<li>Distingue posiciones de intereses: pregunta \"¿para qué?\".</li>\n</ol>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb06j${"tone":"info","title":"Siguiente paso","html":"<p>Piensa en una negociación reciente: ¿fue distributiva o integrativa? ¿Qué variables, además del precio, pudiste negociar?</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo preparar una negociación: MAAN (BATNA), precio de reserva, ZOPA y objetivos', 'Unidad 1 · Clase 1.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb06j${"tone":"info","title":"En esta clase","html":"<p>Cómo preparar una negociación paso a paso: qué es el MAAN o BATNA, el precio de reserva, la ZOPA y cómo fijar objetivos ambiciosos y realistas.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb06j${"html":"<p>La mayor parte del resultado de una negociación se define antes de sentarse a la mesa. Quien llega preparado sabe hasta dónde puede ceder, qué hará si no hay acuerdo y qué le importa realmente a la otra parte. Quien no se prepara, improvisa y suele ceder de más. En esta clase aprenderás cuatro conceptos clave de preparación y una plantilla para aplicarlos.</p><h2>MAAN o BATNA: tu mejor alternativa</h2><p><strong>MAAN</strong> significa <em>Mejor Alternativa a un Acuerdo Negociado</em> (en inglés, <strong>BATNA</strong>: <em>Best Alternative To a Negotiated Agreement</em>). El concepto fue popularizado por Fisher y Ury en <em>Sí, ¡de acuerdo!</em>. Es <strong>lo que harás si la negociación fracasa</strong>.</p>\n<ul>\n<li>Si negocias con un distribuidor, tu MAAN puede ser comprar a otro distribuidor con condiciones conocidas.</li>\n<li>Si negocias un salario, tu MAAN puede ser otra oferta de trabajo o quedarte en tu cargo actual.</li>\n</ul>\n<p><strong>Por qué importa:</strong> tu MAAN es tu fuente de poder. Cuanto mejor sea tu alternativa, menos necesitas el acuerdo y más firme puedes ser. Antes de negociar, <strong>trabaja para mejorar tu MAAN</strong> (por ejemplo, cotizando con otros proveedores).</p>\n<p>Analiza también <strong>la MAAN de la otra parte</strong>: ¿qué hará si no llegan a un acuerdo? Si su alternativa es débil, tienes más margen.</p><h2>Precio de reserva (punto de retirada)</h2><p>Es <strong>el valor mínimo (si vendes) o máximo (si compras) que aceptarías</strong> antes de preferir tu MAAN. Se deriva de tu MAAN.</p>\n<p>Ejemplo: un servicio farmacéutico puede comprar un insumo a otro proveedor a $1.000 por unidad, más $50 de costos logísticos adicionales. Su precio de reserva con el proveedor actual es $1.050: por encima de eso, prefiere su alternativa.</p><h2>ZOPA: la zona de posible acuerdo</h2><p>La <strong>ZOPA</strong> (<em>Zone Of Possible Agreement</em>) es el rango entre el precio de reserva del vendedor y el del comprador. Si se superponen, hay acuerdo posible.</p>\n<ul>\n<li>Precio mínimo del vendedor: $900.</li>\n<li>Precio máximo del comprador: $1.050.</li>\n<li>ZOPA: entre $900 y $1.050.</li>\n</ul>\n<p>Si el vendedor no acepta menos de $1.100 y el comprador no paga más de $1.050, <strong>no hay ZOPA</strong> en el precio: hay que añadir otras variables (plazo, volumen, servicios) o retirarse.</p><h2>Objetivo: aspira alto, pero con fundamento</h2><p>Tu objetivo es el resultado que buscas, más ambicioso que tu precio de reserva. Las investigaciones en negociación sugieren que quienes se fijan metas ambiciosas y específicas suelen obtener mejores resultados que quienes solo buscan \"un buen acuerdo\". Pero el objetivo debe poder <strong>justificarse con criterios objetivos</strong> (precios de mercado, referencias, costos).</p><h2>Mapa de intereses y variables</h2><p>Completa tu preparación con:</p>\n<ul>\n<li><strong>Tus intereses</strong> y su prioridad (alta, media, baja).</li>\n<li><strong>Los intereses probables de la otra parte.</strong></li>\n<li><strong>Variables negociables:</strong> precio, plazo, volumen, entrega, garantía, devoluciones, capacitación, exclusividad.</li>\n<li><strong>Intercambios posibles:</strong> \"Si ustedes me dan X, yo puedo darles Y.\"</li>\n<li><strong>Criterios objetivos:</strong> listas de precios de referencia, cotizaciones, normas.</li>\n</ul>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb06j${"tone":"consejo","title":"Ejemplo aplicado: negociación de un regente con un distribuidor","html":"<ul>\n<li><strong>MAAN:</strong> comprar a otro distribuidor con entrega cada 3 días en lugar de diaria.</li>\n<li><strong>Precio de reserva:</strong> descuento mínimo del 4 % sobre lista.</li>\n<li><strong>Objetivo:</strong> 7 % de descuento + entrega diaria + recogida de vencidos.</li>\n<li><strong>Intereses del distribuidor:</strong> volumen mensual estable, pago puntual, menos devoluciones.</li>\n<li><strong>Intercambio:</strong> compromiso de volumen y pago a 30 días a cambio de 6 % y recogida de vencidos.</li>\n</ul>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb06j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Tu MAAN es lo que harás si no hay acuerdo; mejórala antes de negociar.</li>\n<li>El precio de reserva es tu límite; la ZOPA es el rango de acuerdo posible.</li>\n<li>Fija objetivos ambiciosos con fundamento y mapea intereses y variables.</li>\n</ol>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb06j${"tone":"info","title":"Siguiente paso","html":"<p>Llena la plantilla de preparación para una negociación real de las próximas semanas.</p>"}$hb06j$::jsonb);

