  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'El método Harvard de negociación: los 4 principios para llegar a acuerdos', 'Unidad 2 · Clase 2.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb06j${"tone":"info","title":"En esta clase","html":"<p>El método Harvard de negociación explicado: separar a las personas del problema, intereses no posiciones, opciones de mutuo beneficio y criterios objetivos.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb06j${"html":"<p>En 1981, Roger Fisher y William Ury, del Proyecto de Negociación de Harvard, publicaron <em>Getting to Yes</em> (en español, <em>Sí, ¡de acuerdo!</em>). El libro propuso una alternativa a la negociación dura (ganar a toda costa) y a la negociación blanda (ceder para mantener la relación): la <strong>negociación basada en principios</strong>, conocida como método Harvard. Hoy es uno de los enfoques más enseñados en el mundo. En esta clase aprenderás sus cuatro principios y cómo aplicarlos.</p><h2>Principio 1: separar a las personas del problema</h2><p>Las negociaciones involucran personas con emociones, percepciones y egos. Cuando se mezclan con el problema, cualquier desacuerdo se siente como un ataque personal.</p>\n<p>Cómo aplicarlo:</p>\n<ul>\n<li><strong>Sé suave con las personas y firme con el problema.</strong></li>\n<li>Reconoce las emociones: \"Entiendo que esto ha sido frustrante para su equipo.\"</li>\n<li>Ponte en el lugar del otro: ¿cómo ve él la situación?</li>\n<li>Habla de cómo te afecta a ti, no de lo que el otro \"hace mal\".</li>\n<li>Siéntate \"del mismo lado de la mesa\" frente al problema.</li>\n</ul><h2>Principio 2: centrarse en los intereses, no en las posiciones</h2><p>Detrás de cada posición hay intereses: necesidades, preocupaciones, deseos, temores. Las posiciones suelen ser incompatibles; los intereses, muchas veces, no.</p>\n<p>Cómo descubrir intereses:</p>\n<ul>\n<li>Pregunta \"¿por qué es importante esto para usted?\" y \"¿qué le preocupa?\".</li>\n<li>Pregunta \"¿por qué no?\" ante una negativa: \"¿Qué le impide aceptar esta propuesta?\".</li>\n<li>Comparte tus propios intereses para generar reciprocidad.</li>\n</ul>\n<p>Ejemplo: un hospital exige un 15 % de descuento (posición). Su interés real puede ser cumplir una meta de reducción de costos del 10 % en el año. Un acuerdo de volumen con entregas consignadas puede reducir sus costos de inventario y ayudar a esa meta sin todo el descuento.</p><h2>Principio 3: inventar opciones de mutuo beneficio</h2><p>Antes de decidir, genera opciones. El error común es buscar una única respuesta demasiado pronto.</p>\n<p>Cómo hacerlo:</p>\n<ul>\n<li><strong>Separa la generación de opciones de la evaluación:</strong> primero lluvia de ideas, luego se evalúa.</li>\n<li><strong>Amplía el pastel:</strong> agrega variables (plazos, servicios, capacitación, información).</li>\n<li><strong>Busca intereses compatibles:</strong> lo que es barato para ti y valioso para el otro.</li>\n<li><strong>Facilita la decisión del otro:</strong> ¿qué necesita para poder decir que sí ante su jefe o su comité?</li>\n</ul><h2>Principio 4: insistir en criterios objetivos</h2><p>Cuando los intereses chocan, en lugar de una lucha de voluntades (\"lo tomo o lo dejo\"), busca un estándar independiente que ambas partes puedan aceptar como justo.</p>\n<p>Ejemplos de criterios objetivos:</p>\n<ul>\n<li>Precios de mercado o referencias de compras públicas.</li>\n<li>Costos verificables.</li>\n<li>Normas técnicas y regulatorias.</li>\n<li>Lo que se hizo en casos similares.</li>\n<li>La opinión de un experto independiente.</li>\n</ul>\n<p>Pregunta: \"¿Cuál sería un criterio justo para definir este precio?\"</p><h2>¿Y si el otro es más poderoso?</h2><p>El método Harvard propone dos respuestas: <strong>conoce y mejora tu MAAN</strong> (tu poder real) y no aceptes un acuerdo peor que tu alternativa. Si el otro usa trucos (amenazas, presión de tiempo, \"el policía bueno y el malo\"), <strong>nómbralos con calma</strong> y vuelve a los intereses y criterios.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb06j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un KAM negocia con el comité de compras de una red de clínicas la inclusión de un nuevo antibiótico. El comité se niega por precio (posición). Al explorar intereses descubre que su preocupación principal es el gasto total por paciente y la resistencia antimicrobiana. Proponen un programa conjunto con el servicio de farmacia: uso restringido según protocolo, seguimiento de consumo y revisión a los seis meses con indicadores acordados (criterio objetivo).</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb06j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Separa a las personas del problema: suave con ellas, firme con el problema.</li>\n<li>Explora intereses detrás de las posiciones.</li>\n<li>Genera opciones antes de decidir y usa criterios objetivos.</li>\n</ol>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb06j${"tone":"info","title":"Siguiente paso","html":"<p>Aplica las preguntas de intereses en tu próxima conversación con un proveedor, cliente o jefe.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Preguntas calibradas y escucha táctica: técnicas de Chris Voss para negociar', 'Unidad 2 · Clase 2.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb06j${"tone":"info","title":"En esta clase","html":"<p>Técnicas de negociación de Chris Voss: espejo, etiquetado, preguntas calibradas (cómo/qué) y el valor del \"no\". Ejemplos aplicados a ventas y compras.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb06j${"html":"<p>Chris Voss fue negociador de secuestros del FBI y luego escribió <em>Never Split the Difference</em> (en español, <em>Rompe la barrera del no</em>). Su enfoque complementa el método Harvard con técnicas de <strong>empatía táctica</strong>: escuchar para que la otra parte se sienta comprendida y, desde ahí, influir en la conversación. Estas técnicas funcionan en ventas, compras y negociaciones internas. En esta clase aprenderás cuatro de ellas.</p><h2>Técnica 1: el espejo</h2><p>Consiste en <strong>repetir las últimas una a tres palabras clave</strong> que dijo la otra persona, con tono de interés. Esto la invita a ampliar sin que tengas que hacer una pregunta directa.</p>\n<p>—\"El problema es que su producto llega con poco tiempo de vencimiento.\"\n—\"¿Poco tiempo de vencimiento?\"\n—\"Sí, el último pedido llegó con ocho meses y nuestra rotación de ese producto es de seis. Si se demora la venta, perdemos.\"</p>\n<p>Ahora sabes el problema real: la rotación.</p><h2>Técnica 2: el etiquetado</h2><p>Consiste en <strong>nombrar la emoción o la preocupación</strong> que percibes, empezando con \"Parece que…\", \"Suena como si…\", \"Da la impresión de que…\". Después, <strong>silencio</strong>.</p>\n<p>—\"Parece que han tenido malas experiencias con proveedores que prometen y no cumplen.\"\nEtiquetar emociones negativas tiende a reducir su intensidad; etiquetar las positivas las refuerza. Evita \"Yo siento que usted…\": pone el foco en ti.</p><h2>Técnica 3: preguntas calibradas</h2><p>Son preguntas abiertas que empiezan por <strong>\"cómo\"</strong> o <strong>\"qué\"</strong>, que invitan al otro a resolver el problema contigo y le dan sensación de control. Evita el \"por qué\", que suele sonar acusatorio.</p>\n<p>Ejemplos:</p>\n<ul>\n<li>\"¿Cómo podríamos hacer que esto funcione para ambos?\"</li>\n<li>\"¿Qué necesitaría para poder aprobar esto ante su comité?\"</li>\n<li>\"¿Qué es lo más importante para usted en este acuerdo?\"</li>\n<li>\"¿Cómo se supone que haga eso con este presupuesto?\" (para responder a una exigencia sin decir no directamente)</li>\n<li>\"¿Qué pasaría si no hacemos nada?\"</li>\n</ul><h2>Técnica 4: buscar el \"no\" y el \"eso es correcto\"</h2><p>Voss sostiene que presionar para obtener un \"sí\" genera desconfianza, porque muchas veces es un sí falso. En cambio, una pregunta que permita decir \"no\" da sensación de seguridad:</p>\n<ul>\n<li>\"¿Sería una mala idea revisar los números juntos?\"</li>\n<li>\"¿Ha renunciado a mejorar el abastecimiento de este producto?\"</li>\n</ul>\n<p>Y el objetivo de un buen resumen es que el otro diga <strong>\"eso es correcto\"</strong>: señal de que se siente entendido. Por ejemplo: \"Si entiendo bien, necesitan un proveedor que entregue a tiempo, con productos de vida útil larga, y que responda rápido cuando hay un problema.\" —\"Eso es correcto.\"</p><h2>La voz en la negociación</h2><p>Voss recomienda una voz tranquila, pausada y cálida en los momentos tensos, que transmite calma y control. El tono asertivo y cortante suele generar resistencia.</p><h2>Ética de estas técnicas</h2><p>Las técnicas de empatía táctica pueden usarse para manipular. En el sector salud, y en cualquier relación de largo plazo, su uso debe ser honesto: escuchar para entender y encontrar soluciones reales, no para presionar decisiones que no convienen a la otra parte o a los pacientes.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb06j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una visitadora médica recibe la frase: \"No tengo tiempo para visitas.\" En lugar de insistir, etiqueta: \"Parece que su agenda está muy apretada.\" El médico asiente. Ella usa una pregunta calibrada: \"¿Qué formato le resultaría más útil para recibir información nueva?\". El médico propone un resumen de una página por correo y una visita trimestral de cinco minutos. La relación mejora y obtiene un canal.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb06j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Espejo: repite palabras clave para que el otro amplíe.</li>\n<li>Etiquetado: nombra emociones con \"parece que…\" y haz silencio.</li>\n<li>Preguntas calibradas con \"cómo\" o \"qué\" y busca el \"eso es correcto\".</li>\n</ol>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb06j${"tone":"info","title":"Siguiente paso","html":"<p>Practica el espejo y el etiquetado en tres conversaciones esta semana, incluso fuera del trabajo.</p>"}$hb06j$::jsonb);

