  VALUES (v_clase, 'destacado', 0, $hb06j${"tone":"info","title":"En esta clase","html":"<p>Los 7 principios de persuasión de Robert Cialdini: reciprocidad, compromiso, prueba social, simpatía, autoridad, escasez y unidad, con ejemplos éticos.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb06j${"html":"<p>¿Por qué decimos que sí? El psicólogo social Robert B. Cialdini dedicó décadas a investigar esa pregunta. En su libro <em>Influencia</em> (1984) describió seis principios que aumentan la probabilidad de que una persona acepte una solicitud, y en <em>Pre-suasión</em> (2016) agregó un séptimo. Conocerlos te ayuda a comunicar tus propuestas de forma más efectiva y también a reconocer cuándo alguien intenta influir en ti. En esta clase los revisaremos uno por uno, con ejemplos éticos.</p><h2>1. Reciprocidad</h2><p>Tendemos a devolver lo que recibimos. Si alguien nos da algo, sentimos la obligación de corresponder.</p>\n<ul>\n<li><strong>Uso ético:</strong> compartir información útil y verificada, ayudar a resolver un problema del cliente sin condiciones.</li>\n<li><strong>Límite:</strong> en el sector salud, los obsequios y beneficios a profesionales que prescriben están regulados por normas y códigos de ética, precisamente porque la reciprocidad puede influir en decisiones clínicas. Conoce y respeta las políticas de tu empresa y la normativa vigente.</li>\n</ul><h2>2. Compromiso y coherencia</h2><p>Una vez que tomamos una posición o un pequeño compromiso, tendemos a actuar de forma coherente con él.</p>\n<ul>\n<li><strong>Uso ético:</strong> pedir a un paciente que diga en voz alta a qué hora tomará su medicamento aumenta la probabilidad de que lo haga. Acordar un pequeño piloto antes de un gran cambio.</li>\n</ul><h2>3. Prueba social</h2><p>Cuando no estamos seguros, miramos lo que hacen otros parecidos a nosotros.</p>\n<ul>\n<li><strong>Uso ético:</strong> \"Otras tres clínicas de la región implementaron este protocolo con buenos resultados\" (si es cierto y verificable).</li>\n<li><strong>Límite:</strong> testimonios inventados o cifras infladas destruyen la credibilidad y pueden ser ilegales.</li>\n</ul><h2>4. Simpatía (agrado)</h2><p>Decimos que sí con más facilidad a las personas que nos agradan: que se parecen a nosotros, nos elogian con sinceridad o cooperan con nosotros.</p>\n<ul>\n<li><strong>Uso ético:</strong> encontrar puntos en común reales, reconocer genuinamente el trabajo del otro.</li>\n</ul><h2>5. Autoridad</h2><p>Seguimos a quienes percibimos como expertos legítimos.</p>\n<ul>\n<li><strong>Uso ético:</strong> mostrar tu formación, citar guías clínicas y fuentes reconocidas, presentarte con tu cargo.</li>\n<li><strong>Límite:</strong> no exageres credenciales ni uses la autoridad fuera de tu competencia.</li>\n</ul><h2>6. Escasez</h2><p>Valoramos más lo que es escaso o lo que podemos perder.</p>\n<ul>\n<li><strong>Uso ético:</strong> informar plazos reales (\"las inscripciones cierran el viernes porque el grupo es de 25 personas\").</li>\n<li><strong>Límite:</strong> la escasez falsa (\"¡solo quedan 2 cupos!\" cuando no es cierto) es manipulación.</li>\n</ul><h2>7. Unidad</h2><p>Nos influyen más quienes consideramos \"de los nuestros\": misma profesión, región, institución o identidad compartida.</p>\n<ul>\n<li><strong>Uso ético:</strong> \"Como químicos farmacéuticos, a los dos nos interesa la seguridad del paciente.\"</li>\n</ul><h2>Persuasión vs. manipulación</h2><p>La diferencia está en tres preguntas:</p>\n<ol>\n<li><strong>¿Es verdad?</strong> La información que uso es veraz y verificable.</li>\n<li><strong>¿Es en interés del otro?</strong> La decisión le conviene a la persona (o al paciente).</li>\n<li><strong>¿Lo diría abiertamente?</strong> Me sentiría cómodo si la otra persona supiera cómo intento influirla.</li>\n</ol>\n<p>Si la respuesta a alguna es no, estás manipulando.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb06j${"tone":"consejo","title":"Ejemplo aplicado: aumentar la adherencia","html":"<p>Un servicio farmacéutico aplica los principios para mejorar la adherencia de pacientes hipertensos: la QF explica con autoridad legítima por qué el medicamento importa (autoridad), pide al paciente que elija la hora de la toma y la escriba (compromiso), le comenta que muchos pacientes del programa usan alarmas en el celular (prueba social) y le regala un pastillero (reciprocidad, de bajo valor y con fines educativos).</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb06j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Reciprocidad, compromiso, prueba social, simpatía, autoridad, escasez y unidad.</li>\n<li>Los principios funcionan; por eso su uso debe ser ético y veraz.</li>\n<li>Persuadir es influir con verdad y en interés del otro; manipular no.</li>\n</ol>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb06j${"tone":"info","title":"Siguiente paso","html":"<p>Identifica qué principios usas en tu trabajo y si pasan las tres preguntas éticas.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Persuasión ética en el sector salud: cómo comunicar beneficios sin exagerar ni manipular', 'Unidad 3 · Clase 3.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb06j${"tone":"info","title":"En esta clase","html":"<p>Cómo persuadir de forma ética en el sector salud: comunicar beneficios con evidencia, presentar riesgos, respetar la autonomía y cumplir la normativa de promoción.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb06j${"html":"<p>En la mayoría de los sectores, una exageración comercial cuesta dinero. En salud, puede costar la seguridad de un paciente. Por eso, la persuasión en el sector farmacéutico tiene reglas adicionales: la información debe ser veraz, completa y equilibrada, y las decisiones clínicas deben basarse en el interés del paciente. En esta clase aprenderás a comunicar beneficios de forma persuasiva y ética, y a reconocer las líneas que no se deben cruzar.</p><h2>Por qué la ética es también una estrategia</h2><p>La confianza es el activo más valioso de un profesional de la salud y de un representante de la industria. Un médico que descubre una exageración en un dato deja de creer en todo lo demás. Un paciente que se sintió presionado a comprar algo que no necesitaba no vuelve. La ética no es un freno a la persuasión: es lo que la hace sostenible.</p><h2>Principios para comunicar un medicamento o servicio</h2><ol>\n<li><strong>Veracidad:</strong> solo afirmaciones respaldadas por evidencia y por la información aprobada del producto.</li>\n<li><strong>Equilibrio:</strong> beneficios y riesgos con la misma claridad. Si mencionas la eficacia, menciona también los eventos adversos relevantes, contraindicaciones y precauciones.</li>\n<li><strong>Precisión numérica:</strong> presenta riesgos absolutos y relativos; no uses solo la cifra que suena más impactante.</li>\n<li><strong>Indicaciones aprobadas:</strong> en Colombia, la promoción debe ajustarse a las indicaciones y condiciones aprobadas en el registro sanitario del INVIMA. No promuevas usos no aprobados.</li>\n<li><strong>Público adecuado:</strong> la publicidad dirigida al público general está restringida a medicamentos de venta libre, y debe cumplir los requisitos de la autoridad sanitaria. Los medicamentos de venta bajo fórmula médica se promocionan solo a profesionales de la salud.</li>\n<li><strong>Transparencia en los incentivos:</strong> obsequios, patrocinios y muestras médicas están regulados por la normativa y por los códigos de ética de la industria y de cada empresa. Conócelos y cúmplelos.</li>\n</ol>\n<p><em>Nota: verifica siempre la normativa vigente y las políticas internas de tu organización; este curso no reemplaza la asesoría de las áreas de cumplimiento y asuntos regulatorios.</em></p><h2>Señales de alerta de manipulación</h2><ul>\n<li>\"Este producto no tiene efectos secundarios.\"</li>\n<li>\"Funciona para todo.\"</li>\n<li>Mostrar solo el subgrupo del estudio donde el resultado fue mejor.</li>\n<li>Comparaciones con un competidor sin estudios cabeza a cabeza.</li>\n<li>Presionar con escasez falsa o urgencia artificial.</li>\n<li>Recomendar a un paciente un producto más costoso por comisión cuando existe una alternativa igual de adecuada.</li>\n</ul><h2>Persuasión ética en el mostrador</h2><p>El personal de droguería también persuade: recomienda productos de venta libre, explica la importancia de completar un tratamiento, sugiere consultar al médico. Para hacerlo bien:</p>\n<ul>\n<li><strong>Pregunta antes de recomendar:</strong> síntomas, duración, otros medicamentos, condiciones especiales (embarazo, edad, enfermedades crónicas).</li>\n<li><strong>Ofrece opciones</strong> con sus diferencias, incluida la de no comprar nada o consultar al médico cuando corresponde.</li>\n<li><strong>No sugieras medicamentos de venta bajo fórmula sin la prescripción.</strong></li>\n<li><strong>Respeta la decisión del paciente.</strong></li>\n</ul><h2>El modelo de decisión compartida</h2><p>En la atención en salud, la persuasión ética se acerca al modelo de <strong>decisión compartida</strong>: el profesional aporta la evidencia y las opciones; el paciente aporta sus valores y preferencias; deciden juntos. El objetivo no es \"convencer\" al paciente, sino que tome una decisión informada.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb06j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un visitador presenta un nuevo anticoagulante. En lugar de decir \"es más seguro\", explica: \"En el estudio pivotal, comparado con warfarina, tuvo menos sangrado mayor en la población estudiada; el riesgo absoluto pasó de X % a Y % en Z años. Requiere ajuste en insuficiencia renal y estas son sus contraindicaciones.\" El médico valora la precisión y le pide la ficha técnica completa. La credibilidad del visitador crece.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb06j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>En salud, persuadir exige veracidad, equilibrio entre beneficios y riesgos, y precisión numérica.</li>\n<li>Ajusta la promoción a las indicaciones aprobadas y a la normativa vigente.</li>\n<li>En el mostrador: pregunta, ofrece opciones y respeta la decisión del paciente.</li>\n</ol>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb06j${"tone":"info","title":"Siguiente paso","html":"<p>Revisa un material o argumento comercial que uses con el checklist de comunicación ética.</p>"}$hb06j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 4. Objeciones y cierre', 3)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Manejo de objeciones: cómo responder a "es muy caro", "ya uso otro" y "no tengo tiempo"', 'Unidad 4 · Clase 4.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb06j${"tone":"info","title":"En esta clase","html":"<p>Manejo de objeciones en ventas y negociación con el método escuchar-reconocer-explorar-responder. Respuestas a \"es muy caro\", \"ya uso otro\" y \"no tengo tiempo\".</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb06j${"html":"<p>Una objeción no es un rechazo: es una señal de que la otra persona está considerando tu propuesta y tiene una duda, una preocupación o una necesidad no resuelta. Los profesionales que más cierran no son los que evitan las objeciones, sino los que las reciben con curiosidad. En esta clase aprenderás un método de cuatro pasos y respuestas modelo para las objeciones más frecuentes del sector.</p><h2>Tipos de objeciones</h2><ul>\n<li><strong>Reales:</strong> una preocupación legítima (precio, seguridad, disponibilidad).</li>\n<li><strong>Por falta de información:</strong> el otro no conoce un dato.</li>\n<li><strong>Excusas o pretextos:</strong> ocultan la verdadera razón (\"lo voy a pensar\").</li>\n<li><strong>Por experiencias previas:</strong> \"La última vez el pedido llegó tarde.\"</li>\n</ul>\n<p>Antes de responder, intenta identificar de qué tipo es.</p><h2>El método ERER</h2><h3>1. Escuchar</h3>\n<p>Deja que la persona termine. No interrumpas ni respondas a la mitad.</p>\n<h3>2. Reconocer</h3>\n<p>Valida la preocupación sin darle la razón automáticamente: \"Entiendo, el costo es un factor importante.\" Evita el \"pero\", que anula lo anterior; usa \"y\".</p>\n<h3>3. Explorar</h3>\n<p>Pregunta para entender la objeción real: \"¿Comparado con qué le parece caro?\", \"¿Qué le preocupa específicamente?\", \"Además del precio, ¿hay algo más que le impida avanzar?\". Esta última pregunta ayuda a detectar si hay otras objeciones ocultas.</p>\n<h3>4. Responder</h3>\n<p>Con información específica, adaptada al interés descubierto. Luego verifica: \"¿Eso resuelve su inquietud?\"</p><h2>Respuestas modelo a objeciones frecuentes</h2><h3>\"Es muy caro\"</h3>\n<ul>\n<li>Explora: \"¿Comparado con qué alternativa?\"</li>\n<li>Responde desde el valor total, no solo el precio: costo por día de tratamiento, costos evitados (por ejemplo, menos consultas o eventos), condiciones de pago, volumen.</li>\n<li>Si el precio no puede cambiar, negocia otras variables.</li>\n<li>Nunca desacredites al competidor.</li>\n</ul>\n<h3>\"Ya uso otro producto / ya tengo proveedor\"</h3>\n<ul>\n<li>Reconoce: \"Tiene sentido mantener lo que le funciona.\"</li>\n<li>Explora: \"¿Qué es lo que más valora de su proveedor actual? ¿Hay algo que le gustaría mejorar?\"</li>\n<li>Responde con un diferencial relevante para su interés o propone una prueba limitada.</li>\n</ul>\n<h3>\"No tengo tiempo\"</h3>\n<ul>\n<li>Reconoce: \"Sé que su agenda es muy apretada.\"</li>\n<li>Propón algo breve y concreto: \"Le tomo dos minutos para mostrarle un dato y usted decide si vale la pena continuar.\"</li>\n<li>O pregunta por el mejor canal: \"¿Qué formato le resulta más práctico?\"</li>\n</ul>\n<h3>\"Déjeme pensarlo\"</h3>\n<ul>\n<li>Explora con respeto: \"Claro. Para ayudarle a pensarlo, ¿qué aspecto le genera más dudas?\"</li>\n<li>Acuerda un siguiente paso concreto: \"¿Le parece si lo llamo el jueves para resolver lo que necesite?\"</li>\n</ul>\n<h3>\"No hay evidencia suficiente\" (médico)</h3>\n<ul>\n<li>Reconoce y comparte la evidencia disponible con sus limitaciones, sin exagerar.</li>\n<li>Ofrece el material completo y la información aprobada del producto.</li>\n<li>Respeta que el médico decida con su criterio clínico.</li>\n</ul><h2>Anticipar objeciones</h2><p>Las objeciones se repiten. Haz una lista de las diez más frecuentes en tu trabajo y prepara respuestas basadas en evidencia. Ensáyalas en parejas.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb06j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>El comprador de una cadena de droguerías dice: \"Su línea de dermocosméticos es más cara que la de la competencia.\" La representante pregunta: \"¿Comparado con qué referencias?\" y \"Además del precio, ¿hay algo más?\". Descubre que el problema real es la baja rotación en dos tiendas. Propone capacitación a los vendedores y exhibición en esas tiendas por tres meses, con revisión de rotación. El comprador acepta.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb06j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Una objeción es una señal de interés y una oportunidad para entender.</li>\n<li>ERER: escuchar, reconocer, explorar y responder.</li>\n<li>Prepara respuestas con evidencia a las objeciones más frecuentes.</li>\n</ol>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb06j${"tone":"info","title":"Siguiente paso","html":"<p>Escribe las cinco objeciones más frecuentes en tu trabajo y una respuesta ERER para cada una.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo cerrar acuerdos: técnicas de cierre, concesiones y seguimiento', 'Unidad 4 · Clase 4.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb06j${"tone":"info","title":"En esta clase","html":"<p>Técnicas de cierre de ventas y negociaciones: señales de compra, cierre por resumen, por alternativa y por siguiente paso, reglas de concesiones y seguimiento.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb06j${"html":"<p>Muchas negociaciones bien conducidas fracasan al final: nadie pide el compromiso, las concesiones se entregan sin recibir nada a cambio o el acuerdo queda en el aire y nunca se ejecuta. Cerrar no es presionar; es ayudar a la otra parte a tomar una decisión y dejar claro qué se acordó. En esta clase aprenderás a reconocer el momento del cierre, a usar técnicas de cierre respetuosas, a manejar las concesiones y a asegurar el seguimiento.</p><h2>Señales de que es momento de cerrar</h2><ul>\n<li>La otra persona hace preguntas de implementación: \"¿Cuándo podrían entregar?\", \"¿Cómo sería el pago?\".</li>\n<li>Las objeciones disminuyen o se vuelven detalles.</li>\n<li>Cambia su lenguaje corporal: se inclina, asiente, toma notas.</li>\n<li>Habla en futuro: \"Cuando lo tengamos…\".</li>\n</ul><h2>Técnicas de cierre respetuosas</h2><h3>Cierre por resumen</h3>\n<p>Resume los acuerdos y beneficios, y pide confirmación: \"Entonces: entrega diaria, pago a 30 días, 6 % de descuento por volumen y recogida de vencidos. ¿Avanzamos con esto?\"</p>\n<h3>Cierre por alternativa</h3>\n<p>Ofrece dos opciones válidas: \"¿Prefiere iniciar con el pedido completo o con un piloto en dos sedes?\"</p>\n<h3>Cierre por siguiente paso</h3>\n<p>Cuando la decisión no se puede tomar hoy: \"¿Cuál sería el siguiente paso para que su comité lo evalúe? ¿Le parece si le envío la propuesta mañana y agendamos la revisión para el martes?\"</p>\n<h3>Cierre directo</h3>\n<p>Simplemente pedirlo: \"¿Le parece si cerramos el acuerdo?\" Muchas veces es el más efectivo y el menos usado.</p>\n<p>Evita los cierres de presión (\"si no firma hoy pierde el descuento\" cuando no es cierto).</p><h2>Reglas de las concesiones</h2><ol>\n<li><strong>Nunca concedas sin recibir algo a cambio:</strong> \"Si ustedes amplían el volumen, nosotros podemos mejorar el plazo.\"</li>\n<li><strong>Concede en cantidades decrecientes:</strong> 3 %, luego 1,5 %, luego 0,5 %. Indica que te acercas a tu límite.</li>\n<li><strong>Concede lo que es barato para ti y valioso para el otro.</strong></li>\n<li><strong>No concedas al final por cansancio</strong>; si es necesario, pide una pausa.</li>\n<li><strong>No te muevas de tu precio de reserva</strong>: si no hay acuerdo mejor que tu MAAN, retírate con cortesía.</li>\n</ol><h2>La técnica del \"todo o nada\"</h2><p>Cuando se negocian varios temas, acuerda que <strong>nada está acordado hasta que todo esté acordado</strong>. Así evitas ceder en un tema y quedarte sin margen para el siguiente.</p><h2>Formalizar el acuerdo</h2><p>Un acuerdo verbal se olvida o se interpreta de distintas formas. Después de cerrar:</p>\n<ul>\n<li>Envía un <strong>acta o correo de confirmación</strong> el mismo día con: partes, temas acordados, condiciones, responsables, fechas y próximos pasos.</li>\n<li>Pide confirmación por escrito.</li>\n<li>Si el acuerdo implica contratos, involucra a las áreas jurídica, de cumplimiento o compras según corresponda.</li>\n</ul><h2>Seguimiento: el cierre que construye relaciones</h2><ul>\n<li>Verifica la ejecución en la primera entrega o actividad.</li>\n<li>Agenda una revisión de resultados.</li>\n<li>Resuelve rápido cualquier incumplimiento propio.</li>\n<li>Agradece.</li>\n</ul>\n<p>El cumplimiento del primer acuerdo es la base de la siguiente negociación.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb06j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una KAM cierra con una IPS un acuerdo de suministro. Usa cierre por resumen, recibe un \"sí, pero necesito aprobación del gerente\", y pasa a cierre por siguiente paso: propuesta enviada al día siguiente y reunión con el gerente el jueves. Después de la aprobación envía el acta con responsables y fechas, y agenda una revisión a los 60 días. En la revisión, la IPS amplía el pedido a otras sedes.</p>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb06j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Reconoce las señales de cierre y pide el compromiso.</li>\n<li>Concede siempre a cambio de algo, en cantidades decrecientes y sin bajar de tu límite.</li>\n<li>Formaliza por escrito y haz seguimiento: el primer acuerdo construye el siguiente.</li>\n</ol>"}$hb06j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb06j${"tone":"info","title":"Siguiente paso","html":"<p>Revisa tu último acuerdo: ¿quedó por escrito con responsables y fechas? Si no, envía un correo de confirmación.</p>"}$hb06j$::jsonb);
END
$hb06$;

-- ─── Curso de Inteligencia Emocional en el Trabajo (8 clases) ───
DO $hb07$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Inteligencia Emocional en el Trabajo' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, area, level, tags,
     objective, learning_outcomes, audience, duration_minutes, author_name, status, modality, cover_url, publico)
  VALUES ('edvanta', 'Curso de Inteligencia Emocional en el Trabajo', $hb07t$Curso para reconocer, comprender y regular las emociones propias y ajenas en el trabajo: autoconocimiento, autorregulación, manejo del estrés y prevención del burnout, empatía con pacientes y compañeros, habilidades sociales y resiliencia.$hb07t$,
          $hb07t$<p>Curso para reconocer, comprender y regular las emociones propias y ajenas en el trabajo: autoconocimiento, autorregulación, manejo del estrés y prevención del burnout, empatía con pacientes y compañeros, habilidades sociales y resiliencia.</p><h2>Objetivo</h2><p>Que el participante identifique y nombre con precisión sus emociones, aplique estrategias de autorregulación, responda con empatía a las emociones de pacientes y compañeros (NURSE) y diseñe un plan personal de desarrollo emocional y prevención del desgaste.</p><h2>Para quién es</h2><p>Profesionales y auxiliares del sector salud y farmacéutico, coordinadores de equipo y personal de atención al público.</p><h2>Cómo está organizado</h2><p>Cuatro unidades con dos clases en texto cada una. Cada clase trae un ejemplo aplicado al sector farmacéutico y de la salud, puntos clave y el siguiente paso.</p><h2>Referentes</h2><p>Peter Salovey y John D. Mayer (definición original, 1990); Daniel Goleman (Inteligencia emocional, 1995; modelo de competencias); Christina Maslach (burnout); Matthew Lieberman (etiquetado afectivo, UCLA); VitalTalk (protocolo NURSE para responder a emociones); Organización Mundial de la Salud (CIE-11, burnout como fenómeno ocupacional).</p>$hb07t$,
          'Liderazgo y relaciones laborales', 'Habilidades Blandas', 'basico', ARRAY['Inteligencia emocional', 'Empatía', 'Burnout', 'Resiliencia', 'Habilidades blandas']::text[],
          $hb07t$Que el participante identifique y nombre con precisión sus emociones, aplique estrategias de autorregulación, responda con empatía a las emociones de pacientes y compañeros (NURSE) y diseñe un plan personal de desarrollo emocional y prevención del desgaste.$hb07t$,
          ARRAY['Explicar qué es la inteligencia emocional e identificar y nombrar tus emociones.', 'Regular tus reacciones y prevenir el estrés laboral y el burnout.', 'Responder con empatía a pacientes y compañeros con el protocolo NURSE.', 'Fortalecer tus habilidades sociales y tu resiliencia con un plan de desarrollo emocional.']::text[],
          $hb07t$Profesionales y auxiliares del sector salud y farmacéutico, coordinadores de equipo y personal de atención al público.$hb07t$,
          152, 'Edvanta', 'borrador', 'asincronica', '/img/cursos/inteligencia-emocional.webp', 'profesionales')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Qué es la inteligencia emocional y autoconocimiento', 0)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Qué es la inteligencia emocional: definición, modelos y por qué importa en el trabajo', 'Unidad 1 · Clase 1.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb07j${"tone":"info","title":"En esta clase","html":"<p>Qué es la inteligencia emocional según Salovey, Mayer y Goleman, sus componentes y por qué importa en el trabajo y en la atención en salud.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb07j${"html":"<p>Seguramente conoces a alguien muy brillante técnicamente que no logra trabajar en equipo, y a alguien con menos títulos que todos buscan para resolver problemas difíciles. La diferencia, muchas veces, está en cómo manejan sus emociones y las de los demás. Eso es, en esencia, la inteligencia emocional. En esta clase conocerás su definición, sus principales modelos y por qué es tan importante en el trabajo, especialmente en el sector salud.</p><h2>Definición</h2><p>El concepto fue propuesto en 1990 por los psicólogos <strong>Peter Salovey y John D. Mayer</strong>, que definieron la inteligencia emocional como la capacidad de <strong>percibir, comprender, usar y regular las emociones</strong> propias y ajenas para guiar el pensamiento y la acción.</p>\n<p>En 1995, el periodista y psicólogo <strong>Daniel Goleman</strong> popularizó el término con su libro <em>Inteligencia emocional</em>, y luego lo aplicó al mundo laboral.</p><h2>Dos grandes enfoques</h2><h3>Modelo de habilidades (Mayer y Salovey)</h3>\n<p>Considera la inteligencia emocional como un conjunto de capacidades mentales, organizadas en cuatro ramas:</p>\n<ol>\n<li><strong>Percibir emociones</strong> en uno mismo y en los demás.</li>\n<li><strong>Usar las emociones</strong> para facilitar el pensamiento.</li>\n<li><strong>Comprender las emociones</strong>: su origen y cómo cambian.</li>\n<li><strong>Regular las emociones</strong> propias y de otros.</li>\n</ol>\n<h3>Modelo de competencias (Goleman)</h3>\n<p>Más práctico y orientado al trabajo. En su formulación clásica incluye cinco componentes:</p>\n<ol>\n<li><strong>Autoconciencia:</strong> reconocer las propias emociones y su efecto.</li>\n<li><strong>Autorregulación:</strong> manejar los impulsos y las emociones perturbadoras.</li>\n<li><strong>Motivación:</strong> orientarse a metas con persistencia.</li>\n<li><strong>Empatía:</strong> comprender las emociones y perspectivas de los demás.</li>\n<li><strong>Habilidades sociales:</strong> manejar relaciones, influir, resolver conflictos, trabajar en equipo.</li>\n</ol>\n<p>Este curso se organiza alrededor de esos cinco componentes.</p><h2>Lo que la inteligencia emocional no es</h2><ul>\n<li><strong>No es ser siempre amable</strong> ni evitar las emociones \"negativas\". La tristeza, el enojo o el miedo dan información útil.</li>\n<li><strong>No es reprimir:</strong> regular no es esconder.</li>\n<li><strong>No es un rasgo fijo:</strong> muchas de sus habilidades pueden desarrollarse con práctica.</li>\n<li><strong>No reemplaza la competencia técnica:</strong> la complementa.</li>\n</ul>\n<p>Un apunte de rigor: algunas afirmaciones populares (por ejemplo, que la inteligencia emocional \"importa el doble que el coeficiente intelectual\") no tienen el mismo respaldo que los modelos de investigación. Este curso se basa en habilidades concretas y prácticas.</p><h2>Por qué importa en el sector salud</h2><p>El trabajo en salud tiene una alta carga emocional: pacientes con dolor o miedo, familiares angustiados, presión de tiempo, errores con consecuencias graves y jornadas largas. La inteligencia emocional ayuda a:</p>\n<ul>\n<li>Comunicarse mejor con pacientes y entender lo que no dicen.</li>\n<li>Manejar quejas y situaciones tensas sin escalar.</li>\n<li>Trabajar en equipos interdisciplinarios con menos conflictos.</li>\n<li>Proteger la propia salud mental y prevenir el desgaste.</li>\n<li>Tomar mejores decisiones bajo presión.</li>\n</ul>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb07j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un regente recibe a un paciente que grita porque su EPS no autorizó el medicamento. Sin inteligencia emocional, el regente responde a la defensiva: \"Eso no es culpa mía.\" Con inteligencia emocional, reconoce su propio enojo (autoconciencia), respira antes de responder (autorregulación), entiende la angustia del paciente (empatía) y le explica qué puede hacer y a dónde dirigirse (habilidad social). El problema no desaparece, pero la situación se desescala y el paciente sale con un camino.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb07j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La inteligencia emocional es percibir, comprender, usar y regular emociones propias y ajenas.</li>\n<li>El modelo de Goleman incluye autoconciencia, autorregulación, motivación, empatía y habilidades sociales.</li>\n<li>Se puede desarrollar y es especialmente útil en el trabajo de alta carga emocional.</li>\n</ol>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb07j${"tone":"info","title":"Siguiente paso","html":"<p>Responde el autodiagnóstico y elige el componente que más quieres fortalecer.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Autoconocimiento emocional: cómo identificar y nombrar lo que sientes', 'Unidad 1 · Clase 1.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb07j${"tone":"info","title":"En esta clase","html":"<p>Cómo desarrollar la inteligencia emocional empezando por el autoconocimiento: vocabulario emocional, señales del cuerpo, detonantes y diario emocional.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb07j${"html":"<p>\"¿Cómo estás?\" \"Bien.\" \"Estresado.\" \"Normal.\" Para muchas personas, el vocabulario emocional se reduce a tres o cuatro palabras. Pero no es lo mismo estar frustrado que decepcionado, ansioso que preocupado o irritado que resentido. Cada emoción da información distinta y pide una respuesta distinta. El autoconocimiento emocional es la base de la inteligencia emocional: no puedes regular lo que no reconoces. En esta clase aprenderás a identificar y nombrar lo que sientes con precisión.</p><h2>Por qué nombrar las emociones ayuda</h2><p>Investigaciones del equipo de Matthew Lieberman en la Universidad de California (UCLA) mostraron que <strong>poner en palabras una emoción</strong> (etiquetado afectivo) se asocia con una menor activación de la amígdala, una región cerebral relacionada con las respuestas de amenaza. En términos prácticos: decir \"estoy frustrado\" ya ayuda a regular la frustración.</p>\n<p>Además, la psicóloga Lisa Feldman Barrett habla de <strong>granularidad emocional</strong>: la capacidad de distinguir emociones con precisión. Las personas con mayor granularidad tienden a manejar mejor el estrés porque pueden elegir respuestas más ajustadas.</p><h2>Amplía tu vocabulario emocional</h2><p>Partiendo de emociones básicas, aprende a diferenciar matices:</p>\n<ul>\n<li><strong>Enojo:</strong> irritación, frustración, indignación, resentimiento, impotencia.</li>\n<li><strong>Miedo:</strong> preocupación, ansiedad, inseguridad, temor, pánico.</li>\n<li><strong>Tristeza:</strong> decepción, desánimo, nostalgia, soledad, culpa.</li>\n<li><strong>Alegría:</strong> satisfacción, orgullo, alivio, entusiasmo, gratitud.</li>\n<li><strong>Asco/rechazo:</strong> incomodidad, desagrado, desprecio.</li>\n<li><strong>Sorpresa:</strong> asombro, desconcierto, confusión.</li>\n</ul>\n<p>Usa la rueda de emociones para encontrar la palabra más precisa.</p><h2>Escucha a tu cuerpo</h2><p>Las emociones se sienten primero en el cuerpo. Aprende a reconocer tus señales:</p>\n<ul>\n<li>Mandíbula apretada, calor en la cara → posible enojo.</li>\n<li>Nudo en el estómago, respiración rápida → posible ansiedad.</li>\n<li>Pecho pesado, cansancio → posible tristeza.</li>\n<li>Hombros tensos, dolor de cabeza al final del día → posible estrés acumulado.</li>\n</ul>\n<p>Un ejercicio útil es el <strong>escaneo corporal</strong>: tres veces al día, detente 30 segundos y recorre mentalmente tu cuerpo de la cabeza a los pies preguntando \"¿qué siento aquí?\".</p><h2>Identifica tus detonantes</h2><p>Los detonantes son situaciones que activan emociones intensas de forma predecible. En el trabajo pueden ser:</p>\n<ul>\n<li>Que te interrumpan.</li>\n<li>Que un paciente te grite.</li>\n<li>Que cuestionen tu competencia frente a otros.</li>\n<li>Las filas largas en horas pico.</li>\n<li>Los cambios de última hora.</li>\n</ul>\n<p>Conocer tus detonantes te permite prepararte y responder en lugar de reaccionar.</p><h2>El diario emocional</h2><p>Durante siete días, registra al menos una situación por día:</p>\n<ol>\n<li><strong>Situación:</strong> ¿qué pasó?</li>\n<li><strong>Emoción:</strong> nómbrala con precisión e indica su intensidad (0–10).</li>\n<li><strong>Cuerpo:</strong> ¿dónde la sentiste?</li>\n<li><strong>Pensamiento:</strong> ¿qué te dijiste en ese momento?</li>\n<li><strong>Acción:</strong> ¿qué hiciste?</li>\n<li><strong>Reflexión:</strong> ¿te sirvió esa acción? ¿Qué harías distinto?</li>\n</ol>\n<p>Al final de la semana, busca patrones: ¿qué emociones se repiten?, ¿en qué horarios?, ¿con quién?</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb07j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una QF de un servicio de farmacia hospitalaria nota en su diario que se siente \"estresada\" todos los días a las 11 a. m. Al revisar con más precisión, descubre que lo que siente es <strong>impotencia</strong>: a esa hora llegan las solicitudes urgentes de los pisos y no tiene control sobre el volumen. Con esa claridad, propone a la coordinación un horario de corte para solicitudes no urgentes. La emoción bien identificada la llevó a una acción concreta.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb07j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Nombrar las emociones con precisión ayuda a regularlas.</li>\n<li>El cuerpo da señales tempranas; aprende a escucharlas.</li>\n<li>Identificar detonantes y llevar un diario emocional revela patrones.</li>\n</ol>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb07j${"tone":"info","title":"Siguiente paso","html":"<p>Empieza tu diario emocional de siete días hoy mismo.</p>"}$hb07j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 2. Autorregulación y manejo del estrés', 1)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Autorregulación emocional: técnicas para no reaccionar en caliente', 'Unidad 2 · Clase 2.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb07j${"tone":"info","title":"En esta clase","html":"<p>Técnicas de autorregulación emocional para no reaccionar en caliente en el trabajo: técnica STOP, pausa, reevaluación cognitiva y respuesta consciente.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb07j${"html":"<p>Todos hemos dicho o escrito algo en caliente de lo que luego nos arrepentimos: una respuesta brusca a un compañero, un correo enviado con rabia, un tono duro con un paciente. La autorregulación emocional no consiste en dejar de sentir, sino en <strong>crear un espacio entre lo que sientes y lo que haces</strong>. En esta clase aprenderás técnicas concretas para responder en lugar de reaccionar.</p><h2>¿Qué es la autorregulación emocional?</h2><p>Es la capacidad de <strong>influir en qué emociones tienes, cuándo las tienes y cómo las expresas</strong>. El psicólogo James Gross, de la Universidad de Stanford, describe varias estrategias de regulación según el momento en que se aplican: antes de la situación (elegirla o modificarla), durante (dónde pones la atención y cómo interpretas lo que pasa) y después (cómo modulas tu respuesta).</p><h2>Por qué reaccionamos en caliente</h2><p>Ante una amenaza percibida (un grito, una crítica, una injusticia), el cerebro activa respuestas rápidas de defensa. La parte más reflexiva tarda un poco más en \"llegar\". Si actuamos en esos primeros segundos, actuamos desde la reacción. La clave es <strong>ganar unos segundos</strong>.</p><h2>Técnica 1: STOP</h2><p>Una técnica breve derivada de la práctica de atención plena:</p>\n<ul>\n<li><strong>S — Stop (para):</strong> detente; no hables ni escribas.</li>\n<li><strong>T — Toma aire:</strong> una o dos respiraciones con exhalación larga.</li>\n<li><strong>O — Observa:</strong> ¿qué siento?, ¿dónde lo siento?, ¿qué estoy pensando?</li>\n<li><strong>P — Procede:</strong> elige conscientemente qué decir o hacer.</li>\n</ul>\n<p>Puede hacerse en 10 segundos, incluso frente a un paciente.</p><h2>Técnica 2: la pausa estratégica</h2><p>Cuando la emoción es muy intensa, pide tiempo:</p>\n<ul>\n<li>\"Déjeme revisar su caso y en un minuto le respondo.\"</li>\n<li>\"Quiero darte una respuesta bien pensada; hablemos después del almuerzo.\"</li>\n<li>Ante un correo que te molestó: escribe el borrador, <strong>no lo envíes</strong>, y revísalo una hora después.</li>\n</ul><h2>Técnica 3: reevaluación cognitiva</h2><p>Consiste en <strong>cambiar la interpretación</strong> de la situación. Las investigaciones de Gross y otros muestran que la reevaluación suele ser más saludable a largo plazo que la supresión (esconder la emoción sin procesarla).</p>\n<p>Preguntas para reevaluar:</p>\n<ul>\n<li>¿Hay otra explicación posible para lo que pasó?</li>\n<li>¿Qué podría estar viviendo la otra persona?</li>\n<li>¿Qué importancia tendrá esto en una semana?</li>\n<li>¿Qué haría alguien a quien admiro en esta situación?</li>\n</ul>\n<p>Ejemplo: un paciente te grita. Interpretación inicial: \"Me está irrespetando.\" Reevaluación: \"Lleva tres semanas sin su medicamento y está asustado; el grito no es contra mí, es contra la situación.\" La emoción cambia de enojo a una mezcla de firmeza y comprensión.</p><h2>Técnica 4: nombrar para regular</h2><p>Como vimos, nombrar la emoción reduce su intensidad. Hazlo internamente: \"Estoy sintiendo enojo. Es fuerte, un 7 de 10.\"</p><h2>Técnica 5: cuidar la base fisiológica</h2><p>La autorregulación es más difícil cuando tienes hambre, sueño o llevas horas sin pausa. No es un tema de \"fuerza de voluntad\": cuidar el descanso, la alimentación y las pausas activas aumenta tu capacidad de regularte.</p><h2>Supresión: por qué no es la mejor estrategia</h2><p>Tragarse la emoción y poner cara de nada puede ser necesario en un momento puntual, pero como estrategia habitual se ha asociado con más malestar, peor memoria de la situación y relaciones menos cercanas. Lo ideal es regular en el momento y <strong>procesar después</strong> (hablarlo, escribirlo, hacer ejercicio).</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb07j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un auxiliar recibe la tercera queja del día por un medicamento agotado. Siente que se le calienta la cara. Aplica STOP: para, exhala, nota \"estoy frustrado, 8 de 10\" y elige responder: \"Entiendo la molestia. Revisemos juntos en qué otras sedes lo tenemos.\" Al final del turno le comenta a su coordinadora el patrón de agotados para buscar una solución.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb07j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Regular es crear un espacio entre sentir y actuar.</li>\n<li>STOP, pausa estratégica, reevaluación y nombrar la emoción.</li>\n<li>Cuida tu base fisiológica y procesa después lo que regulaste en el momento.</li>\n</ol>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb07j${"tone":"info","title":"Siguiente paso","html":"<p>Usa la técnica STOP al menos tres veces esta semana y registra el resultado en tu diario.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Estrés laboral y síndrome de burnout en profesionales de la salud: señales y prevención', 'Unidad 2 · Clase 2.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb07j${"tone":"info","title":"En esta clase","html":"<p>Qué es el síndrome de burnout según la OMS y Maslach, sus señales en profesionales de la salud y estrategias individuales y organizacionales de prevención.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb07j${"html":"<p>Llegar al trabajo ya cansado, sentir que los pacientes son \"casos\" y no personas, pensar que nada de lo que haces sirve. Estas no son señales de debilidad: pueden ser señales de <strong>burnout</strong> o síndrome de agotamiento profesional, un problema frecuente entre quienes trabajan en salud. En esta clase aprenderás a diferenciar el estrés del burnout, reconocer sus señales y aplicar estrategias de prevención individuales y organizacionales.</p><h2>Estrés vs. burnout</h2><ul>\n<li><strong>Estrés:</strong> respuesta a demandas que superan temporalmente nuestros recursos. Hay sobreactivación, urgencia, hiperactividad. Puede ser puntual y manejable.</li>\n<li><strong>Burnout:</strong> resultado del <strong>estrés laboral crónico que no se ha manejado con éxito</strong>. Predomina el agotamiento, la desconexión y la pérdida de sentido.</li>\n</ul><h2>¿Qué es el burnout según la OMS?</h2><p>La Organización Mundial de la Salud incluye el burnout en la Clasificación Internacional de Enfermedades (CIE-11) como un <strong>fenómeno ocupacional</strong>, no como una condición médica. Lo describe con tres dimensiones:</p>\n<ol>\n<li><strong>Sentimientos de agotamiento</strong> o falta de energía.</li>\n<li><strong>Mayor distancia mental del trabajo</strong>, o sentimientos negativos o cínicos hacia él.</li>\n<li><strong>Reducción de la eficacia profesional.</strong></li>\n</ol>\n<p>Estas dimensiones coinciden con el modelo de la psicóloga <strong>Christina Maslach</strong>, autora del instrumento más usado para evaluarlo (Maslach Burnout Inventory), que habla de agotamiento emocional, despersonalización y baja realización personal.</p><h2>Señales de alerta</h2><p><strong>Físicas:</strong> cansancio que no mejora con el descanso, dolores de cabeza o musculares frecuentes, problemas de sueño, enfermarse con frecuencia.\n<strong>Emocionales:</strong> irritabilidad, sensación de vacío, desmotivación, cinismo (\"¿para qué?\").\n<strong>Conductuales:</strong> aislamiento, aumento del consumo de alcohol, cafeína u otras sustancias, ausentismo, más errores, trato frío con pacientes.</p><h2>Factores de riesgo en el trabajo</h2><p>Maslach y Michael Leiter identificaron seis áreas de desajuste entre la persona y el trabajo:</p>\n<ol>\n<li><strong>Carga de trabajo</strong> excesiva.</li>\n<li><strong>Falta de control</strong> sobre las decisiones.</li>\n<li><strong>Recompensa insuficiente</strong> (económica, social o de reconocimiento).</li>\n<li><strong>Falta de comunidad</strong> (malas relaciones, aislamiento).</li>\n<li><strong>Falta de equidad</strong> (injusticias percibidas).</li>\n<li><strong>Conflicto de valores</strong> (hacer cosas contrarias a lo que crees correcto).</li>\n</ol>\n<p>Esto muestra algo importante: <strong>el burnout no es solo un problema individual</strong>. La prevención requiere acciones de la persona y de la organización.</p><h2>Estrategias individuales</h2><ul>\n<li><strong>Límites:</strong> horarios de desconexión, pausas reales, vacaciones.</li>\n<li><strong>Recuperación:</strong> sueño suficiente, actividad física, tiempo con personas significativas.</li>\n<li><strong>Regulación emocional:</strong> técnicas de la clase anterior, diario emocional.</li>\n<li><strong>Sentido:</strong> recordar el impacto de tu trabajo (pacientes que ayudaste).</li>\n<li><strong>Red de apoyo:</strong> hablar con colegas de confianza.</li>\n<li><strong>Pedir ayuda profesional</strong> cuando las señales persisten.</li>\n</ul><h2>Estrategias organizacionales</h2><ul>\n<li>Revisar cargas de trabajo y turnos.</li>\n<li>Dar mayor participación en decisiones.</li>\n<li>Reconocer el trabajo de forma frecuente y específica.</li>\n<li>Fomentar espacios de apoyo entre pares.</li>\n<li>Formar a los líderes en detección temprana.</li>\n<li>En Colombia, los programas de riesgo psicosocial hacen parte del Sistema de Gestión de Seguridad y Salud en el Trabajo; la Resolución 2764 de 2022 del Ministerio del Trabajo adoptó la batería de instrumentos para evaluar factores de riesgo psicosocial. Verifica la normativa vigente con tu área de SST.</li>\n</ul><h2>Cuándo consultar</h2><p>Si tienes síntomas persistentes de tristeza, ansiedad, insomnio, pensamientos de desesperanza o de hacerte daño, consulta con un profesional de la salud mental o con los servicios de tu EPS o ARL. Si tienes pensamientos de hacerte daño, busca ayuda inmediata en los servicios de urgencias o líneas de atención en crisis de tu ciudad.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb07j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>El burnout es un fenómeno ocupacional por estrés laboral crónico mal manejado (OMS, CIE-11).</li>\n<li>Sus tres dimensiones: agotamiento, distancia o cinismo y baja eficacia.</li>\n<li>La prevención combina estrategias individuales y organizacionales.</li>\n</ol>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb07j${"tone":"info","title":"Siguiente paso","html":"<p>Completa tu plan de autocuidado e identifica cuál de las seis áreas de Maslach y Leiter está más afectada en tu trabajo.</p>"}$hb07j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 3. Empatía', 2)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Qué es la empatía: tipos, cómo se desarrolla y sus límites', 'Unidad 3 · Clase 3.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb07j${"tone":"info","title":"En esta clase","html":"<p>Qué es la empatía, sus tres tipos (cognitiva, emocional y compasiva), cómo se desarrolla en el trabajo y por qué es importante cuidar sus límites.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb07j${"html":"<p>La empatía es una de las habilidades más valoradas en el trabajo y en la atención en salud. Pero también es una de las más malentendidas: algunos creen que ser empático es estar de acuerdo con todo, otros que es \"sufrir con el otro\". En esta clase aprenderás qué es la empatía, sus tres tipos, cómo desarrollarla y por qué es importante cuidar sus límites para no agotarte.</p><h2>¿Qué es la empatía?</h2><p>La empatía es la capacidad de <strong>comprender y compartir el estado emocional y la perspectiva de otra persona</strong>. No implica estar de acuerdo con ella ni hacer lo que pide; implica entenderla.</p><h2>Los tres tipos de empatía</h2><p>Daniel Goleman y Paul Ekman, entre otros, distinguen tres formas de empatía:</p>\n<h3>1. Empatía cognitiva</h3>\n<p><strong>Entender</strong> lo que el otro piensa y siente; ver la situación desde su perspectiva. Es útil para comunicar, negociar y explicar. Por sí sola puede ser fría: puedes entender a alguien sin que te importe.</p>\n<h3>2. Empatía emocional (afectiva)</h3>\n<p><strong>Sentir</strong> algo de lo que siente el otro. Genera conexión, pero en exceso puede llevar a la angustia personal: absorber el sufrimiento ajeno hasta agotarte.</p>\n<h3>3. Preocupación empática o empatía compasiva</h3>\n<p><strong>Entender, sentir y querer ayudar.</strong> Combina comprensión y conexión con motivación para actuar. Es la forma más útil en la atención en salud.</p><h2>Empatía y compasión</h2><p>Investigaciones en neurociencia, como las de Tania Singer y Olga Klimecki, sugieren que la empatía emocional sostenida frente al sufrimiento puede generar angustia, mientras que la <strong>compasión</strong> (orientada al cuidado y a la acción) se asocia con emociones más positivas y mayor disposición a ayudar. Para quienes trabajan con pacientes, entrenar la compasión puede ser más protector que solo \"sentir con el otro\".</p><h2>Cómo desarrollar la empatía</h2><ol>\n<li><strong>Escucha activa:</strong> atención plena, parafraseo, reflejo de emociones.</li>\n<li><strong>Curiosidad genuina:</strong> pregunta en lugar de suponer. \"¿Cómo ha sido esto para usted?\"</li>\n<li><strong>Toma de perspectiva:</strong> antes de juzgar, pregúntate \"¿qué podría estar viviendo esta persona?\".</li>\n<li><strong>Suspende el juicio:</strong> el comportamiento difícil suele tener una historia detrás.</li>\n<li><strong>Amplía tu contacto:</strong> conocer personas de contextos distintos aumenta la capacidad de comprender perspectivas diferentes.</li>\n<li><strong>Observa señales no verbales</strong> (como vimos en el curso de lenguaje corporal) y verifica preguntando.</li>\n</ol><h2>Lo que no es empatía</h2><ul>\n<li><strong>Minimizar:</strong> \"No es para tanto.\"</li>\n<li><strong>Comparar:</strong> \"A mí me pasó algo peor.\"</li>\n<li><strong>Aconsejar de inmediato:</strong> \"Lo que tiene que hacer es…\".</li>\n<li><strong>Buscar el lado positivo demasiado pronto:</strong> \"Al menos…\".</li>\n<li><strong>Decir \"te entiendo\" sin demostrarlo.</strong></li>\n</ul>\n<p>Brené Brown, investigadora de la Universidad de Houston, señala que la empatía rara vez empieza con \"al menos\": empieza con conectar con lo que el otro siente.</p><h2>Los límites de la empatía</h2><ul>\n<li><strong>Empatía no es aceptar todo:</strong> puedes comprender el enojo de un paciente y, al mismo tiempo, poner un límite si te insulta.</li>\n<li><strong>Fatiga por compasión:</strong> la exposición repetida al sufrimiento ajeno puede agotar. Cuidar tus recursos (clase 2.2) es parte de poder seguir siendo empático.</li>\n<li><strong>Empatía selectiva:</strong> tendemos a sentir más empatía por quienes se parecen a nosotros. Ser consciente de ese sesgo ayuda a tratar a todos con equidad.</li>\n</ul>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb07j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una madre llega a la droguería con un niño con fiebre y pide \"el antibiótico que le dieron la otra vez\". La auxiliar podría responder: \"Sin fórmula no se puede\" (correcto, pero frío). Con empatía compasiva: \"Veo que está muy preocupada por su hijo (empatía). Los antibióticos necesitan fórmula médica porque no siempre son necesarios para la fiebre y pueden hacer daño si no se usan bien (información). Le puedo explicar cómo manejar la fiebre mientras lo ve el médico y cuáles son las señales para ir a urgencias (acción).\"</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb07j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La empatía puede ser cognitiva, emocional o compasiva.</li>\n<li>La empatía compasiva —entender, sentir y actuar— es la más útil y protectora en salud.</li>\n<li>Empatía no es aceptar todo ni absorber todo el sufrimiento: tiene límites sanos.</li>\n</ol>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb07j${"tone":"info","title":"Siguiente paso","html":"<p>En tus próximas cinco interacciones difíciles, evita minimizar, comparar o aconsejar de inmediato, y pregunta primero.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Empatía con el paciente: cómo responder a las emociones con el protocolo NURSE', 'Unidad 3 · Clase 3.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb07j${"tone":"info","title":"En esta clase","html":"<p>Cómo responder a las emociones de los pacientes con el protocolo NURSE (nombrar, entender, respetar, apoyar, explorar). Ejemplos en farmacia y atención en salud.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb07j${"html":"<p>Un paciente llora al recibir su primera insulina. Otro se enoja porque el medicamento es muy costoso. Una cuidadora se muestra agotada al pedir los pañales de su madre. En esos momentos, la información técnica no basta: si no respondes a la emoción, la persona no podrá escuchar lo demás. El protocolo NURSE, desarrollado en el campo de la comunicación clínica, ofrece frases concretas para responder a las emociones con empatía. En esta clase aprenderás a usarlo en la atención farmacéutica.</p><h2>¿Qué es NURSE?</h2><p>NURSE es un acrónimo en inglés usado en la formación en comunicación clínica (por ejemplo, por la organización VitalTalk, enfocada en conversaciones difíciles en salud). Propone cinco tipos de respuesta empática:</p>\n<h3>N — Name (Nombrar)</h3>\n<p>Nombra la emoción que percibes, de forma tentativa.</p>\n<ul>\n<li>\"Parece que esto le preocupa mucho.\"</li>\n<li>\"Me imagino que es frustrante.\"</li>\n</ul>\n<h3>U — Understand (Entender)</h3>\n<p>Expresa que comprendes por qué se siente así, sin decir \"lo entiendo perfectamente\" (nadie entiende perfectamente la experiencia de otro).</p>\n<ul>\n<li>\"Tiene sentido que se sienta así después de tantas vueltas.\"</li>\n<li>\"Es comprensible que asuste empezar con insulina.\"</li>\n</ul>\n<h3>R — Respect (Respetar)</h3>\n<p>Reconoce el esfuerzo, la fortaleza o lo que la persona ha hecho.</p>\n<ul>\n<li>\"Se nota lo mucho que ha hecho por cuidar a su mamá.\"</li>\n<li>\"Ha sido muy constante con su tratamiento.\"</li>\n</ul>\n<h3>S — Support (Apoyar)</h3>\n<p>Expresa tu disposición a acompañar y ayudar.</p>\n<ul>\n<li>\"Vamos a buscar juntos la mejor opción.\"</li>\n<li>\"Aquí estamos para ayudarle con lo que necesite.\"</li>\n</ul>\n<h3>E — Explore (Explorar)</h3>\n<p>Invita a la persona a contar más.</p>\n<ul>\n<li>\"¿Qué es lo que más le preocupa?\"</li>\n<li>\"Cuénteme un poco más de cómo ha sido.\"</li>\n</ul>\n<p>No es necesario usar las cinco en orden ni en cada conversación. Con una o dos respuestas bien elegidas, la emoción suele bajar lo suficiente para continuar.</p><h2>Cuándo usar NURSE</h2><ul>\n<li>Cuando el paciente expresa una emoción de forma verbal o no verbal (llanto, silencio, voz quebrada, enojo).</li>\n<li>Cuando notas que la información técnica no está siendo escuchada.</li>\n<li>Antes de dar instrucciones importantes, si hay una emoción intensa presente.</li>\n</ul><h2>Errores frecuentes</h2><ul>\n<li>Responder a una emoción con información: \"No se preocupe, la insulina es muy segura\" (puede sentirse como minimizar).</li>\n<li>Ignorar la emoción y seguir con la explicación.</li>\n<li>Usar las frases de forma mecánica, sin pausa ni tono adecuado.</li>\n<li>Hacer promesas que no puedes cumplir: \"Le aseguro que todo va a salir bien.\"</li>\n</ul><h2>La pausa después de la respuesta empática</h2><p>Después de una respuesta NURSE, <strong>haz silencio</strong>. Deja que la persona responda. Muchas veces el paciente compartirá información clave (miedos, creencias, barreras económicas) que te permitirá ayudarle mejor.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb07j${"tone":"consejo","title":"Ejemplo aplicado: inicio de insulina","html":"<p>Paciente (con los ojos llorosos): \"Yo sabía que iba a terminar así, con chuzones.\"\nQF: \"Parece que esto le genera mucho miedo (N). Es comprensible: para mucha gente empezar insulina se siente como un fracaso (U). Usted ha hecho un gran esfuerzo con la dieta y las pastillas durante años (R). Vamos a aprender juntos a aplicarla, paso a paso (S). ¿Qué es lo que más le preocupa? (E)\"\nPaciente: \"Que me duela… y que eso quiera decir que me voy a quedar ciego como mi papá.\"\nAhora la QF puede abordar dos temas concretos: la técnica (agujas finas, poco dolor) y la creencia (la insulina ayuda a prevenir complicaciones, no las causa).</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb07j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>NURSE: nombrar, entender, respetar, apoyar y explorar.</li>\n<li>Responde a la emoción antes de dar información técnica.</li>\n<li>Haz silencio después de la respuesta empática y escucha.</li>\n</ol>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb07j${"tone":"info","title":"Siguiente paso","html":"<p>Escribe una frase de cada tipo NURSE para las tres situaciones emocionales más frecuentes en tu trabajo.</p>"}$hb07j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 4. Habilidades sociales y resiliencia', 3)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Habilidades sociales en el trabajo: influir, colaborar y construir confianza', 'Unidad 4 · Clase 4.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb07j${"tone":"info","title":"En esta clase","html":"<p>Habilidades sociales en el trabajo desde la inteligencia emocional: construir confianza, colaborar, influir positivamente y reparar relaciones después de un conflicto.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb07j${"html":"<p>Las habilidades sociales son el componente de la inteligencia emocional que se ve desde afuera: cómo te relacionas, cómo colaboras, cómo influyes y cómo reparas una relación cuando algo sale mal. Se apoyan en todo lo anterior: no puedes relacionarte bien si no reconoces tus emociones, no las regulas o no comprendes las de los demás. En esta clase aprenderás a construir confianza, a influir de forma positiva y a reparar relaciones laborales.</p><h2>La confianza: el cimiento de todo</h2><p>David Maister, Charles Green y Robert Galford propusieron en <em>The Trusted Advisor</em> una \"ecuación de la confianza\" que ayuda a pensar en sus componentes:</p>\n<p><strong>Confianza = (Credibilidad + Confiabilidad + Intimidad) / Autoorientación</strong></p>\n<ul>\n<li><strong>Credibilidad:</strong> lo que dices es correcto y sabes de lo que hablas.</li>\n<li><strong>Confiabilidad:</strong> haces lo que dices que vas a hacer, de forma consistente.</li>\n<li><strong>Intimidad (cercanía):</strong> la otra persona se siente segura compartiendo contigo.</li>\n<li><strong>Autoorientación:</strong> cuánto parece que te importas más tú que el otro. Cuanto mayor, menos confianza.</li>\n</ul>\n<p>No es una fórmula matemática exacta, pero muestra algo útil: puedes ser muy competente y aun así generar poca confianza si los demás perciben que solo buscas tu beneficio.</p><h2>Acciones concretas para construir confianza</h2><ul>\n<li><strong>Cumple los pequeños compromisos:</strong> \"Te lo envío a las 3\" y lo envías a las 3.</li>\n<li><strong>Reconoce lo que no sabes.</strong></li>\n<li><strong>Guarda la confidencialidad.</strong></li>\n<li><strong>Da crédito a los demás.</strong></li>\n<li><strong>Sé coherente:</strong> trata igual a las personas cuando están presentes y cuando no.</li>\n</ul><h2>Colaborar en equipos interdisciplinarios</h2><p>En salud trabajan juntos médicos, enfermeras, químicos farmacéuticos, regentes, auxiliares y administrativos, cada uno con su lenguaje y prioridades. Para colaborar mejor:</p>\n<ul>\n<li><strong>Entiende la presión del otro:</strong> el médico tiene 20 minutos por paciente; la enfermera, 15 pacientes por turno.</li>\n<li><strong>Comunica en su lenguaje:</strong> al médico, la recomendación concreta y su sustento; al administrativo, el impacto en costos o procesos.</li>\n<li><strong>Usa canales y momentos adecuados:</strong> no interrumpas una urgencia por un tema administrativo.</li>\n<li><strong>Reconoce el aporte de cada disciplina.</strong></li>\n</ul><h2>Influir sin autoridad</h2><p>Muchas veces necesitas que otros hagan algo sin ser su jefe. La influencia positiva se basa en:</p>\n<ol>\n<li><strong>Relación previa:</strong> es más fácil influir en quien ya confía en ti.</li>\n<li><strong>Entender sus intereses:</strong> ¿qué gana el otro?</li>\n<li><strong>Argumentos adaptados:</strong> evidencia, impacto, beneficios para el paciente.</li>\n<li><strong>Reciprocidad:</strong> ayuda primero.</li>\n<li><strong>Paciencia:</strong> el cambio de hábitos lleva tiempo.</li>\n</ol><h2>Reparar una relación</h2><p>Los conflictos dejan heridas. Para reparar una relación laboral:</p>\n<ol>\n<li><strong>Toma la iniciativa:</strong> no esperes a que el otro dé el primer paso.</li>\n<li><strong>Reconoce tu parte:</strong> \"Creo que fui muy brusco en la reunión del lunes.\"</li>\n<li><strong>Pide disculpas sin \"pero\":</strong> \"Lo siento\" y no \"Lo siento, pero tú…\".</li>\n<li><strong>Escucha su perspectiva.</strong></li>\n<li><strong>Acuerda cómo seguir:</strong> \"¿Qué podemos hacer para que no vuelva a pasar?\"</li>\n<li><strong>Demuestra el cambio con acciones.</strong></li>\n</ol>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb07j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una QF nueva en un hospital quiere que los médicos acepten sus recomendaciones de ajuste de dosis. En lugar de enviar notas frías, se presenta en las rondas, aprende cómo trabaja cada servicio, empieza por recomendaciones de alto impacto y bien sustentadas, cumple siempre lo que promete y reconoce públicamente cuando un médico acoge una recomendación. En tres meses, los médicos empiezan a llamarla para consultarle.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb07j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La confianza se construye con credibilidad, confiabilidad y cercanía, y baja cuando el otro percibe que solo buscas tu beneficio.</li>\n<li>Colaborar exige entender la presión y el lenguaje de cada disciplina.</li>\n<li>Para reparar una relación: iniciativa, reconocer tu parte, disculpa sin \"pero\" y acciones.</li>\n</ol>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb07j${"tone":"info","title":"Siguiente paso","html":"<p>Identifica una relación laboral que quieras fortalecer y define una acción concreta para esta semana.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Resiliencia: cómo recuperarte de los golpes y diseñar tu plan de desarrollo emocional', 'Unidad 4 · Clase 4.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb07j${"tone":"info","title":"En esta clase","html":"<p>Qué es la resiliencia, los factores que la fortalecen y cómo diseñar un plan personal de desarrollo de la inteligencia emocional con metas y hábitos.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb07j${"html":"<p>Un error de dispensación que tuvo consecuencias. Un despido. Una evaluación injusta. La muerte de un paciente con el que trabajaste meses. En el trabajo, como en la vida, hay golpes. La resiliencia no consiste en no sentirlos, sino en la capacidad de recuperarte, aprender y seguir adelante. En esta clase final aprenderás qué es la resiliencia, qué la fortalece y diseñarás tu plan de desarrollo emocional.</p><h2>¿Qué es la resiliencia?</h2><p>La Asociación Americana de Psicología (APA) define la resiliencia como el proceso y el resultado de <strong>adaptarse con éxito a experiencias de vida difíciles o desafiantes</strong>, a través de la flexibilidad mental, emocional y conductual. Tres ideas clave:</p>\n<ul>\n<li>Es un <strong>proceso</strong>, no un rasgo fijo: se puede desarrollar.</li>\n<li><strong>No implica no sufrir:</strong> las personas resilientes también sienten dolor, tristeza y miedo.</li>\n<li><strong>Depende de factores personales y del entorno:</strong> relaciones, recursos, organización.</li>\n</ul><h2>Factores que fortalecen la resiliencia</h2><h3>1. Conexiones</h3>\n<p>Las relaciones de apoyo son uno de los factores protectores más consistentes. Cultiva una red: colegas, familia, amigos, grupos profesionales.</p>\n<h3>2. Bienestar físico</h3>\n<p>Sueño, actividad física, alimentación y pausas. El cuerpo agotado tiene menos recursos para afrontar.</p>\n<h3>3. Pensamiento flexible y realista</h3>\n<ul>\n<li>Ver las crisis como problemas que se pueden enfrentar, no como catástrofes insuperables.</li>\n<li>Aceptar lo que no se puede cambiar y enfocarse en lo que sí.</li>\n<li>Mantener una perspectiva de largo plazo.</li>\n</ul>\n<h3>4. Sentido y propósito</h3>\n<p>Conectar con el porqué de tu trabajo: el paciente que mejoró, el error que evitaste, el equipo que formaste.</p>\n<h3>5. Aprendizaje de la experiencia</h3>\n<p>Después de una dificultad, pregúntate: ¿qué aprendí?, ¿qué recursos usé?, ¿qué haría distinto?</p><h2>Resiliencia ante el error</h2><p>En salud, los errores tienen un peso emocional enorme. Albert Wu acuñó el término <strong>\"segunda víctima\"</strong> para describir al profesional que sufre después de estar involucrado en un evento adverso. Para afrontarlo:</p>\n<ul>\n<li>Reporta el evento por los canales institucionales; la cultura de seguridad busca aprender, no castigar.</li>\n<li>Habla con alguien de confianza o con el programa de apoyo de tu institución.</li>\n<li>Separa tu valor como persona del error cometido.</li>\n<li>Enfócate en lo que se puede mejorar en el sistema.</li>\n</ul><h2>Tu plan de desarrollo emocional (90 días)</h2><p>Reúne lo aprendido en el curso en un plan concreto:</p>\n<ol>\n<li><strong>Diagnóstico:</strong> ¿qué componente de la inteligencia emocional quieres fortalecer más? (usa el autodiagnóstico inicial y tu diario).</li>\n<li><strong>Meta:</strong> formúlala de forma concreta. \"Responder sin elevar la voz a pacientes molestos, usando STOP y NURSE, en el 80 % de los casos.\"</li>\n<li><strong>Hábitos diarios:</strong> pequeños y sostenibles (diario emocional de 3 minutos, escaneo corporal, una respuesta NURSE al día).</li>\n<li><strong>Prácticas semanales:</strong> una conversación difícil preparada, una retroalimentación pedida, una actividad de recuperación.</li>\n<li><strong>Apoyos:</strong> ¿quién te va a ayudar? ¿A quién le vas a rendir cuentas?</li>\n<li><strong>Medición:</strong> ¿cómo sabrás que avanzas? (diario, autoevaluación mensual, retroalimentación de otros).</li>\n<li><strong>Revisión:</strong> fechas a los 30, 60 y 90 días.</li>\n</ol>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb07j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un regente que vivió un error de dispensación con un paciente pediátrico (sin daño grave) pasó semanas sin dormir bien y pensando en renunciar. Habló con su directora técnica, que lo acompañó en el análisis del evento. Descubrieron que dos presentaciones similares estaban juntas en el estante. Propusieron separarlas y señalizarlas. Él incluyó en su plan de desarrollo la meta de hablar de sus emociones con un colega cada semana y de retomar el ejercicio. A los tres meses se sentía más tranquilo y lideraba la revisión de medicamentos de aspecto o nombre parecido.</p>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb07j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>La resiliencia es un proceso de adaptación que se puede desarrollar.</li>\n<li>Conexiones, bienestar, pensamiento flexible, propósito y aprendizaje la fortalecen.</li>\n<li>Un plan de 90 días con metas, hábitos, apoyos y medición convierte lo aprendido en cambio real.</li>\n</ol>"}$hb07j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb07j${"tone":"info","title":"Siguiente paso","html":"<p>Completa tu plan de 90 días y compártelo con una persona de confianza que te ayude a cumplirlo.</p>"}$hb07j$::jsonb);
END
$hb07$;

-- ─── Curso de Liderazgo y Trabajo en Equipo (8 clases) ───
DO $hb08$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Liderazgo y Trabajo en Equipo' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, area, level, tags,
     objective, learning_outcomes, audience, duration_minutes, author_name, status, modality, cover_url, publico)
  VALUES ('edvanta', 'Curso de Liderazgo y Trabajo en Equipo', $hb08t$Curso para quienes asumen o ya tienen personas a cargo: estilos de liderazgo, transición de técnico a líder, seguridad psicológica, disfunciones de equipo, delegación, reuniones efectivas, conversaciones 1:1, motivación y gestión del cambio.$hb08t$,
          $hb08t$<p>Curso para quienes asumen o ya tienen personas a cargo: estilos de liderazgo, transición de técnico a líder, seguridad psicológica, disfunciones de equipo, delegación, reuniones efectivas, conversaciones 1:1, motivación y gestión del cambio.</p><h2>Objetivo</h2><p>Que el participante adapte su estilo de liderazgo a la madurez de cada colaborador, fomente la seguridad psicológica, delegue con claridad, conduzca reuniones y 1:1 efectivos, y lidere un cambio en su equipo con un plan estructurado.</p><h2>Para quién es</h2><p>Directores técnicos, químicos farmacéuticos y regentes coordinadores, administradores de droguería, supervisores de ventas y gerentes de distrito del sector farmacéutico.</p><h2>Cómo está organizado</h2><p>Cuatro unidades con dos clases en texto cada una. Cada clase trae un ejemplo aplicado al sector farmacéutico y de la salud, puntos clave y el siguiente paso.</p><h2>Referentes</h2><p>Paul Hersey y Ken Blanchard (liderazgo situacional); James MacGregor Burns y Bernard Bass (liderazgo transformacional); Robert K. Greenleaf (liderazgo de servicio); Amy C. Edmondson (seguridad psicológica) y el Proyecto Aristóteles de Google; Patrick Lencioni (Las cinco disfunciones de un equipo); John P. Kotter (8 pasos del cambio); Edward Deci y Richard Ryan (teoría de la autodeterminación).</p>$hb08t$,
          'Liderazgo y relaciones laborales', 'Habilidades Blandas', 'intermedio', ARRAY['Liderazgo', 'Trabajo en equipo', 'Delegación', 'Gestión del cambio', 'Habilidades blandas']::text[],
          $hb08t$Que el participante adapte su estilo de liderazgo a la madurez de cada colaborador, fomente la seguridad psicológica, delegue con claridad, conduzca reuniones y 1:1 efectivos, y lidere un cambio en su equipo con un plan estructurado.$hb08t$,
          ARRAY['Elegir el estilo de liderazgo adecuado y asumir tu primer cargo de coordinación.', 'Construir seguridad psicológica y superar las disfunciones de un equipo.', 'Delegar con claridad y hacer reuniones y conversaciones 1:1 que valgan la pena.', 'Motivar a tu equipo y liderar un cambio con los 8 pasos de Kotter.']::text[],
          $hb08t$Directores técnicos, químicos farmacéuticos y regentes coordinadores, administradores de droguería, supervisores de ventas y gerentes de distrito del sector farmacéutico.$hb08t$,
          152, 'Edvanta', 'borrador', 'asincronica', '/img/cursos/liderazgo-trabajo-en-equipo.webp', 'profesionales')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Fundamentos del liderazgo', 0)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Tipos de liderazgo: situacional, transformacional y de servicio, y cuándo usar cada uno', 'Unidad 1 · Clase 1.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb08j${"tone":"info","title":"En esta clase","html":"<p>Tipos de liderazgo explicados: situacional, transformacional y de servicio, con sus características, ventajas, riesgos y ejemplos de cuándo usar cada uno.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb08j${"html":"<p>¿Hay un estilo de liderazgo correcto? La investigación sugiere que no: los líderes efectivos adaptan su forma de liderar a las personas y a la situación. Un auxiliar recién llegado necesita instrucciones claras; un regente con diez años de experiencia necesita autonomía. En esta clase conocerás tres modelos de liderazgo muy usados y aprenderás cuándo aplicar cada uno.</p><h2>¿Qué es liderazgo?</h2><p>Liderazgo es la capacidad de <strong>influir en un grupo para lograr objetivos compartidos</strong>. No depende solo del cargo: puedes liderar sin ser jefe, y puedes ser jefe sin liderar. La diferencia entre <strong>gestionar</strong> (planear, organizar, controlar) y <strong>liderar</strong> (dar dirección, inspirar, desarrollar personas) es útil, aunque en la práctica un buen coordinador necesita ambas.</p><h2>Modelo 1: liderazgo situacional (Hersey y Blanchard)</h2><p>Propone que el estilo debe ajustarse al <strong>nivel de desarrollo</strong> del colaborador en una tarea específica, combinando dos tipos de conducta: <strong>dirección</strong> (decir qué, cómo y cuándo) y <strong>apoyo</strong> (escuchar, animar, involucrar).</p>\n<table><thead><tr><th>Nivel del colaborador</th><th>Estilo recomendado</th></tr></thead><tbody><tr><td>Baja competencia, alto entusiasmo (nuevo)</td><td><strong>Dirigir:</strong> instrucciones claras, supervisión cercana.</td></tr><tr><td>Algo de competencia, entusiasmo bajo (se frustra)</td><td><strong>Entrenar:</strong> dirección + apoyo, explicar el porqué.</td></tr><tr><td>Competencia alta, confianza variable</td><td><strong>Apoyar:</strong> menos dirección, más escucha y ánimo.</td></tr><tr><td>Alta competencia y compromiso</td><td><strong>Delegar:</strong> autonomía, seguimiento por resultados.</td></tr></tbody></table>\n<p><strong>Clave:</strong> el nivel es <strong>por tarea</strong>, no por persona. Una regente experta en dispensación puede ser principiante en manejo del software de inventario.</p><h2>Modelo 2: liderazgo transformacional</h2><p>Descrito por James MacGregor Burns y desarrollado por Bernard Bass. El líder transformacional inspira a las personas a ir más allá de sus intereses inmediatos por un propósito común. Tiene cuatro componentes (\"las 4 I\"):</p>\n<ol>\n<li><strong>Influencia idealizada:</strong> es un modelo de conducta coherente.</li>\n<li><strong>Motivación inspiradora:</strong> comunica una visión atractiva.</li>\n<li><strong>Estimulación intelectual:</strong> invita a cuestionar y proponer.</li>\n<li><strong>Consideración individualizada:</strong> atiende las necesidades de cada persona.</li>\n</ol>\n<p>Contrasta con el <strong>liderazgo transaccional</strong>, basado en intercambios (cumplimiento a cambio de recompensa). Ambos son necesarios: lo transaccional da orden; lo transformacional, sentido.</p><h2>Modelo 3: liderazgo de servicio</h2><p>Propuesto por Robert K. Greenleaf en 1970. El líder se ve a sí mismo <strong>al servicio de su equipo</strong>: su pregunta principal es \"¿qué necesitan para hacer bien su trabajo?\". Se enfoca en escuchar, quitar obstáculos, desarrollar a las personas y cuidar el bienestar. Es especialmente coherente con el sector salud, donde el equipo a su vez está al servicio del paciente.</p>\n<p><strong>Riesgo:</strong> confundir servir con hacer el trabajo de los demás o evitar exigir.</p><h2>Cuándo usar cada enfoque</h2><ul>\n<li><strong>Situacional:</strong> en el día a día, para decidir cuánta dirección y apoyo dar a cada persona.</li>\n<li><strong>Transformacional:</strong> al comunicar el propósito, liderar cambios o motivar en tiempos difíciles.</li>\n<li><strong>De servicio:</strong> como actitud de base, para construir confianza y compromiso.</li>\n<li><strong>Directivo:</strong> en emergencias o cuando hay riesgo para la seguridad del paciente.</li>\n</ul>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb08j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una directora técnica de una droguería tiene tres colaboradores: un auxiliar nuevo (dirige con un paso a paso de dispensación), una auxiliar con dos años que se desmotivó tras un cambio de software (entrena: explica el porqué y acompaña) y un regente experto (delega la gestión de pedidos con revisión mensual). Al comunicar la meta del trimestre usa un enfoque transformacional: \"Queremos ser la droguería donde los pacientes crónicos nunca se queden sin su medicamento.\"</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb08j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>No hay un estilo único: los mejores líderes se adaptan.</li>\n<li>Situacional: dirige, entrena, apoya o delega según el nivel en cada tarea.</li>\n<li>Transformacional da sentido; de servicio construye confianza.</li>\n</ol>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb08j${"tone":"info","title":"Siguiente paso","html":"<p>Haz el diagnóstico de nivel de cada persona de tu equipo en sus dos tareas principales.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'De técnico a líder: cómo asumir tu primer cargo de coordinación', 'Unidad 1 · Clase 1.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb08j${"tone":"info","title":"En esta clase","html":"<p>Cómo ser un buen líder en tu primer cargo: los cambios de mentalidad del paso de técnico a coordinador, errores comunes y un plan para los primeros 90 días.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb08j${"html":"<p>En el sector farmacéutico es común que el mejor técnico sea ascendido a coordinador: la regente más organizada pasa a administrar la droguería, el QF más sólido se convierte en jefe de servicio, el visitador con mejores resultados pasa a supervisor. Pero las habilidades que te hicieron un gran técnico no son las mismas que te harán un buen líder. En esta clase aprenderás los cambios de mentalidad que exige esta transición y un plan para tus primeros 90 días.</p><h2>Los tres cambios de mentalidad</h2><p>Ram Charan, Stephen Drotter y James Noel describen en <em>The Leadership Pipeline</em> que cada salto de nivel exige cambiar tres cosas: <strong>habilidades, uso del tiempo y valores de trabajo</strong>. Para el primer cargo de liderazgo:</p>\n<h3>1. De hacer a lograr que otros hagan</h3>\n<p>Tu valor ya no está en cuántas fórmulas dispensas o cuántas visitas haces, sino en cuánto logra tu equipo. Si sigues haciendo todo tú, te conviertes en un cuello de botella.</p>\n<h3>2. De tu tiempo a tiempo para otros</h3>\n<p>Una parte importante de tu agenda debe ir a planear, enseñar, dar retroalimentación, resolver problemas del equipo y comunicarte con otras áreas.</p>\n<h3>3. De valorar tu trabajo técnico a valorar el éxito de otros</h3>\n<p>La satisfacción ya no viene solo de resolver tú el problema difícil, sino de ver que alguien de tu equipo aprendió a resolverlo.</p><h2>Errores frecuentes del nuevo líder</h2><ul>\n<li><strong>Seguir siendo el técnico estrella</strong> y no delegar.</li>\n<li><strong>Querer ser amigo de todos</strong> y evitar las conversaciones difíciles.</li>\n<li><strong>Cambiar todo de inmediato</strong> sin entender por qué las cosas funcionan como funcionan.</li>\n<li><strong>Micromanejar:</strong> revisar cada detalle por inseguridad.</li>\n<li><strong>No pedir ayuda</strong> a su propio jefe.</li>\n<li><strong>Liderar a excompañeros</strong> sin hablar abiertamente del cambio de rol.</li>\n</ul><h2>Liderar a quienes antes eran tus compañeros</h2><p>Es una de las situaciones más delicadas. Recomendaciones:</p>\n<ul>\n<li><strong>Habla del cambio de forma individual:</strong> \"Ahora tengo un rol distinto. Valoro nuestra relación y también necesito que cumplamos ciertas metas. ¿Cómo lo ves?\"</li>\n<li><strong>Sé justo y consistente:</strong> las mismas reglas para todos.</li>\n<li><strong>No uses tu nuevo poder para demostrar autoridad.</strong></li>\n<li><strong>Pide su opinión:</strong> conocen el trabajo.</li>\n</ul><h2>Plan para los primeros 90 días</h2><h3>Días 1–30: escuchar y entender</h3>\n<ul>\n<li>Reuniones 1:1 con cada persona: ¿qué funciona?, ¿qué no?, ¿qué necesitas de mí?</li>\n<li>Entender indicadores, procesos y normativa (por ejemplo, condiciones del establecimiento, inventarios, medicamentos de control).</li>\n<li>Aclarar con tu jefe qué espera de ti.</li>\n</ul>\n<h3>Días 31–60: priorizar y lograr victorias tempranas</h3>\n<ul>\n<li>Elegir dos o tres problemas visibles y resolubles.</li>\n<li>Empezar a delegar tareas con acompañamiento.</li>\n<li>Establecer rutinas: reunión semanal, 1:1 quincenales.</li>\n</ul>\n<h3>Días 61–90: construir el equipo y el plan</h3>\n<ul>\n<li>Definir metas del equipo con su participación.</li>\n<li>Identificar necesidades de formación.</li>\n<li>Revisar con tu jefe los avances y ajustar.</li>\n</ul>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb08j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un QF asciende a jefe de farmacia en una clínica. En sus primeras semanas sigue validando él mismo todas las prescripciones de antibióticos y se queda hasta las 9 p. m. Al aplicar el plan, habla 1:1 con su equipo, descubre que dos QF tienen experiencia en antibióticos y les delega la validación con criterios claros. Él se enfoca en el comité de infecciones y en reducir los tiempos de entrega a los pisos. A los 90 días, el equipo está más motivado y él recuperó su tiempo.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb08j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Pasar de técnico a líder exige cambiar habilidades, uso del tiempo y valores.</li>\n<li>Evita seguir siendo el técnico estrella, micromanejar o cambiar todo de inmediato.</li>\n<li>Plan de 90 días: escuchar, lograr victorias tempranas y construir el equipo.</li>\n</ol>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb08j${"tone":"info","title":"Siguiente paso","html":"<p>Descarga la guía de 90 días y programa las reuniones 1:1 con tu equipo.</p>"}$hb08j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 2. Construir equipos de alto desempeño', 1)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Seguridad psicológica: la base de los equipos que aprenden y no esconden errores', 'Unidad 2 · Clase 2.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb08j${"tone":"info","title":"En esta clase","html":"<p>Qué es la seguridad psicológica según Amy Edmondson, qué encontró el Proyecto Aristóteles de Google y cómo construirla en equipos de salud.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb08j${"html":"<p>¿En tu equipo las personas se atreven a decir \"me equivoqué\", \"no entiendo\" o \"creo que esto está mal\"? Si la respuesta es no, los errores se esconden, las ideas no aparecen y los problemas crecen en silencio. En salud, eso puede afectar directamente a los pacientes. En esta clase aprenderás qué es la seguridad psicológica, por qué es un factor clave del desempeño de los equipos y cómo construirla como líder.</p><h2>¿Qué es la seguridad psicológica?</h2><p>Amy C. Edmondson, profesora de Harvard Business School, la define como <strong>la creencia compartida de que el equipo es un lugar seguro para asumir riesgos interpersonales</strong>: hacer preguntas, admitir errores, proponer ideas o expresar desacuerdo sin temor a ser humillado, castigado o excluido.</p>\n<p>Seguridad psicológica <strong>no</strong> es:</p>\n<ul>\n<li>Ser siempre amable o evitar los conflictos.</li>\n<li>Bajar los estándares.</li>\n<li>Que todos estén de acuerdo.</li>\n</ul>\n<p>De hecho, Edmondson sostiene que los equipos de alto desempeño combinan <strong>alta seguridad psicológica y altos estándares</strong>.</p><h2>La investigación</h2><h3>El estudio de los errores en hospitales</h3>\n<p>En su investigación en hospitales en los años noventa, Edmondson encontró algo inesperado: los equipos de enfermería mejor liderados <strong>reportaban más errores</strong>. ¿Cometían más? No: se atrevían a reportarlos, y por eso podían aprender. En los equipos con miedo, los errores se ocultaban.</p>\n<h3>El Proyecto Aristóteles de Google</h3>\n<p>Google estudió durante varios años más de un centenar de sus equipos para entender qué los hacía efectivos. Encontró que <strong>la seguridad psicológica era el factor más importante</strong>, por encima de quiénes conformaban el equipo. Los otros factores fueron confiabilidad, estructura y claridad, significado e impacto del trabajo.</p><h2>Por qué importa en salud</h2><p>La seguridad del paciente depende de que las personas hablen: el auxiliar que nota que la presentación no coincide con la fórmula, la QF que duda de una dosis, el regente que vio una nevera fuera de rango. Si temen ser regañadas o ridiculizadas, callan. La cultura de seguridad del paciente promueve el reporte de eventos adversos con un enfoque de aprendizaje y no punitivo.</p><h2>Diez conductas del líder que construyen seguridad psicológica</h2><ol>\n<li><strong>Enmarca el trabajo como aprendizaje:</strong> \"Esto es nuevo para todos; vamos a equivocarnos y a aprender.\"</li>\n<li><strong>Reconoce tu propia falibilidad:</strong> \"Puede que se me esté escapando algo.\"</li>\n<li><strong>Haz preguntas genuinas:</strong> \"¿Qué estamos pasando por alto?\"</li>\n<li><strong>Agradece a quien trae malas noticias o reporta errores.</strong></li>\n<li><strong>Responde con curiosidad, no con castigo:</strong> \"¿Qué pasó? ¿Qué podemos cambiar en el proceso?\"</li>\n<li><strong>Invita a los callados:</strong> \"Carlos, no te hemos escuchado; ¿cómo lo ves?\"</li>\n<li><strong>No interrumpas ni ridiculices ideas.</strong></li>\n<li><strong>Separa el error honesto de la negligencia o la violación deliberada de normas</strong> (estos últimos sí requieren otras medidas).</li>\n<li><strong>Cierra el círculo:</strong> cuenta qué se hizo con lo que reportaron.</li>\n<li><strong>Sé consistente:</strong> una sola reacción de enojo puede destruir meses de construcción.</li>\n</ol><h2>Cómo medirla</h2><p>Edmondson propuso una escala con afirmaciones como \"Si cometes un error en este equipo, a menudo se usa en tu contra\" o \"Es seguro asumir riesgos en este equipo\". Una encuesta anónima corta, aplicada cada trimestre, te da una línea base.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb08j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>En un servicio farmacéutico hospitalario, el jefe reaccionaba con enojo ante cada error, y los reportes de eventos eran casi nulos. Al cambiar su forma de responder (\"Gracias por reportarlo; veamos qué falló en el proceso\") y compartir en la reunión semanal lo aprendido de cada evento, los reportes aumentaron en los meses siguientes y se identificaron dos problemas del sistema de almacenamiento que causaban confusiones.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb08j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Seguridad psicológica es poder asumir riesgos interpersonales sin temor.</li>\n<li>Se combina con altos estándares; no es complacencia.</li>\n<li>El líder la construye con su forma de responder a errores, preguntas y desacuerdos.</li>\n</ol>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb08j${"tone":"info","title":"Siguiente paso","html":"<p>Aplica la encuesta de seguridad psicológica a tu equipo (anónima) y elige dos conductas para practicar.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Las 5 disfunciones de un equipo según Lencioni y cómo superarlas', 'Unidad 2 · Clase 2.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb08j${"tone":"info","title":"En esta clase","html":"<p>Trabajo en equipo según Patrick Lencioni: las 5 disfunciones de un equipo (confianza, conflicto, compromiso, responsabilidad y resultados) y cómo superarlas.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb08j${"html":"<p>Un grupo de personas que trabajan en el mismo lugar no es necesariamente un equipo. Un equipo comparte metas, se apoya, discute ideas y se hace responsable de los resultados en conjunto. En su libro <em>Las cinco disfunciones de un equipo</em> (2002), Patrick Lencioni propuso un modelo sencillo y muy usado para diagnosticar por qué los equipos no funcionan. En esta clase lo aplicarás a tu equipo.</p><h2>La pirámide de las disfunciones</h2><p>Lencioni organiza las disfunciones como una pirámide: cada una se apoya en la anterior.</p>\n<h3>1. Ausencia de confianza (base)</h3>\n<p>Los miembros no se muestran vulnerables: no admiten errores, debilidades ni piden ayuda. Lencioni se refiere a la <strong>confianza basada en la vulnerabilidad</strong>, no solo a la confianza en que el otro hará su trabajo.</p>\n<ul>\n<li><strong>Señales:</strong> se ocultan errores, no se pide ayuda, se guardan las opiniones.</li>\n<li><strong>Cómo superarla:</strong> el líder muestra vulnerabilidad primero; ejercicios de historias personales; conocer estilos de trabajo de cada uno.</li>\n</ul>\n<h3>2. Temor al conflicto</h3>\n<p>Sin confianza, el equipo evita el debate de ideas. Prefiere una \"armonía artificial\".</p>\n<ul>\n<li><strong>Señales:</strong> reuniones aburridas, decisiones que no se discuten, quejas en los pasillos.</li>\n<li><strong>Cómo superarla:</strong> normalizar el conflicto productivo (sobre ideas, no sobre personas); pedir explícitamente desacuerdos: \"¿Quién ve un riesgo en esta propuesta?\".</li>\n</ul>\n<h3>3. Falta de compromiso</h3>\n<p>Si las personas no expresaron su opinión, no se comprometen con la decisión.</p>\n<ul>\n<li><strong>Señales:</strong> ambigüedad sobre lo decidido, decisiones que se reabren una y otra vez.</li>\n<li><strong>Cómo superarla:</strong> al final de cada reunión, resumir decisiones, responsables y fechas. Principio de \"estar en desacuerdo y comprometerse\": no todos tienen que estar de acuerdo, pero sí ser escuchados.</li>\n</ul>\n<h3>4. Evitar la rendición de cuentas</h3>\n<p>Sin compromiso claro, nadie se siente con derecho a pedir cuentas a los demás.</p>\n<ul>\n<li><strong>Señales:</strong> se toleran incumplimientos, el líder es el único que exige, resentimiento entre compañeros.</li>\n<li><strong>Cómo superarla:</strong> metas y estándares visibles; revisiones periódicas de avance; promover que los compañeros se pidan cuentas entre sí con respeto.</li>\n</ul>\n<h3>5. Falta de atención a los resultados (cima)</h3>\n<p>Cuando no hay rendición de cuentas, cada uno se enfoca en sus intereses (estatus, ego, su área) por encima de los resultados del equipo.</p>\n<ul>\n<li><strong>Señales:</strong> \"mi parte la hice\", competencia interna, metas individuales por encima de las colectivas.</li>\n<li><strong>Cómo superarla:</strong> un tablero de resultados del equipo; reconocimiento colectivo; metas compartidas.</li>\n</ul><h2>Cómo usar el modelo</h2><ol>\n<li><strong>Aplica el cuestionario</strong> de diagnóstico al equipo (o respóndelo tú con honestidad).</li>\n<li><strong>Identifica la disfunción más baja</strong> de la pirámide que esté presente: trabaja primero esa.</li>\n<li><strong>Elige dos o tres acciones concretas</strong> y revisa en un mes.</li>\n</ol><h2>Una nota sobre el modelo</h2><p>El modelo de Lencioni proviene de la experiencia de consultoría y se presenta en forma de fábula; no es una teoría probada experimentalmente como la seguridad psicológica, pero coincide con hallazgos de investigación y es una herramienta práctica de diagnóstico.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb08j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una red de cuatro droguerías tiene metas de ventas que no se cumplen. Los regentes se culpan entre sí por los traslados de inventario. Al aplicar el modelo, la gerente descubre que la base es la falta de confianza: nadie admite errores en los inventarios por miedo. Empieza por una reunión en la que ella reconoce un error suyo de planeación, luego establece una reunión semanal donde se debaten problemas abiertamente, se dejan acuerdos por escrito y se muestra un tablero de resultados de toda la red. En tres meses, los traslados funcionan mejor y las metas se acercan.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb08j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Las cinco disfunciones: confianza, conflicto, compromiso, rendición de cuentas y resultados.</li>\n<li>Cada una se apoya en la anterior: empieza por la base.</li>\n<li>Usa el modelo como diagnóstico práctico y define acciones concretas.</li>\n</ol>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb08j${"tone":"info","title":"Siguiente paso","html":"<p>Aplica el cuestionario de disfunciones y elige la disfunción prioritaria de tu equipo.</p>"}$hb08j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 3. Delegar, reuniones y 1:1', 2)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo delegar tareas de forma efectiva: qué, a quién y cómo', 'Unidad 3 · Clase 3.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb08j${"tone":"info","title":"En esta clase","html":"<p>Cómo delegar tareas de forma efectiva: qué delegar, a quién, los niveles de delegación y una conversación de delegación paso a paso para evitar errores.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb08j${"html":"<p>\"Si quieres que algo salga bien, hazlo tú mismo.\" Esta frase ha llevado a muchos líderes a jornadas interminables y a equipos que no crecen. Delegar no es descargar trabajo: es desarrollar personas y multiplicar la capacidad del equipo. Pero delegar mal (sin claridad, sin recursos o sin seguimiento) genera errores y frustración. En esta clase aprenderás qué delegar, a quién y cómo hacerlo bien.</p><h2>Por qué no delegamos</h2><ul>\n<li>\"Me demoro más explicándolo que haciéndolo.\"</li>\n<li>\"Nadie lo hace tan bien como yo.\"</li>\n<li>\"Me da miedo que se equivoquen.\"</li>\n<li>\"Me gusta hacerlo.\"</li>\n<li>\"No quiero recargar al equipo.\"</li>\n</ul>\n<p>Todas tienen algo de verdad a corto plazo, pero a largo plazo te convierten en cuello de botella e impiden que el equipo aprenda.</p><h2>Qué delegar (y qué no)</h2><p><strong>Sí delegar:</strong></p>\n<ul>\n<li>Tareas recurrentes que otros pueden aprender (pedidos, inventarios periódicos, informes).</li>\n<li>Tareas que desarrollan a alguien.</li>\n<li>Tareas en las que otra persona es más experta que tú.</li>\n</ul>\n<p><strong>No delegar (o con cuidado):</strong></p>\n<ul>\n<li>Decisiones que por normativa requieren tu firma o tu cargo (por ejemplo, responsabilidades legales del director técnico).</li>\n<li>Conversaciones de desempeño, retroalimentación sensible o temas confidenciales del equipo.</li>\n<li>Crisis que requieren tu presencia.</li>\n</ul><h2>A quién delegar</h2><p>Usa el liderazgo situacional: considera la <strong>competencia y el compromiso</strong> de la persona en esa tarea. A quien está empezando, delega con más dirección; a quien domina, con más autonomía. Distribuye las oportunidades de forma justa, no siempre a la misma persona.</p><h2>Niveles de delegación</h2><p>Aclara cuánta autonomía tiene la persona:</p>\n<ol>\n<li><strong>Investiga y repórtame;</strong> yo decido.</li>\n<li><strong>Propón opciones</strong> con tu recomendación; yo decido.</li>\n<li><strong>Decide y avísame</strong> antes de actuar.</li>\n<li><strong>Decide, actúa y cuéntame</strong> después.</li>\n<li><strong>Decide y actúa;</strong> no necesitas informarme.</li>\n</ol>\n<p>Muchos problemas de delegación se deben a que el líder pensaba en el nivel 2 y el colaborador entendió el nivel 4.</p><h2>La conversación de delegación: 7 elementos</h2><ol>\n<li><strong>Qué:</strong> el resultado esperado, no solo la tarea. \"Que el inventario de medicamentos de control cuadre al cierre del mes.\"</li>\n<li><strong>Por qué:</strong> el propósito y la importancia.</li>\n<li><strong>Estándar de calidad:</strong> cómo se ve un trabajo bien hecho.</li>\n<li><strong>Plazo:</strong> fecha y puntos de control intermedios.</li>\n<li><strong>Nivel de autonomía:</strong> cuál de los cinco niveles.</li>\n<li><strong>Recursos y apoyos:</strong> a quién acudir, qué herramientas tiene.</li>\n<li><strong>Seguimiento:</strong> cuándo y cómo revisarán.</li>\n</ol>\n<p>Cierra pidiendo a la persona que te diga con sus palabras qué entendió (enseñar de vuelta).</p><h2>Evita la \"delegación inversa\"</h2><p>Ocurre cuando el colaborador te devuelve el problema: \"Jefe, no pude con esto, ¿usted qué haría?\" y tú lo resuelves. En lugar de tomarlo, pregunta: \"¿Qué opciones ves? ¿Cuál recomiendas?\". Así el problema sigue en manos de quien debe resolverlo, con tu apoyo.</p><h2>Seguimiento sin micromanejo</h2><ul>\n<li>Acuerda los puntos de control desde el inicio.</li>\n<li>Revisa resultados, no cada paso.</li>\n<li>Si algo sale mal, analiza el proceso antes de culpar.</li>\n<li>Reconoce el logro cuando sale bien.</li>\n</ul>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb08j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una administradora de droguería delega a un auxiliar con experiencia la elaboración del pedido semanal. Usa los 7 elementos: resultado (pedido sin agotados de los 50 productos de mayor rotación), propósito (evitar que los pacientes crónicos se queden sin medicamento), estándar (revisar rotación de 4 semanas y stock mínimo), plazo (cada jueves antes de las 10), nivel 3 (decide y avísale antes de enviar), apoyo (el reporte del sistema) y seguimiento (revisión de agotados cada lunes durante un mes). A las seis semanas pasa al nivel 4.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb08j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Delegar desarrolla personas y libera tu tiempo para liderar.</li>\n<li>Aclara el nivel de autonomía: de \"investiga y repórtame\" a \"decide y actúa\".</li>\n<li>Usa los 7 elementos y evita la delegación inversa.</li>\n</ol>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb08j${"tone":"info","title":"Siguiente paso","html":"<p>Elige una tarea que hoy haces tú y deléguela esta semana con los 7 elementos.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Reuniones efectivas y conversaciones 1:1: cómo hacer que el tiempo del equipo valga la pena', 'Unidad 3 · Clase 3.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb08j${"tone":"info","title":"En esta clase","html":"<p>Cómo hacer reuniones efectivas (propósito, agenda, roles, acuerdos) y conversaciones 1:1 con tu equipo. Plantillas y ejemplos para líderes del sector salud.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb08j${"html":"<p>Las reuniones mal hechas son una de las mayores fuentes de frustración en el trabajo: empiezan tarde, nadie sabe para qué son, hablan siempre los mismos y terminan sin acuerdos. Pero bien hechas, son la herramienta principal del líder para alinear, decidir y cuidar al equipo. En esta clase aprenderás a diseñar reuniones efectivas y a conducir conversaciones 1:1 que fortalecen la relación con cada colaborador.</p><h2>Antes de convocar: ¿necesitamos una reunión?</h2><p>Pregúntate si el objetivo se puede lograr con un correo, un mensaje o un documento compartido. Las reuniones son para lo que requiere <strong>conversación</strong>: decidir, resolver problemas, generar ideas, alinear prioridades o construir relación.</p><h2>Los 6 elementos de una reunión efectiva</h2><ol>\n<li><strong>Propósito claro:</strong> \"Decidir el nuevo horario de recepción de pedidos.\" No \"hablar de los pedidos\".</li>\n<li><strong>Participantes necesarios:</strong> solo quienes aportan o deben decidir.</li>\n<li><strong>Agenda con tiempos:</strong> enviada antes, con los temas y quién los presenta.</li>\n<li><strong>Roles:</strong> quien facilita, quien toma notas, quien controla el tiempo.</li>\n<li><strong>Conducción:</strong> empezar y terminar a tiempo; dar la palabra a todos; volver al tema cuando se desvía.</li>\n<li><strong>Acuerdos y seguimiento:</strong> cerrar con decisiones, responsables y fechas, y enviar el acta el mismo día.</li>\n</ol><h2>Tipos de reunión del líder</h2><ul>\n<li><strong>Reunión semanal del equipo (30–45 min):</strong> indicadores, prioridades de la semana, problemas y reconocimientos.</li>\n<li><strong>Reunión diaria breve (10–15 min, de pie):</strong> útil en servicios con alta rotación de tareas. ¿Qué hay hoy? ¿Qué obstáculos?</li>\n<li><strong>Reuniones de resolución de problemas:</strong> un solo tema, con datos.</li>\n<li><strong>Revisión mensual o trimestral:</strong> resultados, aprendizajes, metas.</li>\n</ul><h2>Facilitar para que todos participen</h2><ul>\n<li>Pide primero la opinión de las personas con menos poder o más calladas; si el jefe habla primero, los demás tienden a alinearse.</li>\n<li>Usa rondas: \"Cada uno, en una frase, ¿qué riesgo ve?\"</li>\n<li>Separa la generación de ideas de la evaluación.</li>\n<li>Registra los temas que surgen fuera de la agenda en un \"estacionamiento\" para otra reunión.</li>\n</ul><h2>Las conversaciones 1:1</h2><p>Una reunión 1:1 es un espacio regular (semanal o quincenal) entre el líder y cada colaborador. Es, sobre todo, <strong>la reunión del colaborador</strong>: él trae los temas.</p>\n<h3>Para qué sirven</h3>\n<ul>\n<li>Construir confianza y conocer a la persona.</li>\n<li>Detectar problemas a tiempo.</li>\n<li>Dar y pedir retroalimentación.</li>\n<li>Hablar de desarrollo y crecimiento.</li>\n</ul>\n<h3>Estructura sugerida (20–30 min)</h3>\n<ol>\n<li><strong>Cómo estás</strong> (personal, si la persona quiere compartir).</li>\n<li><strong>Temas del colaborador:</strong> ¿qué te preocupa?, ¿en qué te puedo ayudar?</li>\n<li><strong>Temas del líder:</strong> avances, prioridades, retroalimentación.</li>\n<li><strong>Desarrollo:</strong> ¿qué quieres aprender?, ¿hacia dónde quieres crecer?</li>\n<li><strong>Acuerdos.</strong></li>\n</ol>\n<h3>Preguntas útiles</h3>\n<ul>\n<li>\"¿Qué es lo que más te está costando en este momento?\"</li>\n<li>\"¿Hay algo que yo esté haciendo que te dificulte el trabajo?\"</li>\n<li>\"¿Qué deberíamos dejar de hacer?\"</li>\n<li>\"¿De qué estás más orgulloso este mes?\"</li>\n</ul>\n<h3>Reglas de oro</h3>\n<ul>\n<li><strong>No los canceles:</strong> cancelar transmite que la persona no es prioridad. Si es necesario, reprograma.</li>\n<li><strong>Escucha más de lo que hablas.</strong></li>\n<li><strong>Toma notas y cumple los compromisos.</strong></li>\n</ul>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb08j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un jefe de servicio farmacéutico tenía reuniones semanales de dos horas sin agenda. Las redujo a 40 minutos con agenda enviada el día anterior, un facilitador rotativo y acta de acuerdos. Además, inició 1:1 quincenales de 20 minutos. En uno de ellos, una QF le contó que estaba pensando renunciar porque no veía posibilidades de crecer. Acordaron que lideraría el programa de farmacovigilancia. Se quedó.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb08j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Reúnete solo cuando haga falta conversar; define propósito, agenda, roles y acuerdos.</li>\n<li>Facilita para que todos participen y cierra con responsables y fechas.</li>\n<li>Los 1:1 son la reunión del colaborador: confianza, problemas a tiempo y desarrollo.</li>\n</ol>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb08j${"tone":"info","title":"Siguiente paso","html":"<p>Rediseña tu próxima reunión de equipo con la plantilla e inicia los 1:1 con cada persona.</p>"}$hb08j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 4. Motivación y liderazgo del cambio', 3)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo motivar a un equipo: autonomía, competencia, relación y reconocimiento', 'Unidad 4 · Clase 4.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb08j${"tone":"info","title":"En esta clase","html":"<p>Cómo motivar a un equipo de trabajo con la teoría de la autodeterminación (autonomía, competencia y relación) y un reconocimiento específico y frecuente.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb08j${"html":"<p>Muchos líderes creen que la motivación depende sobre todo del salario y los incentivos. El dinero importa, y un salario injusto desmotiva. Pero una vez cubiertas las necesidades básicas, lo que más impulsa a las personas a dar lo mejor tiene que ver con cómo se sienten en su trabajo. En esta clase aprenderás un modelo de motivación con sólido respaldo de investigación y formas prácticas de aplicarlo.</p><h2>Motivación extrínseca e intrínseca</h2><ul>\n<li><strong>Extrínseca:</strong> hacemos algo por una recompensa o para evitar un castigo (bonos, comisiones, sanciones).</li>\n<li><strong>Intrínseca:</strong> hacemos algo porque nos interesa, nos parece valioso o nos hace sentir capaces.</li>\n</ul>\n<p>Las recompensas externas funcionan para tareas sencillas y repetitivas, pero en tareas complejas o creativas pueden, en algunos casos, reducir la motivación intrínseca. Lo ideal es combinar una compensación justa con un entorno que nutra la motivación interna.</p><h2>La teoría de la autodeterminación</h2><p>Los psicólogos Edward Deci y Richard Ryan, de la Universidad de Rochester, propusieron que las personas tenemos tres necesidades psicológicas básicas. Cuando el entorno las satisface, la motivación, el bienestar y el desempeño mejoran.</p>\n<h3>1. Autonomía</h3>\n<p>Sentir que tenemos cierto control sobre cómo hacemos el trabajo.</p>\n<ul>\n<li>Da opciones: \"¿Cómo te gustaría organizar el inventario?\"</li>\n<li>Explica el porqué de las reglas que no se pueden cambiar (por ejemplo, las normas sanitarias).</li>\n<li>Delega con el nivel adecuado.</li>\n</ul>\n<h3>2. Competencia</h3>\n<p>Sentir que somos capaces y que estamos mejorando.</p>\n<ul>\n<li>Asigna retos ajustados: ni muy fáciles ni imposibles.</li>\n<li>Da retroalimentación frecuente y específica.</li>\n<li>Ofrece formación y oportunidades de aprendizaje.</li>\n<li>Celebra el progreso, no solo el resultado final.</li>\n</ul>\n<h3>3. Relación (vínculo)</h3>\n<p>Sentirnos conectados y valorados por otros.</p>\n<ul>\n<li>Construye un equipo donde las personas se conozcan y se apoyen.</li>\n<li>Muestra interés genuino por cada persona.</li>\n<li>Fomenta la colaboración en lugar de la competencia interna destructiva.</li>\n</ul><h2>A esto se suma el propósito</h2><p>En salud, el propósito es un motivador poderoso: el trabajo tiene impacto directo en la vida de los pacientes. Conecta al equipo con ese impacto: comparte historias de pacientes que mejoraron (con confidencialidad), muestra datos de resultados, invita a un paciente o médico a contar cómo los ayudó el servicio.</p><h2>El reconocimiento: específico, oportuno y frecuente</h2><p>El reconocimiento es una de las herramientas más baratas y subutilizadas. Para que funcione:</p>\n<ul>\n<li><strong>Específico:</strong> \"Gracias por quedarte a reorganizar los termolábiles cuando falló la nevera; evitamos perder $8 millones en insulinas\" es mucho mejor que \"buen trabajo\".</li>\n<li><strong>Oportuno:</strong> cerca del hecho.</li>\n<li><strong>Frecuente:</strong> no esperes a la evaluación anual.</li>\n<li><strong>Adaptado:</strong> algunas personas prefieren el reconocimiento público; otras, privado.</li>\n<li><strong>Entre pares:</strong> promueve que los compañeros se reconozcan entre sí.</li>\n</ul><h2>Lo que desmotiva</h2><ul>\n<li>Injusticias percibidas (cargas, turnos, ascensos).</li>\n<li>Microgestión.</li>\n<li>No escuchar las propuestas.</li>\n<li>Cambios sin explicación.</li>\n<li>Reconocer solo los errores.</li>\n<li>Prometer y no cumplir.</li>\n</ul>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb08j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una supervisora de visitadores médicos tiene un equipo desmotivado tras un cambio de portafolio. Aplica la teoría: da autonomía para que cada visitador diseñe su plan de visitas (autonomía), organiza talleres de práctica con el nuevo producto y retroalimentación semanal (competencia), crea un espacio quincenal para compartir buenas prácticas (relación) y comparte testimonios de médicos sobre cómo el producto ayudó a sus pacientes (propósito). Además, reconoce públicamente los avances semanales. El ánimo del equipo mejora y los resultados lo siguen.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb08j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Más allá del salario justo, la motivación depende de autonomía, competencia y relación.</li>\n<li>El propósito es un motivador poderoso en salud.</li>\n<li>El reconocimiento debe ser específico, oportuno, frecuente y adaptado a la persona.</li>\n</ol>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb08j${"tone":"info","title":"Siguiente paso","html":"<p>Da tres reconocimientos específicos esta semana y pregunta a cada persona qué le daría más autonomía en su trabajo.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Gestión del cambio: cómo liderar un cambio en tu equipo con los 8 pasos de Kotter', 'Unidad 4 · Clase 4.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb08j${"tone":"info","title":"En esta clase","html":"<p>Gestión del cambio con los 8 pasos de John Kotter: cómo liderar un cambio en tu equipo, manejar la resistencia y consolidar nuevos hábitos. Ejemplo en servicio farmacéutico.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb08j${"html":"<p>Un nuevo software de inventario. Un cambio en el proceso de dispensación. La fusión con otra sede. Una nueva norma. En el sector salud los cambios son constantes, y la mayoría de las veces el reto no es técnico sino humano: las personas se resisten, el entusiasmo inicial se apaga y todo vuelve a ser como antes. En esta clase aprenderás a liderar un cambio con el modelo de John Kotter y a manejar la resistencia.</p><h2>Por qué fracasan los cambios</h2><p>John P. Kotter, profesor de Harvard Business School, analizó numerosos procesos de transformación en organizaciones y encontró errores frecuentes: no generar suficiente sentido de urgencia, no formar una coalición fuerte, subestimar el poder de una visión, comunicarla poco, permitir obstáculos, no lograr victorias tempranas, declarar la victoria demasiado pronto y no anclar los cambios en la cultura. A partir de ellos propuso <strong>ocho pasos</strong> (en <em>Leading Change</em>, 1996).</p><h2>Los 8 pasos de Kotter</h2><h3>1. Crear sentido de urgencia</h3>\n<p>Ayuda a las personas a ver por qué el cambio es necesario ahora. Usa datos y casos reales: \"El mes pasado tuvimos 12 errores de dispensación de medicamentos de alto riesgo.\"</p>\n<h3>2. Formar una coalición</h3>\n<p>Reúne a un grupo de personas con influencia y credibilidad (no solo jefes): el auxiliar respetado, la QF con experiencia, alguien del área de sistemas.</p>\n<h3>3. Crear una visión y una estrategia</h3>\n<p>Una imagen clara del futuro que se pueda explicar en menos de un minuto: \"Cero errores en medicamentos de alto riesgo, con doble verificación en cada dispensación.\"</p>\n<h3>4. Comunicar la visión</h3>\n<p>Comunica muchas veces, por varios canales y, sobre todo, con el ejemplo. Escucha las dudas.</p>\n<h3>5. Eliminar obstáculos</h3>\n<p>Identifica lo que impide el cambio: falta de formación, procesos, sistemas, personas que bloquean. Remueve lo que puedas.</p>\n<h3>6. Generar victorias a corto plazo</h3>\n<p>Planea logros visibles en las primeras semanas y celébralos. Demuestran que el cambio funciona y dan energía.</p>\n<h3>7. Consolidar y profundizar</h3>\n<p>No declares la victoria demasiado pronto. Usa la credibilidad ganada para extender el cambio a otros procesos.</p>\n<h3>8. Anclar el cambio en la cultura</h3>\n<p>Integra el cambio en los procedimientos, la inducción de personal nuevo, los indicadores y el reconocimiento. Que se vuelva \"la forma en que hacemos las cosas aquí\".</p><h2>Entender la resistencia</h2><p>La resistencia al cambio es normal. Suele venir de:</p>\n<ul>\n<li><strong>Miedo a perder:</strong> control, estatus, competencia (\"con el sistema nuevo voy a parecer lento\").</li>\n<li><strong>Falta de información:</strong> no entienden por qué.</li>\n<li><strong>Experiencias previas:</strong> \"otro cambio que no va a durar\".</li>\n<li><strong>Carga de trabajo:</strong> el cambio llega sobre lo de siempre.</li>\n</ul>\n<p>Cómo manejarla:</p>\n<ul>\n<li>Escucha las objeciones: a veces tienen razón y mejoran el plan.</li>\n<li>Involucra a las personas en el diseño.</li>\n<li>Ofrece formación y acompañamiento.</li>\n<li>Reconoce lo que se pierde y lo que se gana.</li>\n<li>Sé coherente: si el líder no cambia, nadie cambia.</li>\n</ul>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb08j${"tone":"consejo","title":"Ejemplo aplicado: doble verificación en un servicio farmacéutico","html":"<p>Un jefe de farmacia implementa la doble verificación de medicamentos de alto riesgo. (1) Presenta datos de errores. (2) Forma una coalición con dos QF y un auxiliar líder. (3) Define la visión. (4) La comunica en reuniones y carteleras. (5) Ajusta el flujo de trabajo para que la verificación no retrase los despachos. (6) A las tres semanas celebra cero errores en anticoagulantes. (7) Extiende la verificación a insulinas y opioides. (8) La incluye en el procedimiento, la inducción y los indicadores mensuales.</p>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb08j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Los cambios fracasan más por razones humanas que técnicas.</li>\n<li>Los 8 pasos de Kotter: urgencia, coalición, visión, comunicación, obstáculos, victorias tempranas, consolidación y cultura.</li>\n<li>La resistencia es normal: escucha, involucra, forma y sé coherente.</li>\n</ol>"}$hb08j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb08j${"tone":"info","title":"Siguiente paso","html":"<p>Elige un cambio que necesites liderar y completa la plantilla de 8 pasos.</p>"}$hb08j$::jsonb);
END
$hb08$;

-- ─── Curso de Servicio al Cliente y Comunicación con el Paciente (8 clases) ───
DO $hb09$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Servicio al Cliente y Comunicación con el Paciente' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, area, level, tags,
     objective, learning_outcomes, audience, duration_minutes, author_name, status, modality, cover_url, publico)
  VALUES ('edvanta', 'Curso de Servicio al Cliente y Comunicación con el Paciente', $hb09t$Curso de servicio al cliente aplicado a droguerías, farmacias y servicios farmacéuticos: experiencia del paciente, protocolo de atención, comunicación clara (teach-back), información sobre medicamentos en la dispensación, manejo de clientes difíciles y quejas, desescalamiento, atención por WhatsApp y teléfono, y medición de la satisfacción.$hb09t$,
          $hb09t$<p>Curso de servicio al cliente aplicado a droguerías, farmacias y servicios farmacéuticos: experiencia del paciente, protocolo de atención, comunicación clara (teach-back), información sobre medicamentos en la dispensación, manejo de clientes difíciles y quejas, desescalamiento, atención por WhatsApp y teléfono, y medición de la satisfacción.</p><h2>Objetivo</h2><p>Que el participante aplique un protocolo de atención centrado en el paciente, comunique la información de los medicamentos de forma clara y verificada, maneje quejas y situaciones tensas con método, y mida la satisfacción para mejorar el servicio.</p><h2>Para quién es</h2><p>Auxiliares de farmacia y droguería, regentes, químicos farmacéuticos de servicio ambulatorio, personal de dispensarios de gestores farmacéuticos, cajeros y personal de call center del sector salud.</p><h2>Cómo está organizado</h2><p>Cuatro unidades con dos clases en texto cada una. Cada clase trae un ejemplo aplicado al sector farmacéutico y de la salud, puntos clave y el siguiente paso.</p><h2>Referentes</h2><p>Jan Carlzon (momentos de verdad, SAS); Fred Reichheld (Net Promoter Score); método teach-back o &quot;enseñar de vuelta&quot; (comunicación en salud y alfabetización sanitaria); método LAST (escuchar, disculparse, solucionar, agradecer); Resolución 1403 de 2007 (Modelo de Gestión del Servicio Farmacéutico, Colombia).</p>$hb09t$,
          'Servicio al paciente', 'Habilidades Blandas', 'basico', ARRAY['Servicio al cliente', 'Atención al paciente', 'Droguería', 'Manejo de quejas', 'Habilidades blandas']::text[],
          $hb09t$Que el participante aplique un protocolo de atención centrado en el paciente, comunique la información de los medicamentos de forma clara y verificada, maneje quejas y situaciones tensas con método, y mida la satisfacción para mejorar el servicio.$hb09t$,
          ARRAY['Aplicar un protocolo de atención en farmacia y droguería centrado en la experiencia del paciente.', 'Comunicar la información de los medicamentos con lenguaje sencillo y verificar que se entendió (teach-back).', 'Manejar quejas con el método LAST y desescalar situaciones tensas cuidando la seguridad.', 'Atender por WhatsApp y teléfono protegiendo los datos del paciente, y medir la satisfacción con NPS, CSAT y PQRS.']::text[],
          $hb09t$Auxiliares de farmacia y droguería, regentes, químicos farmacéuticos de servicio ambulatorio, personal de dispensarios de gestores farmacéuticos, cajeros y personal de call center del sector salud.$hb09t$,
          153, 'Edvanta', 'borrador', 'asincronica', '/img/cursos/servicio-al-cliente.webp', 'profesionales')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Fundamentos del servicio', 0)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Qué es el servicio al cliente en farmacia: de la venta a la experiencia del paciente', 'Unidad 1 · Clase 1.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb09j${"tone":"info","title":"En esta clase","html":"<p>Qué es el servicio al cliente en una droguería o farmacia, en qué se diferencia de la atención al paciente y por qué la experiencia define la fidelidad.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb09j${"html":"<p>En una tienda de ropa, un mal servicio significa una venta perdida. En una droguería, puede significar un paciente que toma mal su medicamento, que no regresa a reclamar su tratamiento o que se automedica. El servicio en el sector farmacéutico tiene una doble dimensión: es servicio a un cliente y es atención a un paciente. En esta clase vas a entender esa diferencia, qué es la experiencia del paciente y por qué cada interacción cuenta.</p><h2>Servicio al cliente: la definición básica</h2><p>El servicio al cliente es el <strong>conjunto de acciones e interacciones que una organización ofrece para satisfacer las necesidades de quien la visita</strong>, antes, durante y después de la compra. Incluye la amabilidad, la rapidez, la información, la solución de problemas y el seguimiento.</p><h2>Cliente y paciente: dos dimensiones de la misma persona</h2><p>La persona que llega a la droguería es al mismo tiempo:</p>\n<ul>\n<li><strong>Un cliente:</strong> espera rapidez, amabilidad, disponibilidad del producto, buen precio y comodidad.</li>\n<li><strong>Un paciente</strong> (o cuidador): necesita información correcta sobre su medicamento, protección de su intimidad, orientación segura y, a veces, que le digan que debe consultar al médico.</li>\n</ul>\n<p>El buen servicio en farmacia equilibra ambas dimensiones. Vender rápido sin explicar cómo se toma un antibiótico puede dejar satisfecho al cliente, pero falla con el paciente.</p><h2>El marco normativo en Colombia</h2><p>El servicio farmacéutico en Colombia está regulado, entre otras normas, por el Decreto 780 de 2016 (compilatorio del sector salud) y la Resolución 1403 de 2007, que adopta el Modelo de Gestión del Servicio Farmacéutico. El Decreto 780 de 2016 (artículo 2.5.3.10.18) incluye entre las obligaciones de quien dispensa informar al usuario lo indispensable para lograr el efecto terapéutico y el uso adecuado de los medicamentos. Es decir: <strong>informar bien es parte de la obligación del servicio</strong>, no un extra. Verifica siempre la normativa vigente con tu director técnico.</p><h2>Experiencia del paciente</h2><p>La experiencia es la <strong>suma de todas las percepciones</strong> que una persona tiene de su interacción con el servicio: desde que busca el número de teléfono hasta que sale con su medicamento (y lo que pasa después). Incluye:</p>\n<ul>\n<li><strong>Lo racional:</strong> ¿tenían el medicamento?, ¿cuánto me demoré?, ¿me explicaron?</li>\n<li><strong>Lo emocional:</strong> ¿me sentí respetado?, ¿me escucharon?, ¿me dio pena preguntar?</li>\n</ul>\n<p>Las personas suelen recordar más cómo se sintieron que los detalles de lo que pasó.</p><h2>El recorrido del paciente</h2><p>Mapear el recorrido ayuda a encontrar oportunidades de mejora:</p>\n<ol>\n<li><strong>Antes:</strong> busca la droguería, llama para preguntar si hay el medicamento, llega.</li>\n<li><strong>Durante:</strong> espera en la fila, es atendido, recibe información, paga.</li>\n<li><strong>Después:</strong> usa el medicamento, tiene dudas, vuelve (o no) para la siguiente entrega.</li>\n</ol>\n<p>En cada etapa pregúntate: ¿qué necesita?, ¿qué siente?, ¿qué puede salir mal?</p><h2>Por qué el servicio define la fidelidad</h2><p>Los pacientes con enfermedades crónicas compran o reclaman sus medicamentos cada mes durante años. Para una droguería, perder a un paciente crónico por un mal servicio significa perder años de compras. Para un gestor farmacéutico, la mala experiencia se traduce en quejas ante las EPS y los entes de control. Un buen servicio genera recomendación boca a boca, especialmente en barrios y municipios donde todos se conocen.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb09j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Doña Rosa, de 70 años, reclama cada mes su losartán y su metformina. Un mes, el auxiliar nuevo la atiende mirando la pantalla, no la saluda por su nombre y le entrega los medicamentos sin preguntar cómo está. Doña Rosa no se queja, pero el mes siguiente va a otra droguería \"donde la atienden mejor\". El problema no fue el producto ni el precio: fue la experiencia.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb09j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>En farmacia, la persona es cliente y paciente al mismo tiempo.</li>\n<li>Informar sobre el uso adecuado del medicamento es parte de la obligación del servicio farmacéutico.</li>\n<li>La experiencia del paciente incluye lo racional y lo emocional, y define la fidelidad.</li>\n</ol>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb09j${"tone":"info","title":"Siguiente paso","html":"<p>Dibuja el recorrido del paciente en tu lugar de trabajo e identifica tres momentos críticos.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Protocolo de atención al cliente en droguería: momentos de verdad paso a paso', 'Unidad 1 · Clase 1.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb09j${"tone":"info","title":"En esta clase","html":"<p>Protocolo de atención al cliente en droguería y farmacia paso a paso: saludo, identificación de la necesidad, dispensación con información, cierre y momentos de verdad.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb09j${"html":"<p>En los años ochenta, Jan Carlzon, presidente de la aerolínea escandinava SAS, popularizó el concepto de <strong>momentos de verdad</strong>: cada interacción, por breve que sea, en la que un cliente se forma una opinión de la empresa. En una droguería hay decenas de momentos de verdad al día. Un protocolo de atención no busca robotizar al personal, sino asegurar que en cada uno de esos momentos se cumplan los mínimos de calidad. En esta clase aprenderás un protocolo de seis pasos.</p><h2>Paso 1: recibir (los primeros 10 segundos)</h2><ul>\n<li><strong>Contacto visual y saludo</strong> en cuanto la persona llega al mostrador, aunque estés ocupado: \"Buenos días, ya lo atiendo.\"</li>\n<li><strong>Sonrisa genuina</strong> y postura disponible (no apoyado, no mirando el celular).</li>\n<li>Si hay fila, reconoce la espera: \"Gracias por esperar.\"</li>\n</ul><h2>Paso 2: identificar la necesidad</h2><ul>\n<li>Pregunta abierta: \"¿En qué le puedo ayudar?\"</li>\n<li><strong>Escucha activa:</strong> no interrumpas ni supongas.</li>\n<li>Si trae fórmula médica: revísala completa (paciente, medicamento, concentración, forma farmacéutica, cantidad, vigencia, firma).</li>\n<li>Si pide un medicamento o consejo sin fórmula, pregunta para entender: ¿para quién es?, ¿qué síntomas?, ¿desde cuándo?, ¿toma otros medicamentos?, ¿embarazo o lactancia?, ¿alergias?</li>\n</ul><h2>Paso 3: buscar y verificar</h2><ul>\n<li>Informa lo que estás haciendo: \"Le reviso si lo tenemos.\"</li>\n<li>Verifica el producto contra la fórmula: nombre, concentración, forma, cantidad, fecha de vencimiento, estado del empaque.</li>\n<li>Si no está disponible, <strong>no termines ahí</strong>: ofrece alternativas (otra sede, fecha de llegada, opciones según la norma y con orientación del QF o regente).</li>\n</ul><h2>Paso 4: entregar con información</h2><p>Este es el momento más importante desde el punto de vista del paciente. Explica, como mínimo:</p>\n<ul>\n<li><strong>Para qué</strong> es el medicamento (si el paciente lo desea y es pertinente).</li>\n<li><strong>Cómo y cuándo</strong> tomarlo (dosis, horario, con o sin comida).</li>\n<li><strong>Por cuánto tiempo.</strong></li>\n<li><strong>Precauciones clave</strong> y cómo conservarlo (por ejemplo, insulinas en nevera).</li>\n<li><strong>Qué hacer si olvida una dosis</strong> o si tiene una reacción.</li>\n</ul>\n<p>Y verifica la comprensión con la técnica de <strong>enseñar de vuelta</strong> (la veremos en la clase 2.1).</p><h2>Paso 5: cobrar y cerrar</h2><ul>\n<li>Informa el valor con claridad.</li>\n<li>Entrega la factura o el soporte.</li>\n<li>Cierre cordial: \"¿Tiene alguna otra pregunta?\", \"Que se mejore.\"</li>\n<li>Para pacientes crónicos: recuerda la próxima entrega o el servicio de domicilio.</li>\n</ul><h2>Paso 6: registrar y hacer seguimiento</h2><ul>\n<li>Registra lo que corresponda según los procedimientos (dispensación, pendientes, reportes).</li>\n<li>Si hay un pendiente, deja claro cuándo y cómo se le entregará y cumple.</li>\n</ul><h2>Confidencialidad en el mostrador</h2><ul>\n<li>Habla en un volumen que proteja la intimidad.</li>\n<li>No repitas en voz alta diagnósticos o medicamentos sensibles.</li>\n<li>Ofrece el punto de asesoría privado si lo hay.</li>\n<li>Entrega los productos sensibles en empaque discreto.</li>\n</ul><h2>Protocolo no es guion</h2><p>El protocolo define <strong>qué debe pasar</strong>, no las palabras exactas. Cada persona lo aplica con su estilo. Un saludo memorizado y dicho sin mirar es peor que un saludo natural.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb09j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un señor llega con fórmula de amoxicilina para su hijo. La auxiliar saluda, revisa la fórmula, verifica el producto, explica la preparación de la suspensión (\"agua hasta la marca, agite bien\"), la dosis en mililitros con la jeringa dosificadora, cada cuántas horas y por cuántos días, y que debe completar el tratamiento aunque el niño mejore. Le pide que le repita cómo la va a preparar. El señor se equivoca en la cantidad de agua; ella lo corrige. Un error evitado en un momento de verdad.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb09j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Cada interacción es un momento de verdad que forma la opinión del paciente.</li>\n<li>Protocolo de 6 pasos: recibir, identificar, verificar, entregar con información, cerrar y registrar.</li>\n<li>Protege la confidencialidad y aplica el protocolo con naturalidad.</li>\n</ol>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb09j${"tone":"info","title":"Siguiente paso","html":"<p>Usa la lista de verificación para observar a un compañero (y que él te observe) durante cinco atenciones.</p>"}$hb09j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 2. Comunicación clara con el paciente', 1)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Comunicación con el paciente: lenguaje sencillo y la técnica de enseñar de vuelta (teach-back)', 'Unidad 2 · Clase 2.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb09j${"tone":"info","title":"En esta clase","html":"<p>Cómo comunicarse con el paciente con lenguaje sencillo y la técnica de enseñar de vuelta (teach-back) para verificar que entendió cómo tomar su medicamento.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb09j${"html":"<p>\"¿Me entendió?\" \"Sí, señora.\" Y el paciente sale de la droguería sin tener claro si la pastilla es cada 8 horas o tres veces al día con las comidas. Preguntar \"¿me entendió?\" casi nunca verifica la comprensión: por pena, prisa o confianza, la mayoría responde que sí. En esta clase aprenderás a usar lenguaje sencillo y la técnica de enseñar de vuelta, una de las estrategias más recomendadas en comunicación en salud.</p><h2>La alfabetización en salud</h2><p>La <strong>alfabetización en salud</strong> es la capacidad de una persona para obtener, entender y usar información de salud para tomar decisiones. Muchas personas, incluso con estudios, tienen dificultades para entender instrucciones médicas, sobre todo cuando están enfermas, preocupadas o con prisa. Por eso, una buena práctica es <strong>asumir que todos se benefician de una comunicación clara</strong> (lo que se conoce como \"precauciones universales\" en alfabetización en salud).</p><h2>Lenguaje sencillo: cinco reglas</h2><h3>1. Cambia los términos técnicos</h3>\n<ul>\n<li>\"Vía oral\" → \"por la boca, tragado\".</li>\n<li>\"Cada 8 horas\" → \"tres veces al día: por ejemplo, 6 de la mañana, 2 de la tarde y 10 de la noche\".</li>\n<li>\"En ayunas\" → \"antes del desayuno, sin haber comido nada\".</li>\n<li>\"Hipoglucemia\" → \"azúcar bajita\".</li>\n<li>\"Reacción adversa\" → \"efecto que no se espera o que le hace daño\".</li>\n<li>\"Subcutánea\" → \"debajo de la piel\".</li>\n</ul>\n<h3>2. Lo más importante primero</h3>\n<p>Empieza por lo que el paciente necesita hacer: \"Tome una tableta en la mañana y una en la noche.\"</p>\n<h3>3. Pocos mensajes</h3>\n<p>Limita la explicación a dos o tres puntos clave. Si hay más, escríbelos.</p>\n<h3>4. Concreto y visual</h3>\n<p>Muestra el medicamento, la jeringa, el inhalador. Marca la caja con el horario. Usa dibujos (sol, luna) para pacientes con dificultad para leer.</p>\n<h3>5. Ritmo y tono</h3>\n<p>Habla despacio, sin infantilizar, y haz pausas para que la persona pregunte.</p><h2>La técnica de enseñar de vuelta (teach-back)</h2><p>Consiste en pedirle al paciente que <strong>explique con sus propias palabras</strong> lo que entendió. No es un examen para el paciente: es una prueba de qué tan bien explicaste tú.</p>\n<h3>Cómo hacerlo</h3>\n<ol>\n<li><strong>Explica</strong> el punto clave con lenguaje sencillo.</li>\n<li><strong>Pide que lo repita</strong> con una frase que no lo haga sentir evaluado:\n<ul>\n<li>\"Quiero asegurarme de que le expliqué bien. ¿Me cuenta cómo se va a tomar este medicamento?\"</li>\n<li>\"Cuando llegue a la casa, ¿cómo le va a explicar a su esposo cuándo darle el jarabe?\"</li>\n</ul>\n</li>\n<li><strong>Corrige o vuelve a explicar</strong> si hay algún error, de otra forma.</li>\n<li><strong>Pide que lo repita de nuevo</strong> hasta que sea correcto.</li>\n<li><strong>Repite el ciclo</strong> para cada punto clave (no más de tres).</li>\n</ol>\n<h3>Evita</h3>\n<ul>\n<li>\"¿Entendió?\" o \"¿Tiene alguna pregunta?\" como única verificación.</li>\n<li>Hacer sentir al paciente que lo estás evaluando.</li>\n<li>Usar teach-back para todo: concéntrate en lo crítico (dosis, horario, técnica, señales de alarma).</li>\n</ul><h2>Pregunta \"¿qué preguntas tiene?\" en lugar de \"¿tiene preguntas?\"</h2><p>La primera forma asume que es normal tener preguntas e invita a hacerlas; la segunda invita a decir que no.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb09j${"tone":"consejo","title":"Ejemplo aplicado: inhalador","html":"<p>Una regente explica a un paciente con EPOC el uso del inhalador de dosis medida. Luego dice: \"Quiero ver si le expliqué bien. ¿Me muestra cómo lo usaría?\" El paciente inhala rápido y no contiene el aire. La regente vuelve a mostrar: \"Suelte el aire, selle los labios, presione y tome el aire despacio, como cuando toma sopa caliente; aguante el aire contando hasta diez.\" El paciente lo repite correctamente. Esa demostración puede marcar la diferencia en el control de su enfermedad.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb09j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Asume que todos se benefician de una comunicación clara.</li>\n<li>Lenguaje sencillo: términos cotidianos, lo importante primero, pocos mensajes, concreto y visual.</li>\n<li>Enseñar de vuelta verifica la comprensión y evalúa tu explicación, no al paciente.</li>\n</ol>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb09j${"tone":"info","title":"Siguiente paso","html":"<p>Usa enseñar de vuelta con los próximos cinco pacientes y registra cuántas veces tuviste que corregir algo.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Información de medicamentos en el mostrador: qué decir, qué no decir y cuándo remitir', 'Unidad 2 · Clase 2.2', 1, 'manual', 20, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb09j${"tone":"info","title":"En esta clase","html":"<p>Qué información de medicamentos dar en el mostrador de la droguería, qué no recomendar sin fórmula y cuándo remitir al médico o al químico farmacéutico.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb09j${"html":"<p>El mostrador de la droguería es, para muchas personas en Colombia, el primer y a veces el único contacto con un profesional relacionado con la salud. Por eso, lo que se dice ahí importa mucho: puede ayudar a usar bien un tratamiento o puede llevar a una automedicación peligrosa. En esta clase aprenderás qué información dar al dispensar, qué no hacer y cuándo remitir al médico o al químico farmacéutico.</p><h2>Roles y competencias</h2><p>En el servicio farmacéutico trabajan personas con distintas competencias: auxiliares de servicio farmacéutico, regentes de farmacia y químicos farmacéuticos. Cada rol tiene funciones definidas por la normativa y por el establecimiento. <strong>Conoce los límites de tu rol</strong> y cuándo debes acudir al director técnico o al químico farmacéutico. Ante la duda, consulta antes de responder.</p><h2>Qué información dar en la dispensación</h2><p>Como vimos, la información sobre el uso adecuado hace parte del servicio farmacéutico. En la entrega, asegúrate de que el paciente sepa:</p>\n<ol>\n<li><strong>Cómo tomarlo:</strong> dosis, horario, con o sin alimentos, cómo prepararlo (suspensiones) o aplicarlo (inhaladores, insulinas, gotas).</li>\n<li><strong>Por cuánto tiempo</strong> y la importancia de no suspenderlo sin consultar.</li>\n<li><strong>Cómo conservarlo</strong> (temperatura, luz, nevera para termolábiles).</li>\n<li><strong>Precauciones relevantes:</strong> alcohol, somnolencia al conducir, interacciones frecuentes, según la información del producto.</li>\n<li><strong>Qué hacer si olvida una dosis</strong> o si siente algo inesperado.</li>\n</ol>\n<p>La fuente de esta información es la <strong>fórmula médica</strong> y el <strong>inserto o información aprobada del producto</strong>. No improvises.</p><h2>Qué no hacer</h2><ul>\n<li><strong>No dispensar medicamentos de venta bajo fórmula médica sin la prescripción.</strong> Esto incluye antibióticos, que en Colombia requieren fórmula médica; su uso inadecuado contribuye a la resistencia antimicrobiana.</li>\n<li><strong>No cambiar</strong> el medicamento prescrito por otro sin seguir los procedimientos y la normativa sobre intercambio.</li>\n<li><strong>No dar diagnósticos.</strong> \"Eso es una gastritis\" no es tu competencia.</li>\n<li><strong>No recomendar</strong> productos por comisión o por presión comercial cuando no son lo adecuado.</li>\n<li><strong>No contradecir al médico</strong> frente al paciente; si detectas un posible problema en la fórmula, consulta con el QF o el director técnico y, de ser necesario, contacta al prescriptor por el canal adecuado.</li>\n</ul><h2>Antes de recomendar un producto de venta libre: 5 preguntas</h2><ol>\n<li>¿<strong>Para quién</strong> es? (edad, embarazo, lactancia).</li>\n<li>¿<strong>Qué síntomas</strong> tiene y <strong>desde cuándo</strong>?</li>\n<li>¿Ha <strong>tomado algo</strong> ya para eso?</li>\n<li>¿Toma <strong>otros medicamentos</strong> o tiene <strong>enfermedades</strong> (presión alta, diabetes, riñón, hígado)?</li>\n<li>¿Tiene <strong>alergias</strong>?</li>\n</ol>\n<p>Con esas respuestas, y dentro de las competencias de tu rol y los protocolos del establecimiento, puedes orientar o remitir.</p><h2>Señales de alarma: cuándo remitir al médico o a urgencias</h2><p>Remite siempre que identifiques, por ejemplo:</p>\n<ul>\n<li>Fiebre alta o persistente, especialmente en niños pequeños, o fiebre en bebés menores de 3 meses.</li>\n<li>Dolor en el pecho, dificultad para respirar, desmayo.</li>\n<li>Signos de deshidratación (en niños: no orina, llanto sin lágrimas, decaimiento).</li>\n<li>Sangrado importante, vómito con sangre, heces negras.</li>\n<li>Dolor abdominal intenso.</li>\n<li>Síntomas que duran más de lo esperado o empeoran.</li>\n<li>Embarazo con cualquier síntoma preocupante.</li>\n<li>Reacciones alérgicas con hinchazón de cara, labios o dificultad para respirar (urgencias).</li>\n<li>Pensamientos de hacerse daño (urgencias o líneas de atención en crisis).</li>\n</ul>\n<p>Remitir <strong>es</strong> buen servicio. Di: \"Por lo que me cuenta, es importante que lo vea un médico hoy. Le puedo indicar dónde está el centro de salud más cercano.\"</p><h2>Reporte de eventos adversos</h2><p>Si un paciente cuenta un efecto inesperado con su medicamento, regístralo e informa al responsable de farmacovigilancia del establecimiento para su reporte al INVIMA según los procedimientos.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb09j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una mujer pide \"algo para la gripa\" para su hijo de 2 años con fiebre de tres días. Al hacer las cinco preguntas, la auxiliar descubre que el niño respira rápido y está decaído. En lugar de recomendar un antigripal, explica: \"Por la edad del niño, los días de fiebre y cómo está respirando, es importante que lo vea un médico hoy.\" Le indica el centro de salud más cercano. Esa remisión puede ser decisiva.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb09j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Informa cómo tomar, por cuánto tiempo, cómo conservar y qué precauciones tener, con base en la fórmula y el inserto.</li>\n<li>No dispenses sin fórmula lo que la requiere, no diagnostiques y conoce los límites de tu rol.</li>\n<li>Haz las 5 preguntas antes de orientar y remite ante señales de alarma.</li>\n</ol>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb09j${"tone":"info","title":"Siguiente paso","html":"<p>Imprime la lista de señales de alarma y ubícala en un lugar visible del mostrador.</p>"}$hb09j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 3. Clientes difíciles y quejas', 2)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Manejo de clientes difíciles y quejas: el método LAST paso a paso', 'Unidad 3 · Clase 3.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb09j${"tone":"info","title":"En esta clase","html":"<p>Manejo de clientes difíciles y quejas en el servicio al cliente con el método LAST (escuchar, disculparse, solucionar, agradecer). Ejemplos en farmacia.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb09j${"html":"<p>\"¡Es la tercera vez que vengo y no me tienen el medicamento!\" Las quejas son parte del día a día en una droguería o un dispensario. La forma en que se manejan define si el paciente se va más enojado o con una solución, y muchas veces si regresa o no. Una queja bien resuelta puede generar más lealtad que un servicio sin problemas. En esta clase aprenderás el método LAST, una secuencia sencilla para manejar quejas.</p><h2>Cambia la mirada sobre las quejas</h2><p>Una queja es <strong>información valiosa</strong>: muestra dónde falla el servicio. Muchos clientes insatisfechos no se quejan; simplemente no vuelven. Quien se queja te está dando una oportunidad de corregir.</p><h2>El método LAST</h2><p>Es un método de servicio al cliente usado en distintas industrias. Sus siglas en inglés corresponden a cuatro pasos:</p>\n<h3>L — Listen (Escuchar)</h3>\n<ul>\n<li>Deja que la persona hable sin interrumpir.</li>\n<li>Mantén contacto visual y una postura abierta.</li>\n<li>No te defiendas ni expliques todavía.</li>\n<li>Toma nota si es necesario.</li>\n<li>Usa escucha activa: \"Entonces, vino el lunes y el jueves, y en ninguna de las dos le entregaron el medicamento.\"</li>\n</ul>\n<h3>A — Apologize (Disculparse)</h3>\n<ul>\n<li>Ofrece una disculpa sincera por la experiencia, aunque no sea tu culpa personal: \"Lamento mucho que haya tenido que venir tres veces.\"</li>\n<li>La disculpa no es aceptar culpas legales; es reconocer el impacto en la persona.</li>\n<li>Evita: \"Disculpe, pero eso no es culpa mía\", \"Es que el sistema…\".</li>\n</ul>\n<h3>S — Solve (Solucionar)</h3>\n<ul>\n<li>Pregunta qué necesita: \"¿Cuántos días le quedan de medicamento?\"</li>\n<li>Ofrece opciones concretas dentro de lo posible: buscar en otra sede, gestionar la entrega a domicilio, dar una fecha comprometida, escalar el caso.</li>\n<li><strong>No prometas lo que no puedes cumplir.</strong></li>\n<li>Si no tienes la solución, di quién la tiene y cuándo responderá.</li>\n</ul>\n<h3>T — Thank (Agradecer)</h3>\n<ul>\n<li>Agradece que te lo haya dicho: \"Gracias por avisarnos; nos ayuda a mejorar.\"</li>\n<li>Cierra confirmando el acuerdo: \"Entonces le confirmamos el viernes antes de las 12.\"</li>\n</ul><h2>Lo que no debes hacer</h2><ul>\n<li>Discutir quién tiene la razón.</li>\n<li>Tomarlo como algo personal.</li>\n<li>Culpar a otros frente al paciente (\"es culpa de la EPS\", \"el de la mañana no registró\").</li>\n<li>Usar frases que cierran la conversación: \"Esas son las políticas\", \"No se puede\".</li>\n<li>Prometer y no cumplir (es la forma más rápida de convertir una queja en una queja formal).</li>\n</ul><h2>Frases que ayudan</h2><ul>\n<li>\"Entiendo lo molesto que es esto para usted.\"</li>\n<li>\"Déjeme revisar qué podemos hacer.\"</li>\n<li>\"Lo que sí puedo hacer es…\"</li>\n<li>\"Voy a hacer seguimiento personalmente.\"</li>\n</ul><h2>Quejas formales: PQRS</h2><p>En Colombia, las entidades del sector salud deben tener canales para peticiones, quejas, reclamos y sugerencias (PQRS o PQRSD) y responderlas en los términos de ley (la Ley 1755 de 2015 regula el derecho de petición). Si el paciente quiere poner una queja formal, <strong>facilítale el canal</strong> sin resistencia: es su derecho. Además, registra las quejas verbales para analizar patrones.</p><h2>Del caso individual al sistema</h2><p>Si la misma queja se repite (por ejemplo, agotados del mismo medicamento), no basta con resolver caso por caso. Reporta el patrón a tu coordinador: puede requerir un cambio en el pedido, en el proveedor o en el proceso.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb09j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un paciente llega molesto porque su insulina lleva una semana pendiente. La regente escucha sin interrumpir (L), le dice \"Lamento mucho la espera; sé que la insulina no puede faltar\" (A), revisa y encuentra unidades en otra sede, gestiona el traslado y le ofrece entregársela a domicilio esa tarde (S), y le agradece por insistir: \"Gracias por avisarnos, vamos a revisar por qué se retrasó\" (T). El paciente se va calmado. Al día siguiente, la regente reporta el patrón de pendientes de insulinas al coordinador.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb09j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Una queja es información valiosa y una oportunidad.</li>\n<li>LAST: escuchar, disculparse, solucionar y agradecer.</li>\n<li>No prometas lo que no puedes cumplir, facilita las PQRS y reporta los patrones.</li>\n</ol>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb09j${"tone":"info","title":"Siguiente paso","html":"<p>Escribe la respuesta LAST para las tres quejas más frecuentes en tu lugar de trabajo.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo calmar a un cliente agresivo: técnicas de desescalamiento y seguridad', 'Unidad 3 · Clase 3.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb09j${"tone":"info","title":"En esta clase","html":"<p>Cómo calmar a un cliente enojado o agresivo con técnicas de desescalamiento verbal y no verbal, y qué hacer si la situación pone en riesgo tu seguridad.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb09j${"html":"<p>A veces la molestia se convierte en gritos, insultos o amenazas. En el sector salud, donde las personas llegan con dolor, miedo, frustración por trámites o medicamentos pendientes, estas situaciones no son raras. Saber desescalar protege al paciente, al equipo y a ti. Pero también es importante saber cuándo la prioridad es la seguridad. En esta clase aprenderás técnicas de desescalamiento verbal y no verbal, y qué hacer si la situación se sale de control.</p><h2>Entender la escalada</h2><p>Cuando una persona está muy alterada, su capacidad de razonar disminuye. Darle explicaciones lógicas en ese momento (\"Señor, el sistema de la EPS funciona así…\") rara vez funciona. Primero hay que <strong>bajar la intensidad emocional</strong>; después se puede resolver el problema.</p><h2>Siete técnicas de desescalamiento</h2><h3>1. Cuida tu propia regulación</h3>\n<p>Antes que nada, regúlate tú: respira con exhalación larga (técnica STOP). Si tú te alteras, la situación escala. No lo tomes como algo personal: la persona está enojada con la situación.</p>\n<h3>2. Lenguaje corporal no amenazante</h3>\n<ul>\n<li>Postura abierta, manos visibles, sin cruzar los brazos.</li>\n<li>Mantén una distancia prudente (más allá de un brazo).</li>\n<li>Ubícate en ángulo, no de frente confrontando.</li>\n<li>Evita señalar o hacer movimientos bruscos.</li>\n<li>Mantén una vía de salida para ti.</li>\n</ul>\n<h3>3. Voz baja y pausada</h3>\n<p>Habla más bajo y más despacio que la persona. Por contagio, muchas veces el otro también baja el volumen. No grites para hacerte escuchar.</p>\n<h3>4. Escucha y valida la emoción</h3>\n<p>\"Veo que está muy molesto.\" \"Entiendo que esto es muy frustrante.\" Validar la emoción no es darle la razón en todo; es reconocer lo que siente.</p>\n<h3>5. Frases cortas y claras</h3>\n<p>Una idea por frase. Evita los tecnicismos y las explicaciones largas.</p>\n<h3>6. Ofrece opciones y control</h3>\n<p>Las personas alteradas suelen sentir que han perdido el control. Ofrecer opciones ayuda: \"¿Prefiere que revisemos en otra sede o que le gestionemos el domicilio?\" \"¿Quiere sentarse mientras lo reviso?\"</p>\n<h3>7. Pon límites con respeto</h3>\n<p>Si hay insultos: \"Quiero ayudarle, y para eso necesito que hablemos sin insultos.\" Si continúa: \"Si sigue gritando, voy a tener que pedirle a mi coordinador que lo atienda.\"</p><h2>Lo que escala la situación</h2><ul>\n<li>Decir \"cálmese\".</li>\n<li>Discutir o corregir a la persona mientras está alterada.</li>\n<li>Reírse, ironizar o poner los ojos en blanco.</li>\n<li>Amenazar (\"voy a llamar a la policía\") como primera respuesta.</li>\n<li>Ignorarla o seguir atendiendo a otro.</li>\n<li>Tocarla.</li>\n</ul><h2>Cuando la seguridad está en riesgo</h2><p>Si hay amenazas de violencia física, armas, agresión a personas o daño a las instalaciones:</p>\n<ol>\n<li><strong>Tu seguridad es primero.</strong> No te enfrentes físicamente.</li>\n<li><strong>Aléjate</strong> y pon una barrera de por medio (el mostrador).</li>\n<li><strong>Pide ayuda:</strong> activa el protocolo del establecimiento, llama al vigilante, al coordinador o a la Policía (línea 123 en Colombia).</li>\n<li><strong>Protege a otros clientes y compañeros.</strong></li>\n<li><strong>Después, registra lo ocurrido</strong> y busca apoyo: estas situaciones afectan emocionalmente.</li>\n</ol>\n<p>Cada establecimiento debería tener un <strong>protocolo de seguridad</strong> acordado con el equipo: cómo pedir ayuda, quién interviene, palabras clave.</p><h2>Después del incidente</h2><ul>\n<li>Habla con un compañero o tu coordinador sobre lo que pasó.</li>\n<li>Analiza qué detonó la situación y si se puede prevenir (por ejemplo, mejorar la información sobre pendientes).</li>\n<li>Si te afectó emocionalmente, busca apoyo en tu ARL o en los programas de bienestar.</li>\n</ul>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb09j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un hombre golpea el mostrador y grita porque su mamá no ha recibido un medicamento para el dolor oncológico. El auxiliar respira, baja la voz, se ubica en ángulo y dice: \"Veo que está muy preocupado por su mamá. Quiero ayudarle.\" El hombre sigue gritando. El auxiliar repite con calma y ofrece opciones: \"¿Me permite revisar en el sistema mientras usted se sienta un momento?\" El hombre baja el tono. El auxiliar llama a la regente, que encuentra una alternativa. Al final, el hombre se disculpa.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb09j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Primero baja la intensidad emocional; después resuelve el problema.</li>\n<li>Regúlate, cuida tu lenguaje corporal y tu voz, valida, ofrece opciones y pon límites con respeto.</li>\n<li>Si la seguridad está en riesgo, aléjate y pide ayuda según el protocolo.</li>\n</ol>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb09j${"tone":"info","title":"Siguiente paso","html":"<p>Revisa si tu lugar de trabajo tiene un protocolo de seguridad ante agresiones; si no, propón uno con la plantilla.</p>"}$hb09j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 4. Canales digitales y medición', 3)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Atención al cliente por WhatsApp y teléfono: protocolo, tiempos y protección de datos', 'Unidad 4 · Clase 4.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb09j${"tone":"info","title":"En esta clase","html":"<p>Cómo dar atención al cliente por WhatsApp y teléfono en una droguería: protocolo, tiempos de respuesta, mensajes modelo y protección de datos personales.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb09j${"html":"<p>Hoy muchos pacientes prefieren escribir por WhatsApp antes que ir a la droguería: preguntan si hay un medicamento, piden un domicilio o envían una foto de la fórmula. El teléfono sigue siendo clave, sobre todo para personas mayores. Estos canales tienen ventajas (comodidad, rapidez) y riesgos (malentendidos, demoras, manejo de datos personales). En esta clase aprenderás un protocolo para atender por WhatsApp y teléfono de forma profesional y segura.</p><h2>Atención telefónica: el protocolo básico</h2><ol>\n<li><strong>Contesta pronto</strong> (idealmente antes del tercer timbre).</li>\n<li><strong>Saluda e identifícate:</strong> \"Droguería San José, habla Andrea, ¿en qué le puedo ayudar?\"</li>\n<li><strong>Sonríe al hablar:</strong> se nota en la voz.</li>\n<li><strong>Escucha y toma nota</strong> de lo esencial (nombre, medicamento, necesidad).</li>\n<li><strong>Si debes dejar en espera,</strong> pide permiso y no superes un minuto sin volver: \"¿Me permite un momento mientras lo reviso?\"</li>\n<li><strong>Confirma la información</strong> antes de colgar (enseñar de vuelta si son instrucciones).</li>\n<li><strong>Despídete cordialmente</strong> y deja que el cliente cuelgue primero.</li>\n</ol><h2>WhatsApp: ventajas y riesgos</h2><p><strong>Ventajas:</strong> el paciente consulta sin desplazarse, queda registro escrito, permite enviar fotos de la fórmula y de los productos.\n<strong>Riesgos:</strong> mensajes ambiguos, demoras en la respuesta, falta de tono (un mensaje seco se lee como grosero), riesgos de privacidad y tentación de dar asesoría que requiere evaluación presencial.</p><h2>Protocolo de WhatsApp</h2><h3>1. Perfil profesional</h3>\n<p>Usa WhatsApp Business con nombre, horario, dirección y un mensaje de bienvenida automático que indique el tiempo de respuesta.</p>\n<h3>2. Tiempos de respuesta</h3>\n<p>Define un estándar (por ejemplo, responder en menos de 15 minutos en horario de atención) y cúmplelo. Si no puedes resolver de inmediato, responde algo: \"Recibido, ya lo reviso y le confirmo en 10 minutos.\"</p>\n<h3>3. Tono escrito</h3>\n<ul>\n<li>Saluda por el nombre.</li>\n<li>Mensajes cortos y claros, una idea por mensaje.</li>\n<li>Usa emojis con moderación y solo si encaja con el estilo de la marca.</li>\n<li>Evita mayúsculas sostenidas (se leen como gritos).</li>\n<li>Cierra con una pregunta o confirmación.</li>\n</ul>\n<h3>4. Respuestas rápidas</h3>\n<p>Prepara plantillas para lo frecuente: horario, domicilios, disponibilidad, documentos para reclamar medicamentos, confirmación de pedido. Personalízalas siempre con el nombre.</p>\n<h3>5. Límites de la asesoría a distancia</h3>\n<ul>\n<li>No dispenses medicamentos de venta bajo fórmula sin la prescripción válida según los procedimientos del establecimiento y la normativa.</li>\n<li>Para síntomas o dudas que requieren evaluación, invita a acercarse o remite al médico.</li>\n<li>Ante señales de alarma, indica ir a urgencias de inmediato.</li>\n</ul><h2>Protección de datos personales</h2><p>En Colombia, la Ley 1581 de 2012 regula el tratamiento de datos personales, y los datos de salud se consideran <strong>datos sensibles</strong>, con protección reforzada. Buenas prácticas:</p>\n<ul>\n<li>Usa un celular institucional, no el personal.</li>\n<li>Informa la política de tratamiento de datos y obtén la autorización según los procedimientos de la empresa.</li>\n<li>No compartas fotos de fórmulas ni datos de pacientes en grupos internos no autorizados ni con terceros.</li>\n<li>Borra o archiva la información según la política de la empresa.</li>\n<li>Confirma la identidad antes de dar información de un tratamiento a un tercero.</li>\n</ul>\n<p>Consulta con el área legal o de cumplimiento de tu empresa los procedimientos específicos.</p><h2>Ejemplo de conversación por WhatsApp</h2><p>Paciente: \"Hola, tienen la losartán de 50\"\nDroguería: \"¡Buenas tardes, don Jorge! Sí, tenemos losartán de 50 mg. ¿Cuántas cajas necesita?\"\nPaciente: \"2. Me la pueden traer?\"\nDroguería: \"Claro. El domicilio llega en aproximadamente 40 minutos y tiene un costo de $X. ¿Nos confirma la dirección?\"\nPaciente: \"Cra 45 # 12-30\"\nDroguería: \"Perfecto, don Jorge. Le confirmo: 2 cajas de losartán 50 mg a Cra 45 # 12-30. Total $X. ¿Paga en efectivo o transferencia?\"</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb09j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Teléfono: contesta pronto, identifícate, sonríe al hablar y confirma la información.</li>\n<li>WhatsApp: perfil profesional, tiempos de respuesta definidos, tono claro y plantillas personalizadas.</li>\n<li>Protege los datos de salud como datos sensibles y conoce los límites de la asesoría a distancia.</li>\n</ol>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb09j${"tone":"info","title":"Siguiente paso","html":"<p>Crea cinco plantillas de respuestas rápidas para las consultas más frecuentes de tu droguería.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo medir la satisfacción del cliente: NPS, CSAT, PQRS y mejora continua', 'Unidad 4 · Clase 4.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb09j${"tone":"info","title":"En esta clase","html":"<p>Cómo medir la satisfacción del cliente en una droguería o servicio farmacéutico con NPS, CSAT y el análisis de PQRS, y cómo convertir los datos en mejoras.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb09j${"html":"<p>\"Creemos que atendemos bien.\" Esa frase es común, pero sin datos es solo una opinión. Medir la satisfacción permite saber cómo perciben los pacientes el servicio, detectar problemas antes de que se conviertan en quejas formales y comprobar si las mejoras funcionan. En esta clase aprenderás a usar tres herramientas sencillas: NPS, CSAT y el análisis de PQRS, y a convertirlas en un ciclo de mejora.</p><h2>Herramienta 1: Net Promoter Score (NPS)</h2><p>Creado por Fred Reichheld y publicado en <em>Harvard Business Review</em> en 2003. Se basa en una sola pregunta:</p>\n<p><strong>\"Del 0 al 10, ¿qué tan probable es que recomiende nuestra droguería a un familiar o amigo?\"</strong></p>\n<p>Las respuestas se clasifican en:</p>\n<ul>\n<li><strong>Promotores (9–10):</strong> clientes leales que recomiendan.</li>\n<li><strong>Pasivos (7–8):</strong> satisfechos pero no entusiastas.</li>\n<li><strong>Detractores (0–6):</strong> insatisfechos, pueden hablar mal del servicio.</li>\n</ul>\n<p><strong>Cálculo:</strong> NPS = % de promotores − % de detractores. Va de −100 a +100.</p>\n<p>Ejemplo: de 100 encuestados, 55 son promotores, 30 pasivos y 15 detractores. NPS = 55 − 15 = <strong>+40</strong>.</p>\n<p><strong>Clave:</strong> agrega una pregunta abierta: \"¿Cuál es la razón principal de su calificación?\". Ahí está la información para mejorar.</p><h2>Herramienta 2: CSAT (satisfacción del cliente)</h2><p>Mide la satisfacción con una interacción concreta:</p>\n<p><strong>\"¿Qué tan satisfecho quedó con la atención de hoy?\"</strong> (escala de 1 a 5).</p>\n<p><strong>Cálculo:</strong> % de respuestas 4 y 5 sobre el total.</p>\n<p>Ejemplo: 80 de 100 respuestas fueron 4 o 5 → CSAT = 80 %.</p>\n<p>El CSAT es útil para evaluar momentos específicos (la atención en el mostrador, el domicilio, la atención por WhatsApp).</p><h2>Herramienta 3: análisis de PQRS</h2><p>Las peticiones, quejas, reclamos y sugerencias son datos valiosos. Para analizarlas:</p>\n<ol>\n<li><strong>Registra todas</strong>, incluidas las verbales.</li>\n<li><strong>Clasifícalas</strong> por categoría: agotados/pendientes, tiempo de espera, trato, información, precio, domicilio, errores.</li>\n<li><strong>Cuenta cuántas hay por categoría</strong> cada mes.</li>\n<li><strong>Identifica las más frecuentes</strong> (por lo general, unas pocas categorías concentran la mayoría de las quejas).</li>\n<li><strong>Mide el tiempo de respuesta</strong> y verifica que se cumplan los plazos.</li>\n</ol><h2>Cómo recoger la información</h2><ul>\n<li>Encuesta corta por WhatsApp después de la compra o el domicilio.</li>\n<li>Código QR en el mostrador con la encuesta.</li>\n<li>Tableta o formulario en papel a la salida.</li>\n<li>Llamadas a pacientes crónicos (muestra mensual).</li>\n</ul>\n<p>Reglas: preguntas cortas, encuesta anónima o con autorización de datos, y frecuencia razonable para no cansar.</p><h2>El ciclo de mejora</h2><p>Medir sin actuar no sirve. Usa un ciclo sencillo (inspirado en el ciclo PHVA: planear, hacer, verificar, actuar):</p>\n<ol>\n<li><strong>Mide</strong> (NPS, CSAT, PQRS).</li>\n<li><strong>Analiza:</strong> ¿cuáles son las causas principales de insatisfacción?</li>\n<li><strong>Decide una o dos mejoras</strong> concretas.</li>\n<li><strong>Implementa</strong> con responsables y fechas.</li>\n<li><strong>Vuelve a medir</strong> para ver si funcionó.</li>\n<li><strong>Comparte los resultados</strong> con el equipo y reconoce los avances.</li>\n</ol><h2>Tablero mensual de servicio</h2><p>Un tablero simple, visible para el equipo, puede incluir:</p>\n<ul>\n<li>NPS del mes y su tendencia.</li>\n<li>CSAT por canal (mostrador, WhatsApp, domicilio).</li>\n<li>Número de PQRS por categoría.</li>\n<li>Tiempo promedio de respuesta a PQRS.</li>\n<li>Una mejora en curso y su estado.</li>\n</ul>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb09j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una droguería mide NPS durante un mes y obtiene +18. En los comentarios de los detractores, la causa más repetida es \"demoran mucho en la fila del mediodía\". Deciden que entre las 12 y las 2 nadie del mostrador sale a almorzar y que una persona atiende solo pedidos rápidos. Al mes siguiente, el NPS sube a +35 y las quejas por tiempo de espera bajan a la mitad.</p>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb09j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>NPS mide lealtad (% promotores − % detractores); CSAT mide satisfacción con una interacción.</li>\n<li>Las PQRS clasificadas muestran dónde se concentran los problemas.</li>\n<li>Medir sirve solo si cierra el ciclo: analizar, mejorar, volver a medir y compartir.</li>\n</ol>"}$hb09j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb09j${"tone":"info","title":"Siguiente paso","html":"<p>Implementa la encuesta NPS + CSAT durante dos semanas y calcula tus primeros resultados con la plantilla.</p>"}$hb09j$::jsonb);
END
$hb09$;

-- ─── Curso para Hablar Frente a la Cámara: Oratoria Digital para Videos y Videollamadas (8 clases) ───
DO $hb10$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso para Hablar Frente a la Cámara: Oratoria Digital para Videos y Videollamadas' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, area, level, tags,
     objective, learning_outcomes, audience, duration_minutes, author_name, status, modality, cover_url, publico)
  VALUES ('edvanta', 'Curso para Hablar Frente a la Cámara: Oratoria Digital para Videos y Videollamadas', $hb10t$Curso práctico para comunicar con naturalidad frente a la cámara: diferencias con el escenario, set con celular (luz, encuadre, audio), guion para videos cortos y educativos, naturalidad sin leer, voz y mirada al lente, videollamadas y webinars, ética y normativa del contenido de salud en redes y plan de contenido de 30 días.$hb10t$,
          $hb10t$<p>Curso práctico para comunicar con naturalidad frente a la cámara: diferencias con el escenario, set con celular (luz, encuadre, audio), guion para videos cortos y educativos, naturalidad sin leer, voz y mirada al lente, videollamadas y webinars, ética y normativa del contenido de salud en redes y plan de contenido de 30 días.</p><h2>Objetivo</h2><p>Que el participante produzca con su celular videos educativos de 60–90 segundos con guion, encuadre, luz, audio y presencia adecuados, conduzca videollamadas y webinars efectivos, y publique contenido de salud ético y conforme a la normativa.</p><h2>Para quién es</h2><p>Químicos farmacéuticos, regentes, docentes, visitadores médicos, equipos de mercadeo y profesionales que quieren crear contenido educativo o mejorar su presencia en reuniones virtuales.</p><h2>Cómo está organizado</h2><p>Cuatro unidades con dos clases en texto cada una. Cada clase trae un ejemplo aplicado al sector farmacéutico y de la salud, puntos clave y el siguiente paso.</p><h2>Referentes</h2><p>Principios de oratoria aplicados a cámara (Toastmasters, TED); buenas prácticas de producción con celular; Superintendencia de Industria y Comercio (Guía de buenas prácticas en la publicidad a través de influenciadores, 2020); normativa sanitaria colombiana sobre publicidad de medicamentos (INVIMA).</p>$hb10t$,
          'Oratoria y presentaciones', 'Habilidades Blandas', 'basico', ARRAY['Oratoria digital', 'Video', 'Webinars', 'Redes sociales', 'Habilidades blandas']::text[],
          $hb10t$Que el participante produzca con su celular videos educativos de 60–90 segundos con guion, encuadre, luz, audio y presencia adecuados, conduzca videollamadas y webinars efectivos, y publique contenido de salud ético y conforme a la normativa.$hb10t$,
          ARRAY['Perder el miedo a la cámara y grabar con el celular con buena luz, encuadre y audio.', 'Escribir guiones de 60 segundos y hablar con naturalidad sin leer.', 'Conectar a través del lente y conducir videollamadas y webinars.', 'Publicar contenido de salud ético y conforme a la normativa, con un plan de contenido de 30 días.']::text[],
          $hb10t$Químicos farmacéuticos, regentes, docentes, visitadores médicos, equipos de mercadeo y profesionales que quieren crear contenido educativo o mejorar su presencia en reuniones virtuales.$hb10t$,
          152, 'Edvanta', 'borrador', 'asincronica', '/img/cursos/hablar-frente-a-la-camara.webp', 'profesionales')
  RETURNING id INTO v_curso;

