  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Hablar en cámara vs. hablar en público: qué cambia y cómo perder el miedo a la cámara', 'Unidad 1 · Clase 1.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb10j${"tone":"info","title":"En esta clase","html":"<p>Qué cambia al hablar frente a la cámara frente a hablar en público y cómo perder el miedo a la cámara con práctica gradual y técnicas sencillas.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb10j${"html":"<p>Hay personas que hablan con soltura frente a un auditorio y se paralizan cuando se enciende la cámara del celular. Otras se sienten más cómodas grabando que con público. Hablar en cámara es una forma de oratoria con reglas propias: el público no está presente, no hay retroalimentación inmediata y todo queda grabado. En esta clase verás qué cambia frente al escenario y cómo empezar a perder el miedo a la cámara.</p><h2>Qué cambia frente a la cámara</h2><table><thead><tr><th>Escenario</th><th>Cámara</th></tr></thead><tbody><tr><td>Público presente que reacciona</td><td>Público invisible; no ves reacciones</td></tr><tr><td>Hablas a muchos a la vez</td><td>Hablas a <strong>una persona</strong> al otro lado</td></tr><tr><td>Los errores pasan rápido</td><td>Los errores quedan grabados (pero se pueden repetir o editar)</td></tr><tr><td>Gestos amplios</td><td>Gestos contenidos dentro del encuadre</td></tr><tr><td>Atención relativamente cautiva</td><td>Atención que se pierde en segundos con un deslizamiento</td></tr><tr><td>Duración larga posible</td><td>Formatos cortos (30 s a 3 min) para redes</td></tr></tbody></table><h2>La idea clave: hablas con una persona</h2><p>Aunque tu video lo vean mil personas, cada una lo ve sola, en su celular. Habla como si le explicaras algo a <strong>una persona concreta</strong> que está al otro lado del lente: un paciente, un colega, un estudiante. Esto cambia tu tono: más cercano, más natural, menos \"discurso\".</p>\n<p>Un truco práctico: imagina la cara de alguien que te cae bien detrás de la cámara, o pega una foto pequeña junto al lente.</p><h2>Por qué da miedo la cámara</h2><ul>\n<li><strong>Autoobservación:</strong> verte y oírte grabado es incómodo (como vimos en el Curso de Oratoria, tu voz suena distinta en la grabación).</li>\n<li><strong>Perfeccionismo:</strong> como se puede repetir, sentimos que debe quedar perfecto.</li>\n<li><strong>Miedo al juicio en redes:</strong> comentarios, colegas que lo verán, permanencia del contenido.</li>\n<li><strong>Falta de práctica:</strong> la cámara es una situación nueva.</li>\n</ul><h2>Cómo perder el miedo: el reto de 7 días</h2><p>Aplica la exposición gradual que vimos en el curso de miedo escénico:</p>\n<ul>\n<li><strong>Día 1:</strong> grábate 30 segundos diciendo qué hiciste hoy. No lo veas. No lo publiques.</li>\n<li><strong>Día 2:</strong> graba 30 segundos y míralo una vez, solo para acostumbrarte.</li>\n<li><strong>Día 3:</strong> graba un consejo de tu área de 45 segundos.</li>\n<li><strong>Día 4:</strong> repite el consejo mejorando una sola cosa (mirada, energía o inicio).</li>\n<li><strong>Día 5:</strong> graba 60 segundos y envíalo a una persona de confianza.</li>\n<li><strong>Día 6:</strong> graba un video corto con un guion sencillo.</li>\n<li><strong>Día 7:</strong> publícalo en un círculo cercano (estado de WhatsApp, grupo de colegas) o guárdalo como tu primer video del portafolio.</li>\n</ul><h2>Mentalidad: hecho es mejor que perfecto</h2><p>Los primeros videos no serán los mejores. Es normal. Lo importante es la constancia: cada video te enseña algo. Muchos creadores de contenido reconocen que sus primeros videos les parecen incómodos de ver, y que su naturalidad llegó con la práctica.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb10j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una QF quiere grabar videos cortos sobre el uso correcto de medicamentos para la página de su droguería. Las primeras veces repite la toma 15 veces y se rinde. Con el reto de 7 días, empieza sin publicar, se acostumbra a su imagen y a su voz, y al día 7 publica un video de 50 segundos sobre cómo guardar la insulina. Le llegan preguntas de pacientes. Eso la motiva a seguir.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb10j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Frente a la cámara hablas con una persona, no con una multitud.</li>\n<li>El miedo a la cámara es normal y se reduce con exposición gradual.</li>\n<li>Hecho es mejor que perfecto: la naturalidad llega con la práctica.</li>\n</ol>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb10j${"tone":"info","title":"Siguiente paso","html":"<p>Empieza hoy el reto de 7 días.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo grabar videos con el celular: luz, encuadre y audio profesionales sin gastar mucho', 'Unidad 1 · Clase 1.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb10j${"tone":"info","title":"En esta clase","html":"<p>Cómo grabar videos con el celular con calidad profesional: iluminación, encuadre, estabilidad y audio, con equipo básico y de bajo costo.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb10j${"html":"<p>No necesitas una cámara costosa para hacer videos educativos de buena calidad. Los celulares actuales graban con muy buena calidad de imagen. Lo que separa un video casero de uno profesional casi nunca es la cámara: es la <strong>luz, el encuadre y, sobre todo, el audio</strong>. En esta clase aprenderás a preparar un set básico con lo que ya tienes o con una inversión mínima.</p><h2>1. El audio es lo más importante</h2><p>Las personas toleran una imagen regular, pero abandonan rápido un video con audio malo (eco, ruido, volumen bajo).</p>\n<ul>\n<li><strong>Graba en un lugar silencioso:</strong> apaga ventiladores, cierra ventanas, avisa en casa o en el trabajo.</li>\n<li><strong>Evita espacios con eco:</strong> baños, cocinas, salas vacías. Las cortinas, alfombras y muebles absorben el sonido.</li>\n<li><strong>Acércate al micrófono:</strong> el micrófono del celular funciona mejor a menos de un metro.</li>\n<li><strong>Micrófono externo:</strong> un micrófono de solapa (con cable o inalámbrico para celular) es la mejor inversión inicial; mejora notablemente la calidad.</li>\n<li><strong>Haz una prueba</strong> de 10 segundos y escúchala con audífonos antes de grabar todo.</li>\n</ul><h2>2. La luz</h2><ul>\n<li><strong>Luz natural de frente:</strong> ubícate frente a una ventana (la ventana detrás del celular). Es la luz más favorecedora y gratuita.</li>\n<li><strong>Evita el contraluz:</strong> con una ventana detrás de ti, tu cara se verá oscura.</li>\n<li><strong>Evita la luz cenital dura</strong> (un bombillo justo encima): crea sombras en los ojos.</li>\n<li><strong>Luz artificial:</strong> un aro de luz o un panel LED pequeño frente a ti, a la altura de los ojos o un poco más arriba.</li>\n<li><strong>Consistencia:</strong> si grabas una serie de videos, usa la misma luz para que se vean uniformes.</li>\n</ul><h2>3. El encuadre</h2><ul>\n<li><strong>Vertical (9:16)</strong> para videos cortos en redes (Reels, TikTok, Shorts, estados).</li>\n<li><strong>Horizontal (16:9)</strong> para YouTube, presentaciones y clases.</li>\n<li><strong>Altura:</strong> el celular a la altura de los ojos. Desde abajo se ve poco favorecedor; desde muy arriba, distante.</li>\n<li><strong>Plano medio:</strong> de la mitad del pecho hacia arriba, con un poco de espacio sobre la cabeza.</li>\n<li><strong>Regla de los tercios:</strong> los ojos en la línea del tercio superior de la pantalla.</li>\n<li><strong>Fondo:</strong> ordenado, con algo de profundidad (no pegado a la pared). En contexto farmacéutico, un fondo de estantería ordenada o un consultorio limpio da contexto, pero cuida que no se vean marcas que impliquen publicidad no deseada ni información de pacientes.</li>\n</ul><h2>4. La estabilidad</h2><ul>\n<li>Usa un <strong>trípode</strong> sencillo o apoya el celular en una superficie firme.</li>\n<li>Limpia el lente antes de grabar (parece obvio, pero es la causa número uno de imagen borrosa).</li>\n<li>Usa la <strong>cámara trasera</strong> si alguien te ayuda (suele tener mejor calidad) o la frontal si grabas solo.</li>\n<li>Bloquea el enfoque y la exposición tocando tu cara en la pantalla y manteniendo presionado (según el modelo).</li>\n</ul><h2>5. Configuración básica</h2><ul>\n<li>Resolución 1080p o 4K, 30 cuadros por segundo es suficiente.</li>\n<li>Modo avión o \"no molestar\" para evitar interrupciones.</li>\n<li>Espacio de almacenamiento y batería suficientes.</li>\n</ul><h2>Kit básico recomendado</h2><ol>\n<li>Trípode con soporte para celular.</li>\n<li>Micrófono de solapa.</li>\n<li>Luz LED pequeña o aro de luz (opcional si tienes buena luz natural).</li>\n</ol>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb10j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un regente graba en el mostrador un video sobre protector solar. Primera versión: contraluz de la puerta, ruido de la calle y celular en la mano. Segunda versión: se ubica dentro, frente a la vitrina iluminada, con el celular en un trípode a la altura de los ojos y un micrófono de solapa, en un horario de poca afluencia. La diferencia es enorme con muy poca inversión.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb10j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Prioriza el audio: lugar silencioso, sin eco y micrófono cerca.</li>\n<li>Luz de frente, cámara a la altura de los ojos y plano medio.</li>\n<li>Estabilidad con trípode, lente limpio y modo avión.</li>\n</ol>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb10j${"tone":"info","title":"Siguiente paso","html":"<p>Arma tu set con el checklist y graba una prueba de 30 segundos en vertical y horizontal.</p>"}$hb10j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 2. Guion y naturalidad', 1)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo hacer un guion para video: gancho, desarrollo y llamado a la acción en 60 segundos', 'Unidad 2 · Clase 2.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb10j${"tone":"info","title":"En esta clase","html":"<p>Cómo hacer un guion para video corto educativo: gancho en los primeros 3 segundos, desarrollo con una sola idea y llamado a la acción. Plantilla y ejemplos.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb10j${"html":"<p>En redes sociales, la decisión de seguir viendo un video se toma en los primeros segundos. Si el inicio no engancha, el espectador desliza al siguiente. Un buen guion no es un texto largo para leer: es una estructura que asegura que el mensaje llegue rápido, se entienda y lleve a una acción. En esta clase aprenderás una estructura de guion para videos educativos de 60 segundos.</p><h2>La estructura de 4 partes</h2><h3>1. Gancho (0–3 segundos)</h3>\n<p>Una frase que haga que la persona se detenga. Tipos de gancho:</p>\n<ul>\n<li><strong>Error común:</strong> \"Si guarda la insulina en la puerta de la nevera, está cometiendo un error.\"</li>\n<li><strong>Pregunta:</strong> \"¿Sabía que el jugo de toronja puede cambiar el efecto de algunos medicamentos?\"</li>\n<li><strong>Dato sorprendente</strong> (verificado): una cifra relevante.</li>\n<li><strong>Promesa:</strong> \"En 30 segundos le explico cómo usar bien su inhalador.\"</li>\n<li><strong>Contradicción:</strong> \"Más antibiótico no le quita la gripa más rápido.\"</li>\n</ul>\n<h3>2. Contexto (3–10 segundos)</h3>\n<p>Por qué importa: \"Porque la temperatura cambia mucho cada vez que se abre la puerta, y la insulina es sensible a los cambios.\"</p>\n<h3>3. Desarrollo (10–50 segundos)</h3>\n<p><strong>Una sola idea</strong>, con dos o tres pasos o consejos concretos. Usa ejemplos, demostraciones u objetos reales.\n\"Guárdela en la parte media de la nevera, nunca en el congelador. La que está en uso puede estar a temperatura ambiente el tiempo que indique el inserto. Y nunca la deje en el carro.\"</p>\n<h3>4. Cierre y llamado a la acción (50–60 segundos)</h3>\n<p>Resume y di qué hacer:</p>\n<ul>\n<li>\"Revise hoy dónde está su insulina.\"</li>\n<li>\"Guarde este video para no olvidarlo.\"</li>\n<li>\"Si tiene dudas, pregúntele a su químico farmacéutico.\"</li>\n<li>\"Compártalo con alguien que use insulina.\"</li>\n</ul><h2>Escribe para el oído</h2><ul>\n<li>Frases cortas.</li>\n<li>Palabras cotidianas.</li>\n<li>Habla en segunda persona (\"usted\" o \"tú\", según tu público y tu marca).</li>\n<li>Una idea por frase.</li>\n<li>Lee el guion en voz alta: si te trabas, reescribe.</li>\n</ul><h2>Cuántas palabras</h2><p>A un ritmo natural de 130–160 palabras por minuto, un video de 60 segundos tiene entre 120 y 150 palabras. Si tu guion tiene 250, tienes dos videos.</p><h2>Apoyos visuales</h2><p>Planea qué se verá en cada momento:</p>\n<ul>\n<li>Tu cara para el gancho y el cierre.</li>\n<li>El objeto o la demostración en el desarrollo (la insulina, el inhalador, la nevera).</li>\n<li>Texto en pantalla con la idea clave (muchas personas ven videos sin sonido).</li>\n<li>Subtítulos: mejoran la accesibilidad y la retención.</li>\n</ul><h2>Ejemplo de guion completo (≈130 palabras)</h2><p><strong>Gancho:</strong> \"¿Toma el omeprazol después del desayuno? Puede que no le esté haciendo el efecto que debería.\"\n<strong>Contexto:</strong> \"El omeprazol funciona mejor cuando se toma antes de comer.\"\n<strong>Desarrollo:</strong> \"Por eso, la recomendación habitual es tomarlo en ayunas, unos 30 a 60 minutos antes del desayuno, con un vaso de agua. Trague la cápsula entera, sin masticarla. Y si lo toma desde hace mucho tiempo, consulte con su médico si todavía lo necesita, porque no es un medicamento para tomar indefinidamente sin control.\"\n<strong>Cierre:</strong> \"Antes del desayuno, entero y con control médico. Guarde este video y compártalo con alguien que lo tome.\"</p>\n<p><em>Nota: verifica siempre las recomendaciones con el inserto aprobado y las guías vigentes antes de grabar.</em></p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb10j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Estructura: gancho (0–3 s), contexto, desarrollo de una sola idea y llamado a la acción.</li>\n<li>Escribe para el oído: frases cortas y cotidianas; 120–150 palabras por minuto de video.</li>\n<li>Planea los apoyos visuales y usa subtítulos.</li>\n</ol>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb10j${"tone":"info","title":"Siguiente paso","html":"<p>Escribe tres guiones de 60 segundos con la plantilla, cada uno con un tipo de gancho distinto.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Cómo hablar natural frente a la cámara: teleprompter, puntos clave y grabación por bloques', 'Unidad 2 · Clase 2.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb10j${"tone":"info","title":"En esta clase","html":"<p>Cómo hablar frente a la cámara con naturalidad: cuándo usar teleprompter, cómo grabar con puntos clave o por bloques, y trucos para no sonar leído.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb10j${"html":"<p>Tienes un buen guion. Ahora el reto es decirlo sin sonar como si lo estuvieras leyendo. La naturalidad frente a la cámara es una de las habilidades que más se notan y una de las que más preocupa a quienes empiezan. En esta clase compararás tres métodos para grabar (teleprompter, puntos clave y bloques) y aprenderás técnicas para sonar como en una conversación.</p><h2>Método 1: teleprompter</h2><p>Aplicaciones de teleprompter para celular muestran el texto en la pantalla mientras grabas.</p>\n<ul>\n<li><strong>Ventajas:</strong> precisión en el mensaje (útil en contenido técnico o regulado), menos repeticiones.</li>\n<li><strong>Desventajas:</strong> riesgo de sonar leído; los ojos se mueven de lado a lado.</li>\n<li><strong>Cómo usarlo bien:</strong>\n<ul>\n<li>Coloca el texto lo más cerca posible del lente.</li>\n<li>Ajusta la velocidad a tu ritmo natural, no al revés.</li>\n<li>Usa letra grande y pocas palabras por línea para reducir el movimiento de los ojos.</li>\n<li>Marca pausas y énfasis en el texto.</li>\n<li>Ensaya dos o tres veces antes de grabar.</li>\n</ul>\n</li>\n</ul><h2>Método 2: puntos clave</h2><p>Memorizas la estructura y tienes a la vista (fuera de cámara o en una nota junto al lente) solo 3–5 palabras clave.</p>\n<ul>\n<li><strong>Ventajas:</strong> suena muy natural y conversacional.</li>\n<li><strong>Desventajas:</strong> más repeticiones; puedes olvidar algo o alargarte.</li>\n<li><strong>Ideal para:</strong> personas con experiencia en el tema y videos de tono cercano.</li>\n</ul><h2>Método 3: grabación por bloques</h2><p>Grabas frase por frase o idea por idea, mirando el guion entre cada toma, y luego unes los cortes en la edición.</p>\n<ul>\n<li><strong>Ventajas:</strong> no necesitas memorizar; cada bloque sale con buena energía.</li>\n<li><strong>Desventajas:</strong> requiere edición; si cambias de posición o de luz entre bloques, se nota.</li>\n<li><strong>Truco:</strong> los cortes entre bloques se pueden disimular cambiando ligeramente el encuadre (acercando la imagen) o insertando una imagen de apoyo.</li>\n</ul>\n<p><strong>Recomendación:</strong> combina. Muchos creadores graban por bloques con puntos clave y usan teleprompter solo para datos precisos.</p><h2>Técnicas para sonar natural</h2><ol>\n<li><strong>Ensaya en voz alta</strong> varias veces antes de grabar; no la primera lectura frente a la cámara.</li>\n<li><strong>Cambia palabras del guion</strong> que no usarías al hablar.</li>\n<li><strong>Habla con alguien imaginario:</strong> imagina que le explicas a un paciente concreto.</li>\n<li><strong>Sube la energía un 10–20 %:</strong> la cámara aplana la expresión; lo que en persona parece exagerado, en video se ve normal.</li>\n<li><strong>Sonríe en el saludo y en el cierre</strong> (si el tema lo permite).</li>\n<li><strong>Usa las manos</strong> dentro del encuadre.</li>\n<li><strong>Permite pequeñas imperfecciones:</strong> una pausa natural o un \"bueno\" ocasional humanizan el video.</li>\n<li><strong>Graba varias tomas</strong> y elige la más natural, no la más perfecta.</li>\n</ol><h2>La primera frase define la toma</h2><p>Si la primera frase sale con energía y mirando al lente, el resto fluye. Si sale apagada, repite desde el inicio. No sigas grabando una toma que empezó mal.</p><h2>Postproducción mínima</h2><ul>\n<li>Corta los silencios del inicio y el final.</li>\n<li>Elimina los errores entre bloques.</li>\n<li>Agrega subtítulos (muchas aplicaciones los generan automáticamente; revísalos, sobre todo nombres de medicamentos y cifras).</li>\n<li>Agrega texto en pantalla con la idea clave.</li>\n</ul>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb10j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un QF que graba microclases para estudiantes empezó con teleprompter y sus videos sonaban leídos. Cambió a grabación por bloques: lee una frase del guion, mira al lente, la dice con sus palabras y corta. Luego une los bloques en una aplicación de edición del celular y agrega subtítulos. Los estudiantes comentan que \"parece que les está hablando a ellos\".</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb10j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Teleprompter para precisión, puntos clave para naturalidad, bloques para facilidad; combínalos.</li>\n<li>Ensaya en voz alta, sube la energía y habla con alguien imaginario.</li>\n<li>Elige la toma más natural y revisa los subtítulos, sobre todo en términos técnicos.</li>\n</ol>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb10j${"tone":"info","title":"Siguiente paso","html":"<p>Graba el mismo guion con los tres métodos y compara cuál te sale más natural.</p>"}$hb10j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 3. Voz, mirada y formatos en vivo', 2)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Voz y mirada en video: cómo conectar a través del lente', 'Unidad 3 · Clase 3.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb10j${"tone":"info","title":"En esta clase","html":"<p>Oratoria digital: cómo usar la voz y la mirada en video para conectar a través del lente, con ritmo, pausas, énfasis y expresión facial ajustados a la cámara.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb10j${"html":"<p>En video, el espectador está a centímetros de tu cara. Ve cada gesto, escucha cada cambio de voz y nota de inmediato si miras hacia otro lado. Eso es una ventaja: permite una conexión muy cercana. Pero también exige ajustar la voz y la mirada a la cámara. En esta clase aprenderás a usar el lente como si fueran los ojos de una persona y a modular tu voz para mantener la atención.</p><h2>La mirada: el lente son los ojos de tu espectador</h2><p>Cuando miras al lente, el espectador siente que lo miras a él. Cuando miras la pantalla (tu propia imagen) o tus notas, siente que miras a otro lado.</p>\n<h3>Técnicas para mirar al lente</h3>\n<ul>\n<li><strong>El punto rojo:</strong> pon una pequeña calcomanía o un punto de color junto al lente para recordar dónde mirar.</li>\n<li><strong>Cubre tu imagen:</strong> si te distrae verte en la pantalla, tápala con una nota adhesiva.</li>\n<li><strong>Imagina una persona:</strong> visualiza los ojos de alguien concreto detrás del lente.</li>\n<li><strong>Mira hacia otro lado con intención:</strong> está bien desviar la mirada para \"pensar\" brevemente, como en una conversación, pero vuelve al lente para las ideas clave.</li>\n</ul>\n<h3>Cuándo no mirar al lente</h3>\n<p>En formatos de entrevista o conversación (dos personas en cámara), se suele mirar al entrevistador, no al lente. Define el formato antes de grabar.</p><h2>La voz en video</h2><p>El micrófono capta matices que en un salón pasan desapercibidos. Ajusta:</p>\n<h3>Volumen</h3>\n<p>No necesitas proyectar como en un auditorio. Habla con volumen de conversación cercana, firme y claro. El micrófono hace el resto.</p>\n<h3>Ritmo</h3>\n<p>En videos cortos, el ritmo suele ser un poco más ágil que en una presentación, pero sin atropellarte. Baja la velocidad en los datos clave (dosis, horarios, advertencias).</p>\n<h3>Pausas</h3>\n<p>Las pausas siguen siendo importantes: después del gancho, antes del dato clave y antes del llamado a la acción. En edición, puedes acortar las pausas largas, pero no elimines todas.</p>\n<h3>Énfasis y variación</h3>\n<p>Una voz monótona en video se nota aún más que en vivo. Marca en el guion la palabra clave de cada frase y dale énfasis.</p>\n<h3>Calentamiento antes de grabar (3 minutos)</h3>\n<ol>\n<li>Tres respiraciones con exhalación larga.</li>\n<li>Vibración de labios (\"brrr\") subiendo y bajando el tono.</li>\n<li>Exagerar la articulación de las vocales: \"a-e-i-o-u\".</li>\n<li>Decir la primera frase del guion tres veces con énfasis distinto.</li>\n</ol><h2>La expresión facial</h2><ul>\n<li><strong>Coherencia:</strong> si hablas de algo serio (una alerta sanitaria), una sonrisa constante resulta incongruente. Si das un consejo útil y positivo, una expresión amable ayuda.</li>\n<li><strong>Cejas y ojos:</strong> son los que más comunican en un primer plano. Una expresión neutra prolongada puede parecer aburrimiento.</li>\n<li><strong>Escucha mientras hablas:</strong> imagina que la persona te responde; tu expresión se vuelve más natural.</li>\n</ul><h2>Energía sostenida</h2><p>Las tomas largas tienden a perder energía hacia el final. Si notas que bajas, corta y vuelve a empezar el bloque. Grabar de pie, en lugar de sentado, ayuda a muchas personas a mantener más energía.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb10j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una visitadora médica graba un video interno de 90 segundos para presentar un nuevo material educativo a su equipo. En la primera toma mira su imagen en la pantalla y su voz suena plana. En la segunda pega un punto rojo junto al lente, se pone de pie, hace el calentamiento vocal y marca en el guion tres palabras de énfasis. El resultado se siente como si hablara con cada compañero.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb10j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>El lente son los ojos del espectador: míralo en las ideas clave.</li>\n<li>Volumen de conversación, ritmo ágil con pausas y énfasis en la palabra clave.</li>\n<li>Expresión facial coherente con el mensaje y energía sostenida.</li>\n</ol>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb10j${"tone":"info","title":"Siguiente paso","html":"<p>Graba un video de 60 segundos con el punto rojo y el calentamiento vocal, y compáralo con uno anterior.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Videollamadas y webinars profesionales: cómo dar un webinar que la gente vea hasta el final', 'Unidad 3 · Clase 3.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb10j${"tone":"info","title":"En esta clase","html":"<p>Cómo dar un webinar o una videollamada profesional: estructura, interacción, roles, guion técnico y seguimiento para que la audiencia se quede hasta el final.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb10j${"html":"<p>Los webinars se volvieron una herramienta habitual en el sector farmacéutico: capacitaciones a redes de droguerías, actualizaciones científicas para médicos, lanzamientos de productos, educación a pacientes. Pero muchos webinars pierden a buena parte de su audiencia en los primeros minutos. En esta clase aprenderás a diseñar y conducir un webinar que la gente vea hasta el final, aplicando todo lo que has aprendido sobre presencia en cámara.</p><h2>Antes: diseño del webinar</h2><h3>Define el objetivo y la audiencia</h3>\n<p>¿Qué debe saber, sentir o hacer la audiencia al terminar? ¿Quiénes son, qué saben y qué les preocupa? (Recuerda el triángulo del Curso de Presentaciones.)</p>\n<h3>Duración</h3>\n<p>Para la mayoría de temas, 45–60 minutos incluidas las preguntas es suficiente. Un webinar de dos horas necesita pausas y mucha interacción.</p>\n<h3>Estructura recomendada (60 minutos)</h3>\n<ul>\n<li><strong>0–5 min:</strong> bienvenida, reglas de participación, una pregunta de apertura (encuesta o chat).</li>\n<li><strong>5–15 min:</strong> el problema y por qué importa (con una historia o caso).</li>\n<li><strong>15–40 min:</strong> contenido en 3 bloques, cada uno con una interacción.</li>\n<li><strong>40–50 min:</strong> caso práctico o demostración.</li>\n<li><strong>50–58 min:</strong> preguntas y respuestas.</li>\n<li><strong>58–60 min:</strong> resumen y llamado a la acción (encuesta de satisfacción, recurso descargable, próximo evento).</li>\n</ul>\n<h3>Roles</h3>\n<ul>\n<li><strong>Presentador:</strong> contenido.</li>\n<li><strong>Moderador o anfitrión:</strong> da la bienvenida, controla tiempos, lee preguntas del chat.</li>\n<li><strong>Soporte técnico:</strong> resuelve problemas de audio, enlaces, permisos.\nEn webinars pequeños, el moderador y el soporte pueden ser la misma persona, pero <strong>no el presentador</strong>.</li>\n</ul>\n<h3>Ensayo técnico</h3>\n<p>Prueba un día antes: plataforma, compartir pantalla, videos, encuestas, audio, conexión y plan B (presentación en PDF, segundo dispositivo).</p><h2>Durante: conducción</h2><ul>\n<li><strong>Empieza a tiempo</strong> (puedes dar 2 minutos de cortesía con música o una diapositiva de bienvenida).</li>\n<li><strong>Cámara encendida</strong> del presentador, con la configuración de set que ya aprendiste.</li>\n<li><strong>Interacción cada 5–7 minutos:</strong> encuestas, preguntas al chat, reacciones, un \"escriba 1 si…\".</li>\n<li><strong>Nombra a los participantes</strong> cuando leas sus comentarios: \"Carolina, desde Pereira, pregunta…\".</li>\n<li><strong>Narra lo que haces:</strong> \"Les comparto ahora un caso.\"</li>\n<li><strong>Cuida la energía:</strong> de pie si es posible, voz con variación, mirada al lente en los momentos clave.</li>\n<li><strong>Gestiona el tiempo:</strong> el moderador avisa discretamente si te estás pasando.</li>\n</ul><h2>Manejo de preguntas</h2><ul>\n<li>Pide que escriban las preguntas en el chat o en la herramienta de preguntas y respuestas a lo largo de la sesión.</li>\n<li>El moderador las agrupa y selecciona.</li>\n<li>Responde con PREP (punto, razón, ejemplo, punto).</li>\n<li>Si no sabes, ofrece responder por correo; en temas de salud, no improvises datos.</li>\n</ul><h2>Después: seguimiento</h2><ul>\n<li>Envía la grabación (si se autorizó), la presentación y los recursos en las siguientes 24 horas.</li>\n<li>Comparte la encuesta de satisfacción.</li>\n<li>Responde las preguntas que quedaron pendientes.</li>\n<li>Analiza los datos: asistencia, permanencia, participación, satisfacción y acciones posteriores (descargas, inscripciones).</li>\n</ul><h2>Consideraciones del sector</h2><ul>\n<li>Si el webinar es para profesionales de la salud y trata sobre medicamentos, el contenido debe ajustarse a la información aprobada y a las normas de promoción.</li>\n<li>Si es para pacientes, usa lenguaje sencillo y no promociones medicamentos de venta bajo fórmula.</li>\n<li>Informa si se graba y gestiona los datos personales de los inscritos según la política de tratamiento de datos.</li>\n</ul>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb10j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una cadena de droguerías organiza un webinar mensual para sus regentes sobre actualización en farmacovigilancia. Antes, era una conferencia de 90 minutos con la cámara apagada y caía la asistencia. Ahora dura 50 minutos, tiene un moderador, abre con una encuesta, presenta un caso real por bloque, cierra con un cuestionario de cinco preguntas y envía un resumen de una página. La permanencia hasta el final y los reportes de eventos adversos aumentan.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb10j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Diseña con objetivo, estructura por bloques y roles definidos; ensaya la parte técnica.</li>\n<li>Conduce con cámara, energía e interacción cada 5–7 minutos; el moderador gestiona el chat.</li>\n<li>Haz seguimiento en 24 horas y mide permanencia, participación y acciones.</li>\n</ol>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb10j${"tone":"info","title":"Siguiente paso","html":"<p>Diseña el guion técnico minuto a minuto de un webinar de 45 minutos sobre un tema de tu área.</p>"}$hb10j$::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 4. Contenido de salud en redes y plan de 30 días', 3)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Contenido educativo de salud en redes sociales: ética, normativa y credibilidad', 'Unidad 4 · Clase 4.1', 0, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb10j${"tone":"info","title":"En esta clase","html":"<p>Cómo crear contenido educativo de salud en redes sociales con ética: normativa de publicidad de medicamentos en Colombia, transparencia comercial y fuentes confiables.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb10j${"html":"<p>Las redes sociales están llenas de información de salud: algunas útiles, muchas incompletas y otras peligrosas. Los profesionales del sector farmacéutico pueden ser una voz confiable que ayude a las personas a usar mejor sus medicamentos. Pero esa voz tiene responsabilidades: lo que publicas puede influir en decisiones de salud, y existe normativa sobre lo que se puede comunicar al público. En esta clase aprenderás los principios éticos y normativos para crear contenido de salud en redes.</p><h2>Por qué tu contenido importa</h2><ul>\n<li>Las personas buscan información de salud en internet y redes antes o después de ir al médico.</li>\n<li>La desinformación sobre medicamentos (dosis, usos no aprobados, productos \"milagrosos\") puede causar daño.</li>\n<li>Un profesional que comunica con rigor construye confianza y aporta a la salud pública.</li>\n</ul><h2>Principios éticos del contenido de salud</h2><ol>\n<li><strong>Veracidad y evidencia:</strong> basa el contenido en fuentes confiables (información aprobada del producto, guías clínicas, autoridades sanitarias). Revisa la fecha de las fuentes.</li>\n<li><strong>Educación, no prescripción:</strong> explica cómo usar bien los medicamentos y cuándo consultar; no indiques tratamientos individuales por redes.</li>\n<li><strong>Aviso claro:</strong> aclara que el contenido es educativo y no reemplaza la consulta con un profesional.</li>\n<li><strong>No sembrar miedo ni falsas expectativas.</strong></li>\n<li><strong>Respetar la confidencialidad:</strong> nunca muestres datos, fórmulas, rostros o historias identificables de pacientes sin su consentimiento.</li>\n<li><strong>Transparencia sobre conflictos de interés:</strong> si trabajas para un laboratorio, una cadena o recibes pago por un contenido, dilo.</li>\n<li><strong>Respeto profesional:</strong> no descalifiques a colegas ni a otras profesiones.</li>\n</ol><h2>Normativa a tener en cuenta en Colombia</h2><p><em>Esta es una orientación general; verifica siempre la normativa vigente y consulta con el área regulatoria o legal.</em></p>\n<ul>\n<li><strong>Publicidad de medicamentos:</strong> según la normativa sanitaria (por ejemplo, el Decreto 677 de 1995 y sus desarrollos), solo los medicamentos de <strong>venta libre</strong> pueden anunciarse al público general, cumpliendo los requisitos del INVIMA. Los de <strong>venta bajo fórmula médica</strong> solo se promocionan a profesionales de la salud.</li>\n<li><strong>Diferencia entre educación y publicidad:</strong> hablar de cómo usar bien un inhalador (sin promover una marca) es educación; mostrar una marca específica de un medicamento de venta bajo fórmula con un mensaje favorable al público puede considerarse publicidad no permitida.</li>\n<li><strong>Publicidad con influenciadores:</strong> la Superintendencia de Industria y Comercio publicó en 2020 una guía de buenas prácticas que pide <strong>revelar de forma clara</strong> cuando un contenido es publicitario o patrocinado (por ejemplo, con etiquetas como #Publicidad).</li>\n<li><strong>Productos fraudulentos:</strong> el INVIMA emite alertas sobre productos sin registro sanitario o fraudulentos (por ejemplo, productos promocionados en redes para bajar de peso). No promociones ni compartas productos sin registro.</li>\n<li><strong>Protección de datos:</strong> aplica la Ley 1581 de 2012 si recoges datos de seguidores.</li>\n<li><strong>Código deontológico</strong> de tu profesión: los químicos farmacéuticos y otros profesionales tienen normas éticas propias.</li>\n</ul><h2>Señales de alerta en tu propio contenido</h2><ul>\n<li>Usas una marca de medicamento de venta bajo fórmula dirigiéndote al público.</li>\n<li>Recomiendas una dosis o un cambio de tratamiento a una persona concreta en comentarios.</li>\n<li>Prometes resultados (\"baja 10 kilos en un mes\").</li>\n<li>Usas un testimonio de paciente sin consentimiento.</li>\n<li>No revelas que es un contenido pagado.</li>\n<li>No puedes citar de dónde sale un dato.</li>\n</ul><h2>Cómo responder comentarios y mensajes</h2><ul>\n<li>Agradece y responde con información general.</li>\n<li>Ante preguntas personales de tratamiento: \"Para darle una recomendación segura necesito conocer su caso; le sugiero consultarlo con su médico o acercarse a su químico farmacéutico.\"</li>\n<li>Ante señales de alarma: indica buscar atención médica de inmediato.</li>\n<li>Ante desinformación en comentarios: corrige con respeto y con fuente.</li>\n</ul>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb10j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una QF quiere hacer un video sobre medicamentos para bajar de peso, un tema muy buscado. En lugar de mostrar marcas y hablar de resultados, crea un video educativo: qué son, por qué requieren fórmula médica, por qué no se deben comprar por redes y cómo verificar alertas del INVIMA sobre productos fraudulentos. Cita fuentes y agrega el aviso educativo. El video es útil, ético y conforme a la norma.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb10j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Contenido de salud: veraz, educativo, con fuentes, con aviso y respetando la confidencialidad.</li>\n<li>En Colombia, solo los medicamentos de venta libre pueden anunciarse al público; revela siempre el contenido patrocinado.</li>\n<li>No prescribas por redes y remite ante preguntas individuales o señales de alarma.</li>\n</ol>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb10j${"tone":"info","title":"Siguiente paso","html":"<p>Revisa tus tres últimas publicaciones (o tus guiones) con el checklist ético-normativo.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Plan de contenido de 30 días: temas, calendario, métricas y mejora continua', 'Unidad 4 · Clase 4.2', 1, 'manual', 19, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, $hb10j${"tone":"info","title":"En esta clase","html":"<p>Cómo hacer un plan de contenido de 30 días para redes sociales: pilares temáticos, calendario, producción por lotes, métricas y mejora continua.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, $hb10j${"html":"<p>Publicar un video de vez en cuando no construye una audiencia ni una marca profesional. La constancia sí. Pero la constancia sin un plan agota: cada día hay que pensar qué publicar, grabar a última hora y editar con prisa. En esta clase final diseñarás un plan de contenido de 30 días con pilares temáticos, un calendario realista, producción por lotes y métricas para mejorar.</p><h2>Paso 1: define tu objetivo y tu audiencia</h2><ul>\n<li><strong>Objetivo:</strong> ¿qué quieres lograr? Educar a pacientes de tu droguería, posicionarte como referente en tu especialidad, atraer estudiantes a tus cursos, mejorar la comunicación interna de tu empresa.</li>\n<li><strong>Audiencia:</strong> ¿a quién le hablas? Pacientes crónicos, cuidadores, colegas, estudiantes, médicos. Una audiencia definida hace que el contenido sea más útil.</li>\n</ul><h2>Paso 2: elige 3 a 4 pilares temáticos</h2><p>Los pilares son las grandes categorías de tu contenido. Ejemplo para una QF que educa a pacientes:</p>\n<ol>\n<li><strong>Uso correcto de medicamentos</strong> (cómo tomar, guardar, aplicar).</li>\n<li><strong>Mitos y verdades</strong> (antibióticos y gripa, genéricos, suplementos).</li>\n<li><strong>Enfermedades crónicas</strong> (diabetes, hipertensión: hábitos y adherencia).</li>\n<li><strong>Detrás del mostrador</strong> (cómo funciona la droguería, qué hace un QF).</li>\n</ol><h2>Paso 3: genera ideas con base en lo que la gente busca</h2><ul>\n<li>Las preguntas que te hacen en el mostrador o en consulta.</li>\n<li>Las sugerencias de autocompletar del buscador (\"cómo tomar…\", \"para qué sirve…\").</li>\n<li>Los comentarios de tus videos anteriores.</li>\n<li>Fechas de salud (Día Mundial de la Diabetes, 14 de noviembre; Día Mundial de la Hipertensión, 17 de mayo; Semana Mundial de Concienciación sobre la Resistencia a los Antimicrobianos, en noviembre).</li>\n</ul>\n<p>Haz una lista de al menos 20 ideas y clasifícalas por pilar.</p><h2>Paso 4: arma el calendario</h2><p>Sé realista. Es mejor publicar tres veces por semana durante tres meses que todos los días durante una semana y abandonar.</p>\n<p>Ejemplo de semana:</p>\n<ul>\n<li><strong>Lunes:</strong> uso correcto (video 60 s).</li>\n<li><strong>Miércoles:</strong> mito o verdad (video 30–45 s).</li>\n<li><strong>Viernes:</strong> enfermedad crónica o detrás del mostrador (video 60–90 s o carrusel).</li>\n</ul>\n<p>En 30 días son 12–13 piezas.</p><h2>Paso 5: produce por lotes</h2><p>En lugar de grabar cada día:</p>\n<ol>\n<li><strong>Escribe</strong> los guiones de dos semanas en una sesión.</li>\n<li><strong>Graba</strong> todos en una sola jornada (mismo set, misma luz, cambiando de camisa si quieres variedad).</li>\n<li><strong>Edita</strong> en otra sesión.</li>\n<li><strong>Programa</strong> las publicaciones.</li>\n</ol>\n<p>La producción por lotes ahorra tiempo y da coherencia visual.</p><h2>Paso 6: mide lo que importa</h2><p>Métricas útiles (los nombres varían según la plataforma):</p>\n<ul>\n<li><strong>Retención o tiempo de visualización:</strong> ¿la gente ve el video hasta el final? Es una de las señales más importantes.</li>\n<li><strong>Alcance e impresiones:</strong> ¿cuántas personas lo vieron?</li>\n<li><strong>Interacción:</strong> comentarios, compartidos, guardados (los guardados y compartidos indican contenido útil).</li>\n<li><strong>Acciones:</strong> mensajes recibidos, visitas a la droguería, clics al enlace, inscripciones.</li>\n</ul>\n<p>Evita obsesionarte con los \"me gusta\": no siempre reflejan el impacto.</p><h2>Paso 7: revisa y mejora cada semana</h2><p>Una vez por semana, 15 minutos:</p>\n<ul>\n<li>¿Qué video tuvo mejor retención? ¿Qué gancho usó?</li>\n<li>¿Qué temas generaron más preguntas?</li>\n<li>¿Qué haré diferente la próxima semana?</li>\n</ul>\n<p>Ajusta el calendario según lo aprendido.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, $hb10j${"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un regente de una droguería de barrio arma su plan de 30 días con tres pilares (uso correcto, mitos y \"conozca su droguería\"). Graba los lunes en la tarde, cuando hay poca afluencia, seis videos por sesión. Al mes nota que los videos de mitos tienen más compartidos y que varios pacientes llegan diciendo \"lo vi en el video\". Ajusta su plan para el segundo mes con más mitos y un video semanal de respuestas a preguntas de pacientes.</p>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, $hb10j${"tone":"importante","title":"Puntos clave","html":"<ol>\n<li>Define objetivo, audiencia y 3–4 pilares temáticos.</li>\n<li>Calendario realista y producción por lotes.</li>\n<li>Mide retención, interacción útil y acciones, y mejora cada semana.</li>\n</ol>"}$hb10j$::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, $hb10j${"tone":"info","title":"Siguiente paso","html":"<p>Completa tu calendario de 30 días y graba tu primer lote de cuatro videos.</p>"}$hb10j$::jsonb);
END
$hb10$;

-- ─── Publicación aprobada ───
-- Solo los que acaban de crearse aquí: si alguien ya los publicó a mano
-- o los borró, no se toca nada.
INSERT INTO aula_publicaciones_aprobadas (course_id, aprobado_por, nota)
SELECT c.id, 'Dirección académica de Edvanta',
       'Aprobado para publicar el 9-nov-2026 (Edvanta_Cursos_Habilidades_Blandas.xlsx).'
  FROM aula_courses c
 WHERE c.kind = 'edvanta' AND c.deleted_at IS NULL
   AND c.status = 'borrador' AND c.current_version_id IS NULL
   AND c.title IN ('Curso de Oratoria: cómo hablar en público con seguridad', 'Curso para perder el miedo a hablar en público', 'Curso de Presentaciones Efectivas y Storytelling', 'Curso de Comunicación Asertiva en el Trabajo', 'Curso de Lenguaje Corporal y Comunicación No Verbal', 'Curso de Negociación y Persuasión', 'Curso de Inteligencia Emocional en el Trabajo', 'Curso de Liderazgo y Trabajo en Equipo', 'Curso de Servicio al Cliente y Comunicación con el Paciente', 'Curso para Hablar Frente a la Cámara: Oratoria Digital para Videos y Videollamadas')
ON CONFLICT (course_id) DO NOTHING;
